import { type CharacterObject } from "../../../entities/common/character-object";
import { type DeliveryBox } from "../../../entities/objects/delivery_box";
import { HeldObjectComponent } from "../../held-object-component";
import { InteractiveObjectComponent } from "../../interactive-object-component";
import { BaseCharacterState } from "./base-character-state";
import { CHARACTER_STATES } from "./character-states";

export class DeliverItemState extends BaseCharacterState {
  constructor(gameObject: CharacterObject) {
    super(CHARACTER_STATES.DELIVER_ITEM_STATE, gameObject);
  }

  public onEnter(args: unknown[]): void {
    const deliveryBox = args[0] as DeliveryBox;

    this._resetVelocity();

    this._gameObject.animationComponent.playReverseAnimation(
      `LIFT_${this._gameObject.direction}`,
    );

    const heldComponent = HeldObjectComponent.getComponent<HeldObjectComponent>(
      this._gameObject,
    );
    if (heldComponent?.object === undefined) {
      return;
    }

    const interactiveComponent =
      InteractiveObjectComponent.getComponent<InteractiveObjectComponent>(
        deliveryBox,
      );
    if (!interactiveComponent) {
      return;
    }
    console.debug("delivery box", deliveryBox);
    console.debug("held object", heldComponent?.object);
    if (interactiveComponent.interact()) {
      heldComponent.drop(this._gameObject.direction);
    }
  }

  public onUpdate(): void {
    if (this._gameObject.animationComponent.isAnimationPlaying()) {
      return;
    }
    const heldComponent = HeldObjectComponent.getComponent<HeldObjectComponent>(
      this._gameObject,
    );
    if (heldComponent?.object === undefined) {
      this._stateMachine.setState(CHARACTER_STATES.IDLE_STATE);
      return;
    }
    this._stateMachine.setState(CHARACTER_STATES.IDLE_HOLDING_STATE);
  }
}
