import type { TeamHuntState } from "@hunt/public-client";
import { cn } from "@hunt/styled-ui";
import { FileText } from "lucide-react";
import React from "react";

type SolutionBadgeVariant = "long" | "short";

type SolutionBadgeProps = Omit<
  React.AnchorHTMLAttributes<HTMLAnchorElement>,
  "children"
> & {
  variant?: SolutionBadgeVariant;
  disabled?: boolean;
};

const SolutionBadgeBase = React.forwardRef<
  HTMLAnchorElement,
  SolutionBadgeProps
>(
  (
    {
      className,
      variant = "long",
      "aria-label": ariaLabel,
      disabled = false,
      href,
      tabIndex,
      onClick,
      role,
      ...anchorProps
    },
    ref,
  ) => {
    const isLong = variant === "long";
    const handleClick: React.MouseEventHandler<HTMLAnchorElement> = (event) => {
      if (disabled) {
        event.preventDefault();
        event.stopPropagation();
        return;
      }

      onClick?.(event);
    };

    return (
      <a
        {...anchorProps}
        ref={ref}
        aria-label={ariaLabel ?? "Solution"}
        aria-disabled={disabled || undefined}
        className={cn(
          "group inline-flex h-12 items-center justify-center gap-0.5 rounded-lg border-2 border-[#FFE100] bg-[#2C599C] text-[#FFE100] no-underline hover:no-underline shadow-[0_0_6px_rgba(0,0,0,0.5)] transition-colors duration-150",
          disabled
            ? "cursor-not-allowed opacity-60 hover:border-[#FFE100] hover:bg-[#2C599C] hover:text-[#FFE100] hover:shadow-[0_0_6px_rgba(0,0,0,0.5)]"
            : "hover:border-[#2C599C] hover:bg-[#FFE100] hover:text-[#2C599C]",
          isLong ? "w-28" : "w-12",
          className,
        )}
        href={disabled ? undefined : href}
        onClick={handleClick}
        role={role ?? (disabled ? "link" : undefined)}
        tabIndex={disabled ? (tabIndex ?? 0) : tabIndex}
      >
        {isLong ? (
          <div className="flex flex-col justify-center font-normal not-italic">
            <span className="text-lg leading-normal">Solution</span>
          </div>
        ) : null}
        <FileText className="h-5 w-5" />
      </a>
    );
  },
);

SolutionBadgeBase.displayName = "SolutionBadgeBase";

export const SolutionBadge = React.forwardRef<
  HTMLAnchorElement,
  Omit<SolutionBadgeProps, "variant">
>((props, ref) => <SolutionBadgeBase ref={ref} {...props} variant="long" />);

SolutionBadge.displayName = "SolutionBadge";

export const SolutionBadgeCompact = React.forwardRef<
  HTMLAnchorElement,
  Omit<SolutionBadgeProps, "variant">
>((props, ref) => <SolutionBadgeBase ref={ref} {...props} variant="short" />);

SolutionBadgeCompact.displayName = "SolutionBadgeCompact";

const SolutionLinkWrapper = ({
  children,
  className,
}: {
  children: React.ReactNode;
  className?: string;
}) => <div className={cn("inline-flex", className)}>{children}</div>;

export default function RoundSolutionLink({
  slug,
  teamState,
  variant = "long",
  className,
}: {
  slug: string;
  teamState: TeamHuntState;
  variant?: "long" | "short";
  className?: string;
}) {
  // Only show solution if the global solutions gate is satisfied
  const solutionsReleased =
    teamState.gates_satisfied.includes("solutions_released");

  if (!solutionsReleased) {
    return null;
  }

  const BadgeComponent =
    variant === "short" ? SolutionBadgeCompact : SolutionBadge;

  return (
    <SolutionLinkWrapper className={className}>
      <BadgeComponent href={`/rounds/${slug}/solution`} aria-label="Solution" />
    </SolutionLinkWrapper>
  );
}
