import type { GameObject, CustomObject } from "../common/types";
import { isCustomObject } from "../common/utils";
import type {
  HidingPlace,
  HidingEntity,
} from "../entities/objects/campground/hiding_place";
import { BaseGameObjectComponent } from "./base-game-object";

export type HidingComponentConfig = {
  /**
   * Callback invoked when the entity is hidden in a hiding place
   */
  onHide?: (hidingPlace: HidingPlace) => void;

  /**
   * Callback invoked when the entity is revealed from a hiding place
   */
  onReveal?: () => void;
};

/**
 * Component that makes a game object hideable in hiding places.
 * Implements the HidingEntity interface.
 *
 * @requires The gameObject parameter must implement both {@link GameObject} and
 * {@link CustomObject} interfaces. This is enforced at compile time by the type
 * signature (`GameObject & CustomObject`) and validated at runtime.
 * CustomObject requires `enableObject()` and `disableObject()` methods.
 */
export class HidingComponent
  extends BaseGameObjectComponent
  implements HidingEntity
{
  #currentHidingPlace: HidingPlace | null = null;
  #targetHidingPlace: HidingPlace | null = null;
  #onHide?: (hidingPlace: HidingPlace) => void;
  #onReveal?: () => void;

  constructor(
    gameObject: GameObject & CustomObject,
    config: HidingComponentConfig = {},
  ) {
    super(gameObject);

    // Verify the object implements CustomObject
    if (!isCustomObject(gameObject)) {
      throw new Error(
        "HidingComponent can only be used on objects that implement CustomObject (have enableObject and disableObject methods)",
      );
    }

    this.#onHide = config.onHide;
    this.#onReveal = config.onReveal;
  }

  /**
   * Gets the current hiding place the entity is in, or null if not hiding
   * Part of HidingEntity interface
   */
  public get currentHidingPlace(): HidingPlace | null {
    return this.#currentHidingPlace;
  }

  /**
   * Sets the target hiding place the entity is moving toward.
   * Called by the entity when it decides to move to a hiding place.
   */
  public setTargetHidingPlace(hidingPlace: HidingPlace | null): void {
    this.#targetHidingPlace = hidingPlace;
  }

  /**
   * Checks if the given hiding place is the target the entity is moving to.
   * Returns true if this hiding place should be handled, false otherwise.
   */
  public isTargetHidingPlace(hidingPlace: HidingPlace): boolean {
    // Only handle if this is our target hiding place
    if (this.#targetHidingPlace !== hidingPlace) {
      return false;
    }

    // Only handle if we're not already hiding somewhere
    if (this.#currentHidingPlace !== null) {
      return false;
    }

    // This is our target and we're ready to hide
    return true;
  }

  /**
   * Hides the entity in the specified hiding place
   * Called by the collision system when an entity reaches a hiding place
   */
  public hideInHidingPlace(hidingPlace: HidingPlace): void {
    if (this.#currentHidingPlace === hidingPlace) {
      return; // Already hiding here
    }

    this.#currentHidingPlace = hidingPlace;
    this.#targetHidingPlace = null; // Clear target once we're hiding

    // Hide the object (CustomObject has these methods)
    this.customObject.setVisible(false);
    this.customObject.disableObject();

    // Call entity-specific hide callback
    if (this.#onHide) {
      this.#onHide(hidingPlace);
    }
  }

  /**
   * Reveals the entity from its hiding place
   * Part of HidingEntity interface
   */
  public revealFromHidingPlace(): void {
    if (this.#currentHidingPlace === null) {
      return;
    }

    const wasHidingPlace = this.#currentHidingPlace;

    // Unregister from the hiding place
    wasHidingPlace.unregisterHidingEntity(this);
    this.#currentHidingPlace = null;

    // Show and enable the object (CustomObject has these methods)
    this.customObject.enableObject();
    this.customObject.setVisible(true);

    // Position at the hiding place location
    this.gameObject.setPosition(wasHidingPlace.x, wasHidingPlace.y);

    // Call entity-specific reveal callback
    if (this.#onReveal) {
      this.#onReveal();
    }
  }

  /**
   * Gets the underlying game object, typed as CustomObject
   */
  protected get customObject(): GameObject & CustomObject {
    return this.gameObject as GameObject & CustomObject;
  }
}
