import { DIVING_SPEED_MODIFIER } from "../../../common/config";
import { type CharacterObject } from "../../../entities/common/character-object";
import { SpeedComponent } from "../../speed-component";
import { BaseMoveState } from "./base-move-state";
import { CHARACTER_STATES } from "./character-states";
import { handleInteraction } from "./interaction-utils";

export class MoveDivingState extends BaseMoveState {
  constructor(gameObject: CharacterObject) {
    super(CHARACTER_STATES.MOVE_DIVING_STATE, gameObject, "WALK_DIVING");
  }

  public onEnter(): void {
    // Set diving speed penalty (70% speed)
    const speedComponent = SpeedComponent.getComponent<SpeedComponent>(
      this._gameObject,
    );
    speedComponent.setSpeedModifier(DIVING_SPEED_MODIFIER);
  }

  public onExit(): void {
    // Reset speed modifier back to normal (100% speed)
    const speedComponent = SpeedComponent.getComponent<SpeedComponent>(
      this._gameObject,
    );
    speedComponent.resetSpeedModifier();
  }

  public onUpdate(): void {
    const controls = this._gameObject.controls;

    // Can't use item while diving.
    if (controls.isUseJustDown) {
      return;
    }

    if (this.isNoMoveInput(controls)) {
      this._stateMachine.setState(CHARACTER_STATES.IDLE_DIVING_STATE);
      return;
    }

    if (
      handleInteraction(this._gameObject, this._stateMachine, controls, {
        isDiving: true,
      })
    ) {
      return;
    }
    this.handleCharacterMovement();
  }
}
