import * as Phaser from "phaser";
import {
  ASSET_KEYS,
  CHEST_FRAME_KEYS,
  EFFECTS_ANIMATION_KEYS,
} from "../../common/assets";
import {
  CHEST_STATE,
  INTERACTIVE_OBJECT_TYPE,
  type StoryFlag,
} from "../../common/constants";
import {
  getSceneDataManager,
  type DataManager,
} from "../../common/data-manager";
import type {
  ChestReward,
  TiledChestObject,
  TriggerInfo,
} from "../../common/tiled/types";
import type { ChestState, CustomObject, LevelName } from "../../common/types";
import { InteractiveObjectComponent } from "../../components/interactive-object-component";
import { InventoryManager } from "../../components/inventory/inventory-manager";

const LEVEL_AND_ID_TO_DIALOG: Partial<
  Record<LevelName, Record<number, string[]>>
> = {
  CAT_CATSLE: {
    1: ["You found the Night Key! This might be useful later..."],
  },
  CEMETERY: {
    1: ["You found the Wisdom Key! This might be useful later..."],
  },
};

// Mapping from story flag to puzzle info (slug and title) for elder drifts chests
// Trace: story_flag -> interaction_id (FLAG_TO_INTERACTION_MAP) -> puzzle slot (r5pdXX -> r5pXX) -> puzzle slug (ID_TO_PUZZLE_AND_PUZZMON_SLUGS_RAW)
const ELDER_DRIFTS_STORY_FLAG_TO_PUZZLE: Record<
  string,
  { slug: string; title: string }
> = {
  cemetery01: { slug: "financial_literacy", title: "Financial Literacy" }, // r5pd01 -> r5p01
  cemetery02: { slug: "data_revisualization", title: "Data Revisualization" }, // r5pd02 -> r5p02
  cemetery03: { slug: "shapes", title: "Shapes" }, // r5pd03 -> r5p03
  cemetery04: { slug: "uneven", title: "Uneven" }, // r5pd04 -> r5p04
  cemetery05: { slug: "railway_terminal", title: "Railway Terminal" }, // r5pd05 -> r5p05
  cemetery06: { slug: "chemical_x", title: "Chemical X" }, // r5pd06 -> r5p06
  cemetery07: {
    slug: "method_to_the_mathmess",
    title: "Method to the Mathmess",
  }, // r5pd07 -> r5p07
  cemetery08: {
    slug: "nominative_determinism",
    title: "Nominative Determinism",
  }, // r5pd08 -> r5p08
  cemetery09: {
    slug: "go_back_to_square_fourteen",
    title: "Go Back to Square Fourteen",
  }, // r5pd09 -> r5p09
  cemetery10: { slug: "turing_machine", title: "Turing Machine" }, // r5pd10 -> r5p10
  cemetery11: { slug: "convalarium", title: "Convalarium" }, // r5pd11 -> r5p11
  cemetery12: { slug: "tribute_puzzle", title: "Tribute Puzzle" }, // r5pd12 -> r5p12
};

const LEVEL_AND_ID_TO_OPENED_DIALOG: Partial<
  Record<LevelName, Record<number, string[]>>
> = {
  CAT_CATSLE: {
    1: ["The chest is already empty, someone must have looted it already!"],
  },
  CEMETERY: {
    1: ["The chest is already empty, someone must have looted it already!"],
  },
};

export class Chest extends Phaser.Physics.Arcade.Image implements CustomObject {
  #state: ChestState;
  #isSpecialChest: boolean;
  #id: number;
  #revealTrigger: TriggerInfo;
  #contents: ChestReward;
  #dataManager: DataManager;
  #level: LevelName;
  #storyFlag: StoryFlag | undefined;
  #exclamationSprite?: Phaser.GameObjects.Sprite;

  constructor(
    scene: Phaser.Scene,
    config: TiledChestObject,
    level: LevelName,
    chestState = CHEST_STATE.HIDDEN,
  ) {
    const frameKey = config.requiresBossKey
      ? CHEST_FRAME_KEYS.BIG_CHEST_CLOSED
      : CHEST_FRAME_KEYS.SMALL_CHEST_CLOSED;
    super(scene, config.x, config.y, ASSET_KEYS.DUNGEON_OBJECTS, frameKey);

    scene.add.existing(this);
    scene.physics.add.existing(this);
    this.setOrigin(0, 1).setImmovable(true);

    this.#id = config.id;
    this.#contents = config.contents;
    this.#state = chestState;
    this.#level = level;
    this.#isSpecialChest = config.requiresBossKey ?? false;
    this.#revealTrigger = config.revealChestTrigger ?? {
      type: "NONE",
      ids: [],
    };
    this.#dataManager = getSceneDataManager(scene);
    this.#storyFlag = config.storyFlag;

    if (this.#isSpecialChest) {
      (this.body as Phaser.Physics.Arcade.Body).setSize(32, 24).setOffset(0, 8);
    }

    new InteractiveObjectComponent(
      this,
      INTERACTIVE_OBJECT_TYPE.OPEN,
      () => {
        return true;
      },
      () => {
        // Check boss key requirement for special chests
        if (this.#isSpecialChest) {
          if (!InventoryManager.instance.getAreaInventory(level).bossKey) {
            return false;
          }
        }
        return true;
      },
    );

    // Check reveal conditions and set initial state
    if (this.shouldReveal(level)) {
      this.reveal();
    }
    this.disableObject();
  }

  get revealTrigger(): TriggerInfo {
    return this.#revealTrigger;
  }

  get contents(): ChestReward {
    return this.#contents;
  }

  get id(): number {
    return this.#id;
  }

  get storyFlag(): StoryFlag | undefined {
    return this.#storyFlag;
  }

  get dialog(): string[] {
    // For elder drifts chests, add clickable puzzle name reference
    const puzzleInfo =
      this.#level === "CEMETERY" &&
      this.#storyFlag &&
      ELDER_DRIFTS_STORY_FLAG_TO_PUZZLE[this.#storyFlag]
        ? ELDER_DRIFTS_STORY_FLAG_TO_PUZZLE[this.#storyFlag]
        : undefined;

    if (this.#state === CHEST_STATE.OPEN) {
      const baseDialog =
        LEVEL_AND_ID_TO_OPENED_DIALOG[this.#level]?.[this.#id] ?? [];
      if (puzzleInfo) {
        // Format puzzle name as clickable BBCode link (same format as NPC text)
        const puzzleLink = `[url=/puzzles/${puzzleInfo.slug}][b][color=#801a79]${puzzleInfo.title}[/color][/b][/url]`;
        // If there's a base dialog, append puzzle reference; otherwise create new message
        return [
          `The chest is already opened, but someone was thoughtful enough to leave a copy of ${puzzleLink} behind.`,
        ];
      }
      return baseDialog;
    }

    // For REVEALED state (not yet opened), also add puzzle reference
    const baseDialog = LEVEL_AND_ID_TO_DIALOG[this.#level]?.[this.#id] ?? [];
    if (puzzleInfo) {
      // Format puzzle name as clickable BBCode link (same format as NPC text)
      const puzzleLink = `[url=/puzzles/${puzzleInfo.slug}][b][color=#801a79]${puzzleInfo.title}[/color][/b][/url]`;
      // If there's a base dialog, append puzzle reference; otherwise create new message
      if (baseDialog.length > 0) {
        return [`You found ${puzzleLink}!`];
      } else {
        return [`You found ${puzzleLink}!`];
      }
    }
    return baseDialog;
  }

  get chestState(): ChestState {
    return this.#state;
  }

  public reveal(): void {
    if (this.#state !== CHEST_STATE.HIDDEN) {
      return;
    }
    this.#state = CHEST_STATE.REVEALED;
    this.enableObject();
    this.#updateExclamationMark();
  }

  /**
   * Check if the chest should be revealed based on current conditions
   */
  public shouldReveal(level: LevelName): boolean {
    if (
      this.#state !== CHEST_STATE.HIDDEN ||
      this.#revealTrigger.type === "NONE"
    ) {
      return true;
    }

    // Handle SWITCH trigger type
    if (this.#revealTrigger.type === "SWITCH") {
      const activatedSwitches = this.#dataManager.getActivatedSwitches(level);
      return this.#revealTrigger.ids.every((switchId) =>
        activatedSwitches.includes(switchId),
      );
    }

    return false;
  }

  public open(): void {
    console.log(`Opening chest at position (${this.x}, ${this.y})`);
    if (this.#state !== CHEST_STATE.REVEALED) {
      return;
    }
    this.#setOpenedState();
  }

  /**
   * Sets the chest directly to opened state (used when loading from saved state)
   */
  public setOpenedFromState(): void {
    // Reveal first if hidden, then open
    if (this.#state === CHEST_STATE.HIDDEN) {
      this.#state = CHEST_STATE.REVEALED;
      this.enableObject();
    }
    this.#setOpenedState();
  }

  #setOpenedState(): void {
    this.#state = CHEST_STATE.OPEN;
    const frameKey = this.#isSpecialChest
      ? CHEST_FRAME_KEYS.BIG_CHEST_OPEN
      : CHEST_FRAME_KEYS.SMALL_CHEST_OPEN;
    this.setFrame(frameKey);
    this.#updateExclamationMark();
    // Keep InteractiveObjectComponent so player can interact with opened chest to see dialog
  }

  public enableObject(): void {
    if (this.#state === CHEST_STATE.HIDDEN) {
      return;
    }
    (this.body as Phaser.Physics.Arcade.Body).enable = true;
    this.active = true;
    this.visible = true;
    this.#updateExclamationMark();
  }

  public disableObject(): void {
    (this.body as Phaser.Physics.Arcade.Body).enable = false;
    this.active = false;
    this.visible = false;
    this.#destroyExclamationSprite();
  }

  #updateExclamationMark(): void {
    const shouldShow = this.#state === CHEST_STATE.REVEALED && this.visible;

    if (shouldShow && !this.#exclamationSprite) {
      this.#createExclamationMark();
    } else if (this.#exclamationSprite) {
      this.#exclamationSprite.setVisible(shouldShow);
    }
  }

  #createExclamationMark(): void {
    // Position exclamation mark above the chest
    const x = this.x + this.width / 2;
    const y = this.y - 14;

    this.#exclamationSprite = this.scene.add.sprite(
      x,
      y,
      ASSET_KEYS.EXCLAMATION,
    );
    this.#exclamationSprite.setOrigin(0.5, 1);
    this.#exclamationSprite.setDepth(this.depth + 3); // Render above chest
    this.#exclamationSprite.setVisible(this.visible);

    // Start the animation on loop
    this.#exclamationSprite.play({
      key: EFFECTS_ANIMATION_KEYS.EXCLAMATION,
      repeat: -1,
    });
  }

  #destroyExclamationSprite(): void {
    if (this.#exclamationSprite) {
      this.#exclamationSprite.destroy();
      this.#exclamationSprite = undefined;
    }
  }
}
