/**
 * Finds all of the valid 'HidingPlace' Tiled Objects on a given layer of a Tilemap.
 */
export function getTiledHidingPlaceObjectsFromMap(
  map: Phaser.Tilemaps.Tilemap,
  layerName: string,
): TILED_TYPES.TiledHidingPlaceObject[] {
  const hidingPlaceObjects: TILED_TYPES.TiledHidingPlaceObject[] = [];

  // loop through each object and validate object has properties for the object we are planning to build
  const tiledObjects = getTiledObjectsFromLayer(map, layerName);
  tiledObjects.forEach((tiledObject) => {
    const identifier = getTiledPropertyByName<string>(
      tiledObject.properties,
      TILED_CONSTANTS.TILED_HIDING_PLACE_OBJECT_PROPERTY.IDENTIFIER,
    );

    if (identifier === undefined) {
      console.error(
        `Invalid hiding place object: ${JSON.stringify(tiledObject)}`,
      );
      return;
    }

    const requiresDirection =
      getTiledPropertyByName<boolean>(
        tiledObject.properties,
        TILED_CONSTANTS.TILED_HIDING_PLACE_OBJECT_PROPERTY.REQUIRES_DIRECTION,
      ) ?? false;

    let requiredDirection: Direction | undefined;
    if (requiresDirection) {
      const directionString = getTiledPropertyByName<string>(
        tiledObject.properties,
        TILED_CONSTANTS.TILED_HIDING_PLACE_OBJECT_PROPERTY.REQUIRED_DIRECTION,
      );
      if (directionString !== undefined) {
        if (!isDirection(directionString)) {
          console.error(
            `Invalid hiding place direction: ${directionString} in object: ${JSON.stringify(tiledObject)}`,
          );
          return;
        }
        requiredDirection = directionString;
      }
    }

    hidingPlaceObjects.push({
      identifier,
      requiresDirection,
      requiredDirection,
      x: tiledObject.x,
      y: tiledObject.y,
      width: tiledObject.width,
      height: tiledObject.height,
    });
  });

  return hidingPlaceObjects;
}

/**
 * Finds all of the valid 'NPC' Tiled Objects on a given layer of a Tilemap.
 */
export function getTiledNpcObjectsFromMap(
  map: Phaser.Tilemaps.Tilemap,
  layerName: string,
): TILED_TYPES.TiledNpcObject[] {
  const npcObjects: TILED_TYPES.TiledNpcObject[] = [];

  // loop through each object and validate object has properties for the object we are planning to build
  const tiledObjects = getTiledObjectsFromLayer(map, layerName);
  tiledObjects.forEach((tiledObject) => {
    const identifier = getTiledPropertyByName<string>(
      tiledObject.properties,
      TILED_CONSTANTS.TILED_NPC_OBJECT_PROPERTY.IDENTIFIER,
    );

    if (identifier === undefined) {
      console.warn(`Invalid NPC object: ${JSON.stringify(tiledObject)}`);
      return;
    }

    // Validate that the identifier is a valid NPC identifier
    if (!isNpcIdentifier(identifier)) {
      console.warn(`Invalid NPC identifier: ${identifier}`);
      return;
    }

    npcObjects.push({
      x: tiledObject.x,
      y: tiledObject.y,
      width: tiledObject.width,
      height: tiledObject.height,
      identifier: identifier,
    });
  });

  return npcObjects;
}

export function isNpcIdentifier(
  identifier: string,
): identifier is TILED_TYPES.NPCIdentifier {
  // Allow any non-empty string as an NPC identifier to support custom levels
  // The existing NPC_IDENTIFIER constants are kept for documentation purposes

  // Check if it's a known NPC identifier
  const isKnownIdentifier =
    NPC_IDENTIFIER[identifier as keyof typeof NPC_IDENTIFIER] !== undefined;

  // If it's not a known identifier, log a warning but still allow it
  if (!isKnownIdentifier) {
    console.warn(
      `Custom NPC identifier detected: "${identifier}". This is allowed but ensure the corresponding NPC data exists in your custom npcs.json file.`,
    );
  }

  return typeof identifier === "string" && identifier.trim().length > 0;
}

