/**
 * Finds all of the valid 'Switch' Tiled Objects on a given layer of a Tilemap.
 */
export function getTiledSwitchObjectsFromMap(
  map: Phaser.Tilemaps.Tilemap,
  layerName: string,
): TILED_TYPES.TiledSwitchObject[] {
  const switchObjects: TILED_TYPES.TiledSwitchObject[] = [];

  // loop through each object and validate object has properties for the object we are planning to build
  const tiledObjects = getTiledObjectsFromLayer(map, layerName);
  tiledObjects.forEach((tiledObject) => {
    const id = getTiledPropertyByName<number>(
      tiledObject.properties,
      TILED_CONSTANTS.TILED_SWITCH_OBJECT_PROPERTY.ID,
    );
    const action = getTiledPropertyByName<string>(
      tiledObject.properties,
      TILED_CONSTANTS.TILED_SWITCH_OBJECT_PROPERTY.ACTION,
    );
    const targetIds = getTiledPropertyByName<string>(
      tiledObject.properties,
      TILED_CONSTANTS.TILED_SWITCH_OBJECT_PROPERTY.TARGET_IDS,
    );
    const texture = getTiledPropertyByName<string>(
      tiledObject.properties,
      TILED_CONSTANTS.TILED_SWITCH_OBJECT_PROPERTY.TEXTURE,
    );

    if (
      id === undefined ||
      action === undefined ||
      targetIds === undefined ||
      texture === undefined ||
      !isSwitchAction(action) ||
      !isSwitchTexture(texture)
    ) {
      console.warn(`Invalid switch object: ${JSON.stringify(tiledObject)}`);
      return;
    }

    // Parse target IDs from comma-separated string
    const parsedTargetIds = targetIds
      .split(",")
      .map((id) => parseInt(id.trim(), 10))
      .filter((id) => !isNaN(id));

    switchObjects.push({
      x: tiledObject.x,
      y: tiledObject.y,
      width: tiledObject.width,
      height: tiledObject.height,
      id,
      action: action as TILED_TYPES.SwitchAction,
      targetIds: parsedTargetIds,
      texture: texture as TILED_TYPES.SwitchTexture,
    });
  });

  return switchObjects;
}

export function isSwitchTexture(
  switchTexture: string,
): switchTexture is TILED_TYPES.SwitchTexture {
  return (
    TILED_CONSTANTS.SWITCH_TEXTURE[
      switchTexture as keyof typeof TILED_CONSTANTS.SWITCH_TEXTURE
    ] !== undefined
  );
}

export function isSwitchAction(
  switchAction: string,
): switchAction is TILED_TYPES.SwitchAction {
  return (
    TILED_CONSTANTS.SWITCH_ACTION[
      switchAction as keyof typeof TILED_CONSTANTS.SWITCH_ACTION
    ] !== undefined
  );
}

