import type * as Phaser from "phaser";
import {
  ASSET_KEYS,
  DOOR_FRAME_KEYS,
  DUNGEON_DOOR_FRAME_KEYS,
} from "../../common/assets";
import { DIRECTION } from "../../common/constants";
import {
  getSceneDataManager,
  type DataManager,
} from "../../common/data-manager";
import { DOOR_TYPE } from "../../common/tiled/constants";
import type {
  DoorType,
  TiledDoorObject,
  TriggerInfo,
} from "../../common/tiled/types";
import type {
  CustomObject,
  Direction,
  LevelName,
  Position,
} from "../../common/types";
import { assertNeverCalled } from "../../common/utils";

export class Door implements CustomObject {
  // Architecture:
  // - #doorObject: Purely visual representation (no physics/collision)
  // - #doorCollider: Invisible collision rectangle for physics detection
  // - #doorTransitionZone: Interactive zone for door transitions
  // - This separation allows visual doors to have different collision behavior

  #scene: Phaser.Scene;
  #roomId: number;
  #targetRoomId: number;
  #targetDoorId: number;
  #x: number;
  #y: number;
  #targetLevel: string;
  #doorTransitionZone: Phaser.GameObjects.Zone;
  #debugDoorTransitionZone: Phaser.GameObjects.Rectangle | undefined;
  #direction: Direction;
  #id: number;
  #isUnlocked: boolean;
  #doorObject?: Phaser.Types.Physics.Arcade.ImageWithDynamicBody;
  #trapDoorTrigger: TriggerInfo;
  #doorType: DoorType;
  #requiredFlags?: string[];
  #requiredFrontendFlags?: Record<string, string>;
  #doorCollider?: Phaser.Types.Physics.Arcade.ImageWithDynamicBody;
  #dataManager: DataManager;
  #assetKey: string | undefined;
  #openFrameName: string | undefined;
  #closedFrameName: string | undefined;
  #animation: string | undefined;
  #animateWalk: boolean;

  constructor(
    scene: Phaser.Scene,
    config: TiledDoorObject,
    level: LevelName,
    roomId: number,
  ) {
    this.#scene = scene;
    this.#roomId = roomId;
    this.#targetRoomId = config.targetRoomId ?? 0;
    this.#targetDoorId = config.targetDoorId ?? 0;
    this.#x = config.x;
    this.#y = config.y;
    this.#targetLevel = config.targetLevel ?? "";
    this.#direction = config.direction;
    this.#id = config.id;
    this.#isUnlocked = config.isUnlocked ?? false;
    this.#trapDoorTrigger = config.trapDoorTrigger ?? { type: "NONE", ids: [] };
    this.#doorType = config.doorType ?? "OPEN";
    this.#requiredFlags = config.requiredFlags;
    this.#requiredFrontendFlags = config.requiredFrontendFlags;
    this.#dataManager = getSceneDataManager(scene);
    this.#assetKey = config.assetKey;
    this.#openFrameName = config.openFrameName;
    this.#closedFrameName = config.closedFrameName;
    this.#animation = config.animation;
    this.#animateWalk = config.animateWalk ?? false;

    this.#doorTransitionZone = this.#scene.add
      .zone(config.x, config.y, config.width, config.height)
      .setOrigin(0, 0)
      .setName(config.id.toString(10));
    this.#scene.physics.world.enable(this.#doorTransitionZone);

    this.#debugDoorTransitionZone = this.#scene.add.rectangle(
      this.#doorTransitionZone.x,
      this.#doorTransitionZone.y,
      this.#doorTransitionZone.width,
      this.#doorTransitionZone.height,
      0xffff00,
      0, //set alpha to 0,
    );
    this.#debugDoorTransitionZone.setOrigin(0, 0);

    // Create visual door objects for door types that have sprites
    if (
      this.#doorType === DOOR_TYPE.LOCK ||
      this.#doorType === DOOR_TYPE.TRAP ||
      this.#doorType === DOOR_TYPE.BOSS ||
      this.#doorType === DOOR_TYPE.SECRET ||
      this.#doorType === DOOR_TYPE.FLAG_REQUIRED
    ) {
      let frameName: string | undefined;
      let assetKey: string;
      if (this.#assetKey !== undefined) {
        assetKey = this.#assetKey;
        frameName = this.#closedFrameName;
      } else if (
        this.#doorType === DOOR_TYPE.LOCK ||
        this.#doorType === DOOR_TYPE.TRAP ||
        this.#doorType === DOOR_TYPE.BOSS
      ) {
        frameName =
          DUNGEON_DOOR_FRAME_KEYS[`${this.#doorType}_${this.#direction}`];
        assetKey = ASSET_KEYS.DUNGEON_OBJECTS;
      } else {
        frameName = DOOR_FRAME_KEYS.SHORT_RED;
        assetKey = ASSET_KEYS.DOORS;
      }
      const door = this.#scene.physics.add
        .sprite(this.#x, this.#y + config.height / 2, assetKey, frameName)
        .setImmovable(true)
        .setSize(config.width, config.height)
        .setName(config.id.toString(10));

      switch (this.#direction) {
        case DIRECTION.UP:
          door.setOrigin(0, 0.5);
          break;
        case DIRECTION.DOWN:
          door.setOrigin(0, 0.5);
          break;
        case DIRECTION.LEFT:
          door.setOrigin(0.25, 0);
          break;
        case DIRECTION.RIGHT:
          door.setOrigin(0.5, 0);
          break;
        default:
          assertNeverCalled(this.#direction);
      }

      // For secret doors, start invisible until flags are met
      if (this.#doorType === DOOR_TYPE.SECRET) {
        door.setVisible(false);
      }

      this.#doorObject = door;
      this.#doorCollider = door;
    }

    // FLAG_REQUIRED and SECRET doors need invisible collision sprites
    if (this.shouldOpen(level)) {
      this.open();
    }

    // For secret doors, update visibility based on flags
    if (
      this.#doorType === DOOR_TYPE.SECRET ||
      this.#doorType === DOOR_TYPE.FLAG_REQUIRED
    ) {
      this.updateDoor();
    }

    this.disableObject();
  }

  get x(): number {
    return this.#x;
  }

  get y(): number {
    return this.#y;
  }

  get roomId(): number {
    return this.#roomId;
  }

  get targetRoomId(): number {
    return this.#targetRoomId;
  }

  get targetDoorId(): number {
    return this.#targetDoorId;
  }

  get targetLevel(): string {
    return this.#targetLevel;
  }

  get doorTransitionZone(): Phaser.GameObjects.Zone {
    return this.#doorTransitionZone;
  }

  get direction(): Direction {
    return this.#direction;
  }

  get id(): number {
    return this.#id;
  }

  get isUnlocked(): boolean {
    return this.#isUnlocked;
  }

  get trapDoorTrigger(): TriggerInfo {
    return this.#trapDoorTrigger;
  }

  get doorType(): DoorType {
    return this.#doorType;
  }

  get requiredFlags(): string[] | undefined {
    return this.#requiredFlags;
  }

  get requiredFrontendFlags(): Record<string, string> | undefined {
    return this.#requiredFrontendFlags;
  }

  get doorObject(): Phaser.GameObjects.Image | undefined {
    return this.#doorObject;
  }

  get doorCollider():
    | Phaser.Types.Physics.Arcade.ImageWithDynamicBody
    | undefined {
    return this.#doorCollider;
  }

  get animation(): string | undefined {
    return this.#animation;
  }

  get animateWalk(): boolean {
    return this.#animateWalk;
  }

  get animationDirection(): Direction | undefined {
    // New approach: use animateWalk boolean with door direction
    if (this.#animateWalk) {
      return this.#direction;
    }

    // Backwards compatibility: parse animation string
    if (this.#animation === undefined) {
      return undefined;
    }

    const animationParts = this.#animation.toLowerCase().split(" ");
    const directionStr = animationParts.at(-1);

    switch (directionStr) {
      case "left":
        return DIRECTION.LEFT;
      case "right":
        return DIRECTION.RIGHT;
      case "up":
        return DIRECTION.UP;
    }
    return DIRECTION.DOWN;
  }

  /**
   * Check if all required flags are completed
   */
  public hasRequiredFlags(): boolean {
    if (
      this.#doorType !== DOOR_TYPE.FLAG_REQUIRED &&
      this.#doorType !== DOOR_TYPE.SECRET
    ) {
      return true;
    }
    if (
      (!this.#requiredFlags || this.#requiredFlags.length === 0) &&
      (!this.#requiredFrontendFlags ||
        Object.entries(this.#requiredFrontendFlags).length === 0)
    ) {
      return true;
    }

    return (
      (this.#requiredFlags ?? []).every(
        (flag) => this.#dataManager.getFlagValue(flag) === "completed",
      ) &&
      this.#dataManager.hasFrontendFlagValues(this.#requiredFrontendFlags ?? {})
    );
  }

  /**
   * Check if the door should be opened based on current conditions
   */
  public shouldOpen(level: LevelName): boolean {
    if (
      this.#doorType === DOOR_TYPE.TRAP &&
      this.#trapDoorTrigger.type === "SWITCH"
    ) {
      const activatedSwitches = this.#dataManager.getActivatedSwitches(level);
      return this.#trapDoorTrigger.ids.every((switchId) =>
        activatedSwitches.includes(switchId),
      );
    }
    return false;
  }

  /**
   * Check if a secret door should be revealed (flags are met)
   */
  public shouldRevealSecret(): boolean {
    if (this.#doorType !== DOOR_TYPE.SECRET) {
      return true;
    }
    return this.hasRequiredFlags();
  }

  /**
   * Update secret door visibility based on current flag status
   */
  public updateDoor(): void {
    if (this.#doorType === DOOR_TYPE.SECRET) {
      const shouldReveal = this.shouldRevealSecret();

      // Update visual door object
      if (this.#doorObject) {
        this.#doorObject.setVisible(shouldReveal);
        this.#doorObject.active = shouldReveal;
      }

      // Update collision - show collision when door is hidden, hide when revealed
      if (this.#doorCollider) {
        const body = this.#doorCollider.body as Phaser.Physics.Arcade.Body;
        body.enable = !shouldReveal;
        this.#doorCollider.active = !shouldReveal;
      }
      if (shouldReveal && this.#openFrameName !== undefined) {
        this.#doorObject?.setFrame(this.#openFrameName);
      }
    } else if (this.#doorType === DOOR_TYPE.FLAG_REQUIRED) {
      const shouldMakeEnterable = this.hasRequiredFlags();
      if (this.#doorCollider) {
        const body = this.#doorCollider.body as Phaser.Physics.Arcade.Body;
        body.enable = !shouldMakeEnterable;
        this.#doorCollider.active = !shouldMakeEnterable;
        if (shouldMakeEnterable && this.#openFrameName !== undefined) {
          this.#doorObject?.setFrame(this.#openFrameName);
        }
      }
    }
  }

  public open(): void {
    if (
      this.#doorType === DOOR_TYPE.LOCK ||
      this.#doorType === DOOR_TYPE.BOSS ||
      this.#doorType === DOOR_TYPE.TRAP
    ) {
      this.#isUnlocked = true;
    }
    this.disableObject(false);
  }

  public enableObject(): void {
    (this.#doorTransitionZone.body as Phaser.Physics.Arcade.Body).enable = true;
    this.#doorTransitionZone.active = true;

    if (this.#isUnlocked) {
      return;
    }

    // For secret doors, only show visual/collision if flags are met
    if (this.#doorType === DOOR_TYPE.SECRET) {
      const shouldReveal = this.shouldRevealSecret();

      if (this.#doorObject) {
        this.#doorObject.active = shouldReveal;
        this.#doorObject.visible = shouldReveal;
      }

      if (this.#doorCollider) {
        this.#doorCollider.body.enable = !shouldReveal;
      }
    } else {
      // Normal door behavior for other types
      if (this.#doorObject) {
        this.#doorObject.active = true;
        this.#doorObject.visible = true;
      }

      if (this.#doorCollider) {
        (this.#doorCollider.body as Phaser.Physics.Arcade.Body).enable = true;
        this.#doorCollider.active = true;
      }
    }
  }

  public disableObject(disableDoorTrigger = true): void {
    if (disableDoorTrigger) {
      (this.#doorTransitionZone.body as Phaser.Physics.Arcade.Body).enable =
        false;
      this.#doorTransitionZone.active = false;
    }

    if (this.#doorObject) {
      this.#doorObject.active = false;
    }
    if (this.#doorCollider) {
      (this.#doorCollider.body as Phaser.Physics.Arcade.Body).enable = false;
      this.#doorCollider.active = false;
    }
  }

  /**
   * Calculate player position relative to this door, using the closest edge of the door
   * and accounting for player dimensions (assumes 12x12 player). Places player 4px off the door edge, then optionally
   * moves further into the room.
   * @param exitDirection - The direction the player is exiting (opposite of door direction)
   * @param distanceIntoRoom - Optional distance in pixels to move further into the room from the door edge (default: 0)
   * @returns The calculated position {x, y} for the player's origin (top-left)
   */
  public getPlayerPositionAtDoor(
    exitDirection: Direction,
    distanceIntoRoom = 4,
  ): Position {
    const doorWidth = this.#doorTransitionZone.width;
    const doorHeight = this.#doorTransitionZone.height;
    const playerSize = 12; // Player is always 12x12

    // It appears that the player origin is .5, 0 (center top)
    // Which is why some of the math might look a little odd.

    switch (exitDirection) {
      case DIRECTION.UP:
        // Player exits going UP, so use door's top edge
        // Player's bottom should be 4px above door's top
        return {
          x: this.#x + doorWidth / 2, // Center horizontally
          y: this.#y - distanceIntoRoom - playerSize,
        };
      case DIRECTION.DOWN:
        // Player exits going DOWN, so use door's bottom edge
        // Player's top should be 4px below door's bottom
        return {
          x: this.#x + doorWidth / 2, // Center horizontally
          y: this.#y + doorHeight + distanceIntoRoom,
        };
      case DIRECTION.LEFT:
        // Player exits going LEFT, so use door's left edge
        // Player's right should be 4px to the left of door's left
        return {
          x: this.#x - distanceIntoRoom - playerSize / 2,
          y: this.#y + doorHeight / 2 - playerSize / 2, // Center vertically
        };
      case DIRECTION.RIGHT:
        // Player exits going RIGHT, so use door's right edge
        // Player's left should be 4px to the right of door's right
        return {
          x: this.#x + doorWidth + distanceIntoRoom + playerSize / 2,
          y: this.#y + doorHeight / 2 - playerSize / 2, // Center vertically
        };
      default:
        assertNeverCalled(exitDirection);
    }
  }
}
