import { DEBUG_COLLISION_ALPHA } from "../../common/config";
import {
  getSceneDataManager,
  type DataManager,
} from "../../common/data-manager";
import type { TiledEventObject } from "../../common/tiled/types";
import type { CustomObject } from "../../common/types";
import type { ConditionsConfig, EventSequence } from "./npc-types";

type Position = { x: number; y: number };

const REQUIRED_MOVEMENT_TIME_MS = 5000;
const MOVEMENT_TIMEOUT_MS = 500;

export class EventZone implements CustomObject {
  #scene: Phaser.Scene;
  #zone: Phaser.GameObjects.Zone;
  #eventId: string;
  #eventSequence: EventSequence;
  #tiledObject: TiledEventObject;
  #debugRect?: Phaser.GameObjects.Rectangle;
  #dataManager: DataManager;

  // Movement pattern tracking (optional)
  #isMovementPattern: boolean;
  #isPlayerInZone = false;
  #accumulatedMovementTime = 0;
  #lastMovementTime = 0;
  #lastPlayerPosition: Position | null = null;

  constructor(
    scene: Phaser.Scene,
    tiledObject: TiledEventObject,
    eventSequence: EventSequence,
  ) {
    this.#scene = scene;
    this.#eventId = tiledObject.eventId;
    this.#eventSequence = eventSequence;
    this.#tiledObject = tiledObject;
    this.#dataManager = getSceneDataManager(scene);

    this.#isMovementPattern = tiledObject.isMovementPattern ?? false;
    this.#zone = this.#createZone(tiledObject);
    this.#scene.physics.add.existing(this.#zone, true);

    if (DEBUG_COLLISION_ALPHA > 0) {
      this.#createDebugRect();
    }
    this.disableObject();
  }

  #createZone(tiledObject: TiledEventObject): Phaser.GameObjects.Zone {
    const center = this.#getCenter(tiledObject);
    return this.#scene.add.zone(
      center.x,
      center.y,
      tiledObject.width,
      tiledObject.height,
    );
  }

  #getCenter(object: {
    x: number;
    y: number;
    width: number;
    height: number;
  }): Position {
    return {
      x: object.x + object.width / 2,
      y: object.y + object.height / 2,
    };
  }

  public getZone(): Phaser.GameObjects.Zone {
    return this.#zone;
  }

  public getTiledObject(): TiledEventObject {
    return this.#tiledObject;
  }

  public getEventId(): string {
    return this.#eventId;
  }

  public getEventSequence(): EventSequence {
    return this.#eventSequence;
  }

  // ============================================================================
  // Public API: Object lifecycle
  // ============================================================================

  public conditionsMet(): boolean {
    const alreadyTriggered = this.#dataManager.hasEventId(this.#eventId);
    if (alreadyTriggered && !this.#isMovementPattern) {
      return false;
    }

    return conditionsMet(this.#dataManager, this.#scene, this.#eventSequence);
  }

  public enableObject(): void {
    if (!this.conditionsMet()) {
      return;
    }
    this.#setZoneActive(true);
    if (this.#debugRect) {
      this.#debugRect.setVisible(true);
    }
  }

  public disableObject(): void {
    this.#setZoneActive(false);
    if (this.#debugRect) {
      this.#debugRect.setVisible(false);
    }
    if (this.#isMovementPattern) {
      this.#resetMovementTracking();
    }
  }

  public destroy(): void {
    const body = this.#zone.body as Phaser.Physics.Arcade.Body | null;
    if (body && "world" in body) {
      this.#scene.physics.world.remove(body);
    }

    this.#debugRect?.destroy();
    this.#zone.destroy();
  }

  // ============================================================================
  // Public API: Movement pattern zones
  // ============================================================================

  public isMovementPatternZone(): boolean {
    return this.#isMovementPattern;
  }

  public onPlayerEnter(): void {
    if (!this.#isMovementPattern || !this.conditionsMet()) {
      return;
    }
    this.#isPlayerInZone = true;
    this.#lastMovementTime = this.#scene.time.now;
    this.#lastPlayerPosition = null;
  }

  public onPlayerExit(): void {
    if (!this.#isMovementPattern) {
      return;
    }
    this.#isPlayerInZone = false;
    this.#resetMovementTracking();
  }

  /**
   * Update movement pattern zone (call in scene update loop)
   * Handles overlap detection, enter/exit tracking, and movement tracking.
   */
  public update(
    player: Phaser.GameObjects.GameObject,
    physics: Phaser.Physics.Arcade.ArcadePhysics,
    triggerCallback: () => void,
  ): void {
    if (!this.#isMovementPattern || !this.conditionsMet()) {
      return;
    }

    const isOverlapping = physics.overlap(player, this.#zone);
    const wasInZone = this.#isPlayerInZone;

    // Track enter/exit
    if (isOverlapping && !wasInZone) {
      this.onPlayerEnter();
    } else if (!isOverlapping && wasInZone) {
      this.onPlayerExit();
    }

    // Update movement tracking if player is in zone
    if (isOverlapping) {
      this.#updateMovementTracking(player, triggerCallback);
    }
  }

  /**
   * Update movement tracking (internal)
   * Tracks time spent moving within the zone and triggers callback after threshold is met.
   */
  #updateMovementTracking(
    player: Phaser.GameObjects.GameObject,
    triggerCallback: () => void,
  ): void {
    if (!this.#isPlayerInZone) {
      return;
    }

    const currentTime = this.#scene.time.now;
    const currentPosition = this.#getPlayerPosition(player);
    const hasMoved = this.#hasPlayerMoved(currentPosition);

    if (hasMoved) {
      this.#handlePlayerMoving(currentTime, currentPosition, triggerCallback);
    } else {
      this.#handlePlayerStill(currentTime);
    }
  }

  // ============================================================================
  // Private helpers: Zone management
  // ============================================================================

  #setZoneActive(active: boolean): void {
    this.#zone.setActive(active);
    this.#zone.setVisible(active);
    (this.#zone.body as Phaser.Physics.Arcade.Body).enable = active;
  }

  // ============================================================================
  // Private helpers: Movement pattern tracking
  // ============================================================================

  #getPlayerPosition(player: Phaser.GameObjects.GameObject): Position {
    const sprite = player as Phaser.Physics.Arcade.Sprite;
    return { x: sprite.x, y: sprite.y };
  }

  #hasPlayerMoved(currentPosition: Position): boolean {
    return (
      this.#lastPlayerPosition === null ||
      currentPosition.x !== this.#lastPlayerPosition.x ||
      currentPosition.y !== this.#lastPlayerPosition.y
    );
  }

  #handlePlayerMoving(
    currentTime: number,
    currentPosition: Position,
    triggerCallback: () => void,
  ): void {
    // Accumulate time since last movement update
    if (this.#lastMovementTime > 0) {
      const deltaTime = currentTime - this.#lastMovementTime;
      this.#accumulatedMovementTime += deltaTime;

      if (this.#accumulatedMovementTime >= REQUIRED_MOVEMENT_TIME_MS) {
        this.#resetMovementTracking();
        triggerCallback();
        return;
      }
    }
    // Update tracking state for next frame
    this.#lastMovementTime = currentTime;
    this.#lastPlayerPosition = currentPosition;
  }

  #handlePlayerStill(currentTime: number): void {
    if (
      this.#lastMovementTime > 0 &&
      currentTime - this.#lastMovementTime > MOVEMENT_TIMEOUT_MS
    ) {
      this.#resetMovementTracking();
    }
  }

  #resetMovementTracking(): void {
    this.#accumulatedMovementTime = 0;
    this.#lastMovementTime = 0;
    this.#lastPlayerPosition = null;
  }

  // ============================================================================
  // Private helpers: Debug visualization
  // ============================================================================

  #createDebugRect(): void {
    const center = this.#getCenter(this.#zone);
    const color = this.#isMovementPattern ? 0xff00ff : 0x00ff00; // Magenta for movement, green for regular

    this.#debugRect = this.#scene.add.rectangle(
      center.x,
      center.y,
      this.#zone.width,
      this.#zone.height,
      color,
      DEBUG_COLLISION_ALPHA,
    );
    this.#debugRect.setOrigin(0.5, 0.5);
  }
}

export function conditionsMet(
  dataManager: DataManager,
  scene: Phaser.Scene,
  config?: ConditionsConfig,
): boolean {
  if (!config) {
    return true;
  }

  if (
    config.requiresFlags &&
    !dataManager.hasStoryFlagValues(config.requiresFlags)
  ) {
    return false;
  }

  if (
    config.excludesFlags &&
    !dataManager.hasStoryFlagValuesNot(config.excludesFlags)
  ) {
    return false;
  }

  if (config.requiresRounds) {
    const teamState = scene.registry.get("teamState") as
      | {
          rounds?: Record<string, { locked?: string }>;
        }
      | undefined;
    if (!teamState?.rounds) {
      return false;
    }

    // Check if all required rounds are unlocked
    if (
      config.requiresRounds.some((roundSlug) => {
        const roundState = teamState.rounds?.[roundSlug];
        return roundState?.locked !== "unlocked";
      })
    ) {
      return false;
    }
  }

  if (config.requiresPuzzles) {
    const teamState = scene.registry.get("teamState") as
      | {
          puzzles?: Record<
            string,
            { locked?: string; solved?: boolean; answer?: string }
          >;
        }
      | undefined;
    if (!teamState?.puzzles) {
      return false;
    }

    for (const [puzzleSlug, requiredStates] of Object.entries(
      config.requiresPuzzles,
    )) {
      const puzzleState = teamState.puzzles?.[puzzleSlug];

      // Normalize requiredStates to array
      const requiredStatesArray = Array.isArray(requiredStates)
        ? requiredStates
        : [requiredStates];

      // If puzzle not found, treat it as locked
      if (!puzzleState) {
        // If "locked" is one of the required states, condition is met
        if (requiredStatesArray.includes("locked")) {
          return true;
        }
        // Otherwise, condition is not met
        return false;
      }

      // Check if puzzle matches any of the required states
      const matches = requiredStatesArray.some((requiredState) => {
        if (puzzleState.solved === true || puzzleState.answer !== undefined) {
          return requiredState === "solved" || requiredState === "completed";
        } else if (puzzleState.locked === "unlocked") {
          return requiredState === "unlocked";
        } else if (puzzleState.locked === "unlockable") {
          return requiredState === "unlockable";
        } else if (puzzleState.locked === "locked") {
          return requiredState === "locked";
        }
      });

      if (!matches) {
        return false;
      }
    }
  }

  if (
    config.requiresFrontendFlags &&
    !dataManager.hasFrontendFlagValues(config.requiresFrontendFlags)
  ) {
    return false;
  }

  if (config.excludesFrontendFlags) {
    // Check if any excluded frontend flags are set - if so, conditions are not met
    for (const [flag, value] of Object.entries(config.excludesFrontendFlags)) {
      if (dataManager.hasFrontendFlagValues({ [flag]: value })) {
        return false;
      }
    }
  }

  return true;
}
