import { INSTRUMENT_TOOL_TYPE, LEVEL_NAME } from "../../common/constants";
import type { LevelName } from "../../common/types";
import type { ToolType } from "../../components/inventory/inventory-manager";
import { FISHING_ROD_TOOL_TYPE } from "./fishing-rod";
import { SHOVEL_TOOL_TYPE } from "./shovel";

type ToolAvailabilityOptions = {
  hasLute: boolean;
  hasFishingReel: boolean;
  hasShovel: boolean;
};

const DEFAULT_TOOL_SET: ToolType[] = [
  INSTRUMENT_TOOL_TYPE.LUTE,
  SHOVEL_TOOL_TYPE,
];

const TOOL_OVERRIDES: Partial<Record<LevelName, ToolType[]>> = {
  [LEVEL_NAME.MOUNTAIN]: [INSTRUMENT_TOOL_TYPE.LUTE],
  [LEVEL_NAME.SHORE]: [FISHING_ROD_TOOL_TYPE],
  [LEVEL_NAME.WESTERN]: [SHOVEL_TOOL_TYPE],
  [LEVEL_NAME.CAT_CATSLE]: [],
  [LEVEL_NAME.CEMETERY]: [INSTRUMENT_TOOL_TYPE.LUTE],
  [LEVEL_NAME.HEDGE]: [SHOVEL_TOOL_TYPE],
  [LEVEL_NAME.CITY]: [],
  [LEVEL_NAME.CAMPGROUND]: [SHOVEL_TOOL_TYPE],
  [LEVEL_NAME.HEBI]: [SHOVEL_TOOL_TYPE],
  [LEVEL_NAME.CARDINAL_ISLAND]: [],
};

const cloneToolList = (tools: ToolType[]): ToolType[] => [...tools];

const filterToolsByUnlock = (
  tools: ToolType[],
  options?: ToolAvailabilityOptions,
): ToolType[] => {
  const hasLute = options?.hasLute ?? false;
  const hasFishingReel = options?.hasFishingReel ?? false;
  const hasShovel = options?.hasShovel ?? false;
  const toolList = cloneToolList(tools);
  return toolList.filter((tool) => {
    if (tool === INSTRUMENT_TOOL_TYPE.LUTE && !hasLute) {
      return false;
    }
    if (tool === FISHING_ROD_TOOL_TYPE && !hasFishingReel) {
      return false;
    }
    if (tool === SHOVEL_TOOL_TYPE && !hasShovel) {
      return false;
    }
    return true;
  });
};

export const getToolsForLevel = (
  level?: LevelName,
  options?: ToolAvailabilityOptions,
): ToolType[] => {
  if (level && Object.prototype.hasOwnProperty.call(TOOL_OVERRIDES, level)) {
    return filterToolsByUnlock(TOOL_OVERRIDES[level] ?? [], options);
  }

  return getDefaultTools(options);
};

export const getDefaultTools = (
  options?: ToolAvailabilityOptions,
): ToolType[] => {
  return filterToolsByUnlock(DEFAULT_TOOL_SET, options);
};
