import type { GameObject } from "../common/types";
import { BaseGameObjectComponent } from "./base-game-object";

export class SpeedComponent extends BaseGameObjectComponent {
  #baseSpeed: number;
  #modifier: number;

  constructor(gameObject: GameObject, baseSpeed: number) {
    super(gameObject);
    this.#baseSpeed = baseSpeed;
    this.#modifier = 1.0; // Default modifier (100% speed)
  }

  get speed(): number {
    return this.#baseSpeed * this.#modifier;
  }

  public setSpeedModifier(modifier: number): void {
    this.#modifier = modifier;
  }

  public resetSpeedModifier(): void {
    this.#modifier = 1.0;
  }
}
