import * as Phaser from "phaser";
import { DEATH_MESSAGES, DEATH_REASON } from "../common/constants";
import { getSceneDataManager } from "../common/data-manager";
import { type DeathReason } from "../common/types";
import { SCENE_KEYS } from "./scene-keys";
import { getSceneKeyForLevel } from "./scene-selection";

export class GameOverScene extends Phaser.Scene {
  private deathReason: DeathReason = DEATH_REASON.UNKNOWN as DeathReason;

  constructor() {
    super({ key: SCENE_KEYS.GAME_OVER_SCENE });
  }

  public init(data: { deathReason?: DeathReason }): void {
    this.deathReason =
      data.deathReason || (DEATH_REASON.UNKNOWN as DeathReason);
  }

  public create(): void {
    const { centerX, centerY, width, height } = this.cameras.main;

    // Add black overlay to hide the paused game scene
    this.add.rectangle(centerX, centerY, width, height, 0x000000);

    this.add
      .text(centerX, centerY - 90, "Game Over", {
        fontSize: "48px",
        color: "#ff3333",
        fontFamily: "Arial",
        fontStyle: "bold",
      })
      .setOrigin(0.5);

    // Display death message
    const deathMessage = DEATH_MESSAGES[this.deathReason];
    this.add
      .text(centerX, centerY - 10, deathMessage, {
        fontSize: "24px",
        color: "#ffffff",
        fontFamily: "Arial",
        align: "center",
      })
      .setOrigin(0.5);

    const resumeButton = this.add
      .text(centerX, centerY + 60, "Resume", {
        fontSize: "32px",
        color: "#ffffff",
        backgroundColor: "#4CAF50",
        padding: { x: 30, y: 15 },
        fontFamily: "Arial",
      })
      .setOrigin(0.5)
      .setInteractive({ useHandCursor: true });

    resumeButton.on("pointerdown", () => {
      this.resumeGame();
    });

    resumeButton.on("pointerover", () => {
      resumeButton.setBackgroundColor("#45a049");
    });
    resumeButton.on("pointerout", () => {
      resumeButton.setBackgroundColor("#4CAF50");
    });

    // Add keyboard input for space and enter keys
    this.input.keyboard?.on("keydown-SPACE", () => {
      this.resumeGame();
    });

    this.input.keyboard?.on("keydown-ENTER", () => {
      this.resumeGame();
    });
  }

  private resumeGame(): void {
    // Get the current game scene and fade it in
    const currentLevel = getSceneDataManager(this).data.currentArea.level;
    const targetSceneKey = getSceneKeyForLevel(currentLevel);
    const gameScene = this.scene.get(targetSceneKey);

    if (gameScene) {
      gameScene.cameras.main.fadeIn(250, 0, 0, 0);
      this.scene.resume(targetSceneKey);
    }

    this.scene.stop(SCENE_KEYS.GAME_OVER_SCENE);
  }
}
