import { getRandomInt } from "../mini-game-helpers";
import type { FishingMiniGameDefinition } from "../mini-game-registry";

const ARITHMETIC_OPERATIONS = [
  {
    symbol: "+",
    getOperands: () =>
      [getRandomInt(100, 999), getRandomInt(100, 999)] as const,
    compute: (a: number, b: number) => a + b,
  },
  {
    symbol: "-",
    getOperands: () => {
      const left = getRandomInt(100, 999);
      const right = getRandomInt(100, left);
      return [left, right] as const;
    },
    compute: (a: number, b: number) => a - b,
  },
  {
    symbol: "x",
    getOperands: () => [getRandomInt(2, 25), getRandomInt(2, 25)] as const,
    compute: (a: number, b: number) => a * b,
  },
] as const;

export const ARITHMETIC_MINI_GAME: FishingMiniGameDefinition = {
  id: "arithmetic-practice",
  instructions: "Solve the problem\nto reel it in!",
  inputPlaceholder: "Enter the answer",
  scoring: {
    correctDelta: 6,
    incorrectDelta: 2,
    timerDelayMs: 1000,
    timerProgressDelta: 1,
  },
  getNextQuestion: () => {
    const operation =
      ARITHMETIC_OPERATIONS[
        Math.floor(Math.random() * ARITHMETIC_OPERATIONS.length)
      ];
    const operands = operation.getOperands();
    const question = `${operands[0]} ${operation.symbol} ${operands[1]}`;
    const answer = operation.compute(...operands).toString();

    return {
      id: `arithmetic-${question}`,
      answers: [answer],
      content: {
        type: "text",
        text: question,
        style: {
          fontSize: "48px",
          fontFamily: "monospace",
          letterSpacing: 4,
        },
        maxWidthRatio: 0.8,
      },
    };
  },
};
