import type Phaser from "phaser";

type QuestionPool<T> = {
  session: number;
  remaining: T[];
};

const MINI_GAME_SESSION_STATE = new WeakMap<Phaser.Scene, number>();
const QUESTION_POOL_STATE = new WeakMap<
  Phaser.Scene,
  Map<string, QuestionPool<unknown>>
>();

export function resetMiniGameQuestionPools(scene: Phaser.Scene): void {
  const nextSession = (MINI_GAME_SESSION_STATE.get(scene) ?? 0) + 1;
  MINI_GAME_SESSION_STATE.set(scene, nextSession);
  QUESTION_POOL_STATE.delete(scene);
}

export function drawFromQuestionPool<T>(
  scene: Phaser.Scene,
  poolId: string,
  sourceItems: readonly T[],
): T {
  const session = MINI_GAME_SESSION_STATE.get(scene) ?? 0;
  let poolMap = QUESTION_POOL_STATE.get(scene);
  if (!poolMap) {
    poolMap = new Map<string, QuestionPool<unknown>>();
    QUESTION_POOL_STATE.set(scene, poolMap);
  }

  let pool = poolMap.get(poolId) as QuestionPool<T> | undefined;
  if (pool?.session !== session || pool.remaining.length === 0) {
    pool = {
      session,
      remaining: shuffleArray([...sourceItems]),
    };
  }

  const nextItem = pool.remaining.pop();
  if (!nextItem) {
    throw new Error(`Question pool "${poolId}" is empty.`);
  }

  poolMap.set(poolId, pool);
  return nextItem;
}

export function getRandomInt(min: number, max: number): number {
  const lower = Math.ceil(min);
  const upper = Math.floor(max);
  return Math.floor(Math.random() * (upper - lower + 1)) + lower;
}

export function shuffleArray<T>(items: T[]): T[] {
  for (let i = items.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1));
    [items[i], items[j]] = [items[j], items[i]];
  }
  return items;
}

export function scrambleWord(word: string): string {
  if (word.length < 2) {
    return word;
  }
  const characters = shuffleArray(word.split(""));
  const candidate = characters.join("");
  return candidate === word ? scrambleWord(word) : candidate;
}
