import * as Phaser from "phaser";
import { ASSET_KEYS, CHEST_REWARD_TO_TEXTURE_FRAME } from "../../common/assets";
import { DIRECTION } from "../../common/constants";
import { getSceneDataManager } from "../../common/data-manager";
import { CUSTOM_EVENTS, EVENT_BUS } from "../../common/event-bus";
import { logger } from "../../common/logger";
import { type Direction } from "../../common/types";
import { type InputComponent } from "../../components/input-component";
import { type ToolComponent } from "../../components/tool-component";
import {
  getMiniGameIdForFishingSpot,
  type FishingMiniGameId,
} from "../../scenes/fishing-mini-game/mini-game-registry";
import { SCENE_KEYS } from "../../scenes/scene-keys";
import { type GameEventChoice } from "../npcs/npc-types";
import { BaseTool, type UseToolAnimationConfig } from "./base-tool";

export const FISHING_ROD_TOOL_TYPE = "fishing_rod" as const;

type FishingState =
  | "idle"
  | "casting"
  | "waiting"
  | "biting"
  | "caught"
  | "not_caught";

const ANIMATION_KEYS = {
  CAST: "CAST",
  WAIT: "WAIT",
  BITE: "FISH_BITE",
  CAUGHT: "FISH_CAUGHT",
};

// Timing constants (in milliseconds)
const TIMING = {
  WAIT_TIMEOUT: 2000,
  BITE_DELAY_MIN: 500,
  BITE_DELAY_MAX: 1500,
  BITE_TIMEOUT: 5000,
  FISH_Y_OFFSET: 24,
} as const;

/* Fishing animations are defined in base-preload-scene */

export class FishingRod extends BaseTool {
  public readonly toolType = FISHING_ROD_TOOL_TYPE;

  private _fishingUpDown: Phaser.GameObjects.Sprite;
  private _fishingRightLeft: Phaser.GameObjects.Sprite;

  public static readonly OFFSETS = {
    [DIRECTION.UP]: { x: -16, y: -80 },
    [DIRECTION.DOWN]: { x: -16, y: 48 },
    [DIRECTION.LEFT]: { x: -80, y: -8 },
    [DIRECTION.RIGHT]: { x: 48, y: -8 },
  } as const;

  #state: FishingState = "idle";
  #waitTimer?: Phaser.Time.TimerEvent;
  #biteTimer?: Phaser.Time.TimerEvent;
  #caughtTimer?: Phaser.Time.TimerEvent;
  #biteTimeout?: Phaser.Time.TimerEvent;
  #miniGameCompleteHandler?: (data: { success: boolean }) => void;
  #currentFishingSpotStoryFlag?: string;
  #caughtFishSprite?: Phaser.GameObjects.Image;
  #direction?: Direction | undefined;
  #npcDialogActive = false;

  constructor(
    sprite: Phaser.GameObjects.Sprite,
    toolComponent: ToolComponent,
    animationConfig: UseToolAnimationConfig,
  ) {
    super(sprite, toolComponent, animationConfig);

    this._fishingRightLeft = sprite.scene.add
      .sprite(0, 0, ASSET_KEYS.FISHING_RIGHT_LEFT)
      .setVisible(false);
    this._fishingUpDown = sprite.scene.add
      .sprite(0, 0, ASSET_KEYS.FISHING_UP_DOWN)
      .setVisible(false);
  }

  public use(direction: Direction): void {
    if (this._inUse) {
      return; // Already in use
    }

    this.#direction = direction;

    this._toolComponent.body.setSize(24, 24);

    this._toolComponent.body.position.set(
      this._sprite.x + FishingRod.OFFSETS[direction].x,
      this._sprite.y + FishingRod.OFFSETS[direction].y,
    );
    this._toolComponent.body.enable = true;

    // Start casting
    this.#state = "casting";
    this._inUse = true;

    this.#playAnimation(ANIMATION_KEYS.CAST, direction, 0, () => {
      this.#startWaiting(direction);
    });
  }

  #startWaiting(direction: Direction): void {
    this.#state = "waiting";
    this.#playAnimation(ANIMATION_KEYS.WAIT, direction, -1);

    // Set up timeout: if no fishing spot detected, show message
    this.#waitTimer = this._sprite.scene.time.delayedCall(
      TIMING.WAIT_TIMEOUT,
      () => {
        if (this.#state === "waiting") {
          this.#noFishingSpotFound();
        }
      },
    );
  }

  #noFishingSpotFound(): void {
    if (this.#npcDialogActive) {
      return;
    }

    this.#clearTimers();
    this.#complete();

    EVENT_BUS.emit(CUSTOM_EVENTS.DIALOG_START as string, {
      messages: ["There's nothing to fish here."],
      choices: [],
    });
  }

  /**
   * Called when overlap with fishing spot is detected during waiting state
   * Cancels the wait timer and starts the bite sequence
   */
  public startBiteSequence(fishingSpotStoryFlag?: string): void {
    if (!this.#isState("waiting") || this.#biteTimer) {
      return; // Not in waiting state or already starting bite sequence
    }

    this.#currentFishingSpotStoryFlag = fishingSpotStoryFlag;

    // Cancel wait timer
    if (this.#waitTimer) {
      this.#waitTimer.destroy();
      this.#waitTimer = undefined;
    }

    // Random delay before fish bites
    const biteDelay = Phaser.Math.Between(
      TIMING.BITE_DELAY_MIN,
      TIMING.BITE_DELAY_MAX,
    );
    this.#biteTimer = this._sprite.scene.time.delayedCall(biteDelay, () => {
      this.#startBiting();
    });
  }

  #startBiting(): void {
    if (!this.#isState("waiting")) {
      return;
    }

    this.#state = "biting";
    this.#playAnimation(ANIMATION_KEYS.BITE, this.#direction ?? "DOWN", -1);

    // Set up mini-game completion handler
    this.#setupMiniGameHandler();

    void this.#reelIn();
  }

  #setupMiniGameHandler(): void {
    this.#miniGameCompleteHandler = (data: {
      success: boolean;
      message?: string;
    }) => {
      if (!this.#isState("biting")) {
        return;
      }

      this.#cleanupMiniGameHandler();

      if (data.success) {
        this.#fishCaught();
      } else {
        this.#fishEscaped();
      }
    };

    EVENT_BUS.on(
      CUSTOM_EVENTS.FISHING_MINI_GAME_COMPLETE,
      this.#miniGameCompleteHandler,
    );
  }

  #cleanupMiniGameHandler(): void {
    if (this.#miniGameCompleteHandler) {
      EVENT_BUS.off(
        CUSTOM_EVENTS.FISHING_MINI_GAME_COMPLETE,
        this.#miniGameCompleteHandler,
      );
      this.#miniGameCompleteHandler = undefined;
    }
  }

  public handleInput?(controls: InputComponent): void {
    const usePressed = controls.isUseJustDown;

    if (this.#isState("waiting")) {
      if (usePressed) {
        this.#reelInFromWaiting();
      }
      return;
    }
  }

  #reelInFromWaiting(): void {
    if (!this.#isState("waiting")) {
      return;
    }

    this.#clearTimers();
    this.#complete();
  }

  async #reelIn(): Promise<void> {
    if (!this.#isState("biting")) {
      return;
    }

    const hasCompletedCurrentSpot = this.#hasCompletedCurrentFishingSpot();
    if (hasCompletedCurrentSpot) {
      const shouldReplay = await this.#promptReplayMiniGame();
      if (!shouldReplay) {
        this.#fishEscaped();
        return;
      }
    }

    // Clear bite timers (biteTimeout would interfere with mini-game)
    this.#clearBiteTimers();

    // Launch mini-game scene
    const miniGameId = getMiniGameIdForFishingSpot(
      this.#currentFishingSpotStoryFlag ?? "",
    );
    const startData: {
      storyFlag?: string;
      miniGameId?: FishingMiniGameId;
      isReplay?: boolean;
    } = {
      storyFlag: this.#currentFishingSpotStoryFlag,
      miniGameId,
      isReplay: hasCompletedCurrentSpot || undefined,
    };
    EVENT_BUS.emit(CUSTOM_EVENTS.START_FISHING_MINI_GAME, startData);

    this._sprite.scene.scene.launch(
      SCENE_KEYS.FISHING_MINI_GAME_SCENE,
      startData,
    );
  }

  #hasCompletedCurrentFishingSpot(): boolean {
    if (!this.#currentFishingSpotStoryFlag) {
      return false;
    }

    const dataManager = getSceneDataManager(this._sprite.scene);
    return (
      dataManager.getFlagValue(this.#currentFishingSpotStoryFlag) ===
      "completed"
    );
  }

  async #promptReplayMiniGame(): Promise<boolean> {
    return new Promise((resolve) => {
      const choices: GameEventChoice[] = [
        { text: "Yes, play again" },
        { text: "No thanks" },
      ];

      const handleChoiceSelect = (data: {
        choice: GameEventChoice;
        choiceIndex: number;
      }) => {
        if (!choices.includes(data.choice)) {
          return;
        }
        cleanup();
        resolve(data.choice === choices[0]);
      };

      const handleDialogComplete = () => {
        cleanup();
        resolve(false);
      };

      const cleanup = () => {
        EVENT_BUS.off(CUSTOM_EVENTS.DIALOG_CHOICE_SELECT, handleChoiceSelect);
        EVENT_BUS.off(CUSTOM_EVENTS.DIALOG_COMPLETE, handleDialogComplete);
      };

      EVENT_BUS.on(CUSTOM_EVENTS.DIALOG_CHOICE_SELECT, handleChoiceSelect);
      EVENT_BUS.on(CUSTOM_EVENTS.DIALOG_COMPLETE, handleDialogComplete);

      EVENT_BUS.emit(CUSTOM_EVENTS.DIALOG_START as string, {
        messages: [
          "You already hooked this fish's puzzle. Want to play again?",
        ],
        choices,
      });
    });
  }

  #clearBiteTimers(): void {
    if (this.#biteTimer) {
      this.#biteTimer.destroy();
      this.#biteTimer = undefined;
    }
    if (this.#biteTimeout) {
      this.#biteTimeout.destroy();
      this.#biteTimeout = undefined;
    }
  }

  #fishCaught(): void {
    logger.info("Fishing rod: Fish caught");
    this.#state = "caught";

    // Set story flag to completed if one is associated with this fishing spot
    if (this.#currentFishingSpotStoryFlag) {
      const dataManager = getSceneDataManager(this._sprite.scene);
      dataManager.setFlagToCompleted(this.#currentFishingSpotStoryFlag);
      dataManager.completeInteraction(this.#currentFishingSpotStoryFlag);
      logger.info(
        `Fishing rod: Set story flag ${this.#currentFishingSpotStoryFlag} to completed`,
      );
    }

    this.#caughtTimer = this._sprite.scene.time.delayedCall(400, () => {
      this.#showCaughtFish();
    });

    this.#playAnimation(ANIMATION_KEYS.CAUGHT, this.#direction ?? "DOWN", 0);
  }

  #showCaughtFish(): void {
    this.#cleanupCaughtFish();

    this.#caughtFishSprite = this._sprite.scene.add.image(
      this._sprite.x,
      this._sprite.y - TIMING.FISH_Y_OFFSET,
      ASSET_KEYS.CHEST_REWARDS,
      CHEST_REWARD_TO_TEXTURE_FRAME.PUZZLE,
    );
    this.#caughtFishSprite.setOrigin(0.5, 0.5);
    this.#caughtFishSprite.setDepth(this._sprite.depth + 10);

    // Remove puzzle icon when dialog closes
    EVENT_BUS.once(CUSTOM_EVENTS.DIALOG_COMPLETE, () => {
      this.#cleanupCaughtFish();
      this.#complete();
    });
  }

  #cleanupCaughtFish(): void {
    if (this.#caughtFishSprite) {
      this.#caughtFishSprite.destroy();
      this.#caughtFishSprite = undefined;
    }
  }

  #fishEscaped(): void {
    logger.info("Fishing rod: Fish escaped");
    if (!this.#isState("biting") && !this.#isState("waiting")) {
      return;
    }

    this.#state = "not_caught";
    this.#clearTimers();
    this.#stopMiniGameScene();
    this.#complete();
  }

  public interruptForNpcInteraction(): void {
    if (!this._inUse) {
      return;
    }
    this.#clearTimers();
    this.#stopMiniGameScene();
    this.#cleanupCaughtFish();
    this.#complete();
  }

  #stopMiniGameScene(): void {
    if (this._sprite.scene.scene.isActive(SCENE_KEYS.FISHING_MINI_GAME_SCENE)) {
      this._sprite.scene.scene.stop(SCENE_KEYS.FISHING_MINI_GAME_SCENE);
    }
  }

  #complete(): void {
    this.#state = "idle";
    this._inUse = false;
    this._toolComponent.body.enable = false;
    this.#currentFishingSpotStoryFlag = undefined;
    this._fishingUpDown.setVisible(false);
    this._fishingRightLeft.setVisible(false);
    this.#direction = undefined;
    this.#npcDialogActive = false;
  }

  #clearWaitTimer(): void {
    if (this.#waitTimer) {
      this.#waitTimer.destroy();
      this.#waitTimer = undefined;
    }
  }

  #clearTimers(): void {
    this.#clearWaitTimer();
    if (this.#caughtTimer) {
      this.#caughtTimer.destroy();
      this.#caughtTimer = undefined;
    }
    this.#clearBiteTimers();
    this.#cleanupMiniGameHandler();
  }

  #isState(state: FishingState): boolean {
    return this.#state === state;
  }

  #playAnimation(
    key: string,
    direction: Direction,
    repeat: number,
    onComplete?: () => void,
  ): void {
    const playerFullKey = `PLAYER_${key}_${direction}`;
    if (direction === "LEFT") {
      this._sprite.setFlipX(true);
    }

    this._sprite.play({ key: playerFullKey, repeat }, true);
    if (onComplete) {
      this._sprite.once(
        Phaser.Animations.Events.ANIMATION_COMPLETE_KEY + playerFullKey,
        onComplete,
      );
    }

    const fishingRodFullKey = `FISHING_ROD_${key}_${direction}`;
    // Annoyingly, object coordinates in Phaser are the center of the object, but the spritesheet expects one
    // of the corners to align (depends on the direction).
    if (direction === "DOWN") {
      this._fishingUpDown.setPosition(
        this._sprite.x - this._sprite.width / 2 + this._fishingUpDown.width / 2,
        this._sprite.y -
          this._sprite.height / 2 +
          this._fishingUpDown.height / 2,
      );
    } else if (direction === "UP") {
      this._fishingUpDown.setPosition(
        this._sprite.x - this._sprite.width / 2 + this._fishingUpDown.width / 2,
        this._sprite.y +
          this._sprite.height / 2 -
          this._fishingUpDown.height / 2,
      );
    } else if (direction === "RIGHT") {
      this._fishingRightLeft.setPosition(
        this._sprite.x -
          this._sprite.width / 2 +
          this._fishingRightLeft.width / 2,
        this._sprite.y -
          this._sprite.height / 2 +
          this._fishingRightLeft.height / 2,
      );
    } else if (direction === "LEFT") {
      this._fishingRightLeft.setPosition(
        this._sprite.x +
          this._sprite.width / 2 -
          this._fishingRightLeft.width / 2,
        this._sprite.y -
          this._sprite.height / 2 +
          this._fishingRightLeft.height / 2,
      );
    } else {
      throw new Error("invalid direction");
    }

    if (direction === "UP" || direction === "DOWN") {
      this._fishingUpDown.setVisible(true).setToTop();
      this._fishingUpDown.play({ key: fishingRodFullKey, repeat }, true);
    } else if (direction === "LEFT" || direction === "RIGHT") {
      this._fishingRightLeft.setFlipX(direction === "LEFT");
      this._fishingRightLeft.setVisible(true).setToTop();
      this._fishingRightLeft.play({ key: fishingRodFullKey, repeat }, true);
    } else {
      throw new Error("invalid direction");
    }
  }

  public override reset(): void {
    this.#clearTimers();
    this.#complete();
    this.#state = "idle";
    super.reset();
  }

  public setNpcDialogLock(active: boolean): void {
    this.#npcDialogActive = active;
    if (active) {
      // Prevent the "no fishing spot" timeout from completing while dialog is open
      this.#clearWaitTimer();
      this._toolComponent.body.enable = false;
    }
  }
}
