import React from "react";

/**
 * Shared structure for PhaserGame component.
 * Used by both the interactive PhaserGame and the SSR placeholder.
 */
export function PhaserGameStructure({
  wrapperRef,
  onFullscreenClick,
  isFullscreen = false,
}: {
  wrapperRef?: React.RefObject<HTMLDivElement>;
  onFullscreenClick?: () => void;
  isFullscreen?: boolean;
}) {
  return (
    <div ref={wrapperRef} className="absolute inset-0 w-full h-full bg-black">
      <div id="game-container" className="w-full h-full"></div>
      <button
        onClick={onFullscreenClick}
        className="absolute top-2 right-2 z-5 p-2 bg-black/50 hover:bg-black/70 rounded-md text-white transition-colors"
        title={isFullscreen ? "Exit Fullscreen" : "Enter Fullscreen"}
        aria-label={isFullscreen ? "Exit Fullscreen" : "Enter Fullscreen"}
      >
        {isFullscreen ? (
          <svg
            xmlns="http://www.w3.org/2000/svg"
            width="24"
            height="24"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            <path d="M8 3v3a2 2 0 0 1-2 2H3" />
            <path d="M21 8h-3a2 2 0 0 1-2-2V3" />
            <path d="M3 16h3a2 2 0 0 1 2 2v3" />
            <path d="M16 21v-3a2 2 0 0 1 2-2h3" />
          </svg>
        ) : (
          <svg
            xmlns="http://www.w3.org/2000/svg"
            width="24"
            height="24"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            <path d="M8 3H5a2 2 0 0 0-2 2v3" />
            <path d="M21 8V5a2 2 0 0 0-2-2h-3" />
            <path d="M3 16v3a2 2 0 0 0 2 2h3" />
            <path d="M16 21h3a2 2 0 0 0 2-2v-3" />
          </svg>
        )}
      </button>
    </div>
  );
}

/**
 * Placeholder component that matches the initial structure of PhaserGame.
 * Used for server-side rendering to prevent hydration mismatches.
 */
export function PhaserGamePlaceholder() {
  return <PhaserGameStructure />;
}
