import { type CharacterObject } from "../../../entities/common/character-object";
import { ToolComponent } from "../../tool-component";
import { BaseCharacterState } from "./base-character-state";
import { CHARACTER_STATES } from "./character-states";

export class UseItemState extends BaseCharacterState {
  constructor(gameObject: CharacterObject) {
    super(CHARACTER_STATES.USE_ITEM_STATE, gameObject);
  }

  public onEnter(): void {
    this._resetVelocity();

    const toolComponent = ToolComponent.getComponent<ToolComponent>(
      this._gameObject,
    );
    if (toolComponent?.tool === undefined) {
      this._stateMachine.setState(CHARACTER_STATES.IDLE_STATE);
      return;
    }

    const tool = toolComponent.tool;
    tool.use(this._gameObject.direction);
  }

  public onUpdate(): void {
    const toolComponent = ToolComponent.getComponent<ToolComponent>(
      this._gameObject,
    );
    if (toolComponent?.tool === undefined) {
      this._stateMachine.setState(CHARACTER_STATES.IDLE_STATE);
      return;
    }
    const tool = toolComponent.tool;

    // Handle input for tools that support it
    if (tool.handleInput) {
      tool.handleInput(this._gameObject.controls);
    }

    if (tool.inUse) {
      return;
    }
    this._stateMachine.setState(CHARACTER_STATES.IDLE_STATE);
  }
}
