import type { GameObject } from "../common/types";
import { BaseGameObjectComponent } from "./base-game-object";

export class InvulnerableComponent extends BaseGameObjectComponent {
  #alwaysInvulnerable: boolean;
  #invulnerable: boolean;
  #invulnerableDuration: number;

  constructor(
    gameObject: GameObject,
    invulnerable = false,
    invulnerableDuration = 0,
  ) {
    super(gameObject);
    this.#invulnerable = invulnerable;
    this.#alwaysInvulnerable = invulnerable;
    this.#invulnerableDuration = invulnerableDuration;
  }

  get invulnerable(): boolean {
    return this.#invulnerable;
  }
  set invulnerable(value: boolean) {
    this.#invulnerable = value;
  }

  get invulnerableDuration(): number {
    return this.#invulnerableDuration;
  }

  public resetInvulnerable(): void {
    this.#invulnerable = this.#alwaysInvulnerable;
  }
}
