import { DIRECTION } from "../../../common/constants";
import type { Direction } from "../../../common/types";
import { isArcadePhysicsBody } from "../../../common/utils";
import { type CharacterObject } from "../../../entities/common/character-object";
import { BaseMoveState } from "./base-move-state";
import { CHARACTER_STATES } from "./character-states";

export class IceStairsMoveState extends BaseMoveState {
  #lastMovementDirection: Direction | null = null;
  #slideSpeedUp: number;
  #slideSpeedDown = 150; // Faster slide downhill

  constructor(gameObject: CharacterObject) {
    super(CHARACTER_STATES.ICE_STAIRS_MOVE_STATE, gameObject, "WALK");
    this.#slideSpeedUp = this._gameObject.speed; // Match normal walk speed
  }

  public onEnter(): void {
    this.#handleMovementMode();
  }

  public onUpdate(): void {
    if (this.#hasLeftIceStairs()) {
      if (this._gameObject.isOnIce()) {
        this._stateMachine.setState(CHARACTER_STATES.ICE_MOVE_STATE);
      } else {
        this._stateMachine.setState(CHARACTER_STATES.MOVE_STATE);
      }
      return;
    }

    this.#handleMovementMode();
  }

  #handleMovementMode(): void {
    const controls = this._gameObject.controls;
    const movingUp = controls.isUpDown && !controls.isMovementLocked;
    const horizontalInput =
      !controls.isMovementLocked && controls.isLeftDown
        ? -1
        : !controls.isMovementLocked && controls.isRightDown
          ? 1
          : 0;

    if (movingUp) {
      this.#walkUp(horizontalInput);
      return;
    }

    this.#slideDown(horizontalInput);
  }

  #walkUp(horizontalInput: -1 | 0 | 1 = 0): void {
    this.#lastMovementDirection = DIRECTION.UP;
    if (!isArcadePhysicsBody(this._gameObject.body)) {
      return;
    }
    if (horizontalInput < 0) {
      this._gameObject.direction = DIRECTION.LEFT;
    } else if (horizontalInput > 0) {
      this._gameObject.direction = DIRECTION.RIGHT;
    } else {
      this._gameObject.direction = DIRECTION.UP;
    }
    this._gameObject.animationComponent.playAnimation(
      `WALK_${this._gameObject.direction}`,
    );
    const horizontalSpeed = this._gameObject.speed;
    this._gameObject.body.velocity.x = horizontalInput * horizontalSpeed;
    this._gameObject.body.velocity.y = -this.#slideSpeedUp;
  }

  #slideDown(horizontalInput: -1 | 0 | 1 = 0): void {
    this.#lastMovementDirection = DIRECTION.DOWN;
    if (!isArcadePhysicsBody(this._gameObject.body)) {
      return;
    }

    if (this._gameObject.anims?.isPlaying) {
      this._gameObject.anims.pause(); // freeze current frame for sliding
    }
    const horizontalSpeed = this._gameObject.speed;
    this._gameObject.body.velocity.x = horizontalInput * horizontalSpeed;
    this._gameObject.body.velocity.y = this.#slideSpeedDown;

    if (horizontalInput < 0) {
      this._gameObject.direction = DIRECTION.LEFT;
    } else if (horizontalInput > 0) {
      this._gameObject.direction = DIRECTION.RIGHT;
    } else {
      this._gameObject.direction = DIRECTION.DOWN;
    }

    if (this.#hasHitObstacle()) {
      this._resetVelocity();
      this._stateMachine.setState(CHARACTER_STATES.IDLE_STATE);
    }
  }

  #hasLeftIceStairs(): boolean {
    return !this._gameObject.isOnIceStairs();
  }

  #hasHitObstacle(): boolean {
    if (!isArcadePhysicsBody(this._gameObject.body)) {
      return false;
    }

    const velocity = this._gameObject.body.velocity;
    const expectedVelocity =
      this.#lastMovementDirection === DIRECTION.UP
        ? this.#slideSpeedUp
        : this.#slideSpeedDown;
    const lastDir = this.#lastMovementDirection;

    if (lastDir === DIRECTION.UP) {
      return velocity.y > -expectedVelocity * 0.5;
    }
    return velocity.y < expectedVelocity * 0.5;
  }

  protected normalizeVelocity(): void {
    // Override to prevent normal velocity normalization on ice stairs
  }
}
