/**
 * Base input component that provides input state management and control locking.
 *
 * Provides two levels of input control:
 * - isMovementLocked: Flag used by other systems to indicate movement should be locked
 * - movementControlsLocked: Locks keyboard input but allows programmatic input via setters
 */
export class InputComponent {
  #up: boolean;
  #down: boolean;
  #left: boolean;
  #right: boolean;
  #actionKey: boolean;
  #enterKey: boolean;
  #useKey: boolean;
  #flagKey: boolean;
  #isMovementLocked: boolean;
  protected _movementControlsLocked: boolean;
  protected _infoKeyLocked: boolean;

  constructor() {
    this.#up = false;
    this.#down = false;
    this.#left = false;
    this.#right = false;
    this.#actionKey = false;
    this.#enterKey = false;
    this.#useKey = false;
    this.#flagKey = false;
    this.#isMovementLocked = false;
    this._movementControlsLocked = false;
    this._infoKeyLocked = false;
  }
  set isMovementLocked(value: boolean) {
    this.#isMovementLocked = value;
  }
  get isMovementLocked(): boolean {
    return this.#isMovementLocked;
  }
  set movementControlsLocked(value: boolean) {
    this._movementControlsLocked = value;
  }
  get movementControlsLocked(): boolean {
    return this._movementControlsLocked;
  }
  set infoKeyLocked(value: boolean) {
    this._infoKeyLocked = value;
  }
  get infoKeyLocked(): boolean {
    return this._infoKeyLocked;
  }
  set isUpDown(value: boolean) {
    this.#up = value;
  }
  get isUpDown(): boolean {
    return this.#up;
  }
  get isUpJustDown(): boolean {
    return this.#up;
  }
  set isDownDown(value: boolean) {
    this.#down = value;
  }
  get isDownDown(): boolean {
    return this.#down;
  }
  get isDownJustDown(): boolean {
    return this.#down;
  }
  set isLeftDown(value: boolean) {
    this.#left = value;
  }
  get isLeftDown(): boolean {
    return this.#left;
  }
  get isLeftJustDown(): boolean {
    return this.#left;
  }
  set isRightDown(value: boolean) {
    this.#right = value;
  }
  get isRightDown(): boolean {
    return this.#right;
  }
  get isRightJustDown(): boolean {
    return this.#right;
  }
  set isActionKeyJustDown(value: boolean) {
    this.#actionKey = value;
  }
  get isActionKeyJustDown(): boolean {
    return this.#actionKey;
  }
  set isEnterKeyJustDown(value: boolean) {
    this.#enterKey = value;
  }
  get isEnterKeyJustDown(): boolean {
    return this.#enterKey;
  }
  set isUseJustDown(value: boolean) {
    this.#useKey = value;
  }
  get isUseJustDown(): boolean {
    return this.#useKey;
  }
  set isFlagKeyJustDown(value: boolean) {
    this.#flagKey = value;
  }
  get isFlagKeyJustDown(): boolean {
    return this.#flagKey;
  }
  public reset(): void {
    this.#up = false;
    this.#down = false;
    this.#left = false;
    this.#right = false;
    this.#actionKey = false;
    this.#enterKey = false;
    this.#useKey = false;
    this.#flagKey = false;
  }
}
