    if (config.characterColor) {
      this.setCharacterColor(config.characterColor);
    }

    // Add components
    this.#proximityComponent = new ProximityDetectionComponent(this);
    new HeldObjectComponent(this);
    this.#toolComponent = new ToolComponent(this);
    this.#hasLuteUnlocked = this.#isLuteUnlocked();
    this.#hasFishingReelUnlocked = this.#isFishingReelUnlocked();
    this.#hasShovelUnlocked = this.#isShovelUnlocked();
    this.#configureAvailableTools();

    // Add states
    this._stateMachine.addState(new IdleState(this));
    this._stateMachine.addState(new MoveState(this));
    this._stateMachine.addState(new IceMoveState(this));
    this._stateMachine.addState(new IceStairsMoveState(this));
    this._stateMachine.addState(new RockJumpState(this));
    this._stateMachine.addState(
      new HurtState(this, PLAYER_HURT_PUSHBACK_SPEED, () => {
        flash(this);
      }),
    );
    this._stateMachine.addState(new DeliverItemState(this));
    this._stateMachine.addState(new DeathState(this));
    this._stateMachine.addState(new DialogState(this));
    this._stateMachine.addState(new GiveItemState(this));
    this._stateMachine.addState(new IdleDivingState(this));
    this._stateMachine.addState(new IdleHoldingState(this));
    this._stateMachine.addState(new LiftState(this));
    this._stateMachine.addState(new MoveDivingState(this));
    this._stateMachine.addState(new MoveHoldingState(this));
    this._stateMachine.addState(new OpenChestState(this));
    this._stateMachine.addState(new RacingIdleState(this));
    this._stateMachine.addState(new RacingMoveState(this));
    this._stateMachine.addState(new ReceiveItemState(this));
    this._stateMachine.addState(new ThrowState(this));
    this._stateMachine.addState(new UseItemState(this));

