import { type CharacterObject } from "../../../entities/common/character-object";
import { BaseCharacterState } from "./base-character-state";
import { CHARACTER_STATES } from "./character-states";

export class RacingIdleState extends BaseCharacterState {
  constructor(gameObject: CharacterObject) {
    super(CHARACTER_STATES.RACING_IDLE_STATE, gameObject);
  }

  public onEnter(): void {
    this._resetVelocity();
    // Set racing animation based on current direction (uses same frames as move)
    this._gameObject.animationComponent.playAnimation(
      `RACING_MOVE_${this._gameObject.direction}`,
    );
  }

  public onUpdate(): void {
    // Racing idle state is managed externally (countdown)
    // Transition to racing move state happens from the scene
  }
}
