import type * as Phaser from "phaser";
import { ASSET_KEYS } from "../../common/assets";
import { DIRECTION } from "../../common/constants";
import { getSceneDataManager } from "../../common/data-manager";
import { DIGGABLE_ROOMS } from "../../common/tiled/constants";
import type { Direction } from "../../common/types";
import { type BaseGameScene } from "../../scenes/base-game-scene";
import { BaseTool } from "./base-tool";

export const SHOVEL_TOOL_TYPE = "shovel" as const;

type DigTarget = {
  tileX: number;
  tileY: number;
  gridX: number;
  gridY: number;
  holeKey: string;
  worldX: number;
  worldY: number;
  canCreateHole: boolean;
};

export class Shovel extends BaseTool {
  public readonly toolType = SHOVEL_TOOL_TYPE;

  public static readonly SHOVEL_SIZE = 4;
  private _currentDigTarget?: DigTarget;

  public static readonly OFFSETS = {
    [DIRECTION.UP]: { x: 0, y: -12 },
    [DIRECTION.DOWN]: { x: 0, y: 16 },
    [DIRECTION.LEFT]: { x: -20, y: 4 },
    [DIRECTION.RIGHT]: { x: 16, y: 4 },
  } as const;
  public use(direction: Direction): void {
    this._toolComponent.body.setSize(Shovel.SHOVEL_SIZE, Shovel.SHOVEL_SIZE);
    const offset = Shovel.OFFSETS[direction];
    this._toolComponent.body.position.set(
      this._sprite.x + offset.x,
      this._sprite.y + offset.y,
    );

    const scene = this._sprite.scene as BaseGameScene;
    this._currentDigTarget = undefined;
    const digTarget = this.#getDigTarget(scene);

    if (!digTarget) {
      this.useTool(direction);
      return;
    }

    this._currentDigTarget = digTarget;

    if (!digTarget.canCreateHole) {
      this.useTool(direction);
      return;
    }

    this._sprite.scene.sound.play(ASSET_KEYS.DIG_SFX);
    const digHole = this._sprite.scene.add.image(
      digTarget.gridX,
      digTarget.gridY,
      ASSET_KEYS.DIG_HOLE,
    );
    digHole.setOrigin(0, 0);
    digHole.setDepth(this._sprite.depth - 1);
    scene.dugHoles.add(digTarget.holeKey);
    this.useTool(direction);
  }

  public get currentDigTarget(): DigTarget | undefined {
    return this._currentDigTarget;
  }

  #getDigTarget(scene: BaseGameScene): DigTarget | null {
    const tilemap = scene.tilemap as Phaser.Tilemaps.Tilemap;
    const level = getSceneDataManager(scene).data.currentArea.level;

    if (!DIGGABLE_ROOMS[level]) {
      return null;
    }

    const diggableRooms = DIGGABLE_ROOMS[level];
    const roomNumber = scene.currentRoomId;
    if (!diggableRooms.includes(roomNumber)) {
      return null;
    }

    // Use the tool body position (which includes the offset) for consistency with minesweepers
    const toolBodyX = this._toolComponent.body.x;
    const toolBodyY = this._toolComponent.body.y;
    const toolCenterX = toolBodyX + this._toolComponent.body.width / 2;
    const toolCenterY = toolBodyY + this._toolComponent.body.height / 2;
    const tileX = Math.floor(toolCenterX / tilemap.tileWidth);
    const tileY = Math.floor(toolCenterY / tilemap.tileHeight);
    const gridX = tileX * tilemap.tileWidth;
    const gridY = tileY * tilemap.tileHeight;
    if (
      tileY <= 0 ||
      tileX <= 0 ||
      tileY >= tilemap.height ||
      tileX >= tilemap.width
    ) {
      return null;
    }

    const holeKey = `${gridX},${gridY}`;
    const holeAlreadyDug = scene.dugHoles.has(holeKey);

    const hasObstacle = tilemap.layers.some(
      (layerData: Phaser.Tilemaps.LayerData) => {
        if (layerData.name.toLowerCase().includes("collision")) {
          const tile = layerData.data[tileY][tileX];
          const globalId = tile.index;
          if (globalId === -1) {
            return false;
          }

          let tileset = null;
          for (let i = tilemap.tilesets.length - 1; i >= 0; i--) {
            if (globalId >= tilemap.tilesets[i].firstgid) {
              tileset = tilemap.tilesets[i];
              break;
            }
          }

          if (!tileset) {
            console.log("No tileset found for global ID:", globalId);
            return false;
          }

          const localId = globalId - tileset.firstgid;
          // Treat full, reserved, and partial collision tiles (0–9) as obstacles
          if (localId >= 0 && localId <= 9) {
            return true;
          }
        }

        return false;
      },
    );

    if (hasObstacle) {
      return null;
    }

    return {
      tileX,
      tileY,
      gridX,
      gridY,
      holeKey,
      worldX: gridX + tilemap.tileWidth / 2,
      worldY: gridY + tilemap.tileHeight / 2,
      canCreateHole: !holeAlreadyDug && !hasObstacle,
    };
  }

  public override reset(): void {
    this._currentDigTarget = undefined;
    super.reset();
  }
}
