import * as Phaser from "phaser";
import { ASSET_KEYS, BUTTON_FRAME_KEYS } from "../../common/assets";
import { INTERACTIVE_OBJECT_TYPE } from "../../common/constants";
import { FLOOR_TOGGLE_COLOR } from "../../common/tiled/constants";
import type {
  FloorToggleColor,
  TiledFloorToggleObject,
} from "../../common/tiled/types";
import type { CustomObject } from "../../common/types";
import { assertNeverCalled } from "../../common/utils";
import { InteractiveObjectComponent } from "../../components/interactive-object-component";

export class FloorToggle
  extends Phaser.Physics.Arcade.Image
  implements CustomObject
{
  #color: FloorToggleColor;

  constructor(scene: Phaser.Scene, config: TiledFloorToggleObject) {
    super(
      scene,
      config.x,
      config.y,
      ASSET_KEYS.DUNGEON_OBJECTS,
      BUTTON_FRAME_KEYS.PLATE_SWITCH,
    );

    scene.add.existing(this);
    scene.physics.add.existing(this);
    this.setOrigin(0, 0).setImmovable(true);
    this.#color = config.color;
    this.#setColor(this.#color);

    this.disableObject();

    new InteractiveObjectComponent(this, INTERACTIVE_OBJECT_TYPE.AUTO, () => {
      this.trigger();
      return true;
    });
  }

  public trigger(): void {
    switch (this.#color) {
      case FLOOR_TOGGLE_COLOR.RED:
        this.#color = FLOOR_TOGGLE_COLOR.GREEN;
        break;
      case FLOOR_TOGGLE_COLOR.GREEN:
        this.#color = FLOOR_TOGGLE_COLOR.BLUE;
        break;
      case FLOOR_TOGGLE_COLOR.BLUE:
        this.#color = FLOOR_TOGGLE_COLOR.YELLOW;
        break;
      case FLOOR_TOGGLE_COLOR.YELLOW:
        this.#color = FLOOR_TOGGLE_COLOR.RED;
        break;
      default:
        assertNeverCalled(this.#color);
    }
    this.#setColor(this.#color);
  }

  public disableObject(): void {
    (this.body as Phaser.Physics.Arcade.Body).enable = false;
    this.active = false;
    this.visible = false;
  }

  public enableObject(): void {
    (this.body as Phaser.Physics.Arcade.Body).enable = true;
    this.active = true;
    this.visible = true;
  }

  #setColor(color: FloorToggleColor): void {
    switch (color) {
      case FLOOR_TOGGLE_COLOR.RED:
        this.setTint(0xff0000);
        break;
      case FLOOR_TOGGLE_COLOR.GREEN:
        this.setTint(0x00ff00);
        break;
      case FLOOR_TOGGLE_COLOR.BLUE:
        this.setTint(0x0000ff);
        break;
      case FLOOR_TOGGLE_COLOR.YELLOW:
        this.setTint(0xffff00);
        break;
      default:
        assertNeverCalled(color);
    }
  }
}
