const ENCODING_WORDS = ANAGRAM_WORDS.filter((word) => word.length <= 6);

export type MorseQuestionContent = Extract<
  FishingMiniGameQuestion["content"],
  { type: "morse" }
>;

type MorseSymbolWidths = {
  dot: number;
  dash: number;
};

type MorseRenderLetter = {
  letter: string;
  spacingBefore: number;
};

export const WORD_ENCODINGS_MINI_GAME: FishingMiniGameDefinition = {
  id: "word-encodings",
  instructions: "Decode the signal!",
  inputPlaceholder: "Enter the word",
  scoring: {
    correctDelta: 15,
    incorrectDelta: 3,
    timerDelayMs: 1000,
    timerProgressDelta: 1,
    progressBounds: {
      caught: 0,
      start: 30,
      escaped: 60,
    },
  },
  preload: (scene) => {
    Object.entries(SEMAPHORE_ASSETS).forEach(([letter, assetUrl]) => {
      scene.load.svg(getSemaphoreTextureKey(letter), assetUrl);
    });
    Object.entries(NAUTICAL_FLAG_ASSETS).forEach(([letter, assetUrl]) => {
      scene.load.image(getNauticalFlagTextureKey(letter), assetUrl);
    });
    scene.load.image(MORSE_DOT_TEXTURE_KEY, pufferfishMorse);
    scene.load.image(MORSE_DASH_TEXTURE_KEY, catfishMorse);
  },
  getNextQuestion: (scene) => {
    const word = drawFromQuestionPool(
      scene,
      WORD_ENCODING_POOL_ID,
      ENCODING_WORDS,
    );
    const encoding = getNextEncoding(scene);

    if (encoding === "braille") {
      return {
        id: `encoding-braille-${word}`,
        answers: [word],
        content: {
          type: "text",
          text: encodeWordAsBraille(word),
          style: {
            fontSize: "48px",
            fontFamily: "monospace",
            letterSpacing: 6,
          },
          maxWidthRatio: 0.8,
        },
      };
    }

    if (encoding === "morse") {
      return {
        id: `encoding-morse-${word}`,
        answers: [word],
        content: {
          type: "morse",
          encodedWords: encodeWordAsMorseWords(word),
          dotTextureKey: MORSE_DOT_TEXTURE_KEY,
          dashTextureKey: MORSE_DASH_TEXTURE_KEY,
          maxWidthRatio: 0.75,
        },
      };
    }

    if (encoding === "semaphore" || encoding === "nautical-flags") {
      const getTextureKey =
        encoding === "semaphore"
          ? getSemaphoreTextureKey
          : getNauticalFlagTextureKey;
      const textureKeys = word
        .toUpperCase()
        .split("")
        .map((letter) => getTextureKey(letter));

      return {
        id: `encoding-${encoding}-${word}`,
        answers: [word],
        content: {
          type: "image-sequence",
          textureKeys,
          maxWidthRatio: 0.9,
          itemSize: 100,
          spacing: 16,
          backgroundPadding: 12,
          backgroundColor: 0xffffff,
        },
      };
    }

    throw new Error(`Unsupported encoding type: ${encoding}`);
  },
};

function getNextEncoding(scene: Phaser.Scene): WordEncodingType {
  const currentIndex = WORD_ENCODING_ROTATION_STATE.get(scene);
  if (currentIndex === undefined) {
    const startIndex = Math.floor(Math.random() * ENCODING_TYPES.length);
    WORD_ENCODING_ROTATION_STATE.set(scene, startIndex);
    return ENCODING_TYPES[startIndex];
  }

  const nextIndex = (currentIndex + 1) % ENCODING_TYPES.length;
  WORD_ENCODING_ROTATION_STATE.set(scene, nextIndex);
  return ENCODING_TYPES[nextIndex];
}

function encodeWordAsBraille(word: string): string {
  return word
    .toLowerCase()
    .split("")
    .map((char) => BRAILLE_MAP[char] ?? char)
    .join("");
}

function encodeWordAsMorseWords(input: string): string[][] {
  const letters = input
    .trim()
    .toLowerCase()
    .replace(/\s+/g, "")
    .split("")
    .map((char) => MORSE_MAP[char] ?? char)
    .filter((encoded) => encoded.length > 0);

  if (letters.length === 0) {
    return [[]];
  }

  return [letters];
}

function getSemaphoreTextureKey(letter: string): string {
  return `${SEMAPHORE_TEXTURE_PREFIX}${letter.toUpperCase()}`;
}

function getNauticalFlagTextureKey(letter: string): string {
  return `${NAUTICAL_FLAG_TEXTURE_PREFIX}${letter.toUpperCase()}`;
}

export function createMorseQuestionDisplay(
  scene: Phaser.Scene,
  content: MorseQuestionContent,
  centerX: number,
  y: number,
  _screenWidth: number,
): Phaser.GameObjects.Container {
  const container = scene.add.container(0, 0).setDepth(1000);
  const symbolWidths = getMorseSymbolWidthMap(scene, content);
  const words = content.encodedWords.length > 0 ? content.encodedWords : [[]];
  const lines = buildMorseLines(words);

  const lineWidths: number[] = [];
  const totalHeight =
    lines.length * MORSE_LAYOUT.SYMBOL_HEIGHT +
    Math.max(0, lines.length - 1) * MORSE_LAYOUT.LINE_SPACING;
  const renderWidth = lines.reduce<number>((maxWidth, line) => {
    const width = line.reduce((sum, letter) => {
      return (
        sum +
        letter.spacingBefore +
        measureMorseLetterWidth(letter.letter, symbolWidths)
      );
    }, 0);
    lineWidths.push(width);
    return Math.max(maxWidth, width);
  }, MORSE_LAYOUT.MIN_WIDTH);

  let currentY = 0;
  lines.forEach((line, index) => {
    const lineWidth = Math.max(lineWidths[index], 0);
    let letterX = (renderWidth - lineWidth) / 2;
    line.forEach((letter) => {
      letterX += letter.spacingBefore;
      const widthDrawn = renderMorseLetter(
        scene,
        container,
        letter.letter,
        letterX,
        currentY,
        content,
        symbolWidths,
      );
      letterX += widthDrawn;
    });
    currentY += MORSE_LAYOUT.SYMBOL_HEIGHT + MORSE_LAYOUT.LINE_SPACING;
  });

  container.setPosition(centerX - renderWidth / 2, y - totalHeight / 2);
  container.setSize(renderWidth, totalHeight);
  return container;
}

function getMorseSymbolWidthMap(
  scene: Phaser.Scene,
  content: MorseQuestionContent,
): MorseSymbolWidths {
  return {
    dot: resolveMorseSymbolWidth(scene, content.dotTextureKey),
    dash: resolveMorseSymbolWidth(scene, content.dashTextureKey),
  };
}

function resolveMorseSymbolWidth(
  scene: Phaser.Scene,
  textureKey: string,
): number {
  const texture = scene.textures.get(textureKey);
  if (!texture) {
    return MORSE_LAYOUT.FALLBACK_LETTER_WIDTH;
  }

  const source = texture.getSourceImage();
  const width = source?.width ?? 0;
  const height = source?.height ?? 0;
  if (width === 0 || height === 0) {
    return MORSE_LAYOUT.FALLBACK_LETTER_WIDTH;
  }

  const aspectRatio = width / height;
  if (!Number.isFinite(aspectRatio) || aspectRatio <= 0) {
    return MORSE_LAYOUT.FALLBACK_LETTER_WIDTH;
  }

  return aspectRatio * MORSE_LAYOUT.SYMBOL_HEIGHT;
}

function measureMorseLetterWidth(
  letter: string,
  symbolWidths: MorseSymbolWidths,
): number {
  if (!isMorseSequence(letter)) {
    return Math.max(
      MORSE_LAYOUT.FALLBACK_LETTER_WIDTH,
      letter.length * (MORSE_LAYOUT.FALLBACK_LETTER_WIDTH / 2),
    );
  }

  return letter.split("").reduce((width, symbol, index) => {
    const symbolWidth = symbol === "." ? symbolWidths.dot : symbolWidths.dash;
    if (symbolWidth === 0) {
      return width;
    }

    const extraSpacing =
      index < letter.length - 1 ? MORSE_LAYOUT.SYMBOL_SPACING : 0;
    return width + symbolWidth + extraSpacing;
  }, 0);
}

function renderMorseLetter(
  scene: Phaser.Scene,
  container: Phaser.GameObjects.Container,
  letter: string,
  startX: number,
  y: number,
  content: MorseQuestionContent,
  symbolWidths: MorseSymbolWidths,
): number {
  if (!isMorseSequence(letter)) {
    return renderFallbackMorseLetter(scene, container, letter, startX, y);
  }

  let symbolX = startX;
  const symbols = letter.split("");
  symbols.forEach((symbol, index) => {
    const { textureKey, width } = getMorseSymbolConfig(
      symbol,
      content,
      symbolWidths,
    );
    if (width === 0) {
      return;
    }
    const image = scene.add
      .image(symbolX, y + MORSE_LAYOUT.SYMBOL_HEIGHT / 2, textureKey)
      .setOrigin(0, 0.5);
    image.setDisplaySize(width, MORSE_LAYOUT.SYMBOL_HEIGHT);
    container.add(image);
    symbolX += width;
    if (index < symbols.length - 1) {
      symbolX += MORSE_LAYOUT.SYMBOL_SPACING;
    }
  });

  return symbolX - startX;
}

function renderFallbackMorseLetter(
  scene: Phaser.Scene,
  container: Phaser.GameObjects.Container,
  letter: string,
  startX: number,
  y: number,
): number {
  const fallbackWidth = Math.max(
    MORSE_LAYOUT.FALLBACK_LETTER_WIDTH,
    letter.length * (MORSE_LAYOUT.FALLBACK_LETTER_WIDTH / 2),
  );
  const text = scene.add
    .text(
      startX + fallbackWidth / 2,
      y + MORSE_LAYOUT.SYMBOL_HEIGHT / 2,
      letter,
      {
        ...DEFAULT_UI_TEXT_STYLE,
        fontSize: "24px",
        fontFamily: "monospace",
        color: "#FFFFFF",
      },
    )
    .setOrigin(0.5, 0.5);
  container.add(text);
  return fallbackWidth;
}

function getMorseSymbolConfig(
  symbol: string,
  content: MorseQuestionContent,
  symbolWidths: MorseSymbolWidths,
): { textureKey: string; width: number } {
  if (symbol === ".") {
    return { textureKey: content.dotTextureKey, width: symbolWidths.dot };
  }

  return { textureKey: content.dashTextureKey, width: symbolWidths.dash };
}

function isMorseSequence(letter: string): boolean {
  return letter.length > 0 && /^[.-]+$/.test(letter);
}

function buildMorseLines(words: string[][]): MorseRenderLetter[][] {
  const flattenedLetters = words.flat();
  if (flattenedLetters.length === 0) {
    return [[{ letter: "", spacingBefore: 0 }]];
  }

  const lines: MorseRenderLetter[][] = [];
  let currentLine: MorseRenderLetter[] = [];

  flattenedLetters.forEach((letter) => {
    if (currentLine.length >= MORSE_MAX_LETTERS_PER_LINE) {
      lines.push(currentLine);
      currentLine = [];
    }

    const spacingBefore =
      currentLine.length === 0 ? 0 : MORSE_LAYOUT.LETTER_SPACING;
    currentLine.push({ letter, spacingBefore });
  });

  if (currentLine.length > 0) {
    lines.push(currentLine);
  }

  return lines;
}
