import * as Phaser from "phaser";
import {
  ASSET_KEYS,
  EFFECTS_ANIMATION_KEYS,
  NPC_ANIMATION_KEYS,
} from "../../common/assets";
import { NPC_MAX_HP, NPC_SPEED } from "../../common/config";
import {
  CHARACTER_ACTIVE_STATE,
  DIRECTION,
  INTERACTIVE_OBJECT_TYPE,
} from "../../common/constants";
import { EVENT_BUS, CUSTOM_EVENTS } from "../../common/event-bus";
import { logger } from "../../common/logger";
import {
  type NPCIdentifier,
  type TiledNpcObject,
} from "../../common/tiled/types";
import type { CharacterActiveState, Position } from "../../common/types";
import type { AnimationConfig } from "../../components/animation-component";
import { HidingComponent } from "../../components/hiding-component";
import { InputComponent } from "../../components/input-component";
import { InteractiveObjectComponent } from "../../components/interactive-object-component";
import { CHARACTER_STATES } from "../../components/state-machine/states/character-states";
import { IdleState } from "../../components/state-machine/states/idle-state";
import { MoveState } from "../../components/state-machine/states/move-state";
import { CharacterObject } from "../common/character-object";
import type { HidingPlace } from "../objects/campground/hiding_place";
import { conditionsMet } from "./npc-game-events";
import {
  type ConditionsConfig,
  type EventSequence,
  type ShowExclamationConfig,
  type ExclamationDismissConfig,
} from "./npc-types";

export type NPCConfig = ConditionsConfig & {
  scene: Phaser.Scene;
  tiledObject: TiledNpcObject;
  assetKey: string;
  activeState: CharacterActiveState;
  sequences: EventSequence[];
  talkSfx?: string;
  showExclamation?: ShowExclamationConfig;
};

export class NPC extends CharacterObject {
  #identifier: NPCIdentifier;
  #sequences: EventSequence[];
  #validSequences: EventSequence[] = [];
  #validSongSequences: EventSequence[] = [];
  #originalPosition: Position;
  #config: NPCConfig;
  #showExclamation?: ShowExclamationConfig;
  // Tracks whether ctor logic has assigned NPC-specific fields before Phaser lifecycle calls into visibility helpers
  private _exclamationInitialized = false;
  #hasGlowEffect = false;
  #currentInteractionIndex = 0;
  #talkSfx?: string;
  #hidingComponent?: HidingComponent;

  constructor(config: NPCConfig) {
    const { animationConfig, shouldFlipLeft } = createAnimationConfig(
      config.assetKey,
      config.scene,
    );

    super({
      id: `npc-${Phaser.Math.RND.uuid()}`,
      scene: config.scene,
      position: { x: config.tiledObject.x, y: config.tiledObject.y },
      assetKey: ASSET_KEYS[config.assetKey as keyof typeof ASSET_KEYS],
      frame: 0,
      isPlayer: false,
      animationConfig,
      speed: NPC_SPEED,
      inputComponent: new InputComponent(),
      isInvulnerable: true,
      maxHP: NPC_MAX_HP,
      shouldFlipLeft,
      activeState: config.activeState,
    });

    // NPCs should not be pushable.
    this.physicsBody.setImmovable(true);
    this.setOrigin(0, 0);
    this.setOffset(0, 0);
    this.setDepth(0.5);

    // Set up physics body with correct offset for bottom-left origin
    this.adjustPhysicsBodyToSpriteSize();

    // Listen for animation changes to update physics body
    this.on(Phaser.Animations.Events.ANIMATION_START, () => {
      setTimeout(() => {
        this.adjustPhysicsBodyToSpriteSize();
      }, 0);
    });
    // Every NPC should at least be idle.
    this._stateMachine.addState(new IdleState(this));
    this._stateMachine.addState(new MoveState(this));
    this._stateMachine.setState(CHARACTER_STATES.IDLE_STATE);

    // Identification
    this.#identifier = config.tiledObject.identifier;
    this.#sequences = config.sequences;
    this.#originalPosition = {
      x: config.tiledObject.x,
      y: config.tiledObject.y,
    };

    // Store config for later use
    this.#config = config;
    this.#showExclamation = config.showExclamation;

    // Store optional talk sfx
    this.#talkSfx = config.talkSfx;

    this._exclamationInitialized = true;

    this.refreshSequences();
    this.updateExclamationMark();

    // Listen for frontend flag changes to update exclamation marks and sequences
    EVENT_BUS.on(CUSTOM_EVENTS.FRONTEND_FLAG_CHANGED, () => {
      this.refreshSequences();
      this.updateExclamationMark();
    });

    // Add interactive component for consistent interaction handling
    new InteractiveObjectComponent(this, INTERACTIVE_OBJECT_TYPE.NPC, () => {
      this.interact();
      return true;
    });
  }

  public get identifier(): NPCIdentifier {
    return this.#identifier;
  }

  public get sequences(): EventSequence[] {
    return this.#sequences;
  }

  public get originalPosition(): Position {
    return { ...this.#originalPosition };
  }

  override update(): void {
    super.update();
    this.#updateExclamationPosition();
  }

  /**
   * Updates the exclamation sprite position to follow the NPC
   */
  #updateExclamationPosition(): void {
    if (!this._exclamationSprite || !this.#showExclamation) {
      return;
    }

    const effectConfig = this.#getEffectConfig(this.#showExclamation.effect);
    const position = effectConfig.getPosition(
      this.x,
      this.y,
      this.width,
      this.height,
    );
    const offsetX = this.#showExclamation.offset?.x ?? 0;
    const offsetY = this.#showExclamation.offset?.y ?? 0;

    this._exclamationSprite.setPosition(
      position.x + offsetX,
      position.y + offsetY,
    );
  }

  public removeNPC(): void {
    this.activeState = CHARACTER_ACTIVE_STATE.HIDDEN as CharacterActiveState;
    this.setPosition(this.originalPosition.x, this.originalPosition.y);
    this.direction = DIRECTION.DOWN;
    this.disableObject();
  }

  public interact(): void {
    if (this.#validSequences.length === 0) {
      return;
    }

    if (this.#showExclamation) {
      const dismissConfig = this.#getExclamationDismissConfig();
      if (dismissConfig.type === "immediately") {
        this.dataManager.dismissNpcExclamation(
          this.identifier,
          dismissConfig.permanent,
        );
      }
      this.updateExclamationMark();
    }

    // Play optional talk sound effect when interacted with
    if (this.#talkSfx) {
      this.scene.sound.play(this.#talkSfx);
    }

    // Trigger the first valid sequence
    EVENT_BUS.emit(CUSTOM_EVENTS.NPC_INTERACTION, {
      npc: this,
      sequence: this.#validSequences[this.#currentInteractionIndex],
    });
  }

  /**
   * Hides the NPC in the specified hiding place.
   * Creates a HidingComponent if one doesn't exist.
   */
  public hideInHidingPlace(hidingPlace: HidingPlace): void {
    // Create hiding component if it doesn't exist
    if (!this.#hidingComponent) {
      this.#hidingComponent = new HidingComponent(this, {
        onReveal: () => {
          // Auto-trigger interaction when revealed
          this.interact();
        },
      });
    }

    // Set target and hide
    this.#hidingComponent.setTargetHidingPlace(hidingPlace);
    hidingPlace.registerHidingEntity(this.#hidingComponent);
    this.#hidingComponent.hideInHidingPlace(hidingPlace);
  }

  public refreshSequences(): void {
    const validSequences = this.#sequences.filter((sequence) => {
      const isValid = conditionsMet(this.dataManager, this.scene, sequence);

      return isValid;
    });

    this.#validSequences = validSequences.filter((sequence) => {
      return !sequence.requiresSong;
    });

    this.#validSongSequences = validSequences.filter((sequence) => {
      return sequence.requiresSong;
    });
  }

  public setCurrentInteraction(index: number): void {
    this.#currentInteractionIndex = index;
  }

  /**
   * Adjust the physics body size to match the sprite frame size for better collision detection.
   * For NPCs smaller than 24x24, use a 16x16 collision box centered at their feet.
   */
  private adjustPhysicsBodyToSpriteSize(): void {
    // Check if frame is available
    if (!this.frame) {
      console.warn(
        `NPC ${this.#identifier}: Frame not available for physics body adjustment`,
      );
      return;
    }

    // Get the current frame dimensions
    const frameWidth = this.frame.width;
    const frameHeight = this.frame.height;

    // For NPCs smaller than 24x24, use a 16x16 collision box centered at their feet
    if (frameWidth < 24 && frameHeight < 24) {
      const collisionSize = 16;
      // Center horizontally: (frameWidth / 2) - (collisionSize / 2)
      const offsetX = frameWidth / 2 - collisionSize / 2;
      // Position at feet: bottom of sprite minus collision box height
      const offsetY = frameHeight - collisionSize;

      this.physicsBody.setSize(collisionSize, collisionSize);
      this.physicsBody.setOffset(offsetX, offsetY);
    } else {
      // For larger NPCs, use the full sprite size
      this.physicsBody.setSize(frameWidth, frameHeight);
      this.physicsBody.setOffset(0, 0);
    }
  }

  /**
   * Process a song sequence and check if it matches any required songs
   * @param notes The note sequence to check
   * @returns true if a song matched and triggered an event, false otherwise
   */
  public processSong(notes: string[]): boolean {
    // Check if any valid song sequences match the played note sequence
    for (const sequence of this.#validSongSequences) {
      if (sequence.requiresSong) {
        // Check if any of the required songs match the played notes
        for (const requiredSong of sequence.requiresSong) {
          if (this.#doesSongMatch(requiredSong, notes)) {
            // Song matched! Trigger the event sequence
            EVENT_BUS.emit(CUSTOM_EVENTS.NPC_INTERACTION, {
              npc: this,
              sequence: sequence,
            });

            logger.info(
              `Song matched! Triggered event sequence for NPC: ${this.identifier}`,
            );
            return true; // Song matched - caller should clear note history
          }
        }
      }
    }
    return false; // No match found
  }

  /**
   * Start a cup shuffling game
   * @param numSwaps Number of random swaps to perform
   * @param animationSpeed Speed multiplier (1.0 = normal, 2.0 = twice as fast, 0.5 = half speed)
   * @param templateChoices Template choices with correct and incorrect event IDs
   * @returns Promise that resolves with the choices for the player
   */
  #doesSongMatch(requiredSong: string[], noteHistory: string[]): boolean {
    if (requiredSong.length > noteHistory.length) {
      return false;
    }

    const recentNotes = noteHistory.slice(-requiredSong.length);
    return requiredSong.every((note, index) => note === recentNotes[index]);
  }

  public conditionsMet(): boolean {
    return conditionsMet(this.dataManager, this.scene, this.#config);
  }

  #isGlowEffect(): boolean {
    return this.#showExclamation?.effect?.toLowerCase() === "glow";
  }

  /**
   * Maps effect names to their corresponding asset, animation keys, and positioning
   */
  #getEffectConfig(effectName?: string): {
    assetKey: keyof typeof ASSET_KEYS;
    animationKey: string;
    getPosition: (
      x: number,
      y: number,
      w: number,
      h: number,
    ) => { x: number; y: number };
    originX: number;
    originY: number;
  } {
    const effect = (effectName ?? "exclamation").toLowerCase();

    if (effect === "sparkle") {
      return {
        assetKey: "SPARKLE",
        animationKey: EFFECTS_ANIMATION_KEYS.SPARKLE,
        getPosition: (x, y, w, h) => ({ x: x + w / 2, y: y + h / 2 }),
        originX: 0.5,
        originY: 0.5,
      };
    }

    // Default to exclamation
    return {
      assetKey: "EXCLAMATION",
      animationKey: EFFECTS_ANIMATION_KEYS.EXCLAMATION,
      getPosition: (x, y, w) => ({ x: x + w / 2, y: y - 1 }),
      originX: 0.5,
      originY: 1,
    };
  }

  /**
   * Creates the exclamation mark or effect sprite above the NPC if conditions are met
   */
  #createExclamationMark(): void {
    if (!this.#showExclamation) {
      return;
    }

    const dismissConfig = this.#getExclamationDismissConfig();
    // Check if exclamation conditions are met
    const storyFlagsMet =
      !this.#showExclamation.requires ||
      this.dataManager.hasStoryFlagValues(this.#showExclamation.requires);
    const frontendFlagsMet =
      !this.#showExclamation.requiresFrontendFlags ||
      this.dataManager.hasFrontendFlagValues(
        this.#showExclamation.requiresFrontendFlags,
      );
    if (!storyFlagsMet || !frontendFlagsMet) {
      return;
    }

    if (
      dismissConfig.type === "immediately" &&
      this.dataManager.hasDismissedNpcExclamation(this.identifier)
    ) {
      return;
    }

    // Glow effect is handled separately via postFX
    if (this.#isGlowEffect()) {
      this.#applyGlowEffect();
      return;
    }

    const effectConfig = this.#getEffectConfig(this.#showExclamation.effect);
    const position = effectConfig.getPosition(
      this.x,
      this.y,
      this.width,
      this.height,
    );
    const offsetX = this.#showExclamation.offset?.x ?? 0;
    const offsetY = this.#showExclamation.offset?.y ?? 0;

    // Create effect sprite
    this._exclamationSprite = this.scene.add.sprite(
      position.x + offsetX,
      position.y + offsetY,
      ASSET_KEYS[effectConfig.assetKey],
    );

    this._exclamationSprite.setOrigin(
      effectConfig.originX ?? 0.5,
      effectConfig.originY ?? 0.5,
    );
    this._exclamationSprite.setDepth(this.depth + 3); // Render above NPC
    this._exclamationSprite.setVisible(this.visible);

    // Start the animation on loop
    this._exclamationSprite.play({
      key: effectConfig.animationKey,
      repeat: -1,
    });
  }

  #applyGlowEffect(): void {
    if (this.#hasGlowEffect) return;
    // Use postFX instead of preFX to allow glow to extend beyond sprite bounds
    this.postFX?.addGlow(0xffffff, 4, 0, false, 0.1, 32);
    this.#hasGlowEffect = true;
  }

  #removeGlowEffect(): void {
    if (!this.#hasGlowEffect) return;
    this.postFX?.clear();
    this.#hasGlowEffect = false;
  }

  /**
   * Updates the exclamation mark visibility based on current conditions
   */
  public updateExclamationMark(): void {
    if (!this.#showExclamation) {
      return;
    }

    const dismissConfig = this.#getExclamationDismissConfig();
    const storyFlagsMet =
      !this.#showExclamation.requires ||
      this.dataManager.hasStoryFlagValues(this.#showExclamation.requires);
    const frontendFlagsMet =
      !this.#showExclamation.requiresFrontendFlags ||
      this.dataManager.hasFrontendFlagValues(
        this.#showExclamation.requiresFrontendFlags,
      );
    const requirementsMet = storyFlagsMet && frontendFlagsMet;

    let dismissed = false;
    if (dismissConfig.type === "immediately") {
      dismissed = this.dataManager.hasDismissedNpcExclamation(this.identifier);
    } else if (dismissConfig.type === "story_flag") {
      dismissed = this.dataManager.hasStoryFlagValues(dismissConfig.requires);
    }

    const shouldShow = requirementsMet && !dismissed;

    if (this.#isGlowEffect()) {
      if (shouldShow) {
        this.#applyGlowEffect();
      } else {
        this.#removeGlowEffect();
      }
      return;
    }

    if (shouldShow && !this._exclamationSprite) {
      this.#createExclamationMark();
    } else if (this._exclamationSprite) {
      this._exclamationSprite.setVisible(shouldShow);
    }
  }

  protected override updateExclamationVisibility(): void {
    if (!this._exclamationInitialized) {
      super.updateExclamationVisibility();
      return;
    }

    if (!this.#showExclamation) {
      super.updateExclamationVisibility();
      return;
    }

    if (!this.visible) {
      if (this._exclamationSprite) {
        this._exclamationSprite.setVisible(false);
      }
      return;
    }

    this.updateExclamationMark();
  }

  #getExclamationDismissConfig(): ExclamationDismissConfig {
    if (!this.#showExclamation?.dismiss) {
      return { type: "immediately", permanent: true };
    }

    if (this.#showExclamation.dismiss.type === "immediately") {
      return {
        ...this.#showExclamation.dismiss,
        permanent: this.#showExclamation.dismiss.permanent ?? true,
      };
    }

    return this.#showExclamation.dismiss;
  }
}

function createAnimationConfig(
  animPrefix: string,
  scene: Phaser.Scene,
): { animationConfig: AnimationConfig; shouldFlipLeft: boolean } {
  // Helper to get animation key from NPC_ANIMATION_KEYS and verify it exists in the scene
  function getAnimationKey(key: string): string | undefined {
    // Get the key from NPC_ANIMATION_KEYS
    const animKey = NPC_ANIMATION_KEYS[key as keyof typeof NPC_ANIMATION_KEYS];
    // Only return it if it exists in the scene
    if (animKey && scene.anims.exists(animKey)) {
      return animKey;
    }
    return undefined;
  }

  // Check what animations are available (keys are only returned if they exist in the scene)
  const walkDownKey = getAnimationKey(`${animPrefix}_WALK_DOWN`);
  const walkUpKey = getAnimationKey(`${animPrefix}_WALK_UP`);
  const walkLeftKey = getAnimationKey(`${animPrefix}_WALK_LEFT`);
  const walkRightKey = getAnimationKey(`${animPrefix}_WALK_RIGHT`);
  const walkSideKey = getAnimationKey(`${animPrefix}_WALK_SIDE`);

  const idleDownKey = getAnimationKey(`${animPrefix}_IDLE_DOWN`);
  const idleUpKey = getAnimationKey(`${animPrefix}_IDLE_UP`);
  const idleLeftKey = getAnimationKey(`${animPrefix}_IDLE_LEFT`);
  const idleRightKey = getAnimationKey(`${animPrefix}_IDLE_RIGHT`);
  const idleSideKey = getAnimationKey(`${animPrefix}_IDLE_SIDE`);

  const shouldFlipLeft = idleSideKey !== undefined;

  // Determine default keys for fallbacks (guaranteed to be strings or throw error)
  const defaultKey = idleDownKey || idleSideKey || idleRightKey || "";
  const defaultWalkKey = walkSideKey || walkDownKey || defaultKey;

  if (!defaultKey) {
    console.error(`No default animation keys found for NPC ${animPrefix}`);
  }

  const config: AnimationConfig = {};

  // WALK animations - use specific keys or fallback to defaults
  config.WALK_DOWN = {
    key: walkDownKey || defaultWalkKey,
    repeat: -1,
    ignoreIfPlaying: true,
  };
  config.WALK_UP = {
    key: walkUpKey || defaultWalkKey,
    repeat: -1,
    ignoreIfPlaying: true,
  };
  config.WALK_LEFT = {
    key: walkLeftKey || walkSideKey || defaultWalkKey,
    repeat: -1,
    ignoreIfPlaying: true,
  };
  config.WALK_RIGHT = {
    key: walkRightKey || walkSideKey || defaultWalkKey,
    repeat: -1,
    ignoreIfPlaying: true,
  };

  // IDLE animations - use specific keys or fallback to defaults
  config.IDLE_DOWN = {
    key: idleDownKey || defaultKey,
    repeat: -1,
    ignoreIfPlaying: true,
  };
  config.IDLE_UP = {
    key: idleUpKey || defaultKey,
    repeat: -1,
    ignoreIfPlaying: true,
  };
  config.IDLE_LEFT = {
    key: idleLeftKey || idleSideKey || defaultKey,
    repeat: -1,
    ignoreIfPlaying: true,
  };
  config.IDLE_RIGHT = {
    key: idleRightKey || idleSideKey || defaultKey,
    repeat: -1,
    ignoreIfPlaying: true,
  };

  return { animationConfig: config, shouldFlipLeft };
}
