import * as Phaser from "phaser";
import { ASSET_KEYS } from "../../common/assets";
import { INTERACTIVE_OBJECT_TYPE } from "../../common/constants";
import { getSceneDataManager } from "../../common/data-manager";
import { CUSTOM_EVENTS, EVENT_BUS } from "../../common/event-bus";
import type { TiledReadableObject } from "../../common/tiled/types";
import type { CustomObject } from "../../common/types";
import { InteractiveObjectComponent } from "../../components/interactive-object-component";
import { conditionsMet } from "../npcs/npc-game-events";
import type { ConditionsConfig } from "../npcs/npc-types";

type ReadableSpriteState = ConditionsConfig & {
  // Content for this state
  messages?: string[];
  imageAssetKey?: string;
  imageScale?: number;
  frameKey?: string; // Frame to display for this state
};

type ReadableSpriteConfig = {
  spriteAssetKey: string;
  // Optional depth override (defaults to Phaser's automatic depth sorting by y position)
  depth?: number;
  // Support multiple states (checked in order, first match wins)
  // If no states match, falls back to default state (one without requiresFlags/requiresPuzzles)
  variants: ReadableSpriteState[];
};

export class ReadableSprite
  extends Phaser.Physics.Arcade.Image
  implements CustomObject
{
  #spriteConfig: ReadableSpriteConfig;
  #dataManager: ReturnType<typeof getSceneDataManager>;

  constructor(scene: Phaser.Scene, config: TiledReadableObject) {
    // Get readable data to extract sprite information
    // Note: base-game-scene.ts ensures this is only called when spriteAssetKey exists
    const readableData = scene.cache.json.get(ASSET_KEYS.READABLE_MESSAGES) as
      | Record<string, ReadableSpriteConfig | string | string[]>
      | undefined;

    const data = readableData?.[config.identifier];
    // This should never happen if base-game-scene.ts checks correctly
    if (!data || typeof data === "string" || Array.isArray(data)) {
      throw new Error(
        `ReadableSprite requires sprite configuration object for identifier: '${config.identifier}'. Found: ${typeof data}`,
      );
    }

    const spriteConfig = data as ReadableSpriteConfig;
    if (!spriteConfig.spriteAssetKey) {
      throw new Error(
        `ReadableSprite requires spriteAssetKey for identifier: '${config.identifier}'`,
      );
    }

    // Determine initial frame from first matching state
    const dataManager = getSceneDataManager(scene);
    let initialFrame: string | undefined;

    // Check each state in order, use first match
    for (const state of spriteConfig.variants) {
      if (conditionsMet(dataManager, scene, state)) {
        initialFrame = state.frameKey;
        break;
      }
    }

    super(scene, config.x, config.y, spriteConfig.spriteAssetKey, initialFrame);

    scene.add.existing(this);
    scene.physics.add.existing(this);
    this.setOrigin(0, 0).setImmovable(true);

    // Set depth if provided, otherwise use Phaser's default (automatic sorting by y position)
    if (spriteConfig.depth !== undefined) {
      this.setDepth(spriteConfig.depth);
    }

    this.#spriteConfig = spriteConfig;
    this.#dataManager = getSceneDataManager(scene);

    // Add interactive component for reading if any variants have messages
    if (
      spriteConfig.variants.some(
        (state) => state.messages && state.messages.length > 0,
      )
    ) {
      new InteractiveObjectComponent(
        this,
        INTERACTIVE_OBJECT_TYPE.TEXT,
        (_heldObject) => {
          return this.read();
        },
      );
    }

    this.disableObject();
  }

  #updateSpriteFrame(): void {
    // Check each state in order, use first match
    for (const state of this.#spriteConfig.variants) {
      if (conditionsMet(this.#dataManager, this.scene, state)) {
        if (state.frameKey) {
          this.setFrame(state.frameKey);
        }
        return;
      }
    }
    // No state matched, keep current frame
  }

  public read(): boolean {
    let messages: string[] = [];
    let imageAssetKey: string | undefined;
    let imageScale: number | undefined;

    // Check each state in order, use first match
    for (const state of this.#spriteConfig.variants) {
      if (conditionsMet(this.#dataManager, this.scene, state)) {
        // Use this state's content
        messages = state.messages ?? [];
        imageAssetKey = state.imageAssetKey;
        imageScale = state.imageScale;
        break;
      }
    }

    // Display image if provided
    if (imageAssetKey) {
      const centerX = this.scene.cameras.main.centerX;
      const centerY = this.scene.cameras.main.centerY;
      EVENT_BUS.emit(CUSTOM_EVENTS.DISPLAY_PNG, {
        assetKey: imageAssetKey,
        x: centerX,
        y: centerY,
        scale: imageScale,
      });
    }

    // Display dialog (empty messages array is allowed)
    if (messages.length > 0) {
      EVENT_BUS.emit(CUSTOM_EVENTS.DIALOG_START, {
        messages,
        choices: [],
      });
    }
    return true;
  }

  public enableObject(): void {
    (this.body as Phaser.Physics.Arcade.Body).enable = true;
    this.active = true;
    this.visible = true;

    // Update sprite frame when enabled (in case conditions changed)
    this.#updateSpriteFrame();
  }

  public disableObject(): void {
    (this.body as Phaser.Physics.Arcade.Body).enable = false;
    this.active = false;
    this.visible = false;
  }
}
