import * as Phaser from "phaser";
import { DIRECTION, LEVEL_NAME } from "./constants";
import type {
  CustomObject,
  Direction,
  GameObject,
  LevelName,
  Position,
} from "./types";

/**
 * Utility function to ensure we handle the full possible range of types when checking a variable for a possible
 * type in a union.
 *
 * A good example of this is when we check for all of the possible values in a `switch` statement, and we want
 * to ensure we check for all possible values in an enum type object.
 */

export function assertNeverCalled(_value: never): never {
  throw new Error(
    `Error! Reached forbidden guard function with unexpected value: ${JSON.stringify(_value)}`,
  );
}

export function getRelativeDirection(
  object: Position,
  targetObject: Position,
): Direction {
  // Calculate the absolute differences in x and y coordinates
  const deltaX = Math.abs(object.x - targetObject.x);
  const deltaY = Math.abs(object.y - targetObject.y);

  // If the difference in x is greater than or equal to the difference in y,
  // prioritize horizontal direction
  if (deltaX >= deltaY) {
    if (object.x < targetObject.x) {
      return DIRECTION.RIGHT;
    } else {
      return DIRECTION.LEFT;
    }
  } else {
    // If the difference in y is greater, prioritize vertical direction
    if (object.y < targetObject.y) {
      return DIRECTION.DOWN;
    } else {
      return DIRECTION.UP;
    }
  }
}

export function isArcadePhysicsBody(
  body:
    | Phaser.Physics.Arcade.Body
    | Phaser.Physics.Arcade.StaticBody
    | MatterJS.BodyType
    | null,
): body is Phaser.Physics.Arcade.Body {
  if (body === undefined || body === null) {
    return false;
  }
  return body instanceof Phaser.Physics.Arcade.Body;
}

export function isCustomObject(
  obj: GameObject,
): obj is GameObject & CustomObject {
  const gameObject = obj as GameObject & CustomObject;
  return (
    gameObject.disableObject !== undefined &&
    gameObject.enableObject !== undefined
  );
}

export function isDirection(direction: string): direction is Direction {
  return DIRECTION[direction as keyof typeof DIRECTION] !== undefined;
}

export function isLevelName(levelName: string): levelName is LevelName {
  return LEVEL_NAME[levelName as keyof typeof LEVEL_NAME] !== undefined;
}

/**
 * Calculate a position in a given direction from a starting point
 * @param startPosition - The starting position {x, y}
 * @param direction - The direction to move
 * @param distance - The distance to move
 * @returns The calculated position {x, y}
 */
export function getPositionInDirection(
  startPosition: Position,
  direction: Direction,
  distance: number,
): Position {
  switch (direction) {
    case DIRECTION.UP:
      return { x: startPosition.x, y: startPosition.y - distance };
    case DIRECTION.DOWN:
      return { x: startPosition.x, y: startPosition.y + distance };
    case DIRECTION.LEFT:
      return { x: startPosition.x - distance, y: startPosition.y };
    case DIRECTION.RIGHT:
      return { x: startPosition.x + distance, y: startPosition.y };
    default:
      assertNeverCalled(direction);
  }
}

export function getOppositeDirection(direction: Direction): Direction {
  switch (direction) {
    case DIRECTION.UP:
      return DIRECTION.DOWN;
    case DIRECTION.DOWN:
      return DIRECTION.UP;
    case DIRECTION.LEFT:
      return DIRECTION.RIGHT;
    case DIRECTION.RIGHT:
      return DIRECTION.LEFT;
    default:
      assertNeverCalled(direction);
  }
}

/**
 * Checks if a position is on an ice tile in the given ice layer.
 * @param iceLayer - The tilemap layer containing ice tiles, or null if no ice layer exists
 * @param x - The x position in pixels
 * @param y - The y position in pixels
 * @returns true if the position is on an ice tile, false otherwise
 */
export function isPositionOnIce(
  iceLayer: Phaser.Tilemaps.TilemapLayer | null,
  x: number,
  y: number,
): boolean {
  if (!iceLayer) {
    return false;
  }

  const tileX = Math.floor(x / 16);
  const tileY = Math.floor((y + 6) / 16);

  const iceTile = iceLayer.getTileAt(tileX, tileY);
  if (!iceTile) {
    return false;
  }
  return iceTile.index !== -1;
}
