import * as Phaser from "phaser";
import { ASSET_KEYS, DELIVERABLE_FRAME_KEYS } from "../../common/assets";
import {
  DELIVERABLE_STATE,
  INTERACTIVE_OBJECT_TYPE,
} from "../../common/constants";
import { REVEAL_TRIGGER } from "../../common/tiled/constants";
import type {
  DeliverableTexture,
  TiledDeliverableObject,
  RevealTriggerType,
} from "../../common/tiled/types";
import type { CustomObject, DeliverableState } from "../../common/types";
import { InteractiveObjectComponent } from "../../components/interactive-object-component";
import { PushableComponent } from "../../components/pushable-component";

export class Deliverable
  extends Phaser.Physics.Arcade.Image
  implements CustomObject
{
  #id: number;
  #texture: DeliverableTexture;
  #revealTrigger: RevealTriggerType;
  #state: DeliverableState;
  #maxHoldTime: number;

  constructor(
    scene: Phaser.Scene,
    config: TiledDeliverableObject,
    deliverableState = DELIVERABLE_STATE.REVEALED,
    maxHoldTime = -1,
  ) {
    super(
      scene,
      config.x,
      config.y,
      ASSET_KEYS.GRASSLAND_OBJECTS,
      DELIVERABLE_FRAME_KEYS[config.texture],
    );

    scene.add.existing(this);
    scene.physics.add.existing(this);
    this.setOrigin(0, 0).setImmovable(true);

    this.#id = config.id;
    this.#texture = config.texture;
    this.#revealTrigger = config.revealDeliverableTrigger;
    this.#state = deliverableState;
    this.#maxHoldTime = maxHoldTime;

    // Create pushable component
    if (config.pushConfig) {
      new PushableComponent(this, config.pushConfig);
    }

    if (this.#revealTrigger !== REVEAL_TRIGGER.NONE) {
      this.#state = DELIVERABLE_STATE.HIDDEN;
      this.disableObject();
    }

    new InteractiveObjectComponent(this, INTERACTIVE_OBJECT_TYPE.LIFTUP);
  }

  get revealTrigger(): RevealTriggerType {
    return this.#revealTrigger;
  }

  get id(): number {
    return this.#id;
  }

  get databaseId(): string {
    return `deliverable_${this.#id}`;
  }
  get deliverableType(): DeliverableTexture {
    return this.#texture;
  }

  public reveal(): void {
    if (this.#state !== DELIVERABLE_STATE.HIDDEN) {
      return;
    }
    this.#state = DELIVERABLE_STATE.REVEALED;
    this.enableObject();
  }

  public consume(): void {
    this.#state = DELIVERABLE_STATE.CONSUMED;
    this.disableObject();
  }

  public holdBySelf(): void {
    this.#state = DELIVERABLE_STATE.HELD;
  }

  public holdByOthers(): void {
    this.#state = DELIVERABLE_STATE.HELD;
    this.disableObject();
  }

  public drop(): void {
    if (this.#state === DELIVERABLE_STATE.HELD) {
      this.#state = DELIVERABLE_STATE.REVEALED;
      this.enableObject();
    }
  }

  get deliverableState(): DeliverableState {
    return this.#state;
  }

  get maxHoldTime(): number {
    return this.#maxHoldTime;
  }

  public disableObject(): void {
    (this.body as Phaser.Physics.Arcade.Body).enable = false;
    this.active = false;
    this.visible = false;
  }

  public enableObject(): void {
    if (
      this.#state === DELIVERABLE_STATE.HIDDEN ||
      this.#state === DELIVERABLE_STATE.CONSUMED ||
      this.#state === DELIVERABLE_STATE.HELD
    ) {
      return;
    }
    (this.body as Phaser.Physics.Arcade.Body).enable = true;
    this.active = true;
    this.visible = true;
  }
}
