import type { TeamHuntState } from "@hunt/public-client";
import { cn } from "@hunt/styled-ui";
import { ArrowLeft } from "lucide-react";
import React from "react";
import { type BaseTaskDisplay, type PuzzleSummary } from "../../rounds/types";
import { ErratumIcon } from "../ErratumIcon";
import { PuzzleBacklink } from "../PuzzleLayout";
import RoundHintLink from "../RoundHintLink";
import RoundSolutionLink from "../RoundSolutionLink";
import { TeamStateProvider } from "../TeamStateProvider";
import { TiledBackgroundPuzzleWrapper } from "../TiledBackgroundPuzzleWrapper";
import OverworldPuzzleList from "./PuzzleList";
import OverworldTaskList from "./TaskList";
import PixelArrowDown from "./assets/arrow_down.png";
import PixelArrowLeft from "./assets/arrow_left.png";
import PixelArrowRight from "./assets/arrow_right.png";
import PixelArrowUp from "./assets/arrow_up.png";
import Decoration from "./assets/gameworld_wrapper_decoration.svg";

const BASE_KEY_STYLING =
  "text-white font-pixel text-2xl bg-[#3C70B5] rounded shadow-[0px_4px_0px_0px_#153A62] flex justify-center items-center select-none";
const LETTER_STYLING = cn("h-7 w-7 rounded", BASE_KEY_STYLING);
const ARROW_STYLING = cn("pixelated p-1.5", LETTER_STYLING);
const CONTROL_LABEL_CLASSNAME =
  "flex justify-center text-2xl lg:text-3xl lg:mt-3 font-pixel text-[#153A62] select-none";

export default function GameworldZoneBody({
  puzzles,
  tasks,
  teamState,
  gameNode,
  roundSlug,
  allFeedersDiscovered,
  backgroundImage,
  darkModeBackgroundImage,
  useToolEnabled = true,
  omitPuzzleList = false,
  title = "",
  headerMessage,
}: {
  puzzles: PuzzleSummary[];
  tasks: BaseTaskDisplay[];
  teamState: TeamHuntState;
  gameNode?: React.ReactNode;
  roundSlug: string;
  allFeedersDiscovered: boolean;
  backgroundImage: string;
  darkModeBackgroundImage?: string;
  useToolEnabled?: boolean;
  omitPuzzleList?: boolean;
  title?: string;
  headerMessage?: React.ReactNode;
}) {
  return (
    <TeamStateProvider teamState={teamState}>
      <TiledBackgroundPuzzleWrapper
        backgroundImage={backgroundImage}
        darkModeBackgroundImage={darkModeBackgroundImage}
        isPixelImage={true}
        backgroundOffsetY={0}
      >
        <div
          id="main-content"
          className="w-full overflow-x-auto flex flex-col items-start justify-start"
        >
          {/* Header with title and back button */}
          <div className="w-full flex justify-center pt-24">
            <div className="w-full max-w-screen-lg px-4 flex items-center justify-between gap-4">
              <PuzzleBacklink href="/" className="flex items-center gap-1">
                <ArrowLeft /> Back to Home
              </PuzzleBacklink>
              <h1
                className={cn(
                  "text-3xl font-bold text-center flex-1 flex items-center justify-center gap-2",
                  darkModeBackgroundImage && "dark:text-gray-100",
                )}
              >
                <span>{title || teamState.rounds[roundSlug]?.title}</span>
                <ErratumIcon
                  resource={{ type: "round", slug: roundSlug }}
                  iconClassName="h-5 w-5"
                />
              </h1>
              <div className="flex-shrink-0 flex justify-end gap-2 min-w-[158px]">
                <RoundSolutionLink
                  slug={roundSlug}
                  teamState={teamState}
                  variant="long"
                />
                <RoundHintLink
                  slug={roundSlug}
                  teamState={teamState}
                  variant="short"
                />
              </div>
            </div>
          </div>

          {/* Optional header message */}
          {headerMessage}

          {gameNode && (
            <div className="w-full px-10 box-border my-4">
              <div className="max-h-[518px] max-w-[750px] lg:max-w-[1100px] lg:max-h-none flex flex-row border border-[#F98F3F] bg-gradient-to-br from-[#F6CC70] to-[#FFA15D] w-full aspect-[700/485] lg:aspect-[884/485] min-w-[600px] rounded-[16%/24%] lg:rounded-[13%/24%] m-auto shadow-[0px_5.42px_5.42px_0px_#00000040] select-none">
                <img
                  src={Decoration}
                  className="h-full ml-10 hidden lg:block pointer-events-none"
                  alt=""
                  aria-hidden="true"
                />
                <div className="flex flex-col grow justify-center min-w-0 ml-14 console-sm:ml-24 console-sm:mr-10 lg:mx-14">
                  <div className="grow mt-5 min-h-0">
                    <div
                      className="border-[16px] border-[#153A62] aspect-square max-h-full max-w-full mx-auto relative"
                      style={{
                        height: "min(100%, 512px)" /* 512px = 480px + 2*16px */,
                      }}
                    >
                      {gameNode}
                    </div>
                  </div>
                  <div className="my-2 flex justify-center">
                    <span className="text-4xl lg:text-5xl font-pixel text-[#153A62] select-none">
                      MonQuest
                    </span>
                  </div>
                </div>
                <div className="mr-8 lg:mr-[72px] flex flex-col justify-evenly min-w-[140px]">
                  <div>
                    <div className="flex justify-center mb-2">
                      <img
                        className={ARROW_STYLING}
                        src={PixelArrowUp}
                        alt="Up Arrow"
                      />
                    </div>
                    <div className="flex justify-center gap-1">
                      <img
                        className={ARROW_STYLING}
                        src={PixelArrowLeft}
                        alt="Left Arrow"
                      />
                      <img
                        className={ARROW_STYLING}
                        src={PixelArrowDown}
                        alt="Down Arrow"
                      />
                      <img
                        className={ARROW_STYLING}
                        src={PixelArrowRight}
                        alt="Right Arrow"
                      />
                    </div>
                    <div className={CONTROL_LABEL_CLASSNAME}>Move</div>
                  </div>
                  <div>
                    <div className="flex justify-center mb-1 lg:mb-2">
                      <SpecialKey text="SPACE" />
                    </div>
                    <div className={CONTROL_LABEL_CLASSNAME}>Interact</div>
                  </div>
                  <div>
                    <div className="flex justify-center mb-1 lg:mb-2">
                      <LetterKey letter="E" disabled={!useToolEnabled} />
                    </div>
                    <div className={CONTROL_LABEL_CLASSNAME}>Use Tool</div>
                  </div>
                  <div>
                    <div className="flex justify-center mb-1 lg:mb-2">
                      <LetterKey letter="Q" />
                    </div>
                    <div className={CONTROL_LABEL_CLASSNAME}>Show Info</div>
                  </div>
                </div>
              </div>
            </div>
          )}
          {!omitPuzzleList && (
            <>
              <OverworldPuzzleList
                puzzles={puzzles}
                roundName={teamState.rounds[roundSlug]?.title ?? ""}
                allFeedersDiscovered={allFeedersDiscovered}
                roundSlug={roundSlug}
              />
              <OverworldTaskList
                tasks={tasks}
                roundName={teamState.rounds[roundSlug]?.title ?? ""}
              />
            </>
          )}
        </div>
      </TiledBackgroundPuzzleWrapper>
    </TeamStateProvider>
  );
}

const LetterKey = ({
  letter,
  disabled = false,
}: {
  letter: string;
  disabled?: boolean;
}) => {
  return (
    <div className={cn(LETTER_STYLING, disabled && "grayscale opacity-60")}>
      {letter}
    </div>
  );
};

const SpecialKey = ({ text }: { text: string }) => {
  return <div className={cn("h-7 rounded px-4", BASE_KEY_STYLING)}>{text}</div>;
};
