import { DIRECTION } from "../../../common/constants";
import type { Direction } from "../../../common/types";
import { isArcadePhysicsBody } from "../../../common/utils";
import { type CharacterObject } from "../../../entities/common/character-object";
import { BaseMoveState } from "./base-move-state";
import { CHARACTER_STATES } from "./character-states";

export class IceMoveState extends BaseMoveState {
  #lastMovementDirection: Direction | null = null;
  #slideSpeed = 150; // Slower than normal walking speed

  constructor(gameObject: CharacterObject) {
    super(CHARACTER_STATES.ICE_MOVE_STATE, gameObject, "WALK");
  }

  public onEnter(): void {
    // Store the last movement direction when entering ice
    this.#lastMovementDirection = this._gameObject.direction;
    this._gameObject.animationComponent.playAnimation(
      `WALK_${this._gameObject.direction}`,
    );
    this.#setSlideVelocity(this.#lastMovementDirection);
  }

  public onUpdate(): void {
    // Check if we're still on ice
    if (!this._gameObject.isOnIce()) {
      this._stateMachine.setState(CHARACTER_STATES.MOVE_STATE);
      return;
    }

    // Always slide while on ice - no input needed
    this.#continueSliding();
  }

  #continueSliding(): void {
    if (!this.#lastMovementDirection) {
      this._stateMachine.setState(CHARACTER_STATES.IDLE_STATE);
      return;
    }

    // Check if we've hit an obstacle
    if (this.#hasHitObstacle()) {
      this._resetVelocity();
      this._stateMachine.setState(CHARACTER_STATES.IDLE_STATE);
      return;
    }

    // Continue sliding in the same direction - ignore any new input
    this.#setSlideVelocity(this.#lastMovementDirection);
  }

  #setSlideVelocity(direction: Direction): void {
    if (!this._gameObject.isOnIce()) {
      return;
    }

    if (!isArcadePhysicsBody(this._gameObject.body)) {
      return;
    }

    const velocity = this.#slideSpeed;
    let velocityX = 0;
    let velocityY = 0;

    switch (direction) {
      case DIRECTION.LEFT:
        velocityX = -velocity;
        break;
      case DIRECTION.RIGHT:
        velocityX = velocity;
        break;
      case DIRECTION.UP:
        velocityY = -velocity;
        break;
      case DIRECTION.DOWN:
        velocityY = velocity;
        break;
    }

    this._gameObject.body.velocity.x = velocityX;
    this._gameObject.body.velocity.y = velocityY;
  }

  #hasHitObstacle(): boolean {
    if (!isArcadePhysicsBody(this._gameObject.body)) {
      return false;
    }

    // If we're trying to move but velocity is significantly reduced, we've hit something
    const velocity = this._gameObject.body.velocity;
    const expectedVelocity = this.#slideSpeed;
    if (this.#lastMovementDirection) {
      switch (this.#lastMovementDirection) {
        case DIRECTION.LEFT:
          return velocity.x > -expectedVelocity * 0.5; // Significantly slowed down
        case DIRECTION.RIGHT:
          return velocity.x < expectedVelocity * 0.5;
        case DIRECTION.UP:
          return velocity.y > -expectedVelocity * 0.5;
        case DIRECTION.DOWN:
          return velocity.y < expectedVelocity * 0.5;
      }
    }

    return false;
  }

  protected normalizeVelocity(): void {
    // Override to prevent normal velocity normalization on ice
    // Ice sliding uses its own velocity management
  }
}
