import { DEBUG_VISIBILITY_ALPHA } from "../common/config";
import { CHARACTER_COLORS, STORAGE_KEYS } from "../common/constants";
import {
  type CharacterColor,
  type GameObject,
  isVisualGameObject,
} from "../common/types";
import { BaseGameObjectComponent } from "./base-game-object";

export class VisibilityComponent extends BaseGameObjectComponent {
  private visibleTo: CharacterColor[];

  constructor(
    gameObject: GameObject,
    visibleTo: CharacterColor[],
    applyTint = true,
  ) {
    super(gameObject);
    this.visibleTo = visibleTo;
    this.applyVisibilitySettings(applyTint);
  }

  // Apply visibility settings based on the selected character color
  public applyVisibilitySettings(applyTint = true): void {
    const storedColor = localStorage.getItem(STORAGE_KEYS.CHARACTER_COLOR);
    const selectedCharacterColor =
      storedColor && Object.keys(CHARACTER_COLORS).includes(storedColor)
        ? (storedColor as CharacterColor)
        : CHARACTER_COLORS.GREEN.name;
    const alpha = this.visibleTo.includes(selectedCharacterColor)
      ? 1
      : DEBUG_VISIBILITY_ALPHA;

    // Only apply visual changes to sprites and images, not zones
    if (isVisualGameObject(this.gameObject)) {
      this.gameObject.setAlpha(alpha);
      if (applyTint) {
        const tint =
          this.visibleTo.length === 1
            ? CHARACTER_COLORS[selectedCharacterColor].tint
            : 0xffffff;
        this.gameObject.setTint(tint);
      }
    }
  }

  // Update visibility to a new set of colors
  public setVisibleTo(visibleTo: CharacterColor[], applyTint = true): void {
    this.visibleTo = visibleTo;
    this.applyVisibilitySettings(applyTint);
  }
}
