import { newClient } from "@hunt/public-client";
import type * as Phaser from "phaser";
import apiUrl from "../../../../utils/apiUrl";
import { IS_STATIC_SITE } from "../../../../utils/staticSite";
import { EVENT_ID } from "../entities/npcs/npc-constants";
import { type GameEvent } from "../entities/npcs/npc-types";
import {
  appendGameworldActivityEntry,
  recordInteractionCompletedForFlag,
} from "../gameworldLocalState";
import { type InteractionState } from "../types";
import {
  FLAG_TO_GATE_MAP,
  FLAG_TO_INTERACTION_MAP,
  FLAGS_NOT_TO_SAVE,
  LEVEL_NAME,
  STORAGE_KEYS,
  STORY_FLAG,
} from "./constants";
import { CUSTOM_EVENTS, EVENT_BUS } from "./event-bus";
import { logger } from "./logger";
import { type LevelName } from "./types";

export type PlayerData = {
  currentArea: {
    level: LevelName;
    roomId: number;
    doorId: number;
  };
  // Per room data
  areaDetails: Record<
    LevelName,
    Record<
      number,
      {
        doors: Record<
          string,
          {
            unlocked: boolean;
          }
        >;
      }
    >
  >;
  // Per level data
  levelDetails: Record<
    LevelName,
    {
      switches: Record<
        string,
        {
          activated: boolean;
        }
      >;
      minesweepers: Record<
        string,
        {
          completed: boolean;
        }
      >;
      deliveryBoxes: Record<
        string,
        {
          completed: boolean;
        }
      >;
    }
  >;
  viewedNpcEvents: Set<string>;
  storyFlags: Map<string, string>;
  frontendFlags: Map<string, string>;
};

export const DATA_MANAGER_REGISTRY_KEY = "gameworldDataManager";

export function attachDataManagerToGame(
  game: Phaser.Game,
  manager: DataManager,
): void {
  game.registry.set(DATA_MANAGER_REGISTRY_KEY, manager);
}

export function detachDataManagerFromGame(
  game: Phaser.Game,
  manager: DataManager,
): void {
  const existing = game.registry.get(DATA_MANAGER_REGISTRY_KEY) as
    | DataManager
    | undefined;
  if (existing === manager) {
    game.registry.remove(DATA_MANAGER_REGISTRY_KEY);
  }
}

export function getSceneDataManager(scene: Phaser.Scene): DataManager {
  const manager = scene.registry.get(DATA_MANAGER_REGISTRY_KEY) as
    | DataManager
    | undefined;
  if (!manager) {
    throw new Error(
      "Gameworld data manager has not been registered on this scene",
    );
  }
  return manager;
}

export class DataManager {
  #data: PlayerData;
  // All NPC exclamations dismissed for the current session (includes temp + permanent).
  #dismissedNpcExclamations: Set<string>;
  // Subset of dismissed exclamations that should persist between sessions.
  #persistentDismissedNpcExclamations: Set<string>;
  #persistentViewedEvents: Set<string>;
  #eventsOverride: Map<string, GameEvent[]>;

  constructor(initialData?: PlayerData) {
    this.#data = initialData ?? {
      currentArea: {
        level: LEVEL_NAME.MOUNTAIN,
        roomId: 1,
        doorId: 1,
      },
      areaDetails: this.#initializeAreaDetails(),
      levelDetails: this.#initializeLevelDetails(),
      viewedNpcEvents: new Set(),
      storyFlags: new Map(),
      frontendFlags: new Map(),
    };
    this.#data.storyFlags = this.#loadStoryFlagsFromStorage(
      this.#data.storyFlags,
    );
    this.#persistentDismissedNpcExclamations =
      this.#loadDismissedNpcExclamations();
    this.#dismissedNpcExclamations = new Set(
      this.#persistentDismissedNpcExclamations,
    );
    this.#persistentViewedEvents = this.#loadPersistentViewedEvents();
    this.#persistentViewedEvents.forEach((eventId) => {
      this.#data.viewedNpcEvents.add(eventId);
    });
    this.#eventsOverride = new Map<string, GameEvent[]>();
    this.#persistStoryFlags();
  }

  #initializeAreaDetails(): PlayerData["areaDetails"] {
    const areaDetails: PlayerData["areaDetails"] =
      {} as PlayerData["areaDetails"];

    // Initialize all level names with empty objects
    Object.values(LEVEL_NAME).forEach((levelName) => {
      areaDetails[levelName as LevelName] = {};
    });

    return areaDetails;
  }

  #initializeLevelDetails(): PlayerData["levelDetails"] {
    const levelDetails: PlayerData["levelDetails"] =
      {} as PlayerData["levelDetails"];

    // Initialize all level names.
    Object.values(LEVEL_NAME).forEach((levelName) => {
      levelDetails[levelName as LevelName] = {
        switches: {},
        minesweepers: {},
        deliveryBoxes: {},
      };
    });

    return levelDetails;
  }

  get data(): PlayerData {
    return this.#data;
  }

  set data(data: PlayerData) {
    this.#data = data;
    this.#persistStoryFlags();
  }

  public setEventsOverride(sequenceId: string, events: GameEvent[]): void {
    this.#eventsOverride.set(sequenceId, events);
  }

  public getEventsOverride(sequenceId: string): GameEvent[] | undefined {
    return this.#eventsOverride.get(sequenceId);
  }

  // Check if story flags match specific enum values
  public hasStoryFlagValues(
    requiredFlags: Record<string, string | string[]>,
  ): boolean {
    return Object.entries(requiredFlags).every(([flag, requiredValue]) => {
      const flagValue = this.getFlagValue(flag);
      if (Array.isArray(requiredValue)) {
        return requiredValue.includes(flagValue || "");
      }
      return flagValue === requiredValue;
    });
  }

  // Check if story flags do NOT match specific enum values
  public hasStoryFlagValuesNot(
    excludedFlags: Record<string, string | string[]>,
  ): boolean {
    return Object.entries(excludedFlags).every(([flag, excludedValue]) => {
      const flagValue = this.getFlagValue(flag);
      if (Array.isArray(excludedValue)) {
        return !excludedValue.includes(flagValue || "");
      }
      return flagValue !== excludedValue;
    });
  }

  /**
   * Set a flag value. This only sets the flag and does NOT complete any associated interaction.
   * Use setFlagCompleted and completeInteraction separately if you want to also complete the interaction.
   *
   * @param flag - The story flag to set
   * @param value - The value to set
   */
  public setFlagValue(flag: string, value: string): void {
    // Check if this is a supported story flag and warn if not
    const supportedFlags = Object.values(STORY_FLAG) as string[];
    if (!supportedFlags.includes(flag)) {
      console.warn(
        `Warning: Using unsupported story flag "${flag}". Supported flags are: ${supportedFlags.join(", ")}`,
      );
    }

    this.#data.storyFlags.set(flag, value);
    this.#persistStoryFlags();
    EVENT_BUS.emit(CUSTOM_EVENTS.REFRESH_LEVEL_OBJECTS);
  }

  /**
   * Complete the interaction associated with a flag.
   * This only completes the interaction via the API; it does not set the flag.
   * Use setFlagCompleted separately if you want to also set the flag.
   *
   * @param flag - The story flag whose associated interaction should be completed
   */
  public completeInteraction(flag: string): void {
    // Check if there's an associated interaction to complete
    const interactionId =
      FLAG_TO_INTERACTION_MAP[flag as keyof typeof FLAG_TO_INTERACTION_MAP];
    if (!interactionId) {
      logger.info(`No interaction found for flag ${flag}`);
      return;
    }

    if (IS_STATIC_SITE) {
      recordInteractionCompletedForFlag(flag);
      this.setFlagToCompleted(flag);
      EVENT_BUS.emit(CUSTOM_EVENTS.REFRESH_LEVEL_OBJECTS);
      return;
    }

    // Fire and forget - complete the interaction asynchronously
    void (async () => {
      try {
        const client = newClient(apiUrl(), undefined);
        const response = await client.completeInteraction({
          params: { interactionId },
          body: {},
        });

        if (response.status === 200) {
          EVENT_BUS.emit(CUSTOM_EVENTS.REFRESH_LEVEL_OBJECTS);
          logger.event(
            `Successfully completed interaction ${interactionId} for flag ${flag}`,
          );
        } else {
          console.error(
            `Failed to complete interaction ${interactionId}: ${response.status}`,
          );
        }
      } catch (error) {
        console.error(
          `Error completing interaction ${interactionId} for flag ${flag}:`,
          error,
        );
      }
    })();
  }

  /**
   * Set a flag to "completed" without completing any associated interaction.
   * Use completeInteraction separately if you want to also complete the interaction.
   */
  public setFlagToCompleted(flag: string): void {
    this.setFlagValue(flag, "completed");
  }

  /**
   * Clear one or more story flags entirely.
   */
  public clearFlags(flags: string[]): void {
    let updated = false;
    flags.forEach((flag) => {
      if (this.#data.storyFlags.has(flag)) {
        this.#data.storyFlags.delete(flag);
        updated = true;
      }
    });

    if (updated) {
      this.#persistStoryFlags();
      EVENT_BUS.emit(CUSTOM_EVENTS.REFRESH_LEVEL_OBJECTS);
    }
  }

  /**
   * Get flag value (for enum-based flags)
   */
  public getFlagValue(flag: string): string | null {
    return this.#data.storyFlags.get(flag) || null;
  }

  /**
   * Get flags as a simple object for debugging
   */
  public getFlagsObject(): Record<string, string> {
    const result: Record<string, string> = {};
    // Get all flags that are set
    this.#data.storyFlags.forEach((value, flag) => {
      result[flag] = value;
    });

    return result;
  }

  /**
   * Update flags based on interaction state
   */
  public updateFromInteractionState(interactionState: InteractionState): void {
    // Update story flags based on interaction state
    // These flags store the actual state value (locked/unlockable/unlocked/complete)

    // Process all expected interactions, not just the ones that exist in the current state
    Object.keys(FLAG_TO_INTERACTION_MAP).forEach((flag) => {
      const storyFlag = STORY_FLAG[flag as keyof typeof STORY_FLAG];
      const currentFlagValue = this.getFlagValue(storyFlag);
      const interactionId =
        FLAG_TO_INTERACTION_MAP[flag as keyof typeof FLAG_TO_INTERACTION_MAP];

      if (!storyFlag || !interactionId) {
        logger.event(
          `No story flag or interaction ID found for flag ${flag}, skipping`,
        );
        return;
      }

      const interaction = interactionState.interactions?.[interactionId];
      if (!interaction) {
        if (!currentFlagValue) {
          logger.event(`Setting flag ${storyFlag} to unlocked`);
          this.setFlagValue(storyFlag, "unlocked");
        }
        return;
      }

      if (interaction.state === "completed") {
        logger.event(`Setting flag ${storyFlag} to complete`);
        this.setFlagValue(storyFlag, "completed");
      } else if (
        interaction.state === "running" ||
        interaction.state === "unlocked"
      ) {
        logger.event(`Setting flag ${storyFlag} to unlocked`);
        this.setFlagValue(storyFlag, "unlocked");
      }
    });

    Object.keys(FLAG_TO_GATE_MAP).forEach((flag) => {
      const storyFlag = STORY_FLAG[flag as keyof typeof STORY_FLAG];
      const gateSlug = FLAG_TO_GATE_MAP[flag as keyof typeof FLAG_TO_GATE_MAP];
      if (!storyFlag || !gateSlug) {
        return;
      }

      const currentFlagValue = this.getFlagValue(storyFlag);
      const gateState = interactionState.gates?.[gateSlug];

      if (gateState?.satisfied) {
        if (currentFlagValue !== "completed") {
          logger.event(`Setting gate flag ${storyFlag} to complete`);
          this.setFlagValue(storyFlag, "completed");
        }
      } else if (!currentFlagValue) {
        logger.event(`Setting gate flag ${storyFlag} to unlocked`);
        this.setFlagValue(storyFlag, "unlocked");
      }
    });

    // Update client-side only flags
    const dogKeyTransferState = this.getFlagValue(STORY_FLAG.dog_key_transfer);

    if (dogKeyTransferState === "completed") {
      this.setFlagValue(STORY_FLAG.dog_key_pickup, "completed");
    } else {
      this.setFlagValue(STORY_FLAG.dog_key_pickup, "unlocked");
    }
  }

  // Force specific events to be available until required flags are completed
  #shouldForceEvent(eventId: string): boolean {
    if (
      eventId === EVENT_ID.WESTERN_INTRO ||
      eventId === EVENT_ID.HEDGES_INTRO ||
      eventId === EVENT_ID.CAMPGROUND_INTRO
    ) {
      return this.getFlagValue(STORY_FLAG.received_hoe) !== "completed";
    }
    if (
      eventId === EVENT_ID.CEMETERY_INTRO ||
      eventId === EVENT_ID.AVIARIA_INTRO
    ) {
      return this.getFlagValue(STORY_FLAG.received_lute) !== "completed";
    }
    if (eventId === EVENT_ID.SHORE_INTRO) {
      return (
        this.getFlagValue(STORY_FLAG.received_fishing_reel) !== "completed"
      );
    }
    return false;
  }

  public hasEventId(eventId: string): boolean {
    this.#warnIfUnsupportedEvent(eventId);

    if (this.#shouldForceEvent(eventId)) {
      return false;
    }

    return this.#data.viewedNpcEvents.has(eventId);
  }

  public markEventViewed(
    eventId: string,
    options?: { persist?: boolean },
  ): void {
    this.#warnIfUnsupportedEvent(eventId);
    this.#data.viewedNpcEvents.add(eventId);

    if (options?.persist) {
      if (this.#persistentViewedEvents.has(eventId)) {
        return;
      }
      this.#persistentViewedEvents.add(eventId);
      this.#persistPersistentViewedEvents();
    }
  }

  public hasDismissedNpcExclamation(npcId: string): boolean {
    return this.#dismissedNpcExclamations.has(npcId);
  }

  public dismissNpcExclamation(npcId: string, permanently = false): void {
    const alreadyDismissed = this.#dismissedNpcExclamations.has(npcId);
    if (!alreadyDismissed) {
      this.#dismissedNpcExclamations.add(npcId);
    }

    if (permanently) {
      if (!this.#persistentDismissedNpcExclamations.has(npcId)) {
        this.#persistentDismissedNpcExclamations.add(npcId);
        this.#persistDismissedNpcExclamations();
      }
    }
  }

  public undismissNpcExclamation(npcId: string): boolean {
    const removed = this.#dismissedNpcExclamations.delete(npcId);
    const removedPersisted =
      this.#persistentDismissedNpcExclamations.delete(npcId);
    if (removedPersisted) {
      this.#persistDismissedNpcExclamations();
    }
    return removed;
  }

  public updateAreaData(area: LevelName, roomId: number, doorId: number): void {
    this.#data.currentArea = {
      level: area,
      roomId,
      doorId,
    };
  }

  public updateDoorData(
    roomId: number,
    doorId: number,
    unlocked: boolean,
  ): void {
    this.#populateDefaultRoomData(roomId);
    this.#data.areaDetails[this.#data.currentArea.level][roomId].doors[
      doorId.toString()
    ] = {
      unlocked,
    };
  }

  #populateDefaultRoomData(roomId: number): void {
    if (
      this.#data.areaDetails[this.#data.currentArea.level][roomId] === undefined
    ) {
      this.#data.areaDetails[this.#data.currentArea.level][roomId] = {
        doors: {},
      };
    }
  }

  /**
   * Deliver a deliverable to a delivery box via API
   */
  public async deliverDeliverable(
    deliverableId: string,
    frame: string,
  ): Promise<void> {
    const level = this.#data.currentArea.level;

    if (IS_STATIC_SITE) {
      appendGameworldActivityEntry({
        type: "deliverable_consumed",
        level,
        object_id: deliverableId,
        frame,
      });
      return;
    }

    try {
      const client = newClient(apiUrl());
      await client.deliverDeliverable({
        params: { level },
        body: {
          deliverable_id: deliverableId,
          frame: frame,
        },
      });
    } catch (error) {
      console.error("Failed to deliver deliverable:", error);
      throw error;
    }
  }

  /**
   * Get activated switches for a specific level
   */
  public getActivatedSwitches(level: string): number[] {
    const levelData = this.#data.levelDetails[level as LevelName];
    if (!levelData?.switches) {
      return [];
    }

    const activatedSwitches: number[] = [];
    for (const [switchId, switchData] of Object.entries(levelData.switches)) {
      if (switchData.activated) {
        activatedSwitches.push(parseInt(switchId));
      }
    }
    return activatedSwitches;
  }

  /**
   * Activate a switch in a specific level
   */
  public activateSwitch(level: string, switchId: number): void {
    const levelData = this.#data.levelDetails[level as LevelName];
    if (levelData) {
      levelData.switches[switchId.toString()] = {
        activated: true,
      };
    }
  }

  public hasFrontendFlagValues(requiredFlags: Record<string, string>): boolean {
    return Object.entries(requiredFlags).every(([flag, requiredValue]) => {
      return this.#data.frontendFlags.get(flag) === requiredValue;
    });
  }

  public setFrontendFlag(flag: string, value: string): void {
    this.#data.frontendFlags.set(flag, value);
    EVENT_BUS.emit(CUSTOM_EVENTS.FRONTEND_FLAG_CHANGED, { flag, value });
  }

  /**
   * Get completed minesweepers for a specific level
   */
  public getCompletedMinesweepers(level: string): number[] {
    const levelData = this.#data.levelDetails[level as LevelName];
    if (!levelData?.minesweepers) {
      return [];
    }

    const completedMinesweepers: number[] = [];
    for (const [minesweeperId, minesweeperData] of Object.entries(
      levelData.minesweepers,
    )) {
      if (minesweeperData.completed) {
        completedMinesweepers.push(parseInt(minesweeperId));
      }
    }
    return completedMinesweepers;
  }

  /**
   * Mark a minesweeper as completed in a specific level
   */
  public completeMinesweeper(minesweeperId: number): void {
    if (minesweeperId === 3) {
      this.setFlagToCompleted(STORY_FLAG.minesweeper3);
    } else if (minesweeperId === 4) {
      this.setFlagToCompleted(STORY_FLAG.minesweeper4);
    } else if (minesweeperId === 5) {
      this.setFlagToCompleted(STORY_FLAG.minesweeper5);
    }
  }

  /**
   * Get completed delivery boxes for a specific level
   */
  public getCompletedDeliveryBoxes(level: string): number[] {
    const levelData = this.#data.levelDetails[level as LevelName];
    if (!levelData?.deliveryBoxes) {
      return [];
    }

    const completedDeliveryBoxes: number[] = [];
    for (const [deliveryBoxId, deliveryBoxData] of Object.entries(
      levelData.deliveryBoxes,
    )) {
      if (deliveryBoxData.completed) {
        completedDeliveryBoxes.push(parseInt(deliveryBoxId));
      }
    }
    return completedDeliveryBoxes;
  }

  /**
   * Mark a delivery box as completed in a specific level
   */
  public completeDeliveryBox(level: string, deliveryBoxId: number): void {
    const levelData = this.#data.levelDetails[level as LevelName];
    if (levelData) {
      levelData.deliveryBoxes[deliveryBoxId.toString()] = {
        completed: true,
      };
    }
  }

  #loadStoryFlagsFromStorage(
    baseFlags?: Map<string, string>,
  ): Map<string, string> {
    const flags = baseFlags ? new Map(baseFlags) : new Map<string, string>();

    if (typeof window === "undefined" || !window.localStorage) {
      return flags;
    }

    try {
      const stored = window.localStorage.getItem(STORAGE_KEYS.STORY_FLAGS);
      if (!stored) {
        return flags;
      }

      const parsed = JSON.parse(stored) as Record<string, unknown>;
      if (parsed && typeof parsed === "object") {
        Object.entries(parsed).forEach(([key, value]) => {
          if (typeof value === "string") {
            flags.set(key, value);
          }
        });
      }
    } catch (error) {
      console.warn("Failed to load story flags", error);
    }

    return flags;
  }

  #persistStoryFlags(): void {
    if (typeof window === "undefined" || !window.localStorage) {
      return;
    }

    try {
      // Filter out flags that should not be saved to local storage
      const flagsToSave = Array.from(this.#data.storyFlags.entries()).filter(
        ([key]) => !FLAGS_NOT_TO_SAVE.has(key),
      );
      const serialized = JSON.stringify(Object.fromEntries(flagsToSave));
      window.localStorage.setItem(STORAGE_KEYS.STORY_FLAGS, serialized);
    } catch (error) {
      console.warn("Failed to persist story flags", error);
    }
  }

  #loadDismissedNpcExclamations(): Set<string> {
    if (typeof window === "undefined" || !window.localStorage) {
      return new Set();
    }

    try {
      const stored = window.localStorage.getItem(
        STORAGE_KEYS.DISMISSED_NPC_EXCLAMATIONS,
      );
      if (!stored) {
        return new Set();
      }

      const parsed = JSON.parse(stored) as string[];
      if (Array.isArray(parsed)) {
        return new Set(parsed);
      }
    } catch (error) {
      console.warn("Failed to load dismissed NPC exclamations", error);
    }

    return new Set();
  }

  #persistDismissedNpcExclamations(): void {
    if (typeof window === "undefined" || !window.localStorage) {
      return;
    }

    try {
      const serialized = JSON.stringify([
        ...this.#persistentDismissedNpcExclamations.values(),
      ]);
      window.localStorage.setItem(
        STORAGE_KEYS.DISMISSED_NPC_EXCLAMATIONS,
        serialized,
      );
    } catch (error) {
      console.warn("Failed to persist dismissed NPC exclamations", error);
    }
  }

  #loadPersistentViewedEvents(): Set<string> {
    if (typeof window === "undefined" || !window.localStorage) {
      return new Set();
    }

    try {
      const stored = window.localStorage.getItem(STORAGE_KEYS.VIEWED_EVENT_IDS);
      if (!stored) {
        return new Set();
      }

      const parsed = JSON.parse(stored) as unknown;
      if (Array.isArray(parsed)) {
        const eventIds = parsed.filter(
          (eventId): eventId is string => typeof eventId === "string",
        );
        return new Set(eventIds);
      }
    } catch (error) {
      console.warn("Failed to load viewed event IDs", error);
    }

    return new Set();
  }

  #persistPersistentViewedEvents(): void {
    if (typeof window === "undefined" || !window.localStorage) {
      return;
    }

    try {
      const serialized = JSON.stringify([
        ...this.#persistentViewedEvents.values(),
      ]);
      window.localStorage.setItem(STORAGE_KEYS.VIEWED_EVENT_IDS, serialized);
    } catch (error) {
      console.warn("Failed to persist viewed event IDs", error);
    }
  }

  #warnIfUnsupportedEvent(eventId: string): void {
    const supportedEventIds = Object.values(EVENT_ID) as string[];
    if (!supportedEventIds.includes(eventId)) {
      console.warn(
        `Warning: Using unsupported event ID "${eventId}". Supported event IDs are: ${supportedEventIds.join(", ")}`,
      );
    }
  }
}
