import React, { useMemo } from "react";
import {
  type AllPuzzlesRound,
  type AllPuzzlesState,
} from "../../client/all_puzzles_types";
import { type BaseTaskDisplay } from "../../rounds/types";
import { PuzzleRow } from "../AllPuzzlesList";
import PuzzleCard from "../PuzzleAndTaskDisplay/PuzzleCard";
import { RoundFolder } from "../PuzzleAndTaskDisplay/RoundFolder";
import { type Style } from "../PuzzleAndTaskDisplay/useFolderHeights";

const STATIC_FOLDER_STYLE: Style = {
  height: "auto",
  sticky: false,
  marginTop: 0,
};

const getStaticStyle = () => STATIC_FOLDER_STYLE;

type OverworldTaskListProps = {
  tasks: BaseTaskDisplay[];
  roundName: string;
};

const OverworldTaskList = ({ tasks, roundName }: OverworldTaskListProps) => {
  const unlockedTasks = tasks.filter((task) => task.state === "unlocked");
  const hasTasks = tasks.length > 0;

  const folderRound = useMemo<AllPuzzlesRound>(
    () => ({
      slug: "research_tasks",
      title: "Research Tasks",
      puzzles: unlockedTasks.map((task) => ({
        slug: task.slug,
        title: task.title,
        desc: task.desc,
        state: task.state,
        answer: task.answer,
        unlock_cost: undefined,
        nsfw: false,
        is_overworld_feeder: false,
        round_slug: "research_tasks",
      })),
      is_overworld_round: false,
    }),
    [unlockedTasks],
  );

  const folderState = useMemo<AllPuzzlesState>(
    () => ({
      epoch: 0,
      rounds: [folderRound],
      currency: 0,
    }),
    [folderRound],
  );

  const wrapper = (children: React.ReactNode) => (
    <div className="w-full flex justify-center pb-8 mt-4">
      <div className="w-full max-w-screen-lg px-4">{children}</div>
    </div>
  );

  if (unlockedTasks.length === 0) {
    const message = hasTasks
      ? `Unlock research tasks in ${roundName} to see them here.`
      : `No research tasks are currently assigned to ${roundName}.`;
    return wrapper(
      <RoundFolder
        round={folderRound}
        count={unlockedTasks.length}
        index={0}
        getStyle={getStaticStyle}
        state={folderState}
        href="/research_tasks"
      >
        <div className="w-full px-3 pb-3">
          <p className="text-lg text-neutral-800 italic text-center w-full">
            {message}
          </p>
        </div>
      </RoundFolder>,
    );
  }

  return wrapper(
    <RoundFolder
      variant="overworld"
      round={folderRound}
      count={unlockedTasks.length}
      index={0}
      getStyle={getStaticStyle}
      state={folderState}
      href="/research_tasks"
    >
      <div className="w-full px-3 pb-3">
        <div className="flex flex-col gap-3 w-full">
          {unlockedTasks.map((task) => (
            <PuzzleRow key={task.slug} bolded={false}>
              <PuzzleCard
                lockState={task.state}
                title={task.title}
                slug={task.slug}
                desc={task.desc ?? ""}
                solved={task.solved}
                prize={task.prize}
                prizeMax={task.prizeMax}
                is_overworld_feeder={false}
                submissionType={task.submissionType}
                taskSubmissionState={task.taskSubmissionState}
              />
            </PuzzleRow>
          ))}
        </div>
      </div>
    </RoundFolder>,
  );
};

export default OverworldTaskList;
