import { isCustomObject } from "../common/utils";
import { BaseGameObjectComponent } from "./base-game-object";

export class DiggableComponent extends BaseGameObjectComponent {
  #isBuried = true;

  public isBuried(): boolean {
    return this.#isBuried;
  }

  public unbury(): void {
    this.#isBuried = false;
    if (isCustomObject(this.gameObject)) {
      this.gameObject.enableObject();
    }
  }

  public reset(): void {
    this.#isBuried = true;
    if (isCustomObject(this.gameObject)) {
      this.gameObject.disableObject();
    }
  }
}
