import { type LevelName } from "../common/types";
import { type SCENE_KEYS } from "./scene-keys";

const LEVEL_TO_SCENE_KEY: Record<LevelName, keyof typeof SCENE_KEYS> = {
  CAMPGROUND: "ELAND_ISLANDS_GAME_SCENE",
  CARDINAL_ISLAND: "GLITCH_GAME_SCENE",
  CAT_CATSLE: "KITTY_CITY_GAME_SCENE",
  CEMETERY: "ELDER_DRIFTS_GAME_SCENE",
  CITY: "THE_BRIGHTS_GAME_SCENE",
  HEBI: "SERPENTINE_HILLS_GAME_SCENE",
  HEDGE: "ROYAL_GROVES_GAME_SCENE",
  MOUNTAIN: "AVIARIA_GAME_SCENE",
  SHORE: "BUBBLE_COVE_GAME_SCENE",
  WESTERN: "OLD_BARK_TOWN_GAME_SCENE",
};

export const getSceneKeyForLevel = (
  level: LevelName,
): keyof typeof SCENE_KEYS => {
  return LEVEL_TO_SCENE_KEY[level];
};
