import { DIRECTION } from "../../../common/constants";
import { isArcadePhysicsBody } from "../../../common/utils";
import { type CharacterObject } from "../../../entities/common/character-object";
import { HeldObjectComponent } from "../../held-object-component";
import { BaseMoveState } from "./base-move-state";
import { CHARACTER_STATES } from "./character-states";
import { handleInteraction } from "./interaction-utils";

export class MoveHoldingState extends BaseMoveState {
  constructor(gameObject: CharacterObject) {
    super(CHARACTER_STATES.MOVE_HOLDING_STATE, gameObject, "WALK_HOLD");
  }

  public onEnter(): void {
    this._gameObject.animationComponent.playAnimation(
      `IDLE_${this._gameObject.direction}`,
    );

    if (isArcadePhysicsBody(this._gameObject.body)) {
      this._gameObject.body.setVelocity(0, 0);
    }
  }

  public onUpdate(): void {
    const controls = this._gameObject.controls;
    const heldComponent = HeldObjectComponent.getComponent<HeldObjectComponent>(
      this._gameObject,
    );

    if (
      handleInteraction(this._gameObject, this._stateMachine, controls, {
        isHolding: true,
        heldComponent,
      })
    ) {
      return;
    }

    if (this.isNoMoveInput(controls)) {
      this._stateMachine.setState(CHARACTER_STATES.IDLE_HOLDING_STATE);
      return;
    }

    this.handleCharacterMovement();

    if (heldComponent?.object === undefined) {
      this._stateMachine.setState(CHARACTER_STATES.IDLE_STATE);
      return;
    }

    if (this._gameObject.direction === DIRECTION.DOWN) {
      heldComponent.object.setPosition(
        this._gameObject.x + 1,
        this._gameObject.y - 2,
      );
    } else if (this._gameObject.direction === DIRECTION.UP) {
      heldComponent.object.setPosition(
        this._gameObject.x + 1,
        this._gameObject.y - 6,
      );
    } else {
      heldComponent.object.setPosition(
        this._gameObject.x,
        this._gameObject.y - 8,
      );
    }
    if (this._gameObject.flipX) {
      heldComponent.object.setX(this._gameObject.x);
    }
  }
}
