import { DEBUG_PROXIMITY_DETECTION } from "../common/config";
import type { InteractiveGameObject } from "../common/types";

export type ProximityDebugWindow = {
  getProximityRadius: () => number | undefined;
  setProximityRadius: (radius: number) => void;
  printInteractiveObjects: () => void;
};

export class ProximityDebugManager {
  private static instance: ProximityDebugManager;
  private player:
    | {
        getProximityDetectionRadius: () => number;
        setProximityDetectionRadius: (radius: number) => void;
      }
    | undefined;
  private currentRoomObjects: InteractiveGameObject[] = [];

  private constructor() {
    // Private constructor for singleton
  }

  public static getInstance(): ProximityDebugManager {
    if (!ProximityDebugManager.instance) {
      ProximityDebugManager.instance = new ProximityDebugManager();
    }
    return ProximityDebugManager.instance;
  }

  public initialize(player: {
    getProximityDetectionRadius: () => number;
    setProximityDetectionRadius: (radius: number) => void;
  }): void {
    this.player = player;
    this.setupDebugWindow();
  }

  public updateRoomObjects(objects: InteractiveGameObject[]): void {
    this.currentRoomObjects = objects;
  }

  private setupDebugWindow(): void {
    if (!DEBUG_PROXIMITY_DETECTION) {
      return;
    }

    const debugWindow = window as unknown as ProximityDebugWindow;

    debugWindow.getProximityRadius = () => this.getProximityRadius();
    debugWindow.setProximityRadius = (radius: number) => {
      this.setProximityRadius(radius);
    };
    debugWindow.printInteractiveObjects = () => {
      this.printInteractiveObjects();
    };

    console.log(
      "Proximity Debug methods available (DEBUG_PROXIMITY_DETECTION enabled):",
    );
    console.log("  window.getProximityRadius() - get current detection radius");
    console.log(
      "  window.setProximityRadius(radius) - set detection radius (default: 24)",
    );
    console.log(
      "  window.printInteractiveObjects() - print all interactive objects in current room",
    );
  }

  // Debug toggle methods removed - use DEBUG_PROXIMITY_DETECTION in config.ts instead

  private getProximityRadius(): number | undefined {
    return this.player?.getProximityDetectionRadius();
  }

  private setProximityRadius(radius: number): void {
    this.player?.setProximityDetectionRadius(radius);
  }

  private printInteractiveObjects(): void {
    if (this.currentRoomObjects.length === 0) {
      console.log("No interactive objects in current room");
      return;
    }

    console.log(
      `\n=== Interactive Objects in Current Room (${this.currentRoomObjects.length} total) ===`,
    );

    // Group objects by type
    const objectsByType = this.currentRoomObjects.reduce<
      Record<string, InteractiveGameObject[]>
    >((acc, obj) => {
      const type = obj.constructor.name;
      if (!acc[type]) {
        acc[type] = [];
      }
      acc[type].push(obj);
      return acc;
    }, {});

    // Print each type
    Object.entries(objectsByType).forEach(([type, objects]) => {
      console.log(`\n${type}s (${objects.length}):`);
      objects.forEach((obj, index) => {
        const id = this.getObjectId(obj);
        console.log(
          `  ${index + 1}. ${type} ${id} at (${Math.round(obj.x)}, ${Math.round(obj.y)})`,
        );
      });
    });

    console.log(
      `\n=== Total Interactive Objects: ${this.currentRoomObjects.length} ===\n`,
    );
  }

  private getObjectId(obj: InteractiveGameObject): string {
    if (obj && typeof obj === "object" && "id" in obj) {
      const id = (obj as { id: string | number }).id;
      return String(id);
    }
    return "unknown";
  }
}
