import { type CharacterObject } from "../../../entities/common/character-object";
import { BaseMoveState } from "./base-move-state";
import { CHARACTER_STATES } from "./character-states";
import { handleInteraction } from "./interaction-utils";

export class MoveState extends BaseMoveState {
  constructor(gameObject: CharacterObject) {
    super(CHARACTER_STATES.MOVE_STATE, gameObject, "WALK");
  }

  public onEnter(): void {
    if (this._gameObject.touchingRock()) {
      this._stateMachine.setState(CHARACTER_STATES.ROCK_JUMP_STATE);
      return;
    }
    if (this._gameObject.isOnIce()) {
      this.updateDirectionFromInput();
      this._stateMachine.setState(CHARACTER_STATES.ICE_MOVE_STATE);
      return;
    }
  }

  public onUpdate(): void {
    const controls = this._gameObject.controls;

    if (!controls.isMovementLocked && controls.isUseJustDown) {
      this._stateMachine.setState(CHARACTER_STATES.USE_ITEM_STATE);
      return;
    }

    // Check if player is on a rock and should transition to rock jumping
    if (this._gameObject.touchingRock()) {
      this._stateMachine.setState(CHARACTER_STATES.ROCK_JUMP_STATE);
      return;
    }

    // Check if player is on ice and should transition to ice movement
    if (this._gameObject.isOnIceStairs()) {
      // Update player direction based on input before transitioning to ice stairs
      this.updateDirectionFromInput();
      this._stateMachine.setState(CHARACTER_STATES.ICE_STAIRS_MOVE_STATE);
      return;
    }
    if (this._gameObject.isOnIce()) {
      // Update player direction based on input before transitioning to ice
      this.updateDirectionFromInput();
      this._stateMachine.setState(CHARACTER_STATES.ICE_MOVE_STATE);
      return;
    }

    if (this.isNoMoveInput(controls)) {
      this._stateMachine.setState(CHARACTER_STATES.IDLE_STATE);
      return;
    }

    if (handleInteraction(this._gameObject, this._stateMachine, controls)) {
      return;
    }
    this.handleCharacterMovement();
  }
}
