import * as Phaser from "phaser";
import { ASSET_KEYS, BUTTON_FRAME_KEYS } from "../../common/assets";
import {
  getSceneDataManager,
  type DataManager,
} from "../../common/data-manager";
import { SWITCH_TEXTURE } from "../../common/tiled/constants";
import type { SwitchAction, TiledSwitchObject } from "../../common/tiled/types";
import type { CustomObject, LevelName } from "../../common/types";

type ButtonPressedEvent = {
  action: SwitchAction;
  targetIds: number[];
};

export class Switch
  extends Phaser.Physics.Arcade.Image
  implements CustomObject
{
  #switchTargetIds: number[];
  #switchAction: SwitchAction;
  #switchId: number;
  #isActivated: boolean;
  #dataManager: DataManager;

  constructor(
    scene: Phaser.Scene,
    config: TiledSwitchObject,
    level: LevelName,
  ) {
    const frame =
      config.texture === SWITCH_TEXTURE.FLOOR
        ? BUTTON_FRAME_KEYS.FLOOR_SWITCH
        : BUTTON_FRAME_KEYS.PLATE_SWITCH;
    super(scene, config.x, config.y, ASSET_KEYS.DUNGEON_OBJECTS, frame);

    scene.add.existing(this);
    scene.physics.add.existing(this);
    this.setOrigin(0, 0).setImmovable(true);

    this.#switchTargetIds = config.targetIds;
    this.#switchAction = config.action;
    this.#switchId = config.id;
    this.#isActivated = false;
    this.#dataManager = getSceneDataManager(scene);

    // Check if this switch has already been activated
    const activatedSwitches = this.#dataManager.getActivatedSwitches(level);
    if (activatedSwitches.includes(config.id)) {
      this.trigger(level);
    }
    this.disableObject();
  }

  public trigger(level: LevelName): ButtonPressedEvent {
    // For PLATE switches, show pressed state instead of disabling
    if (
      this.texture.key === ASSET_KEYS.DUNGEON_OBJECTS &&
      this.frame.name === BUTTON_FRAME_KEYS.FLOOR_SWITCH
    ) {
      this.disableObject();
    } else if (
      this.texture.key === ASSET_KEYS.DUNGEON_OBJECTS &&
      this.frame.name === BUTTON_FRAME_KEYS.PLATE_SWITCH
    ) {
      this.setFrame(BUTTON_FRAME_KEYS.PLATE_SWITCH_PRESSED);
      this.disableTrigger();
    }

    // Update DataManager with the activated switch
    this.#dataManager.activateSwitch(level, this.#switchId);
    this.#isActivated = true;

    return {
      action: this.#switchAction,
      targetIds: this.#switchTargetIds,
    };
  }

  public get switchId(): number {
    return this.#switchId;
  }

  public disableObject(): void {
    (this.body as Phaser.Physics.Arcade.Body).enable = false;
    this.active = false;
    this.visible = false;
  }

  public enableObject(): void {
    this.visible = true;
    // if activated return early
    if (this.#isActivated) {
      return;
    }
    (this.body as Phaser.Physics.Arcade.Body).enable = true;
    this.active = true;
  }

  public disableTrigger(): void {
    // Disable physics body but keep object visible for pressed state
    (this.body as Phaser.Physics.Arcade.Body).enable = false;
    this.active = false;
    this.visible = true;
  }
}
