import { type CharacterObject } from "../../../entities/common/character-object";
import { BaseCharacterState } from "./base-character-state";
import { CHARACTER_STATES } from "./character-states";

export class PacingState extends BaseCharacterState {
  constructor(gameObject: CharacterObject) {
    super(CHARACTER_STATES.PACING_STATE, gameObject);
  }

  public onEnter(): void {
    this._gameObject.animationComponent.playAnimation(
      `IDLE_${this._gameObject.direction}`,
    );

    const speed = this._gameObject.speed;
    this._gameObject.setVelocity(
      this._gameObject.direction === "LEFT" ? -1 * speed : speed,
      0,
    );
    this._gameObject.setFlipX(this._gameObject.direction === "LEFT");
    this._gameObject.setBounce(1);
  }
}
