import { type CharacterObject } from "../../../entities/common/character-object";
import { HeldObjectComponent } from "../../held-object-component";
import { ThrowableObjectComponent } from "../../throwable-object-component";
import { BaseCharacterState } from "./base-character-state";
import { CHARACTER_STATES } from "./character-states";
import { handleInteraction } from "./interaction-utils";

export class IdleState extends BaseCharacterState {
  constructor(gameObject: CharacterObject) {
    super(CHARACTER_STATES.IDLE_STATE, gameObject);
  }

  public onEnter(): void {
    this._gameObject.animationComponent.playAnimation(
      `IDLE_${this._gameObject.direction}`,
    );

    this._resetVelocity();

    const heldComponent = HeldObjectComponent.getComponent<HeldObjectComponent>(
      this._gameObject,
    );
    if (heldComponent?.object !== undefined) {
      const throwComponent =
        ThrowableObjectComponent.getComponent<ThrowableObjectComponent>(
          heldComponent.object,
        );
      if (throwComponent !== undefined) {
        throwComponent.drop();
      }
      heldComponent.drop(this._gameObject.direction);
    }
  }

  public onUpdate(): void {
    const controls = this._gameObject.controls;

    if (this._gameObject.isOnIceStairs()) {
      this.updateDirectionFromInput();
      this._stateMachine.setState(CHARACTER_STATES.ICE_STAIRS_MOVE_STATE);
      return;
    }

    if (!controls.isMovementLocked && controls.isUseJustDown) {
      this._stateMachine.setState(CHARACTER_STATES.USE_ITEM_STATE);
      return;
    }

    // Handle interactions while idle
    if (handleInteraction(this._gameObject, this._stateMachine, controls)) {
      return;
    }

    if (
      !controls.isDownDown &&
      !controls.isUpDown &&
      !controls.isLeftDown &&
      !controls.isRightDown
    ) {
      return;
    }

    if (this._gameObject.isOnIce()) {
      this.updateDirectionFromInput();
      this._stateMachine.setState(CHARACTER_STATES.ICE_MOVE_STATE);
      return;
    }

    // Transition to move state (now uses tile-based movement)
    this._stateMachine.setState(CHARACTER_STATES.MOVE_STATE);
  }
}
