import { DIRECTION } from "../../../common/constants";
import { isArcadePhysicsBody } from "../../../common/utils";
import { type CharacterObject } from "../../../entities/common/character-object";
import {
  type State,
  type StateMachine,
} from "../../state-machine/state-machine";

export abstract class BaseCharacterState implements State {
  protected _gameObject: CharacterObject;
  protected _stateMachine!: StateMachine;
  #name: string;

  constructor(name: string, gameObject: CharacterObject) {
    this.#name = name;
    this._gameObject = gameObject;
  }

  get name(): string {
    return this.#name;
  }

  set stateMachine(stateMachine: StateMachine) {
    this._stateMachine = stateMachine;
  }

  protected _resetVelocity(): void {
    if (isArcadePhysicsBody(this._gameObject.body)) {
      this._gameObject.body.setVelocity(0, 0);
    }
  }

  protected updateDirectionFromInput(): void {
    const controls = this._gameObject.controls;

    // Update direction based on input (prioritize horizontal for diagonal)
    if (controls.isLeftDown) {
      this._gameObject.direction = DIRECTION.LEFT;
    } else if (controls.isRightDown) {
      this._gameObject.direction = DIRECTION.RIGHT;
    } else if (controls.isUpDown) {
      this._gameObject.direction = DIRECTION.UP;
    } else if (controls.isDownDown) {
      this._gameObject.direction = DIRECTION.DOWN;
    }
  }
}
