import { DIRECTION } from "../../../common/constants";
import type { Direction } from "../../../common/types";
import { isArcadePhysicsBody, isDirection } from "../../../common/utils";
import { type CharacterObject } from "../../../entities/common/character-object";
import { BaseMoveState } from "./base-move-state";
import { CHARACTER_STATES } from "./character-states";

export class RockJumpState extends BaseMoveState {
  #jumping = false;
  #jumpSpeed = 160;
  #tileSize = 16; // Standard tile size
  #targetPosition: { x: number; y: number } | null = null;
  #jumpDirection: Direction | null = null;
  #delayedCall: Phaser.Time.TimerEvent | undefined;

  constructor(gameObject: CharacterObject) {
    super(CHARACTER_STATES.ROCK_JUMP_STATE, gameObject, "WALK");
  }

  public onEnter(args: unknown[] = []): void {
    this._gameObject.animationComponent.playAnimation(
      `IDLE_${this._gameObject.direction}`,
    );
    // Don't start jumping immediately, wait for input
    this.#jumping = false;
    this.#targetPosition = null;
    this.#jumpDirection = null;
    this._gameObject.setVelocity(0, 0);

    // Phaser is kind of stupid.
    // The "JustDown" function returns "true" the first time you call it for a particular
    // keypress, and then false until the user releases and re-presses the key. This works
    // if you're constantly calling the function (e.g. in the update loop) but if you aren't
    // then it doesn't behave correctly. The player could start holding a key, then 2
    // seconds later you call JustDown and see that they just pressed the key down.
    //
    // To hack around this here, we clear the JustDown values on entering this state.
    console.debug(
      "clearing justdown",
      this._gameObject.controls.isUpJustDown,
      this._gameObject.controls.isLeftJustDown,
      this._gameObject.controls.isRightJustDown,
      this._gameObject.controls.isDownJustDown,
    );

    const autoJumpConfig = this.#parseAutoJumpArgs(args);
    const rock = this._gameObject.touchingRock();
    if (rock) {
      const [x, y] = this.#centerPlayerOnRock(rock.x, rock.y);
      this._gameObject.x = x;
      this._gameObject.y = y;
    }

    if (autoJumpConfig) {
      this.startAutoJump(autoJumpConfig.direction, autoJumpConfig.origin);
    }
  }

  public onUpdate(): void {
    // Check if we're still on a rock
    if (!this._gameObject.touchingRock() && !this.#jumping) {
      this._stateMachine.setState(CHARACTER_STATES.MOVE_STATE);
      return;
    }

    if (this.#jumping) {
      this.#continueJump();
    } else {
      this.#handleJumpInput();
    }
  }

  public get jumping(): boolean {
    return this.#jumping;
  }

  public startAutoJump(
    direction: Direction,
    origin: { x: number; y: number },
  ): void {
    this.#startJump(direction, origin);
  }

  #centerPlayerOnRock(centerX: number, centerY: number): [number, number] {
    return [centerX, centerY - 6 - (this._gameObject.body?.halfHeight ?? 0)];
  }

  #handleJumpInput(): void {
    const controls = this._gameObject.controls;

    if (controls.isMovementLocked) {
      return;
    }

    let jumpDirection: Direction | null = null;

    // Check for WASD input and determine jump direction
    if (controls.isUpJustDown) {
      jumpDirection = DIRECTION.UP;
    } else if (controls.isDownJustDown) {
      jumpDirection = DIRECTION.DOWN;
    } else if (controls.isLeftJustDown) {
      jumpDirection = DIRECTION.LEFT;
    } else if (controls.isRightJustDown) {
      jumpDirection = DIRECTION.RIGHT;
    }

    if (jumpDirection) {
      this.#startJump(jumpDirection);
    }
  }

  #startJump(direction: Direction, origin?: { x: number; y: number }): void {
    if (this.#jumping || this.#delayedCall) {
      return;
    }

    this.#jumping = true;
    this.#jumpDirection = direction;
    this._gameObject.direction = direction;

    // Calculate target position (2 tiles away)
    const [currentTileX, currentTileY] = this.#getCurrentTile(origin);
    let targetTileX = currentTileX;
    let targetTileY = currentTileY;

    switch (direction) {
      case DIRECTION.LEFT:
        targetTileX = currentTileX - 2;
        break;
      case DIRECTION.RIGHT:
        targetTileX = currentTileX + 2;
        break;
      case DIRECTION.UP:
        targetTileY = currentTileY - 2;
        break;
      case DIRECTION.DOWN:
        targetTileY = currentTileY + 2;
        break;
    }

    if (origin) {
      const [startX, startY] = this.#centerPlayerOnRock(origin.x, origin.y);
      this._gameObject.setPosition(startX, startY);
    }

    const [targetX, targetY] = this.#centerPlayerOnRock(
      targetTileX * this.#tileSize + this.#tileSize / 2,
      targetTileY * this.#tileSize + this.#tileSize / 2,
    );
    this.#targetPosition = {
      x: targetX,
      y: targetY,
    };

    this.#applyDirectionFlip();
    this._gameObject.animationComponent.playAnimation(
      `JUMP_${this._gameObject.direction === "LEFT" ? "RIGHT" : this._gameObject.direction}`,
    );
    this._gameObject.scene.time.delayedCall(200, () => {
      this.#setJumpVelocity(direction);
    });
  }

  #setJumpVelocity(direction: Direction): void {
    if (!isArcadePhysicsBody(this._gameObject.body)) {
      return;
    }

    let velocityX = 0;
    let velocityY = 0;

    switch (direction) {
      case DIRECTION.LEFT:
        velocityX = -this.#jumpSpeed;
        break;
      case DIRECTION.RIGHT:
        velocityX = this.#jumpSpeed;
        break;
      case DIRECTION.UP:
        velocityY = -this.#jumpSpeed;
        break;
      case DIRECTION.DOWN:
        velocityY = this.#jumpSpeed;
        break;
    }

    this._gameObject.body.velocity.x = velocityX;
    this._gameObject.body.velocity.y = velocityY;
  }

  #continueJump(): void {
    if (!this.#targetPosition || !this.#jumpDirection) {
      this.#endJump();
      return;
    }

    // Check if we've reached or passed the target position
    const currentX = this._gameObject.x;
    const currentY = this._gameObject.y;
    const targetX = this.#targetPosition.x;
    const targetY = this.#targetPosition.y;

    let reachedTarget = false;

    switch (this.#jumpDirection) {
      case DIRECTION.LEFT:
        reachedTarget = currentX <= targetX;
        break;
      case DIRECTION.RIGHT:
        reachedTarget = currentX >= targetX;
        break;
      case DIRECTION.UP:
        reachedTarget = currentY <= targetY;
        break;
      case DIRECTION.DOWN:
        reachedTarget = currentY >= targetY;
        break;
    }

    if (reachedTarget) {
      this._resetVelocity();
      // Snap to exact target position
      this.#endJump();
      this._gameObject.setPosition(targetX, targetY);
    }
  }

  #endJump(): void {
    if (this.#delayedCall) {
      return;
    }

    this.#delayedCall = this._gameObject.scene.time.delayedCall(100, () => {
      this.#jumping = false;
      this.#targetPosition = null;
      this.#jumpDirection = null;
      this.#delayedCall = undefined;
      // Check if we're still on a rock, if not transition to normal move state
      if (!this._gameObject.touchingRock()) {
        this._stateMachine.setState(CHARACTER_STATES.MOVE_STATE);
      }

      this.#applyDirectionFlip();
      this._gameObject.animationComponent.playAnimation(
        `IDLE_${this._gameObject.direction}`,
      );
    });
  }

  #parseAutoJumpArgs(
    args: unknown[],
  ): { direction: Direction; origin: { x: number; y: number } } | null {
    if (args?.length === 0) {
      return null;
    }

    const payload = args[0] as {
      autoJump?: { direction?: unknown; origin?: { x?: unknown; y?: unknown } };
    };
    const autoJump = payload?.autoJump;
    if (
      !autoJump ||
      typeof autoJump.origin?.x !== "number" ||
      typeof autoJump.origin?.y !== "number" ||
      typeof autoJump.direction !== "string" ||
      !isDirection(autoJump.direction)
    ) {
      return null;
    }

    return {
      direction: autoJump.direction,
      origin: { x: autoJump.origin.x, y: autoJump.origin.y },
    };
  }

  #getCurrentTile(origin?: { x: number; y: number }): [number, number] {
    if (origin) {
      return [
        Math.floor(origin.x / this.#tileSize),
        Math.floor(origin.y / this.#tileSize),
      ];
    }

    return [
      Math.floor(
        ((this._gameObject.body?.x ?? 0) +
          (this._gameObject.body?.halfWidth ?? 0)) /
          this.#tileSize,
      ),
      Math.floor(
        ((this._gameObject.body?.y ?? 0) +
          (this._gameObject.body?.halfHeight ?? 0)) /
          this.#tileSize,
      ),
    ];
  }

  protected normalizeVelocity(): void {
    // Override to prevent normal velocity normalization during jumps
    // Rock jumping uses its own velocity management
  }

  #applyDirectionFlip(): void {
    this._gameObject.setFlipX(this._gameObject.direction === DIRECTION.LEFT);
  }
}
