import type Phaser from "phaser";
import { STORY_FLAG } from "../../common/constants";
import { ARITHMETIC_MINI_GAME } from "./mini-games/arithmetic-practice";
import { EMOJI_RIDDLES_MINI_GAME } from "./mini-games/emoji-riddles";
import { FISH_IDENTIFICATION_MINI_GAME } from "./mini-games/fish-identification";
import { FLAG_IDENTIFICATION_MINI_GAME } from "./mini-games/flag-identification";
import { WHEEL_OF_FISH_MINI_GAME } from "./mini-games/wheel-of-fish";
import { WORD_ENCODINGS_MINI_GAME } from "./mini-games/word-encodings";
import { WORD_SCRAMBLE_MINI_GAME } from "./mini-games/word-scramble";
export { resetMiniGameQuestionPools } from "./mini-game-helpers";

export type FishingMiniGameId =
  | "flag-identification"
  | "arithmetic-practice"
  | "word-scramble"
  | "fish-identification"
  | "word-encodings"
  | "emoji-riddles"
  | "wheel-of-fish";

export type FishingMiniGameQuestionContent =
  | {
      type: "image";
      textureKey: string;
      maxWidthRatio?: number;
      maxHeight?: number;
    }
  | {
      type: "text";
      text: string;
      style?: Partial<Phaser.Types.GameObjects.Text.TextStyle>;
      maxWidthRatio?: number;
      hasEmoji?: boolean;
    }
  | {
      type: "morse";
      encodedWords: string[][];
      dotTextureKey: string;
      dashTextureKey: string;
      maxWidthRatio?: number;
    }
  | {
      type: "image-sequence";
      textureKeys: string[];
      maxWidthRatio?: number;
      itemSize?: number;
      spacing?: number;
      backgroundPadding?: number;
      backgroundColor?: number;
    };

export type FishingMiniGameQuestion = {
  id: string;
  answers: string[];
  content: FishingMiniGameQuestionContent;
};

export type FishingMiniGameProgressBounds = {
  caught: number;
  start: number;
  escaped: number;
};

export type FishingMiniGameScoringConfig = {
  correctDelta?: number;
  incorrectDelta?: number;
  timerDelayMs?: number;
  timerProgressDelta?: number;
  progressBounds?: Partial<FishingMiniGameProgressBounds>;
};

export type FishingMiniGameDefinition = {
  id: FishingMiniGameId;
  instructions: string;
  inputPlaceholder?: string;
  scoring?: FishingMiniGameScoringConfig;
  preload?(scene: Phaser.Scene): void;
  getNextQuestion(scene: Phaser.Scene): FishingMiniGameQuestion;
};

const MINI_GAME_REGISTRY: Record<FishingMiniGameId, FishingMiniGameDefinition> =
  {
    "flag-identification": FLAG_IDENTIFICATION_MINI_GAME,
    "arithmetic-practice": ARITHMETIC_MINI_GAME,
    "word-scramble": WORD_SCRAMBLE_MINI_GAME,
    "fish-identification": FISH_IDENTIFICATION_MINI_GAME,
    "word-encodings": WORD_ENCODINGS_MINI_GAME,
    "emoji-riddles": EMOJI_RIDDLES_MINI_GAME,
    "wheel-of-fish": WHEEL_OF_FISH_MINI_GAME,
  };

const FISH_STORY_FLAG_MINI_GAME_MAP: Partial<
  Record<string, FishingMiniGameId>
> = {
  [STORY_FLAG.shore_01]: "fish-identification",
  [STORY_FLAG.shore_02]: "arithmetic-practice",
  [STORY_FLAG.shore_03]: "word-scramble",
  [STORY_FLAG.shore_04]: "wheel-of-fish",
  [STORY_FLAG.shore_05]: "word-encodings",
  [STORY_FLAG.shore_06]: "flag-identification",
  [STORY_FLAG.shore_07]: "emoji-riddles",
};

export const DEFAULT_FISHING_MINI_GAME_ID: FishingMiniGameId =
  WORD_SCRAMBLE_MINI_GAME.id;

export function getFishingMiniGameDefinition(
  id?: FishingMiniGameId,
): FishingMiniGameDefinition {
  if (id && MINI_GAME_REGISTRY[id]) {
    return MINI_GAME_REGISTRY[id];
  }

  return MINI_GAME_REGISTRY[DEFAULT_FISHING_MINI_GAME_ID];
}

export function listFishingMiniGameDefinitions(): FishingMiniGameDefinition[] {
  return Object.values(MINI_GAME_REGISTRY);
}

export function getMiniGameIdForFishingSpot(
  storyFlag: string,
): FishingMiniGameId {
  const miniGameForFlag = FISH_STORY_FLAG_MINI_GAME_MAP[storyFlag];
  if (miniGameForFlag) {
    return miniGameForFlag;
  }

  return DEFAULT_FISHING_MINI_GAME_ID;
}
