import type { GameObject } from "../common/types";
import type { Tool } from "../entities/tools/base-tool";
import { BaseGameObjectComponent } from "./base-game-object";

export class ToolComponent extends BaseGameObjectComponent {
  #tool: Tool | undefined;
  #toolPhysicsBody: Phaser.Physics.Arcade.Body;

  constructor(gameObject: GameObject) {
    super(gameObject);
    this.#toolPhysicsBody = gameObject.scene.physics.add.body(
      gameObject.x,
      gameObject.y,
      1,
      1,
    );
    this.#toolPhysicsBody.enable = false;
    this.assignComponentToOject(this.#toolPhysicsBody);
  }

  get tool(): Tool | undefined {
    return this.#tool;
  }

  set tool(tool: Tool | undefined) {
    this.#tool = tool;
  }

  get body(): Phaser.Physics.Arcade.Body {
    return this.#toolPhysicsBody;
  }

  public update(): void {
    if (this.#tool === undefined) {
      return;
    }

    this.#tool.update();
  }
}
