import * as Phaser from "phaser";
import { DEBUG_PROXIMITY_DETECTION } from "../common/config";
import { DIRECTION, PROXIMITY_DETECTION } from "../common/constants";
import type {
  Direction,
  DirectionalObject,
  GameObject,
  InteractiveGameObject,
  PhysicsObject,
} from "../common/types";
import { HidingPlace } from "../entities/objects/campground/hiding_place";
import { BaseGameObjectComponent } from "./base-game-object";
import { InteractiveObjectComponent } from "./interactive-object-component";
import { ProximityDebugManager } from "./proximity-debug-window";

export class ProximityDetectionComponent extends BaseGameObjectComponent {
  // Override the gameObject type to be more specific
  protected gameObject: GameObject & DirectionalObject;
  #nearbyObjects: InteractiveGameObject[] = [];
  #detectionRadius: number = PROXIMITY_DETECTION.RADIUS;
  #facingAngle: number = PROXIMITY_DETECTION.FACING_ANGLE;
  #debugGraphics?: Phaser.GameObjects.Graphics;

  constructor(gameObject: GameObject) {
    super(gameObject);

    // Validate that the gameObject has the required direction property
    if (
      !gameObject ||
      typeof gameObject !== "object" ||
      !("direction" in gameObject)
    ) {
      throw new Error(
        "ProximityDetectionComponent: Game object must have a direction property",
      );
    }

    const direction = (gameObject as { direction: unknown }).direction;
    if (
      typeof direction !== "string" ||
      !Object.values(DIRECTION).includes(direction as Direction)
    ) {
      throw new Error(
        "ProximityDetectionComponent: Game object must have a valid direction value",
      );
    }

    // Type assertion is now safe because we've validated the object
    this.gameObject = gameObject as GameObject & DirectionalObject;
  }

  /**
   * Safely extracts an ID from an object if it has one.
   * Returns a string representation of the ID or "unknown" if no ID is available.
   */
  private getObjectId(obj: InteractiveGameObject): string {
    if (obj && typeof obj === "object" && "id" in obj) {
      const id = (obj as { id: string | number }).id;
      return String(id);
    }
    return "unknown";
  }

  get nearbyObjects(): InteractiveGameObject[] {
    return this.#nearbyObjects;
  }

  public getDetectionRadius(): number {
    return this.#detectionRadius;
  }

  public setDetectionRadius(radius: number): void {
    this.#detectionRadius = radius;
  }

  /**
   * Calculates the distance from the player to the closest edge of an object
   */
  private getDistanceToClosestEdge(obj: InteractiveGameObject): number {
    const thisCenter = this.getCollisionCenter();

    // Get object bounds
    const objBounds = obj.getBounds();

    // Calculate the closest point on the object's rectangle to the player
    const closestX = Phaser.Math.Clamp(
      thisCenter.x,
      objBounds.x,
      objBounds.x + objBounds.width,
    );
    const closestY = Phaser.Math.Clamp(
      thisCenter.y,
      objBounds.y,
      objBounds.y + objBounds.height,
    );

    // Calculate distance to the closest point
    return Phaser.Math.Distance.Between(
      thisCenter.x,
      thisCenter.y,
      closestX,
      closestY,
    );
  }

  public updateNearbyObjects(allObjects: InteractiveGameObject[]): void {
    this.#nearbyObjects = allObjects.filter((obj) => {
      if (obj === this.gameObject) return false;

      if (!obj.active || !obj.visible) return false;

      // Calculate distance to the closest edge of the object
      const distanceToClosestEdge = this.getDistanceToClosestEdge(obj);
      return distanceToClosestEdge <= this.#detectionRadius;
    });

    // Update debug manager with current room objects
    if (DEBUG_PROXIMITY_DETECTION) {
      ProximityDebugManager.getInstance().updateRoomObjects(allObjects);
    }
  }

  public static initializeDebugManager(player: {
    getProximityDetectionRadius: () => number;
    setProximityDetectionRadius: (radius: number) => void;
  }): void {
    if (DEBUG_PROXIMITY_DETECTION) {
      ProximityDebugManager.getInstance().initialize(player);
    }
  }

  public getNearestInteractiveObjectInFront():
    | InteractiveGameObject
    | undefined {
    if (DEBUG_PROXIMITY_DETECTION) {
      console.log(
        "ProximityDebug: Checking",
        this.#nearbyObjects.length,
        "nearby objects",
      );
    }

    const interactiveObjects = this.#nearbyObjects.filter((obj) => {
      const interactiveComponent =
        InteractiveObjectComponent.getComponent<InteractiveObjectComponent>(
          obj,
        );

      if (DEBUG_PROXIMITY_DETECTION) {
        console.log("ProximityDebug: Checking object:", {
          id: this.getObjectId(obj),
          type: obj.constructor.name,
          hasComponent: !!interactiveComponent,
          canInteract: interactiveComponent?.canInteractWith(),
        });
      }

      if (!interactiveComponent?.canInteractWith()) {
        return false;
      }

      // Check if object is in front of the character
      const isInFront = this.isObjectInFront(obj);

      if (DEBUG_PROXIMITY_DETECTION) {
        console.log("ProximityDebug: Object in front:", isInFront);
      }

      return isInFront;
    });

    if (interactiveObjects.length === 0) {
      if (DEBUG_PROXIMITY_DETECTION) {
        console.log("ProximityDebug: No interactive objects in front");
        this.#drawDebugVisualization(); // Show detection area even when no object found
      }
      return undefined;
    }

    // Prioritize hiding places - return the first one that has entities hiding in it
    const hidingPlaceWithEntities = interactiveObjects.find(
      (obj): obj is HidingPlace =>
        obj instanceof HidingPlace && obj.hasHiddenEntities(),
    );
    if (hidingPlaceWithEntities) {
      return hidingPlaceWithEntities;
    }

    // Filter out hiding places from remaining interactive objects
    const nonHidingPlaceObjects = interactiveObjects.filter(
      (obj) => !(obj instanceof HidingPlace),
    );

    // If there are no nonHidingPlace objects return undefined
    if (nonHidingPlaceObjects.length === 0) {
      return undefined;
    }

    // Return the closest one that's in front (non-hiding place objects)
    // Use collision centers for more accurate distance calculation
    const playerCenter = this.getCollisionCenter();
    const nearest = nonHidingPlaceObjects.reduce((closest, current) => {
      const closestCenter = this.getObjectCollisionCenter(closest);
      const currentCenter = this.getObjectCollisionCenter(current);

      const closestDistance = Phaser.Math.Distance.Between(
        playerCenter.x,
        playerCenter.y,
        closestCenter.x,
        closestCenter.y,
      );
      const currentDistance = Phaser.Math.Distance.Between(
        playerCenter.x,
        playerCenter.y,
        currentCenter.x,
        currentCenter.y,
      );
      return currentDistance < closestDistance ? current : closest;
    });

    if (DEBUG_PROXIMITY_DETECTION) {
      const interactiveComponent =
        InteractiveObjectComponent.getComponent<InteractiveObjectComponent>(
          nearest,
        );
      console.log("ProximityDebug: Found interactive object:", {
        objectId: this.getObjectId(nearest),
        objectType: interactiveComponent?.objectType || "unknown",
        distance: Math.round(
          Phaser.Math.Distance.Between(
            this.gameObject.x,
            this.gameObject.y,
            nearest.x,
            nearest.y,
          ),
        ),
      });
      this.#drawDebugVisualization(nearest);
    }

    return nearest;
  }

  private isObjectInFront(obj: InteractiveGameObject): boolean {
    // Direction is guaranteed to exist due to constructor validation
    const characterDirection = this.gameObject.direction;

    // Use collision body centers for more accurate angle calculation
    const thisCenter = this.getCollisionCenter();
    const objCenter = this.getObjectCollisionCenter(obj);

    // Calculate the angle between character and object
    const angleToObject = Phaser.Math.Angle.Between(
      thisCenter.x,
      thisCenter.y,
      objCenter.x,
      objCenter.y,
    );

    // Convert angle to degrees (Phaser uses -180 to 180 range)
    const angleDegrees = (angleToObject * 180) / Math.PI;

    // Define the acceptable angle ranges for each direction
    const directionRanges = this.getDirectionAngleRanges(characterDirection);

    if (DEBUG_PROXIMITY_DETECTION) {
      console.log("ProximityDebug: Direction check:", {
        characterDirection,
        angleToObject: (angleToObject * 180) / Math.PI,
        angleDegrees,
        directionRanges,
        characterPos: thisCenter,
        objectPos: objCenter,
      });
    }

    // Check if the object's angle falls within the acceptable range
    const isInRange = directionRanges.some((range) => {
      // Normalize angles to 0-360 range for easier comparison
      const normalizedAngle = (angleDegrees + 360) % 360;
      const normalizedStart = (range.start + 360) % 360;
      const normalizedEnd = (range.end + 360) % 360;

      if (normalizedStart <= normalizedEnd) {
        return (
          normalizedAngle >= normalizedStart && normalizedAngle <= normalizedEnd
        );
      } else {
        // Handle wraparound case (e.g., 315-45 degrees)
        return (
          normalizedAngle >= normalizedStart || normalizedAngle <= normalizedEnd
        );
      }
    });

    if (DEBUG_PROXIMITY_DETECTION) {
      console.log("ProximityDebug: Is in range:", isInRange);
    }

    return isInRange;
  }

  private getDirectionAngleRanges(
    direction: Direction,
  ): { start: number; end: number }[] {
    const halfAngle = this.#facingAngle / 2;

    switch (direction) {
      case DIRECTION.UP:
        // Up is -90° in Phaser, so range is -90° ± halfAngle
        return [{ start: -90 - halfAngle, end: -90 + halfAngle }];
      case DIRECTION.DOWN:
        // Down is 90° in Phaser, so range is 90° ± halfAngle
        return [{ start: 90 - halfAngle, end: 90 + halfAngle }];
      case DIRECTION.LEFT:
        // Left is 180° in Phaser, so range is 180° ± halfAngle
        return [{ start: 180 - halfAngle, end: 180 + halfAngle }];
      case DIRECTION.RIGHT:
        // Right is 0° in Phaser, so range is 0° ± halfAngle
        return [{ start: 0 - halfAngle, end: 0 + halfAngle }];
      default:
        return [];
    }
  }

  #drawDebugVisualization(targetObject?: InteractiveGameObject): void {
    if (!DEBUG_PROXIMITY_DETECTION) return;

    // Create or get graphics object
    if (!this.#debugGraphics) {
      this.#debugGraphics = this.gameObject.scene.add.graphics();
    }

    // Clear previous drawings
    this.#debugGraphics.clear();

    // Draw detection radius circle
    this.#debugGraphics.lineStyle(2, 0x00ff00, 0.5); // Green, semi-transparent
    this.#debugGraphics.strokeCircle(
      this.gameObject.x,
      this.gameObject.y,
      this.#detectionRadius,
    );

    // Draw facing direction cone
    const characterDirection = (
      this.gameObject as unknown as { direction: Direction }
    ).direction;
    const directionRanges = this.getDirectionAngleRanges(characterDirection);

    this.#debugGraphics.lineStyle(2, 0x0000ff, 0.7); // Blue, semi-transparent
    directionRanges.forEach((range) => {
      const startAngle = (range.start * Math.PI) / 180;
      const endAngle = (range.end * Math.PI) / 180;

      if (this.#debugGraphics) {
        // Draw lines from center to the arc edges to make it look like a cone
        const startX =
          this.gameObject.x + Math.cos(startAngle) * this.#detectionRadius;
        const startY =
          this.gameObject.y + Math.sin(startAngle) * this.#detectionRadius;
        const endX =
          this.gameObject.x + Math.cos(endAngle) * this.#detectionRadius;
        const endY =
          this.gameObject.y + Math.sin(endAngle) * this.#detectionRadius;

        // Line from center to start of arc
        this.#debugGraphics.lineBetween(
          this.gameObject.x,
          this.gameObject.y,
          startX,
          startY,
        );

        // Line from center to end of arc
        this.#debugGraphics.lineBetween(
          this.gameObject.x,
          this.gameObject.y,
          endX,
          endY,
        );

        // Draw the arc only for the detection range
        this.#debugGraphics.arc(
          this.gameObject.x,
          this.gameObject.y,
          this.#detectionRadius,
          startAngle,
          endAngle,
          false,
        );
        this.#debugGraphics.strokePath();
      }
    });

    // Only draw target object lines if we have a target
    if (targetObject) {
      // Draw line to target object
      this.#debugGraphics.lineStyle(3, 0xff0000, 1); // Red, solid
      this.#debugGraphics.lineBetween(
        this.gameObject.x,
        this.gameObject.y,
        targetObject.x,
        targetObject.y,
      );

      // Draw target object highlight
      this.#debugGraphics.lineStyle(3, 0xff0000, 1); // Red, solid
      this.#debugGraphics.strokeCircle(targetObject.x, targetObject.y, 16);
    }
  }

  private getBodyCenter(obj: InteractiveGameObject): {
    x: number;
    y: number;
  } {
    const body = (obj as PhysicsObject).body;
    if (body?.center) {
      return { x: body.center.x, y: body.center.y };
    }
    return { x: obj.x, y: obj.y };
  }

  private getCollisionCenter(): { x: number; y: number } {
    return this.getBodyCenter(this.gameObject as InteractiveGameObject);
  }

  private getObjectCollisionCenter(obj: InteractiveGameObject): {
    x: number;
    y: number;
  } {
    return this.getBodyCenter(obj);
  }
}
