  #createHudRow({
    iconKey,
    label,
    y,
    includeValue = true,
    style,
    showIcon = true,
  }: {
    iconKey?: string;
    label: string;
    y: number;
    includeValue?: boolean;
    style?: Phaser.Types.GameObjects.Text.TextStyle;
    showIcon?: boolean;
  }): {
    row: Phaser.GameObjects.Container;
    label: Phaser.GameObjects.Text;
    value?: Phaser.GameObjects.Text;
    icon?: Phaser.GameObjects.Image;
  } {
    const row = this.add.container(0, y);
    row.setScrollFactor(0, 0);

    const icon =
      iconKey && showIcon
        ? this.add.image(0, 0, iconKey).setOrigin(0, 0.5)
        : undefined;
    icon?.setScrollFactor(0, 0);
    icon?.setVisible(showIcon);

    const labelX = icon ? TAB_OVERLAY_ICON_SIZE + 10 : 0;
    const labelText = this.add
      .text(labelX, -2, label, {
        ...DEFAULT_UI_TEXT_STYLE,
        color: "#f7f7ef",
        fontSize: "18px",
        ...style,
      })
      .setOrigin(0, 0.5);
    labelText.setScrollFactor(0, 0);

    if (icon) {
      row.add(icon);
    }
    row.add(labelText);

    let valueText: Phaser.GameObjects.Text | undefined;
    if (includeValue) {
      const valueX = labelText.x + labelText.width + 6;
      valueText = this.add
        .text(valueX, -2, "", {
          ...DEFAULT_UI_TEXT_STYLE,
          color: "#f7f7ef",
          fontSize: "18px",
        })
        .setOrigin(0, 0.5);
      valueText.setScrollFactor(0, 0);
      row.add(valueText);
    }

    return { row, label: labelText, value: valueText, icon };
  }

  #clampTooltipToViewport(tooltip: Phaser.GameObjects.Text): void {
    const bounds = tooltip.getBounds();
    const minX = TOOLTIP_VIEWPORT_PADDING;
    const minY = TOOLTIP_VIEWPORT_PADDING;
    const maxX = this.scale.width - TOOLTIP_VIEWPORT_PADDING;
    const maxY = this.scale.height - TOOLTIP_VIEWPORT_PADDING;
    let offsetX = 0;
    let offsetY = 0;

    if (bounds.left < minX) {
      offsetX = minX - bounds.left;
    } else if (bounds.right > maxX) {
      offsetX = maxX - bounds.right;
    }

    if (bounds.top < minY) {
      offsetY = minY - bounds.top;
    } else if (bounds.bottom > maxY) {
      offsetY = maxY - bounds.bottom;
    }

    if (offsetX !== 0 || offsetY !== 0) {
      tooltip.setPosition(tooltip.x + offsetX, tooltip.y + offsetY);
    }
  }

