import * as Phaser from "phaser";
import { InputComponent } from "./input-component";

/**
 * Keyboard input handler that extends InputComponent with keyboard-specific functionality.
 *
 * Provides two levels of input control:
 * - isMovementLocked: Flag used by other systems to indicate movement should be locked
 * - movementControlsLocked: Locks keyboard input for movement but allows programmatic input via setters
 *
 */
export class Keyboard extends InputComponent {
  #cursorKeys: Phaser.Types.Input.Keyboard.CursorKeys;
  #actionKey: Phaser.Input.Keyboard.Key;
  #enterKey: Phaser.Input.Keyboard.Key;
  #infoKey: Phaser.Input.Keyboard.Key;
  #upKeys: Phaser.Input.Keyboard.Key[];
  #downKeys: Phaser.Input.Keyboard.Key[];
  #leftKeys: Phaser.Input.Keyboard.Key[];
  #rightKeys: Phaser.Input.Keyboard.Key[];
  #useKey: Phaser.Input.Keyboard.Key;
  #flagKey: Phaser.Input.Keyboard.Key;
  #escapeKey: Phaser.Input.Keyboard.Key;

  constructor(keyboardPlugin: Phaser.Input.Keyboard.KeyboardPlugin) {
    super();
    this.#cursorKeys = keyboardPlugin.createCursorKeys();
    this.#actionKey = keyboardPlugin.addKey(
      Phaser.Input.Keyboard.KeyCodes.SPACE,
      false,
    );
    this.#enterKey = keyboardPlugin.addKey(
      Phaser.Input.Keyboard.KeyCodes.ENTER,
      false,
    );
    this.#infoKey = keyboardPlugin.addKey(Phaser.Input.Keyboard.KeyCodes.Q);
    keyboardPlugin.addCapture(Phaser.Input.Keyboard.KeyCodes.Q);
    this.#useKey = keyboardPlugin.addKey(Phaser.Input.Keyboard.KeyCodes.E);
    this.#flagKey = keyboardPlugin.addKey(Phaser.Input.Keyboard.KeyCodes.F);

    // Create key groups for each direction
    this.#upKeys = [
      this.#cursorKeys.up,
      keyboardPlugin.addKey(Phaser.Input.Keyboard.KeyCodes.W),
    ];
    this.#downKeys = [
      this.#cursorKeys.down,
      keyboardPlugin.addKey(Phaser.Input.Keyboard.KeyCodes.S),
    ];
    this.#leftKeys = [
      this.#cursorKeys.left,
      keyboardPlugin.addKey(Phaser.Input.Keyboard.KeyCodes.A),
    ];
    this.#rightKeys = [
      this.#cursorKeys.right,
      keyboardPlugin.addKey(Phaser.Input.Keyboard.KeyCodes.D),
    ];
    this.#escapeKey = keyboardPlugin.addKey(Phaser.Input.Keyboard.KeyCodes.ESC);
  }

  private isAnyKeyDown(keys: Phaser.Input.Keyboard.Key[]): boolean {
    return keys.some((key) => key.isDown);
  }

  private isAnyKeyJustDown(keys: Phaser.Input.Keyboard.Key[]): boolean {
    return keys.some((key) => Phaser.Input.Keyboard.JustDown(key));
  }

  get isUpDown(): boolean {
    if (this._movementControlsLocked) {
      return super.isUpDown;
    }
    return this.isAnyKeyDown(this.#upKeys);
  }
  set isUpDown(value: boolean) {
    super.isUpDown = value;
  }
  get isUpJustDown(): boolean {
    if (this._movementControlsLocked) {
      return super.isUpJustDown;
    }
    return this.isAnyKeyJustDown(this.#upKeys);
  }
  get isDownDown(): boolean {
    if (this._movementControlsLocked) {
      return super.isDownDown;
    }
    return this.isAnyKeyDown(this.#downKeys);
  }

  set isDownDown(value: boolean) {
    super.isDownDown = value;
  }
  get isDownJustDown(): boolean {
    if (this._movementControlsLocked) {
      return super.isDownJustDown;
    }
    return this.isAnyKeyJustDown(this.#downKeys);
  }
  get isLeftDown(): boolean {
    if (this._movementControlsLocked) {
      return super.isLeftDown;
    }
    return this.isAnyKeyDown(this.#leftKeys);
  }

  set isLeftDown(value: boolean) {
    super.isLeftDown = value;
  }
  get isLeftJustDown(): boolean {
    if (this._movementControlsLocked) {
      return super.isLeftJustDown;
    }
    return this.isAnyKeyJustDown(this.#leftKeys);
  }
  get isRightDown(): boolean {
    if (this._movementControlsLocked) {
      return super.isRightDown;
    }
    return this.isAnyKeyDown(this.#rightKeys);
  }

  set isRightDown(value: boolean) {
    super.isRightDown = value;
  }
  get isRightJustDown(): boolean {
    if (this._movementControlsLocked) {
      return super.isRightJustDown;
    }
    return this.isAnyKeyJustDown(this.#rightKeys);
  }

  get isActionKeyJustDown(): boolean {
    return Phaser.Input.Keyboard.JustDown(this.#actionKey);
  }

  set isActionKeyJustDown(value: boolean) {
    super.isActionKeyJustDown = value;
  }

  get isEnterKeyJustDown(): boolean {
    return Phaser.Input.Keyboard.JustDown(this.#enterKey);
  }

  set isEnterKeyJustDown(value: boolean) {
    super.isEnterKeyJustDown = value;
  }
  get isUseJustDown(): boolean {
    if (this._movementControlsLocked) {
      return super.isUseJustDown;
    }
    return Phaser.Input.Keyboard.JustDown(this.#useKey);
  }

  set isUseJustDown(value: boolean) {
    super.isUseJustDown = value;
  }

  get isFlagKeyJustDown(): boolean {
    if (this._movementControlsLocked) {
      return super.isFlagKeyJustDown;
    }
    return Phaser.Input.Keyboard.JustDown(this.#flagKey);
  }

  set isFlagKeyJustDown(value: boolean) {
    super.isFlagKeyJustDown = value;
  }

  // Dialog-specific input methods
  get isDialogContinueJustDown(): boolean {
    return this.isActionKeyJustDown || this.isEnterKeyJustDown;
  }

  get isDialogChoiceUpJustDown(): boolean {
    // Always check the actual keys, regardless of movement control locking
    return this.isAnyKeyJustDown(this.#upKeys);
  }

  get isDialogChoiceDownJustDown(): boolean {
    // Always check the actual keys, regardless of movement control locking
    return this.isAnyKeyJustDown(this.#downKeys);
  }

  get isDialogChoiceSelectJustDown(): boolean {
    return this.isActionKeyJustDown || this.isEnterKeyJustDown;
  }

  get isEscapeJustDown(): boolean {
    return Phaser.Input.Keyboard.JustDown(this.#escapeKey);
  }

  public resetDialogKeys(): void {
    this.#actionKey.reset();
    this.#enterKey.reset();
  }

  get isInfoKeyDown(): boolean {
    if (this._infoKeyLocked) {
      return false;
    }
    return this.#infoKey.isDown;
  }
}
