import {
  DUNGEON_ITEM,
  GENERAL_ITEM,
  LEVEL_NAME,
  INSTRUMENT_TOOL_TYPE,
} from "../../common/constants";
import {
  type LevelName,
  type DungeonItem,
  type GeneralItem,
} from "../../common/types";
import { assertNeverCalled } from "../../common/utils";

type AreaInventory = {
  bossKey: boolean;
  keys: number;
};

export type ToolType = string;

export type InventoryData = {
  general: Record<GeneralItem, number>;
  area: Record<LevelName, AreaInventory>;
  currentTool: ToolType;
};

export class InventoryManager {
  static #instance: InventoryManager;

  #generalInventory: Record<GeneralItem, number>;
  #areaInventory: Record<LevelName, AreaInventory>;
  #currentTool: ToolType;

  private constructor() {
    this.#generalInventory = Object.values(GENERAL_ITEM).reduce(
      (acc, item) => {
        acc[item] = 0;
        return acc;
      },
      {} as Record<GeneralItem, number>,
    );
    this.#areaInventory = this.#initializeAreaInventory();
    this.#currentTool = INSTRUMENT_TOOL_TYPE.LUTE; // Default to lute
  }

  #initializeAreaInventory(): Record<LevelName, AreaInventory> {
    const areaInventory: Record<LevelName, AreaInventory> = {} as Record<
      LevelName,
      AreaInventory
    >;

    // Initialize all level names with default inventory
    Object.values(LEVEL_NAME).forEach((levelName) => {
      areaInventory[levelName as LevelName] = {
        bossKey: false,
        keys: 0,
      };
    });

    return areaInventory;
  }

  public static get instance(): InventoryManager {
    if (!InventoryManager.#instance) {
      InventoryManager.#instance = new InventoryManager();
    }
    return InventoryManager.#instance;
  }

  get data(): InventoryData {
    return {
      general: { ...this.#generalInventory },
      area: { ...this.#areaInventory },
      currentTool: this.#currentTool,
    };
  }

  set data(data: InventoryData) {
    this.#generalInventory = { ...data.general };
    this.#areaInventory = { ...data.area };
    this.#currentTool = data.currentTool;
  }

  public addAreaItem(area: LevelName, dungeonItem: DungeonItem): void {
    switch (dungeonItem) {
      case DUNGEON_ITEM.BOSS_KEY:
        this.#areaInventory[area].bossKey = true;
        return;
      case DUNGEON_ITEM.SMALL_KEY:
        this.#areaInventory[area].keys++;
        return;
      default:
        assertNeverCalled(dungeonItem);
    }
  }

  public getAreaInventory(area: LevelName): AreaInventory {
    return { ...this.#areaInventory[area] };
  }

  public useAreaSmallKey(area: LevelName): void {
    if (this.#areaInventory[area].keys > 0) {
      this.#areaInventory[area].keys--;
    }
  }

  public getGeneralItemCount(item: GeneralItem): number {
    return this.#generalInventory[item];
  }

  public addGeneralItem(item: GeneralItem, amount = 1): void {
    this.#generalInventory[item] += amount;
    console.log(this.#generalInventory);
  }

  public removeGeneralItem(item: GeneralItem, amount = 1): void {
    this.#generalInventory[item] -= amount;
    console.log(this.#generalInventory);
  }

  public hasGeneralItem(item: GeneralItem): boolean {
    return this.#generalInventory[item] > 0;
  }

  public getCurrentTool(): ToolType {
    return this.#currentTool;
  }

  public setCurrentTool(tool: ToolType): void {
    this.#currentTool = tool;
  }
}
