import * as Phaser from "phaser";
import { ASSET_KEYS, EFFECTS_ANIMATION_KEYS } from "../../common/assets";
import { getSceneDataManager } from "../../common/data-manager";
import type { TiledFishingSpotObject } from "../../common/tiled/types";
import type { CustomObject } from "../../common/types";

export class FishingSpot
  extends Phaser.GameObjects.Zone
  implements CustomObject
{
  #texture?: string;
  #storyFlag?: string;
  #fishShadow?: Phaser.GameObjects.Sprite;
  #exclamation?: Phaser.GameObjects.Sprite;

  constructor(scene: Phaser.Scene, config: TiledFishingSpotObject) {
    super(scene, config.x, config.y, config.width, config.height);

    this.#texture = config.texture;
    this.#storyFlag = config.storyFlag;

    this.setOrigin(0, 0);
    scene.add.existing(this);
    scene.physics.world.enable(this);

    // Create fish shadow effect
    this.#createFishShadow();
    this.#createExclamation();

    // Initially disabled and invisible
    this.disableObject();
  }

  get texture(): string | undefined {
    return this.#texture;
  }

  get storyFlag(): string | undefined {
    return this.#storyFlag;
  }

  public enableObject(): void {
    (this.body as Phaser.Physics.Arcade.Body).enable = true;
    this.active = true;
    this.visible = true;

    this.#updateShadowState(true);
    this.#updateExclamationState(true);
  }

  public refreshObjects(): void {
    if (this.active) {
      this.#updateShadowState(false);
      this.#updateExclamationState(false);
    }
  }

  #updateShadowState(useRandomDelay: boolean): void {
    if (!this.#fishShadow) {
      return;
    }

    const shouldPlayAnimation = !this.#isStoryFlagCompleted();

    if (shouldPlayAnimation) {
      this.#fishShadow.setVisible(true);
      if (!this.#fishShadow.anims.isPlaying) {
        if (useRandomDelay) {
          // Randomize start time (0 to 1000ms delay) for de-syncing
          const randomDelay = Math.random() * 1000;

          // Delay the animation start slightly to de-sync fishing spots
          this.scene.time.delayedCall(randomDelay, () => {
            if (
              this.active &&
              this.#fishShadow &&
              !this.#fishShadow.anims.isPlaying &&
              !this.#isStoryFlagCompleted()
            ) {
              this.#fishShadow.play({
                key: EFFECTS_ANIMATION_KEYS.FISH_SHADOW,
                repeat: -1,
              });
            }
          });
        } else {
          this.#fishShadow.play({
            key: EFFECTS_ANIMATION_KEYS.FISH_SHADOW,
            repeat: -1,
          });
        }
      }
    } else {
      // Hide sprite and stop animation if story flag is completed
      this.#fishShadow.setVisible(false);
      if (this.#fishShadow.anims.isPlaying) {
        this.#fishShadow.stop();
      }
    }
  }

  #updateExclamationState(refreshAnimation: boolean): void {
    if (!this.#exclamation) {
      return;
    }

    const shouldShow = !this.#isStoryFlagCompleted();
    if (!shouldShow) {
      this.#exclamation.setVisible(false);
      if (this.#exclamation.anims.isPlaying) {
        this.#exclamation.stop();
      }
      return;
    }

    this.#exclamation.setVisible(true);
    if (refreshAnimation || !this.#exclamation.anims.isPlaying) {
      this.#exclamation.play({
        key: EFFECTS_ANIMATION_KEYS.EXCLAMATION,
        repeat: -1,
      });
    }
  }

  #isStoryFlagCompleted(): boolean {
    if (!this.#storyFlag) {
      return false;
    }
    const dataManager = getSceneDataManager(this.scene);
    return dataManager.getFlagValue(this.#storyFlag) === "completed";
  }

  public disableObject(): void {
    (this.body as Phaser.Physics.Arcade.Body).enable = false;
    this.active = false;
    this.visible = false;

    // Hide fish shadow when disabled
    if (this.#fishShadow) {
      this.#fishShadow.setVisible(false);
      this.#fishShadow.stop();
    }

    if (this.#exclamation) {
      this.#exclamation.setVisible(false);
      this.#exclamation.stop();
    }
  }

  public destroyObject(): void {
    if (this.#fishShadow) {
      this.#fishShadow.destroy();
    }
    if (this.#exclamation) {
      this.#exclamation.destroy();
    }
    super.destroy();
  }

  #createFishShadow(): void {
    this.#fishShadow = this.scene.add.sprite(
      this.x,
      this.y,
      ASSET_KEYS.FISH_SHADOW,
    );
    this.#fishShadow.setOrigin(0, 0);
    this.#fishShadow.setDepth(this.depth + 3);
    this.#fishShadow.setVisible(false);
  }

  #createExclamation(): void {
    this.#exclamation = this.scene.add.sprite(
      this.x + this.width / 2,
      this.y + this.height / 2,
      ASSET_KEYS.EXCLAMATION,
    );
    this.#exclamation.setOrigin(0.5, 0.5);
    this.#exclamation.setDepth(this.depth + 4);
    this.#exclamation.setVisible(false);
  }
}
