import { PARTIAL_FLAGS } from "../flags";
import { drawFromQuestionPool } from "../mini-game-helpers";
import type { FishingMiniGameDefinition } from "../mini-game-registry";

const FLAG_POOL_ID = "flag-identification";

export const FLAG_IDENTIFICATION_MINI_GAME: FishingMiniGameDefinition = {
  id: "flag-identification",
  instructions: "Which country's flag\nis this?",
  inputPlaceholder: "Press Enter to submit",
  scoring: {
    correctDelta: 6,
    incorrectDelta: 3,
    timerDelayMs: 1000,
    timerProgressDelta: 1,
  },
  preload: (scene) => {
    PARTIAL_FLAGS.forEach((flag) => {
      scene.load.image(flag.key, flag.assetUrl);
    });
  },
  getNextQuestion: (scene) => {
    const flag = drawFromQuestionPool(scene, FLAG_POOL_ID, PARTIAL_FLAGS);

    return {
      id: flag.key,
      answers: flag.answers,
      content: {
        type: "image",
        textureKey: flag.key,
        maxWidthRatio: 0.35,
        maxHeight: 120,
      },
    };
  },
};
