import * as Phaser from "phaser";
import { ASSET_KEYS } from "../../common/assets";
import { INTERACTIVE_OBJECT_TYPE } from "../../common/constants";
import { CUSTOM_EVENTS, EVENT_BUS } from "../../common/event-bus";
import type { TiledReadableObject } from "../../common/tiled/types";
import type { CustomObject } from "../../common/types";
import { InteractiveObjectComponent } from "../../components/interactive-object-component";

type ReadableData =
  | string
  | string[]
  | {
      message?: string;
      messages?: string[];
      imageAssetKey?: string;
      imageScale?: number;
    };

export class Readable extends Phaser.GameObjects.Zone implements CustomObject {
  #messages: string[];
  #identifier: string;
  #imageAssetKey?: string;
  #imageScale?: number;

  constructor(scene: Phaser.Scene, config: TiledReadableObject) {
    super(
      scene,
      config.x + config.width / 2,
      config.y + config.height / 2,
      config.width,
      config.height,
    );

    scene.add.existing(this);
    scene.physics.add.existing(this, true);

    this.#identifier = config.identifier;

    // Get readable data from cache (supports string, string[], or object)
    const readableData = scene.cache.json.get(ASSET_KEYS.READABLE_MESSAGES) as
      | Record<string, ReadableData>
      | undefined;

    const data = readableData?.[config.identifier];
    if (data) {
      if (typeof data === "string") {
        // Simple string format (backward compatible)
        this.#messages = [data];
      } else if (Array.isArray(data)) {
        // Array of strings (backward compatible)
        this.#messages = data;
      } else {
        // Object format with optional image
        this.#messages = data.messages ?? (data.message ? [data.message] : []);
        this.#imageAssetKey = data.imageAssetKey;
        this.#imageScale = data.imageScale;
      }
    } else {
      // No data found - empty messages array is allowed
      this.#messages = [];
    }

    // Add interactive component for reading
    new InteractiveObjectComponent(
      this,
      INTERACTIVE_OBJECT_TYPE.TEXT,
      (_heldObject) => {
        return this.read();
      },
    );

    this.disableObject();
  }

  public read(): boolean {
    if (this.#identifier === "bell") {
      this.scene.sound.play(ASSET_KEYS.BELL_SFX);
      return true;
    }

    if (this.#imageAssetKey) {
      const centerX = this.scene.cameras.main.centerX;
      const centerY = this.scene.cameras.main.centerY;
      EVENT_BUS.emit(CUSTOM_EVENTS.DISPLAY_PNG, {
        assetKey: this.#imageAssetKey,
        x: centerX,
        y: centerY,
        scale: this.#imageScale,
      });
    }

    const player = this.scene.children.list.find(
      (obj) => obj.constructor.name === "Player",
    ) as
      | (Phaser.GameObjects.GameObject & {
          direction: string;
          x: number;
          y: number;
        })
      | undefined;

    if (!player) {
      EVENT_BUS.emit(CUSTOM_EVENTS.DIALOG_START, {
        messages: this.#messages,
        choices: [],
      });
      return true;
    }

    EVENT_BUS.emit(CUSTOM_EVENTS.DIALOG_START, {
      messages: this.#messages,
      choices: [],
    });
    return true;
  }

  public enableObject(): void {
    (this.body as Phaser.Physics.Arcade.Body).enable = true;
    this.active = true;
  }

  public disableObject(): void {
    (this.body as Phaser.Physics.Arcade.Body).enable = false;
    this.active = false;
  }
}
