export const FISH_IDENTIFICATION_MINI_GAME: FishingMiniGameDefinition = {
  id: "fish-identification",
  instructions: "Name that aquatic creature!",
  inputPlaceholder: "Type the creature name",
  scoring: {
    correctDelta: 10,
    incorrectDelta: 2,
    timerDelayMs: 1000,
    timerProgressDelta: 1,
    progressBounds: {
      caught: 0,
      start: 30,
      escaped: 60,
    },
  },
  preload: (scene) => {
    FISH_IMAGE_QUESTIONS.forEach((fish) => {
      scene.load.image(fish.key, fish.assetUrl);
    });
  },
  getNextQuestion: (scene) => {
    const fish = drawFromQuestionPool(
      scene,
      FISH_IDENTIFICATION_POOL_ID,
      FISH_IMAGE_QUESTIONS,
    );

    return {
      id: fish.key,
      answers: fish.answers,
      content: {
        type: "image",
        textureKey: fish.key,
        maxWidthRatio: fish.maxWidthRatio ?? 0.7,
        maxHeight: fish.maxHeight ?? 150,
      },
    };
  },
};
