export type GameObject =
  | Phaser.GameObjects.Sprite
  | Phaser.GameObjects.Image
  | Phaser.GameObjects.Zone;

export type VisualGameObject =
  | Phaser.GameObjects.Sprite
  | Phaser.GameObjects.Image;

/**
 * Type guard to check if a GameObject is a visual object (Sprite or Image)
 * and not a Zone
 */
export function isVisualGameObject(obj: GameObject): obj is VisualGameObject {
  return (
    obj instanceof Phaser.GameObjects.Sprite ||
    obj instanceof Phaser.GameObjects.Image
  );
}

// Union type for all interactive objects that can be detected by proximity
export type InteractiveGameObject =
  | CampgroundButton<CampgroundControlsType>
  | Chest
  | Deliverable
  | DeliveryBox
  | FloorToggle
  | HidingPlace
  | NPC
  | Readable
  | ReadableSprite
  | Switch
  | InteractiveCandle
  | InteractiveDesk
  | MiningSpot
  | Rock;

export type InteractiveObjectType =
  keyof typeof CONSTANTS.INTERACTIVE_OBJECT_TYPE;

