import { CHARACTER_ANIMATIONS } from "../../../common/assets";
import { DEATH_REASON } from "../../../common/constants";
import { CUSTOM_EVENTS, EVENT_BUS } from "../../../common/event-bus";
import type { DeathReason } from "../../../common/types";
import { isArcadePhysicsBody } from "../../../common/utils";
import { type CharacterObject } from "../../../entities/common/character-object";
import { HeldObjectComponent } from "../../held-object-component";
import { ThrowableObjectComponent } from "../../throwable-object-component";
import { ToolComponent } from "../../tool-component";
import { BaseCharacterState } from "./base-character-state";
import { CHARACTER_STATES } from "./character-states";

export class DeathState extends BaseCharacterState {
  #onDieCallback: () => void;

  constructor(
    gameObject: CharacterObject,
    onDieCallback: () => void = () => undefined,
  ) {
    super(CHARACTER_STATES.DEATH_STATE, gameObject);
    this.#onDieCallback = onDieCallback;
  }

  public onEnter(): void {
    if (isArcadePhysicsBody(this._gameObject.body)) {
      this._gameObject.body.setVelocity(0, 0);
    }

    const heldComponent = HeldObjectComponent.getComponent<HeldObjectComponent>(
      this._gameObject,
    );
    if (heldComponent?.object) {
      const throwComponent =
        ThrowableObjectComponent.getComponent<ThrowableObjectComponent>(
          heldComponent.object,
        );
      if (throwComponent !== undefined) {
        throwComponent.drop();
      }
      heldComponent.drop(this._gameObject.direction);
    }

    const toolComponent = ToolComponent.getComponent<ToolComponent>(
      this._gameObject,
    );
    if (toolComponent?.tool) {
      toolComponent.tool.reset();
    }

    this._gameObject.invulnerableComponent.invulnerable = true;
    (this._gameObject.body as Phaser.Physics.Arcade.Body).enable = false;

    this._gameObject.animationComponent.playAnimation(
      CHARACTER_ANIMATIONS.DEFEATED_DOWN,
      () => {
        this.#triggerDefeated();
      },
    );
  }

  public onUpdate(): void {
    // Check for Enter key press to skip death animation
    if (
      this._gameObject.animationComponent.isAnimationPlaying() &&
      this._gameObject.controls.isEnterKeyJustDown
    ) {
      this._gameObject.anims.stop();
      this.#triggerDefeated();
    }
  }

  #triggerDefeated(): void {
    this._gameObject.disableObject();
    if (this._gameObject.isEnemy) {
      EVENT_BUS.emit(CUSTOM_EVENTS.ENEMY_DESTROYED);
    } else {
      // Use the character's stored death reason, defaulting to UNKNOWN if not set
      const deathReason =
        this._gameObject.lastDeathReason ||
        (DEATH_REASON.UNKNOWN as DeathReason);
      EVENT_BUS.emit(CUSTOM_EVENTS.PLAYER_DEFEATED, deathReason);
    }

    this.#onDieCallback();
  }
}
