import type * as Phaser from "phaser";
import type { GameObject } from "../common/types";

export class BaseGameObjectComponent {
  protected scene: Phaser.Scene;
  protected gameObject: GameObject;

  constructor(gameObject: GameObject) {
    this.scene = gameObject.scene;
    this.gameObject = gameObject;
    this.assignComponentToOject(gameObject);
  }

  // eslint-disable-next-line @typescript-eslint/no-unnecessary-type-parameters
  static getComponent<T>(gameObject: GameObject): T {
    return gameObject[`_${this.name}` as keyof GameObject] as T;
  }

  static removeComponent(gameObject: GameObject): void {
    // eslint-disable-next-line @typescript-eslint/no-dynamic-delete
    delete gameObject[`_${this.name}` as keyof GameObject];
  }

  protected assignComponentToOject(
    object: GameObject | Phaser.Physics.Arcade.Body,
  ): void {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any, @typescript-eslint/no-unsafe-member-access
    (object as any)[`_${this.constructor.name}`] = this;
  }
}
