function maskPhrase(phrase: string): string {
  const maskChar = LETTER_MASK_CHAR;
  const letterCounts: Record<string, number> = {};
  let totalLetters = 0;

  for (const ch of phrase) {
    if (/[A-Za-z]/.test(ch)) {
      const upper = ch.toUpperCase();
      letterCounts[upper] = (letterCounts[upper] || 0) + 1;
      totalLetters++;
    }
  }

  if (totalLetters === 0) {
    return phrase;
  }

  const revealed = new Set<string>();

  const getCoverage = () => {
    let visible = 0;
    for (const [letter, count] of Object.entries(letterCounts)) {
      if (revealed.has(letter)) {
        visible += count;
      }
    }
    return visible / totalLetters;
  };

  let coverage = getCoverage();

  if (coverage < TARGET_RATIO) {
    const remainingLetters = Object.keys(letterCounts).filter(
      (letter) => !revealed.has(letter),
    );
    shuffleArray(remainingLetters);

    for (const letter of remainingLetters) {
      revealed.add(letter);
      coverage = getCoverage();
      if (coverage >= TARGET_RATIO) {
        break;
      }
    }
  }

  let result = "";

  for (const ch of phrase) {
    if (/[A-Za-z]/.test(ch)) {
      const upper = ch.toUpperCase();
      result += revealed.has(upper) ? ch : maskChar;
    } else {
      result += ch;
    }
  }

  return result;
}

function formatWheelOfFishBoard(maskedPhrase: string): string {
  const words = maskedPhrase
    .trim()
    .toUpperCase()
    .split(/\s+/)
    .filter((word) => word.length > 0);

  const lines: string[] = [];
  let currentLine = "";

  for (const word of words) {
    const nextToken =
      currentLine.length === 0 ? word : `${WHEEL_WORD_GAP}${word}`;
    if (
      currentLine.length > 0 &&
      currentLine.length + nextToken.length > WHEEL_MAX_LINE_LENGTH
    ) {
      lines.push(currentLine);
      currentLine = word;
      continue;
    }

    currentLine += nextToken;
  }

  if (currentLine.length > 0) {
    lines.push(currentLine);
  }

  return lines.join("\n");
}

const WHEEL_OF_FISH_POOL_ID = "wheel-of-fish";

export const WHEEL_OF_FISH_MINI_GAME: FishingMiniGameDefinition = {
  id: "wheel-of-fish",
  instructions: "Solve the fishy phrase!",
  inputPlaceholder: "Guess the full phrase",
  scoring: {
    correctDelta: 10,
    incorrectDelta: 4,
    timerDelayMs: 1000,
    timerProgressDelta: 1,
  },
  getNextQuestion: (scene) => {
    const puzzle = drawFromQuestionPool(
      scene,
      WHEEL_OF_FISH_POOL_ID,
      WHEEL_OF_FISH_PUZZLES,
    );
    const answers = puzzle.answers ?? [puzzle.phrase];
    const masked = maskPhrase(puzzle.phrase);
    const formatted = formatWheelOfFishBoard(masked);

    return {
      id: `wheel-${puzzle.id}`,
      answers,
      content: {
        type: "text",
        text: formatted,
        style: {
          fontSize: "32px",
          fontFamily: "monospace",
          letterSpacing: 6,
        },
        maxWidthRatio: 0.9,
      },
    };
  },
};
