import type { TeamHuntState } from "@hunt/public-client";
import * as Phaser from "phaser";
import BBCodeTextPlugin from "./common/BBCodeTextPlugin";
import { ENABLE_DEBUG } from "./common/config";
import {
  GAME_RENDER_WINDOW_SIZE,
  ROUND_TO_PRELOAD_SCENE,
} from "./common/constants";
import {
  type DataManager,
  attachDataManagerToGame,
} from "./common/data-manager";
export type { SceneLoader } from "./scene-loaders/types";
import type { SceneLoader } from "./scene-loaders/types";
import { SCENE_KEYS } from "./scenes/scene-keys";
import type { InteractionState } from "./types";

//  Find out more information about the Game Config at:
//  https://docs.phaser.io/api-documentation/typedef/types-core#gameconfig
const config: Phaser.Types.Core.GameConfig = {
  type: Phaser.WEBGL,
  pixelArt: true,
  roundPixels: true,
  width: GAME_RENDER_WINDOW_SIZE.width,
  height: GAME_RENDER_WINDOW_SIZE.height,
  scale: {
    mode: Phaser.Scale.NONE,
  },
  canvasStyle: "height: 100%; aspect-ratio: 1/1; margin: auto",
  backgroundColor: "#000000",
  physics: {
    default: "arcade",
    arcade: {
      gravity: { y: 0, x: 0 },
      debug: ENABLE_DEBUG,
    },
  },
  plugins: {
    global: [
      {
        key: "BBCodeTextPlugin",
        plugin: BBCodeTextPlugin,
        start: true,
      },
    ],
  },
  scene: [],
};

const StartGame = (
  parent: string,
  interactionState: InteractionState | undefined,
  teamState: TeamHuntState | undefined,
  roundSlug: keyof typeof ROUND_TO_PRELOAD_SCENE,
  dataManager: DataManager,
  volume: number,
  sceneLoader?: SceneLoader,
): Phaser.Game => {
  const game = new Phaser.Game({ ...config, parent });

  attachDataManagerToGame(game, dataManager);

  // Store initial state in the game registry so scenes can access it
  if (interactionState) {
    game.registry.set("interactionState", interactionState);
  }
  if (teamState) {
    game.registry.set("teamState", teamState);
  }

  game.registry.set("initialVolume", volume);

  // Call custom scene loader if provided
  if (sceneLoader) {
    sceneLoader(game);
    return game;
  }

  // Start with the appropriate preload scene based on the round
  const preloadSceneKey = roundSlug
    ? ROUND_TO_PRELOAD_SCENE[roundSlug]
    : SCENE_KEYS.AVIARIA_PRELOAD_SCENE;
  game.scene.start(preloadSceneKey);
  return game;
};

export default StartGame;
