const EMOJI_PUZZLE_POOL_ID = "emoji-riddles";

export const EMOJI_RIDDLES_MINI_GAME: FishingMiniGameDefinition = {
  id: "emoji-riddles",
  instructions: "",
  inputPlaceholder: "Type your guess",
  scoring: {
    correctDelta: 10,
    incorrectDelta: 4,
    timerDelayMs: 1000,
    timerProgressDelta: 1,
    progressBounds: {
      caught: 0,
      start: 30,
      escaped: 60,
    },
  },
  preload: (scene) => {
    // Collect all unique emojis from the puzzles
    const allEmojiText = EMOJI_PUZZLES.map(
      (p) => p.categoryEmoji + p.clueEmoji,
    ).join("");
    const uniqueEmojis = new Set<string>();

    // Parse all emojis and collect their URLs
    const parsedEmojis = parseEmoji(allEmojiText);
    parsedEmojis.forEach((emoji) => {
      const key = emoji.url.split("/").pop()?.split(".")[0];
      if (!key) {
        throw new Error(`failed extracting key from ${emoji.url}`);
      }
      const textureKey = `emoji_${key}`;
      if (!uniqueEmojis.has(textureKey)) {
        uniqueEmojis.add(textureKey);
        scene.load.image(textureKey, emoji.url);
      }
    });
  },
  getNextQuestion: (scene) => {
    const puzzle = drawFromQuestionPool(
      scene,
      EMOJI_PUZZLE_POOL_ID,
      EMOJI_PUZZLES,
    );

    return {
      id: `emoji-${puzzle.id}`,
      answers: puzzle.answers,
      content: {
        type: "text",
        text: `${puzzle.categoryEmoji}:${puzzle.clueEmoji}`,
        style: {
          fontSize: "40px",
          fontFamily:
            '"Noto Color Emoji Subset", "Noto Color Emoji", "Apple Color Emoji", "Segoe UI Emoji", "Twemoji Mozilla", "system emoji", "monospace", sans-serif',
        },
        hasEmoji: true,
      },
    };
  },
};
