import type { TeamHuntState } from "@hunt/public-client";
import { useGlobalVolume } from "@hunt/puzzle-components";
import type * as Phaser from "phaser";
import React, { forwardRef, useEffect, useLayoutEffect, useRef } from "react";
import { PhaserGameStructure } from "./PhaserGameStructure";
import {
  FLAG_TO_INTERACTION_MAP,
  ROUND_TO_GAMEWORLD_START,
  ROUND_TO_INTERACTION_START,
} from "./common/constants";
import {
  type DataManager,
  detachDataManagerFromGame,
} from "./common/data-manager";
import { EVENT_BUS, CUSTOM_EVENTS } from "./common/event-bus";
import type { LevelName } from "./common/types";
import { EVENT_ID } from "./entities/npcs/npc-constants";
import StartGame from "./gameworld";
import type { SceneLoader } from "./scene-loaders/types";
import type { InteractionState } from "./types";

export type IRefPhaserGame = {
  game: Phaser.Game | null;
  scene: Phaser.Scene | null;
};

type IProps = {
  currentActiveScene?: (scene_instance: Phaser.Scene) => void;
  interactionState?: InteractionState;
  teamState?: TeamHuntState;
  dataManager: DataManager;
  roundSlug: keyof typeof ROUND_TO_INTERACTION_START;
  sceneLoader?: SceneLoader;
};

const isRoundUnlocked = (teamState: TeamHuntState, round: string): boolean => {
  return (
    !!teamState.rounds[round] && teamState.rounds[round].locked === "unlocked"
  );
};

const isInteractionCompleted = (teamState: TeamHuntState, round: string) => {
  const interactionId =
    FLAG_TO_INTERACTION_MAP[round as keyof typeof FLAG_TO_INTERACTION_MAP];
  return interactionId
    ? teamState.rounds[round].interactions?.[interactionId]?.state ===
        "completed"
    : false;
};

export const PhaserGame = forwardRef<IRefPhaserGame, IProps>(
  function PhaserGame(
    {
      currentActiveScene,
      interactionState,
      teamState,
      dataManager,
      roundSlug,
      sceneLoader,
    },
    ref,
  ) {
    const game = useRef<Phaser.Game | null>(null);
    const wrapperRef = useRef<HTMLDivElement>(null);
    const initialized = useRef(false);
    const [isFullscreen, setIsFullscreen] = React.useState(false);

    const volume = useGlobalVolume();

    useLayoutEffect(() => {
      if (!initialized.current) {
        let start:
          | {
              level: LevelName;
              room: number;
              door: number;
            }
          | undefined;

        if (teamState) {
          start = isRoundUnlocked(teamState, roundSlug)
            ? isInteractionCompleted(teamState, roundSlug)
              ? (ROUND_TO_GAMEWORLD_START[
                  roundSlug as keyof typeof ROUND_TO_GAMEWORLD_START
                ] as (typeof ROUND_TO_GAMEWORLD_START)[keyof typeof ROUND_TO_GAMEWORLD_START])
              : (ROUND_TO_INTERACTION_START[
                  roundSlug as keyof typeof ROUND_TO_INTERACTION_START
                ] as (typeof ROUND_TO_INTERACTION_START)[keyof typeof ROUND_TO_INTERACTION_START])
            : undefined;
        }

        if (roundSlug === "aviaria") {
          const getLuteEventViewed = dataManager.hasEventId(EVENT_ID.GET_LUTE);
          start = {
            level: "MOUNTAIN" as LevelName,
            room: getLuteEventViewed ? 1 : 11,
            door: getLuteEventViewed ? 1 : 1102,
          };
        }

        if (start) {
          dataManager.updateAreaData(start.level, start.room, start.door);
        }

        game.current = StartGame(
          "game-container",
          interactionState,
          teamState,
          roundSlug,
          dataManager,
          volume,
          sceneLoader,
        );
        initialized.current = true;

        if (typeof ref === "function") {
          ref({ game: game.current, scene: null });
        } else if (ref) {
          ref.current = { game: game.current, scene: null };
        }
      }

      return () => {
        if (game.current) {
          detachDataManagerFromGame(game.current, dataManager);
          game.current.destroy(true);
          game.current = null;
        }
        initialized.current = false;
      };
    }, [interactionState, teamState, dataManager, roundSlug, sceneLoader, ref]);

    useEffect(() => {
      EVENT_BUS.on(
        CUSTOM_EVENTS.CURRENT_SCENE_READY,
        (scene_instance: Phaser.Scene) => {
          if (currentActiveScene && typeof currentActiveScene === "function") {
            currentActiveScene(scene_instance);
          }

          if (typeof ref === "function") {
            ref({ game: game.current, scene: scene_instance });
          } else if (ref) {
            ref.current = { game: game.current, scene: scene_instance };
          }
        },
      );
      return () => {
        EVENT_BUS.removeListener(CUSTOM_EVENTS.CURRENT_SCENE_READY);
      };
    }, [currentActiveScene, ref]);

    const toggleFullscreen = () => {
      if (!wrapperRef.current) return;

      if (!document.fullscreenElement) {
        void wrapperRef.current.requestFullscreen();
      } else {
        void document.exitFullscreen();
      }
    };

    useEffect(() => {
      const onFullscreenChange = (): void => {
        setIsFullscreen(!!document.fullscreenElement);
      };

      window.addEventListener("fullscreenchange", onFullscreenChange);

      return () => {
        window.removeEventListener("fullscreenchange", onFullscreenChange);
      };
    }, []);

    return (
      <PhaserGameStructure
        wrapperRef={wrapperRef}
        onFullscreenClick={toggleFullscreen}
        isFullscreen={isFullscreen}
      />
    );
  },
);
