import { DIRECTION } from "../common/constants";
import type { Direction, GameObject } from "../common/types";
import { isCustomObject } from "../common/utils";
import { BaseGameObjectComponent } from "./base-game-object";

export class HeldObjectComponent extends BaseGameObjectComponent {
  #object: GameObject | undefined;

  get object(): GameObject | undefined {
    return this.#object;
  }

  set object(object: GameObject | undefined) {
    this.#object = object;
  }

  public drop(direction: Direction): void {
    if (this.#object === undefined || !isCustomObject(this.#object)) {
      this.#object = undefined;
      return;
    }
    this.#object.setDepth(0);
    this.#object.setOrigin(0, 0);

    let objectX = this.#object.x - this.#object.width / 2;
    let objectY = this.#object.y - this.#object.height / 2;

    if (direction === DIRECTION.LEFT) {
      objectX -= this.#object.width;
    } else if (direction === DIRECTION.RIGHT) {
      objectX += this.#object.width + 4;
    }

    if (direction === DIRECTION.UP) {
      objectY -= this.#object.height;
    } else if (direction === DIRECTION.DOWN) {
      objectY += this.#object.height + 16;
    } else {
      objectY += this.#object.height;
    }

    this.#object.setPosition(objectX, objectY);
    this.#object.enableObject();
    this.#object = undefined;
  }
}
