  #createJumpingAnimations(): void {
    // Create all jumping animations programmatically (not defined in player.json)

    const configs: [string, [number, number, number]][] = [
      ["down", [1, 2, 1]],
      ["up", [17, 18, 17]],
      ["right", [33, 34, 33]],
    ];

    for (const [direction, frames] of configs) {
      this.anims.create({
        key: `player_jump_${direction}`,
        frames: [
          { key: ASSET_KEYS.PLAYER, frame: frames[0], duration: 200 },
          { key: ASSET_KEYS.PLAYER, frame: frames[1], duration: 200 },
          { key: ASSET_KEYS.PLAYER, frame: frames[0], duration: 100 },
        ],
        repeat: 0,
      });
    }
  }

  #createFishingAnimation(config: FishingAnimationConfig): void {
    // Cast sequence: frames 128, 129, 13
    this.anims.create({
      key: `PLAYER_CAST_${config.direction}`,
      frames: [
        { key: ASSET_KEYS.PLAYER, frame: config.cast.player[0], duration: 180 },
        { key: ASSET_KEYS.PLAYER, frame: config.cast.player[1], duration: 100 },
        { key: ASSET_KEYS.PLAYER, frame: config.cast.player[2], duration: 100 },
      ],
      repeat: 0,
    });

    this.anims.create({
      key: `FISHING_ROD_CAST_${config.direction}`,
      frames: [
        {
          key: config.fishingRodAsset,
          frame: config.cast.fishingRod[0],
          duration: 180,
        },
        {
          key: config.fishingRodAsset,
          frame: config.cast.fishingRod[1],
          duration: 100,
        },
        {
          key: config.fishingRodAsset,
          frame: config.cast.fishingRod[2],
          duration: 100,
        },
      ],
      repeat: 0,
    });

    // Wait: frame 13 (holding the line)
    this.anims.create({
      key: `PLAYER_WAIT_${config.direction}`,
      frames: [{ key: ASSET_KEYS.PLAYER, frame: config.wait.player[0] }],
      frameRate: 6.67,
      repeat: -1,
    });

    this.anims.create({
      key: `FISHING_ROD_WAIT_${config.direction}`,
      frames: [
        { key: config.fishingRodAsset, frame: config.wait.fishingRod[0] },
      ],
      frameRate: 6.67,
      repeat: -1,
    });

    // Bite: frames 131 and 129 only (skipping 130)
    this.anims.create({
      key: `PLAYER_FISH_BITE_${config.direction}`,
      frames: [
        {
          key: ASSET_KEYS.PLAYER,
          frame: config.fishBite.player[0],
          duration: 300,
        },
        {
          key: ASSET_KEYS.PLAYER,
          frame: config.fishBite.player[1],
          duration: 400,
        },
      ],
      repeat: -1, // Loop indefinitely
    });

    this.anims.create({
      key: `FISHING_ROD_FISH_BITE_${config.direction}`,
      frames: [
        {
          key: config.fishingRodAsset,
          frame: config.fishBite.fishingRod[0],
          duration: 300,
        },
        {
          key: config.fishingRodAsset,
          frame: config.fishBite.fishingRod[1],
          duration: 400,
        },
      ],
      repeat: -1, // Loop indefinitely
    });

    // Caught: frames 128, 14
    this.anims.create({
      key: `PLAYER_FISH_CAUGHT_${config.direction}`,
      frames: [
        {
          key: ASSET_KEYS.PLAYER,
          frame: config.fishCaught.player[0],
          duration: 400,
        },
        {
          key: ASSET_KEYS.PLAYER,
          frame: config.fishCaught.player[1],
          duration: 900,
        },
      ],
      repeat: 0,
    });

    this.anims.create({
      key: `FISHING_ROD_FISH_CAUGHT_${config.direction}`,
      frames: [
        {
          key: config.fishingRodAsset,
          frame: config.fishCaught.fishingRod[0],
          duration: 400,
        },
        {
          key: config.fishingRodAsset,
          frame: config.fishCaught.fishingRod[1],
          duration: 900,
        },
      ],
      repeat: 0,
    });
  }
