import * as Phaser from "phaser";
import {
  ANIMATED_OBJECT_ANIMATION_KEYS,
  ASSET_KEYS,
} from "../../common/assets";
import { ANIMATED_OBJECT_EFFECT } from "../../common/tiled/constants";
import type { TiledAnimatedObject } from "../../common/tiled/types";
import type { CustomObject } from "../../common/types";

export class AnimatedObject
  extends Phaser.GameObjects.Sprite
  implements CustomObject
{
  #effect?: string;
  #animationKey?: string;
  #trigger?: string;
  #glowImage?: Phaser.GameObjects.Image;

  constructor(scene: Phaser.Scene, config: TiledAnimatedObject) {
    const assetKeyName = config.texture as keyof typeof ASSET_KEYS;
    const assetKey = ASSET_KEYS[assetKeyName];

    if (!assetKey) {
      console.warn(
        `Unknown animated object asset key: ${assetKeyName}. Texture: ${config.texture}`,
      );
    }

    // Create sprite at the position (super must be called first)
    super(scene, config.x, config.y, assetKey, 0);

    // Use texture directly as the animation key (convert to lowercase)
    const animationKey =
      ANIMATED_OBJECT_ANIMATION_KEYS[
        config.texture as keyof typeof ANIMATED_OBJECT_ANIMATION_KEYS
      ];
    // Store animation key after super call
    this.#animationKey = animationKey;

    // Store trigger
    this.#trigger = config.trigger;

    scene.add.existing(this);
    this.setOrigin(0, 0);

    // Start all animated objects at frame 0
    this.setFrame(0);

    // Store effect for later use
    this.#effect = config.effect;

    // Apply glow effect if specified
    if (this.#effect === ANIMATED_OBJECT_EFFECT.GLOW) {
      this.#glowImage = scene.add.image(
        config.x + this.displayWidth / 2,
        config.y + this.displayHeight / 2,
        ASSET_KEYS.GLOW,
      );
      this.#glowImage.setOrigin(0.5, 0.5);
    }

    this.disableObject();
  }

  public enableObject(): void {
    this.active = true;
    this.visible = true;

    // Only auto-play if trigger is "always" or undefined (default behavior)
    if (this.#trigger === "always" || this.#trigger === undefined) {
      const animationKey = this.#animationKey;
      if (animationKey && this.scene.anims.exists(animationKey)) {
        if (!this.anims.isPlaying) {
          // Randomize start time (0 to 1000ms delay) for de-syncing
          const randomDelay = Math.random() * 1000;

          // Delay the animation start slightly to de-sync effects
          this.scene.time.delayedCall(randomDelay, () => {
            if (this.active && !this.anims.isPlaying && animationKey) {
              this.play({ key: animationKey, repeat: -1 });
            }
          });
        }
      }
    }
    // For other triggers, wait for external trigger
  }

  public disableObject(): void {
    this.active = false;
    this.visible = false;
    this.anims.stop();
    // Reset to frame 0
    this.setFrame(0);
  }

  public get trigger(): string | undefined {
    return this.#trigger;
  }

  /**
   * Plays an animation by key. The animation will stay on its final frame when complete.
   * @param animationKey The key of the animation to play
   * @param onComplete Optional callback when animation completes
   */
  public playAnimation(animationKey: string, onComplete?: () => void): void {
    if (!this.scene.anims.exists(animationKey)) {
      console.warn(`Animation key "${animationKey}" does not exist`);
      return;
    }

    // Play animation - Phaser will keep it on the final frame when complete (repeat: 0)
    this.anims.play(animationKey);

    if (onComplete) {
      // Get animation duration from the animation manager
      const anim = this.scene.anims.get(animationKey);
      if (anim) {
        this.scene.time.delayedCall(anim.duration, () => {
          onComplete();
        });
      }
    }
  }
}
