import type {
  ActivityLogEntry,
  GameworldActivityLogEntry,
  GameworldEventLogEntry,
} from "@hunt/public-client";
import React from "react";
import { markTaskSolved } from "../../../components/puzzleSolveLocalState";
import { FLAG_TO_GATE_MAP, FLAG_TO_INTERACTION_MAP } from "./common/constants";
import type { InteractionState } from "./types";

const GAMEWORLD_LOCAL_STATE_KEY = "hunt.gameworld.localState.v1";
const GAMEWORLD_LOCAL_STATE_VERSION = 1;

export const GAMEWORLD_LOCAL_STATE_EVENT = "hunt.gameworldLocalState";

type SerializedGameworldActivityLogEntry =
  GameworldActivityLogEntry extends infer Entry
    ? Entry extends { timestamp: Date }
      ? Omit<Entry, "timestamp"> & { timestamp: string }
      : never
    : never;

type SerializedActivityLogEntry = ActivityLogEntry extends infer Entry
  ? Entry extends { timestamp: Date }
    ? Omit<Entry, "timestamp"> & { timestamp: string }
    : never
  : never;

type GameworldLocalState = {
  version: number;
  nextActivityId: number;
  nextEventId: number;
  nextInteractionId: number;
  activityLog: SerializedGameworldActivityLogEntry[];
  eventLog: GameworldEventLogEntry[];
  interactionLog: SerializedActivityLogEntry[];
  completedInteractions: string[];
};

const DEFAULT_LOCAL_STATE: GameworldLocalState = {
  version: GAMEWORLD_LOCAL_STATE_VERSION,
  nextActivityId: 1,
  nextEventId: 1,
  nextInteractionId: 1,
  activityLog: [],
  eventLog: [],
  interactionLog: [],
  completedInteractions: [],
};

const canUseStorage = () =>
  typeof window !== "undefined" && typeof window.localStorage !== "undefined";

let memoryFallbackState: GameworldLocalState | null = null;

const emitLocalStateEvent = () => {
  if (typeof window === "undefined") return;
  window.dispatchEvent(new CustomEvent(GAMEWORLD_LOCAL_STATE_EVENT));
};

const normalizeActivityLog = (
  entries?: unknown,
): SerializedGameworldActivityLogEntry[] => {
  if (!Array.isArray(entries)) {
    return [];
  }
  return entries.filter(
    (entry): entry is SerializedGameworldActivityLogEntry => {
      if (!entry || typeof entry !== "object") {
        return false;
      }
      const candidate = entry as Record<string, unknown>;
      return (
        typeof candidate.id === "number" &&
        typeof candidate.type === "string" &&
        typeof candidate.level === "string" &&
        typeof candidate.object_id === "string" &&
        typeof candidate.timestamp === "string"
      );
    },
  );
};

const normalizeEventLog = (entries?: unknown): GameworldEventLogEntry[] => {
  if (!Array.isArray(entries)) {
    return [];
  }
  return entries.filter((entry): entry is GameworldEventLogEntry => {
    if (!entry || typeof entry !== "object") {
      return false;
    }
    const candidate = entry as Record<string, unknown>;
    return (
      typeof candidate.id === "number" &&
      typeof candidate.type === "string" &&
      typeof candidate.level === "string" &&
      typeof candidate.timestamp === "string"
    );
  });
};

const normalizeInteractionLog = (
  entries?: unknown,
): SerializedActivityLogEntry[] => {
  if (!Array.isArray(entries)) {
    return [];
  }
  return entries.filter((entry): entry is SerializedActivityLogEntry => {
    if (!entry || typeof entry !== "object") {
      return false;
    }
    const candidate = entry as Record<string, unknown>;
    return (
      typeof candidate.id === "number" &&
      typeof candidate.type === "string" &&
      typeof candidate.timestamp === "string"
    );
  });
};

const normalizeCompletedInteractions = (
  entries?: unknown,
  interactionLog?: SerializedActivityLogEntry[],
): string[] => {
  const completed = new Set<string>();
  if (Array.isArray(entries)) {
    entries.forEach((entry) => {
      if (typeof entry === "string") {
        completed.add(entry);
      }
    });
  }
  (interactionLog ?? []).forEach((entry) => {
    if (
      entry.type === "interaction_completed" &&
      typeof entry.slug === "string"
    ) {
      completed.add(entry.slug);
    }
  });
  return Array.from(completed);
};

const computeNextId = (entries: { id: number }[], fallback = 1): number => {
  const maxId = entries.reduce(
    (max, entry) => (entry.id > max ? entry.id : max),
    0,
  );
  return Math.max(fallback, maxId + 1);
};

const normalizeLocalState = (
  state?: Partial<GameworldLocalState> | null,
): GameworldLocalState => {
  const activityLog = normalizeActivityLog(state?.activityLog);
  const eventLog = normalizeEventLog(state?.eventLog);
  const interactionLog = normalizeInteractionLog(state?.interactionLog);
  const completedInteractions = normalizeCompletedInteractions(
    state?.completedInteractions,
    interactionLog,
  );

  return {
    version: GAMEWORLD_LOCAL_STATE_VERSION,
    activityLog,
    eventLog,
    interactionLog,
    completedInteractions,
    nextActivityId:
      typeof state?.nextActivityId === "number" &&
      Number.isFinite(state.nextActivityId)
        ? Math.max(state.nextActivityId, computeNextId(activityLog))
        : computeNextId(activityLog),
    nextEventId:
      typeof state?.nextEventId === "number" &&
      Number.isFinite(state.nextEventId)
        ? Math.max(state.nextEventId, computeNextId(eventLog))
        : computeNextId(eventLog),
    nextInteractionId:
      typeof state?.nextInteractionId === "number" &&
      Number.isFinite(state.nextInteractionId)
        ? Math.max(state.nextInteractionId, computeNextId(interactionLog))
        : computeNextId(interactionLog),
  };
};

export const loadGameworldLocalState = (): GameworldLocalState => {
  if (!canUseStorage()) {
    if (!memoryFallbackState) {
      memoryFallbackState = { ...DEFAULT_LOCAL_STATE };
    }
    return { ...memoryFallbackState };
  }

  try {
    const stored = window.localStorage.getItem(GAMEWORLD_LOCAL_STATE_KEY);
    const parsed = stored
      ? (JSON.parse(stored) as Partial<GameworldLocalState>)
      : null;
    const normalized = normalizeLocalState(parsed);
    if (!stored) {
      window.localStorage.setItem(
        GAMEWORLD_LOCAL_STATE_KEY,
        JSON.stringify(normalized),
      );
    }
    return normalized;
  } catch {
    if (!memoryFallbackState) {
      memoryFallbackState = { ...DEFAULT_LOCAL_STATE };
    }
    return { ...memoryFallbackState };
  }
};

const saveGameworldLocalState = (state: GameworldLocalState): void => {
  const normalized = normalizeLocalState(state);
  if (!canUseStorage()) {
    memoryFallbackState = normalized;
    return;
  }
  try {
    window.localStorage.setItem(
      GAMEWORLD_LOCAL_STATE_KEY,
      JSON.stringify(normalized),
    );
  } catch {
    memoryFallbackState = normalized;
  }
};

const deserializeActivityLog = (
  entries: SerializedGameworldActivityLogEntry[],
): GameworldActivityLogEntry[] => {
  return entries.map((entry) => ({
    ...entry,
    timestamp: new Date(entry.timestamp),
  }));
};

const deserializeInteractionLog = (
  entries: SerializedActivityLogEntry[],
): ActivityLogEntry[] => {
  return entries.map((entry) => ({
    ...entry,
    timestamp: new Date(entry.timestamp),
  })) as ActivityLogEntry[];
};

const autoSolveRules = new Map<string, { requiredInteractions: string[] }>([
  ["walking_on_water", { requiredInteractions: ["r2i01"] }],
  [
    "x_marks_the_spot",
    { requiredInteractions: ["r3i03", "r3i04", "r3i05", "r3i06", "r3i07"] },
  ],
  ["train_ride", { requiredInteractions: ["r3i02"] }],
  ["squirrel_chase", { requiredInteractions: ["r8i14"] }],
  [
    "riddled_treasures",
    { requiredInteractions: ["r8i15", "r8i16", "r8i17", "r8i18", "r8i19"] },
  ],
  ["burnhams_marbles", { requiredInteractions: ["r2i03"] }],
  ["mountain_cave", { requiredInteractions: ["r1i03"] }],
  [
    "heroic_songs",
    { requiredInteractions: ["r1i05", "r1i06", "r1i07", "r1i08"] },
  ],
  ["lost_papers", { requiredInteractions: ["r1i04"] }],
  ["visiting_mage", { requiredInteractions: ["r4i02"] }],
  ["wall_race", { requiredInteractions: ["r4i03"] }],
  ["cat_off", { requiredInteractions: ["r4i04"] }],
  [
    "paranormal_investigations",
    { requiredInteractions: ["r5i02", "r5i03", "r5i04"] },
  ],
  ["learn_ritual", { requiredInteractions: ["r5i06"] }],
  ["sightseeing", { requiredInteractions: ["r6i01"] }],
  [
    "x_marks_the_spot_2",
    { requiredInteractions: ["r7i01", "r7i02", "r7i03", "r7i04", "r7i05"] },
  ],
  ["hiding_the_trees", { requiredInteractions: ["r7i06"] }],
  ["package_delivery", { requiredInteractions: ["r6i02", "r6i03", "r6i04"] }],
  ["ringing_the_bell", { requiredInteractions: ["r9i01"] }],
]);

const interactionsToAutoSolvePuzzle = new Map<string, string>(
  Array.from(autoSolveRules.entries()).flatMap(([puzzleSlug, rule]) =>
    rule.requiredInteractions.map(
      (interactionId) => [interactionId, puzzleSlug] as [string, string],
    ),
  ),
);

const maybeAutoSolvePuzzle = (
  completedInteractions: Set<string>,
  interactionId: string,
) => {
  const puzzleSlug = interactionsToAutoSolvePuzzle.get(interactionId);
  if (!puzzleSlug) {
    return;
  }
  const requiredInteractions =
    autoSolveRules.get(puzzleSlug)?.requiredInteractions ?? [];
  const hasAllRequired = requiredInteractions.every((requiredId) =>
    completedInteractions.has(requiredId),
  );
  if (!hasAllRequired) {
    return;
  }
  markTaskSolved(puzzleSlug);
};

export const getGameworldActivityLog = (
  level?: string,
): GameworldActivityLogEntry[] => {
  const state = loadGameworldLocalState();
  const entries = deserializeActivityLog(state.activityLog);
  const filtered = level
    ? entries.filter((entry) => entry.level === level)
    : entries;
  return filtered.sort((a, b) => a.id - b.id);
};

export const getGameworldInteractionLog = (): ActivityLogEntry[] => {
  const state = loadGameworldLocalState();
  return deserializeInteractionLog(state.interactionLog).sort(
    (a, b) => a.id - b.id,
  );
};

/**
 * Build InteractionState from local storage for static site mode.
 * Used when there is no server to fetch interaction state from.
 */
export const interactionStateFromLocalStorage = (): InteractionState => {
  const state = loadGameworldLocalState();
  const completedInteractions = new Set(state.completedInteractions);
  const interactionLog = deserializeInteractionLog(state.interactionLog);

  const satisfiedGates = new Set<string>();
  const gateSlugs = new Set(Object.values(FLAG_TO_GATE_MAP));
  interactionLog.forEach((entry) => {
    if (
      entry.type === "gate_completed" &&
      typeof entry.slug === "string" &&
      gateSlugs.has(
        entry.slug as (typeof FLAG_TO_GATE_MAP)[keyof typeof FLAG_TO_GATE_MAP],
      )
    ) {
      satisfiedGates.add(entry.slug);
    }
  });

  const interactions: InteractionState["interactions"] = {};
  Object.entries(FLAG_TO_INTERACTION_MAP).forEach(([, interactionId]) => {
    if (completedInteractions.has(interactionId)) {
      interactions[interactionId] = {
        title: interactionId,
        state: "completed",
        virtual: false,
      };
    }
  });

  const gates: InteractionState["gates"] = {};
  gateSlugs.forEach((gateSlug) => {
    gates[gateSlug] = {
      satisfied: satisfiedGates.has(gateSlug),
    };
  });

  return {
    epoch: 0,
    interactions,
    gates,
  };
};

export const appendGameworldActivityEntry = (params: {
  type: GameworldActivityLogEntry["type"];
  level: string;
  object_id: string;
  frame?: string | null;
  timestamp?: string;
}): GameworldActivityLogEntry | null => {
  const state = loadGameworldLocalState();
  if (
    (params.type === "deliverable_consumed" ||
      params.type === "minesweeper_completed") &&
    state.activityLog.some(
      (entry) =>
        entry.type === params.type &&
        entry.level === params.level &&
        entry.object_id === params.object_id,
    )
  ) {
    return null;
  }

  const entry: SerializedGameworldActivityLogEntry = {
    id: state.nextActivityId,
    timestamp: params.timestamp ?? new Date().toISOString(),
    team_id: 0,
    level: params.level,
    type: params.type,
    object_id: params.object_id,
    frame: params.frame ?? null,
  };
  state.activityLog = [...state.activityLog, entry];
  state.nextActivityId = entry.id + 1;
  saveGameworldLocalState(state);
  emitLocalStateEvent();
  return {
    ...entry,
    timestamp: new Date(entry.timestamp),
  };
};

export const appendGameworldEventEntry = (params: {
  type: GameworldEventLogEntry["type"];
  level: string;
  death_reason?: string;
  data?: GameworldEventLogEntry["data"];
}): GameworldEventLogEntry => {
  const state = loadGameworldLocalState();
  const entry: GameworldEventLogEntry = {
    id: state.nextEventId,
    timestamp: new Date().toISOString(),
    team_id: 0,
    level: params.level,
    type: params.type,
    death_reason: params.death_reason ?? params.data?.death_reason ?? null,
    data: params.data,
  };
  state.eventLog = [...state.eventLog, entry];
  state.nextEventId = entry.id + 1;
  saveGameworldLocalState(state);
  emitLocalStateEvent();
  return entry;
};

export const recordInteractionCompleted = (
  interactionId: string,
  title?: string,
): boolean => {
  const state = loadGameworldLocalState();
  const completedInteractions = new Set(state.completedInteractions);
  if (completedInteractions.has(interactionId)) {
    return false;
  }
  completedInteractions.add(interactionId);
  state.completedInteractions = Array.from(completedInteractions);

  const entry: SerializedActivityLogEntry = {
    id: state.nextInteractionId,
    timestamp: new Date().toISOString(),
    team_id: 0,
    type: "interaction_completed",
    slug: interactionId,
    title: title ?? interactionId,
    result: "success",
    currency_delta: 0,
    strong_currency_delta: 0,
  };
  state.interactionLog = [...state.interactionLog, entry];
  state.nextInteractionId = entry.id + 1;
  saveGameworldLocalState(state);
  emitLocalStateEvent();

  maybeAutoSolvePuzzle(completedInteractions, interactionId);
  return true;
};

export const recordInteractionCompletedForFlag = (flag: string): boolean => {
  const interactionId =
    FLAG_TO_INTERACTION_MAP[flag as keyof typeof FLAG_TO_INTERACTION_MAP];
  if (!interactionId) {
    return false;
  }
  return recordInteractionCompleted(interactionId, flag);
};

export const useGameworldActivityLog = (
  level?: string,
  types?: GameworldActivityLogEntry["type"][],
): GameworldActivityLogEntry[] => {
  const [entries, setEntries] = React.useState<GameworldActivityLogEntry[]>(
    () => getGameworldActivityLog(level),
  );
  const typesKey = React.useMemo(() => (types ? types.join("|") : ""), [types]);

  React.useEffect(() => {
    if (typeof window === "undefined") return;
    const reload = () => {
      const nextEntries = getGameworldActivityLog(level);
      const filtered = types
        ? nextEntries.filter((entry) => types.includes(entry.type))
        : nextEntries;
      setEntries(filtered);
    };
    reload();
    const handleStorage = (event: StorageEvent) => {
      if (event.key === GAMEWORLD_LOCAL_STATE_KEY) {
        reload();
      }
    };
    window.addEventListener(GAMEWORLD_LOCAL_STATE_EVENT, reload);
    window.addEventListener("storage", handleStorage);
    return () => {
      window.removeEventListener(GAMEWORLD_LOCAL_STATE_EVENT, reload);
      window.removeEventListener("storage", handleStorage);
    };
  }, [level, typesKey, types]);

  return entries;
};

export const useGameworldInteractionLog = (): ActivityLogEntry[] => {
  const [entries, setEntries] = React.useState<ActivityLogEntry[]>(() =>
    getGameworldInteractionLog(),
  );

  React.useEffect(() => {
    if (typeof window === "undefined") return;
    const reload = () => {
      setEntries(getGameworldInteractionLog());
    };
    reload();
    const handleStorage = (event: StorageEvent) => {
      if (event.key === GAMEWORLD_LOCAL_STATE_KEY) {
        reload();
      }
    };
    window.addEventListener(GAMEWORLD_LOCAL_STATE_EVENT, reload);
    window.addEventListener("storage", handleStorage);
    return () => {
      window.removeEventListener(GAMEWORLD_LOCAL_STATE_EVENT, reload);
      window.removeEventListener("storage", handleStorage);
    };
  }, []);

  return entries;
};

/**
 * Hook that returns InteractionState from local storage, updating when
 * gameworld local state changes. For use in static site mode.
 */
export const useInteractionStateFromLocalStorage = (): InteractionState => {
  const [state, setState] = React.useState<InteractionState>(() =>
    interactionStateFromLocalStorage(),
  );

  React.useEffect(() => {
    if (typeof window === "undefined") return;
    const reload = () => {
      setState(interactionStateFromLocalStorage());
    };
    reload();
    window.addEventListener(GAMEWORLD_LOCAL_STATE_EVENT, reload);
    return () => {
      window.removeEventListener(GAMEWORLD_LOCAL_STATE_EVENT, reload);
    };
  }, []);

  return state;
};

export const resetGameworldLocalState = (): void => {
  saveGameworldLocalState({ ...DEFAULT_LOCAL_STATE });
  emitLocalStateEvent();
};
