import { THROW_ITEM_EFFECT_DELAY, THROW_ITEM_SPEED } from "../common/config";
import { DIRECTION } from "../common/constants";
import type { Direction, GameObject } from "../common/types";
import {
  assertNeverCalled,
  isArcadePhysicsBody,
  isCustomObject,
} from "../common/utils";
import { BaseGameObjectComponent } from "./base-game-object";

export class ThrowableObjectComponent extends BaseGameObjectComponent {
  #callback: () => void;

  constructor(gameObject: GameObject, callback = () => undefined) {
    super(gameObject);
    this.#callback = callback;
  }

  public drop(): void {
    this.#callback();
  }

  public throw(direction: Direction): void {
    if (
      !isArcadePhysicsBody(this.gameObject.body) ||
      !isCustomObject(this.gameObject)
    ) {
      this.#callback();
      return;
    }
    const body = this.gameObject.body;
    body.setVelocity(0, 0);

    const throwSpeed = THROW_ITEM_SPEED;
    switch (direction) {
      case DIRECTION.DOWN:
        this.gameObject.y += 20;
        body.velocity.y = throwSpeed;
        break;
      case DIRECTION.UP:
        body.velocity.y = -throwSpeed;
        break;
      case DIRECTION.LEFT:
        body.velocity.x = -throwSpeed;
        break;
      case DIRECTION.RIGHT:
        body.velocity.x = throwSpeed;
        break;
      default:
        assertNeverCalled(direction);
    }

    this.gameObject.enableObject();
    this.gameObject.scene.time.delayedCall(THROW_ITEM_EFFECT_DELAY, () => {
      body.setVelocity(0, 0);
      this.#callback();
    });
  }
}
