import { DIRECTION } from "../../../common/constants";
import type { Direction } from "../../../common/types";
import { isArcadePhysicsBody } from "../../../common/utils";
import { type CharacterObject } from "../../../entities/common/character-object";
import { BaseCharacterState } from "./base-character-state";
import { CHARACTER_STATES } from "./character-states";
import { handleInteraction } from "./interaction-utils";

export class RacingMoveState extends BaseCharacterState {
  #acceleration = 100; // Pixels per second squared
  #maxSpeed = 250; // Maximum speed in pixels per second
  #friction = 0.9; // Friction coefficient (0-1, lower = more friction)

  constructor(gameObject: CharacterObject) {
    super(CHARACTER_STATES.RACING_MOVE_STATE, gameObject);
  }

  public onEnter(): void {
    // Start with zero velocity
    this._resetVelocity();
  }

  public onUpdate(): void {
    if (!isArcadePhysicsBody(this._gameObject.body)) {
      return;
    }

    const controls = this._gameObject.controls;

    // Handle interactions (e.g., talking to NPCs) while racing
    if (handleInteraction(this._gameObject, this._stateMachine, controls)) {
      return;
    }

    const body = this._gameObject.body;
    const deltaTime = this._gameObject.scene.game.loop.delta / 1000; // Convert to seconds
    const hasHorizontalInput = controls.isLeftDown || controls.isRightDown;
    const hasVerticalInput = controls.isUpDown || controls.isDownDown;

    // Handle horizontal acceleration
    if (controls.isLeftDown) {
      body.velocity.x -= this.#acceleration * deltaTime;
    } else if (controls.isRightDown) {
      body.velocity.x += this.#acceleration * deltaTime;
    } else {
      // Apply friction when no input
      body.velocity.x *= this.#friction;
    }

    // Handle vertical acceleration
    if (controls.isUpDown) {
      body.velocity.y -= this.#acceleration * deltaTime;
    } else if (controls.isDownDown) {
      body.velocity.y += this.#acceleration * deltaTime;
    } else {
      // Apply friction when no input
      body.velocity.y *= this.#friction;
    }

    // Clamp velocity to max speed
    const speed = Math.sqrt(
      body.velocity.x * body.velocity.x + body.velocity.y * body.velocity.y,
    );
    if (speed > this.#maxSpeed) {
      const scale = this.#maxSpeed / speed;
      body.velocity.x *= scale;
      body.velocity.y *= scale;
    }

    // Stop very small velocities only when there's no input (prevent jitter)
    // This allows low acceleration values to build up velocity over multiple frames
    if (!hasHorizontalInput && Math.abs(body.velocity.x) < 5) {
      body.velocity.x = 0;
    }
    if (!hasVerticalInput && Math.abs(body.velocity.y) < 5) {
      body.velocity.y = 0;
    }

    // Update direction based on primary movement (prioritize horizontal for diagonal)
    if (Math.abs(body.velocity.x) > Math.abs(body.velocity.y)) {
      if (body.velocity.x < 0) {
        this._gameObject.direction = DIRECTION.LEFT;
      } else if (body.velocity.x > 0) {
        this._gameObject.direction = DIRECTION.RIGHT;
      }
    } else {
      if (body.velocity.y < 0) {
        this._gameObject.direction = DIRECTION.UP;
      } else if (body.velocity.y > 0) {
        this._gameObject.direction = DIRECTION.DOWN;
      }
    }

    // Play animation based on direction (same animation for idle and move)
    this._gameObject.animationComponent.playAnimation(
      `RACING_MOVE_${this._gameObject.direction}`,
    );
  }

  /**
   * Called when the player collides with a wall - stops velocity in that direction
   */
  public handleWallCollision(collisionDirection: Direction): void {
    if (!isArcadePhysicsBody(this._gameObject.body)) {
      return;
    }

    const body = this._gameObject.body;

    switch (collisionDirection) {
      case DIRECTION.LEFT:
        if (body.velocity.x < 0) {
          body.velocity.x = 0;
        }
        break;
      case DIRECTION.RIGHT:
        if (body.velocity.x > 0) {
          body.velocity.x = 0;
        }
        break;
      case DIRECTION.UP:
        if (body.velocity.y < 0) {
          body.velocity.y = 0;
        }
        break;
      case DIRECTION.DOWN:
        if (body.velocity.y > 0) {
          body.velocity.y = 0;
        }
        break;
    }
  }
}
