export const WORD_SCRAMBLE_MINI_GAME: FishingMiniGameDefinition = {
  id: "word-scramble",
  instructions: "Unscramble the letters\nfor a catch!",
  inputPlaceholder: "Type the word",
  scoring: {
    correctDelta: 6,
    incorrectDelta: 3,
    timerDelayMs: 1000,
    timerProgressDelta: 1,
  },
  getNextQuestion: (scene) => {
    const word = drawFromQuestionPool(
      scene,
      WORD_SCRAMBLE_POOL_ID,
      ANAGRAM_WORDS,
    );
    const scrambled = scrambleWord(word);

    return {
      id: `scramble-${word}`,
      answers: [word],
      content: {
        type: "text",
        text: scrambled,
        style: {
          letterSpacing: 8,
        },
      },
    };
  },
};
