import * as Phaser from "phaser";
import { ASSET_KEYS, MINE_ANIMATION_KEYS } from "../../common/assets";
import { REVEAL_TRIGGER } from "../../common/tiled/constants";
import type { RevealTriggerType } from "../../common/tiled/types";
import type { Position, CharacterColor } from "../../common/types";
import type { AnimationConfig } from "../../components/animation-component";
import { DiggableComponent } from "../../components/diggable-component";
import { InputComponent } from "../../components/input-component";
import { CHARACTER_STATES } from "../../components/state-machine/states/character-states";
import { IdleState } from "../../components/state-machine/states/idle-state";
import { CharacterObject } from "../common/character-object";

export type MineConfig = {
  scene: Phaser.Scene;
  position: Position;
  revealEnemyTrigger: RevealTriggerType;
  visibleTo?: CharacterColor[];
  type:
    | "MINESWEEPER_STANDARD"
    | "MINESWEEPER_BILLIARDS"
    | "MINESWEEPER_POKEMON";
};

export class Mine extends CharacterObject {
  #diggableComponent?: DiggableComponent;
  #revealEnemyTrigger: RevealTriggerType;

  constructor(config: MineConfig) {
    const animationConfig: AnimationConfig = {
      IDLE_DOWN: {
        key: MINE_ANIMATION_KEYS.IDLE,
        repeat: -1,
        ignoreIfPlaying: true,
      },
    };
    super({
      id: `mine-${Phaser.Math.RND.uuid()}`,
      scene: config.scene,
      position: config.position,
      assetKey: ASSET_KEYS.MINE,
      frame: 0,
      isPlayer: false,
      animationConfig,
      speed: 0,
      inputComponent: new InputComponent(),
      isInvulnerable: true,
      maxHP: 1,
      visibleTo: config.visibleTo,
    });
    this.#revealEnemyTrigger = config.revealEnemyTrigger;

    this.setOrigin(0, 0).setImmovable(true);
    if (this.revealEnemyTrigger === REVEAL_TRIGGER.NONE) {
      this.physicsBody
        .setSize(9, 9, true)
        .setOffset(this.width / 2 - 5, this.height / 2 - 5);
    } else if (this.revealEnemyTrigger === REVEAL_TRIGGER.DIG) {
      // For diggable mines, make the physics body cover the full tile (16x16)
      // TODO[LOWPRI]: Figure out why the bounding boxes of mines are
      // off when minesweeper is created.
      this.physicsBody.setSize(16, 16, true).setOffset(0, 0);
    }

    // Initialize components
    if (this.revealEnemyTrigger === REVEAL_TRIGGER.DIG) {
      this.#diggableComponent = new DiggableComponent(this);
    }

    // Add states
    this._stateMachine.addState(new IdleState(this));
    this._stateMachine.setState(CHARACTER_STATES.IDLE_STATE);
  }

  public enableObject(): void {
    // Only enable if not buried
    if (this.#diggableComponent?.isBuried()) {
      return;
    }
    super.enableObject();
  }

  get revealEnemyTrigger(): RevealTriggerType {
    return this.#revealEnemyTrigger;
  }
}
