import * as Phaser from "phaser";
import {
  ASSET_KEYS,
  DANGER_TUNA_ANIMATION_KEYS,
  DANGER_YELLOWFISH_ANIMATION_KEYS,
} from "../../common/assets";
import type { Direction, Position } from "../../common/types";
import type { AnimationConfig } from "../../components/animation-component";
import { InputComponent } from "../../components/input-component";
import { CHARACTER_STATES } from "../../components/state-machine/states/character-states";
import { PacingState } from "../../components/state-machine/states/pacing-state";
import { CharacterObject } from "../common/character-object";

const FISH_SPEED = 60;
const FISH_MAX_HP = 8;

type FishAsset = {
  assetKey: string;
  animationKey: string;
  boundingBox: {
    width: number;
    height: number;
    offsetX: number;
    offsetY: number;
  };
};

const FISH_ASSETS: FishAsset[] = [
  {
    assetKey: ASSET_KEYS.DANGER_TUNA,
    animationKey: DANGER_TUNA_ANIMATION_KEYS.IDLE_SIDE,
    boundingBox: {
      width: 10,
      height: 25,
      offsetX: 3,
      offsetY: 5,
    },
  },
  {
    assetKey: ASSET_KEYS.DANGER_YELLOWFISH,
    animationKey: DANGER_YELLOWFISH_ANIMATION_KEYS.IDLE_SIDE,
    boundingBox: {
      width: 10,
      height: 25,
      offsetX: 3,
      offsetY: 4,
    },
  },
];

export type FishConfig = {
  scene: Phaser.Scene;
  position: Position;
  initialDirection: Direction | undefined;
};

export class Fish extends CharacterObject {
  constructor(config: FishConfig) {
    const asset = FISH_ASSETS[Math.floor(Math.random() * FISH_ASSETS.length)];

    const animConfig = {
      key: asset.animationKey,
      repeat: -1,
      ignoreIfPlaying: true,
    };
    const animationConfig: AnimationConfig = {
      IDLE_DOWN: animConfig,
      IDLE_UP: animConfig,
      IDLE_LEFT: animConfig,
      IDLE_RIGHT: animConfig,
    };

    super({
      id: `wisp-${Phaser.Math.RND.uuid()}`,
      scene: config.scene,
      position: config.position,
      assetKey: asset.assetKey,
      frame: 0,
      isPlayer: false,
      animationConfig,
      speed: FISH_SPEED,
      inputComponent: new InputComponent(),
      isInvulnerable: true,
      maxHP: FISH_MAX_HP,
    });

    this.physicsBody
      .setSize(asset.boundingBox.width, asset.boundingBox.height, false)
      .setOffset(asset.boundingBox.offsetX, asset.boundingBox.offsetY);

    this.direction = config.initialDirection ?? "RIGHT";

    this._stateMachine.addState(new PacingState(this));
    this._stateMachine.setState(CHARACTER_STATES.PACING_STATE);
    this.setDepth(3);
  }
}
