import { GENERAL_ITEM } from "../../../common/constants";
import { type CharacterObject } from "../../../entities/common/character-object";
import { type NPC } from "../../../entities/npcs/npc";
import { InventoryManager } from "../../inventory/inventory-manager";
import { BaseCharacterState } from "./base-character-state";
import { CHARACTER_STATES } from "./character-states";

export type ReceiveItemData = {
  item: string;
  npc: NPC;
};

export class ReceiveItemState extends BaseCharacterState {
  #item = "";
  #npc!: NPC;

  constructor(gameObject: CharacterObject) {
    super(CHARACTER_STATES.RECEIVE_ITEM_STATE, gameObject);
  }

  public onEnter(args: unknown[]): void {
    const data = args[0] as ReceiveItemData;
    this.#item = data.item;
    this.#npc = data.npc;

    this._resetVelocity();

    // Validate that the item is a valid general item
    if (
      !Object.values(GENERAL_ITEM).includes(
        this.#item as keyof typeof GENERAL_ITEM,
      )
    ) {
      console.warn(
        `ReceiveItemState: Invalid item ${this.#item}. Valid items are: ${Object.values(GENERAL_ITEM).join(", ")}`,
      );
      return;
    }

    // Add the item to the player's inventory
    InventoryManager.instance.addGeneralItem(
      this.#item as keyof typeof GENERAL_ITEM,
    );

    // Face the NPC
    this._gameObject.faceCharacter(this.#npc);
    this.#npc.faceCharacter(this._gameObject);

    // Play receive item animation (uses LIFT animations)
    // TODO: Figure out how to stop dialog from interrupting this.
    this._gameObject.animationComponent.playAnimation(
      `RECEIVE_${this._gameObject.direction}`,
      () => {
        if (InventoryManager.instance.hasGeneralItem("DIVING_GEAR")) {
          this._stateMachine.setState(CHARACTER_STATES.IDLE_DIVING_STATE);
        } else {
          this._stateMachine.setState(CHARACTER_STATES.IDLE_STATE);
        }
      },
    );
  }
}
