import {
  type GameworldActivityLogEntry,
  type GameworldEventType,
  newClient,
} from "@hunt/public-client";
import apiUrl from "../../../utils/apiUrl";
import { IS_STATIC_SITE } from "../../../utils/staticSite";
import { MAX_SCORE } from "./common/eland-islands";
import {
  appendGameworldEventEntry,
  recordInteractionCompleted,
} from "./gameworldLocalState";

export const ELAND_ISLANDS_GAME_TIME_LIMIT_SECONDS = 360;

// ============================================================================
// CLIENT-SIDE GAMEWORLD UTILITIES
// ============================================================================

export type GameworldLevelState = {
  deliveredDeliverables: Set<string>; // IDs of delivered deliverables
  deliverableCounts: Map<string, number>; // deliverable frame -> count
  minesweeperStates: Map<string, MinesweeperState>; // minesweeper ID -> state
  elandIslandsRoundIndex?: number | undefined;
  elandIslandsManualIndex?: number | undefined;
  elandIslandsGameInProgress?: boolean | undefined;
  elandIslandsCurrentScore?: number | undefined;
  elandIslandsHighScore?: number | undefined;
  elandIslandsGameLastEventTime?: Date | undefined;
};

export type MinesweeperState = {
  completed: boolean;
  explosion_count: number;
};

export type GameworldState = {
  levels: Map<string, GameworldLevelState>;
};

/**
 * Process raw database activity data into game-ready state
 */
export function calculateTeamGameworldState(
  activities: GameworldActivityLogEntry[],
): GameworldState {
  const levels = new Map<string, GameworldLevelState>();

  // Ensure activities is an array
  const validActivities = Array.isArray(activities) ? activities : [];
  if (!Array.isArray(activities)) {
    console.warn(
      "calculateTeamGameworldState: activities is not an array, using empty array",
      activities,
    );
  }
  for (const activity of validActivities) {
    if (!levels.has(activity.level)) {
      levels.set(activity.level, {
        deliveredDeliverables: new Set(),
        deliverableCounts: new Map(),
        minesweeperStates: new Map(),
        elandIslandsRoundIndex: -1,
        elandIslandsManualIndex: -1,
        elandIslandsGameInProgress: false,
        elandIslandsCurrentScore: 0,
        elandIslandsHighScore: 0,
        elandIslandsGameLastEventTime: undefined,
      });
    }

    const levelState = levels.get(activity.level);
    if (!levelState) {
      console.warn(`No level state found for level: ${activity.level}`);
      continue;
    }

    if (activity.type === "deliverable_consumed") {
      // Track delivered deliverables
      levelState.deliveredDeliverables.add(activity.object_id);

      // Count by frame from database
      if (activity.frame) {
        const currentCount =
          levelState.deliverableCounts.get(activity.frame) || 0;
        levelState.deliverableCounts.set(activity.frame, currentCount + 1);
      }
    } else if (
      activity.type === "minesweeper_explosion" ||
      activity.type === "minesweeper_completed"
    ) {
      const currentState = levelState.minesweeperStates.get(
        activity.object_id,
      ) ?? {
        completed: false,
        explosion_count: 0,
      };
      if (activity.type === "minesweeper_explosion") {
        currentState.explosion_count += 1;
      } else {
        currentState.completed = true;
      }
      levelState.minesweeperStates.set(activity.object_id, currentState);
    } else if (activity.type === "eland_islands_game_start") {
      levelState.elandIslandsGameInProgress = true;
      levelState.elandIslandsRoundIndex =
        (levelState.elandIslandsRoundIndex ?? 0) + 1;
      levelState.elandIslandsCurrentScore = 0;
      levelState.elandIslandsGameLastEventTime = new Date(activity.timestamp);
      levelState.elandIslandsManualIndex =
        (levelState.elandIslandsManualIndex ?? 0) + 1;
    } else if (activity.type === "eland_islands_game_failure") {
      // This event will be followed by an eland_islands_game_start event if the player restarted,
      // and that will increment the puzzle number.
      levelState.elandIslandsGameInProgress = false;
      levelState.elandIslandsCurrentScore = 0;
      levelState.elandIslandsGameLastEventTime = new Date(activity.timestamp);
    } else if (activity.type === "eland_islands_game_success") {
      levelState.elandIslandsCurrentScore =
        (levelState.elandIslandsCurrentScore ?? 0) + 1;
      levelState.elandIslandsHighScore = Math.max(
        levelState.elandIslandsHighScore ?? 0,
        levelState.elandIslandsCurrentScore,
      );
      levelState.elandIslandsGameLastEventTime = new Date(activity.timestamp);
      levelState.elandIslandsManualIndex =
        (levelState.elandIslandsManualIndex ?? 0) + 1;
    }

    if (levelState.elandIslandsCurrentScore === MAX_SCORE) {
      levelState.elandIslandsCurrentScore = 0;
      levelState.elandIslandsGameInProgress = false;
    }
  }

  levels.forEach((levelState) => {
    if (
      levelState.elandIslandsGameLastEventTime !== undefined &&
      new Date().getTime() -
        levelState.elandIslandsGameLastEventTime.getTime() >
        ELAND_ISLANDS_GAME_TIME_LIMIT_SECONDS * 1000
    ) {
      levelState.elandIslandsGameInProgress = false;
      levelState.elandIslandsCurrentScore = 0;
    }
  });

  return { levels };
}

/**
 * Get minesweeper state for a specific minesweeper (client-side)
 */
export function getMinesweeperState(
  gameState: GameworldState,
  level: string,
  minesweeperId: string,
): MinesweeperState {
  const levelState = gameState.levels.get(level);
  return (
    levelState?.minesweeperStates.get(minesweeperId) ?? {
      completed: false,
      explosion_count: 0,
    }
  );
}

export async function logGameworldEvent(params: {
  type: GameworldEventType;
  level: string;
  death_reason?: string;
  data?: {
    death_reason?: string;
    mini_game_id?: string;
    story_flag?: string;
  };
}): Promise<void> {
  if (IS_STATIC_SITE) {
    appendGameworldEventEntry({
      type: params.type,
      level: params.level,
      death_reason: params.death_reason,
      data: params.data,
    });
    return;
  }
  try {
    const client = newClient(apiUrl(), undefined);
    const response = await client.logGameworldEvent({
      body: params,
    });

    if (response.status !== 200) {
      console.warn(
        `Failed to log gameworld event (${params.type}): ${response.status}`,
      );
    }
  } catch (error) {
    console.error("Error logging gameworld event:", error);
  }
}

export function logGameworldEventAsync(params: {
  type: GameworldEventType;
  level: string;
  death_reason?: string;
  data?: {
    death_reason?: string;
    mini_game_id?: string;
    story_flag?: string;
  };
}): void {
  void logGameworldEvent(params);
}

/**
 * Complete an interaction via the API.
 * Returns true if successful, false otherwise.
 */
export async function completeInteraction(
  interactionId: string,
): Promise<boolean> {
  if (IS_STATIC_SITE) {
    recordInteractionCompleted(interactionId);
    return true;
  }
  try {
    const client = newClient(apiUrl(), undefined);
    const response = await client.completeInteraction({
      params: { interactionId },
      body: {},
    });

    if (response.status === 200) {
      return true;
    } else {
      console.error(
        `Failed to complete interaction ${interactionId}: ${response.status}`,
      );
      return false;
    }
  } catch (error) {
    console.error(`Error completing interaction ${interactionId}:`, error);
    return false;
  }
}

/**
 * Complete an interaction via the API without awaiting (fire and forget).
 */
export function completeInteractionAsync(interactionId: string): void {
  void completeInteraction(interactionId);
}
