import { GENERAL_ITEM, STORY_FLAG } from "../../../common/constants";
import { getSceneDataManager } from "../../../common/data-manager";
import { CUSTOM_EVENTS, EVENT_BUS } from "../../../common/event-bus";
import { type CharacterObject } from "../../../entities/common/character-object";
import { InventoryManager } from "../../inventory/inventory-manager";
import { BaseCharacterState } from "./base-character-state";
import { CHARACTER_STATES } from "./character-states";

export class DialogState extends BaseCharacterState {
  constructor(gameObject: CharacterObject) {
    super(CHARACTER_STATES.DIALOG_STATE, gameObject);

    EVENT_BUS.on(CUSTOM_EVENTS.DIALOG_COMPLETE, this.#handleDialogComplete);
  }

  public onEnter = (): void => {
    this._resetVelocity();
    // Play appropriate idle animation based on diving gear
    if (InventoryManager.instance.hasGeneralItem(GENERAL_ITEM.DIVING_GEAR)) {
      this._gameObject.animationComponent.playAnimation(
        `IDLE_DIVING_${this._gameObject.direction}`,
      );
    } else {
      this._gameObject.animationComponent.playAnimation(
        `IDLE_${this._gameObject.direction}`,
      );
    }
  };

  // TODO: Figure out why idle crashes on enter.
  // Currently we hack around it by transitioning to move state.
  #handleDialogComplete = (): void => {
    const dataManager = getSceneDataManager(this._gameObject.scene);
    if (dataManager.getFlagValue(STORY_FLAG.race_finished) === "in_progress") {
      this._stateMachine.setState(CHARACTER_STATES.RACING_MOVE_STATE);
      return;
    }
    if (InventoryManager.instance.hasGeneralItem(GENERAL_ITEM.DIVING_GEAR)) {
      this._stateMachine.setState(CHARACTER_STATES.MOVE_DIVING_STATE);
    } else {
      this._stateMachine.setState(CHARACTER_STATES.MOVE_STATE);
    }
  };
}
