import * as Phaser from "phaser";
import { ASSET_KEYS, WISP_ANIMATION_KEYS } from "../../common/assets";
import {
  WISP_MAX_HP,
  WISP_PULSE_DURATION,
  WISP_PULSE_X,
  WISP_PULSE_Y,
  WISP_SPEED,
} from "../../common/config";
import type { Position } from "../../common/types";
import type { AnimationConfig } from "../../components/animation-component";
import { InputComponent } from "../../components/input-component";
import { BounceMoveState } from "../../components/state-machine/states/bounce-move-state";
import { CHARACTER_STATES } from "../../components/state-machine/states/character-states";
import { CharacterObject } from "../common/character-object";

export type WispConfig = {
  scene: Phaser.Scene;
  position: Position;
};

export class Wisp extends CharacterObject {
  constructor(config: WispConfig) {
    const animConfig = {
      key: WISP_ANIMATION_KEYS.IDLE,
      repeat: -1,
      ignoreIfPlaying: true,
    };
    const animationConfig: AnimationConfig = {
      IDLE_DOWN: animConfig,
      IDLE_UP: animConfig,
      IDLE_LEFT: animConfig,
      IDLE_RIGHT: animConfig,
    };

    super({
      id: `wisp-${Phaser.Math.RND.uuid()}`,
      scene: config.scene,
      position: config.position,
      assetKey: ASSET_KEYS.WISP,
      frame: 0,
      isPlayer: false,
      animationConfig,
      speed: WISP_SPEED,
      inputComponent: new InputComponent(),
      isInvulnerable: true,
      maxHP: WISP_MAX_HP,
    });

    this.physicsBody
      .setSize(10, 10, true)
      .setOffset(this.width / 2 - 5, this.height / 2 - 5);

    this.setDepth(1); // Render wisps above traps (traps are depth 1)

    this._stateMachine.addState(new BounceMoveState(this));
    this._stateMachine.setState(CHARACTER_STATES.BOUNCE_MOVE_STATE);

    this.scene.tweens.add({
      targets: this,
      scaleX: WISP_PULSE_X,
      scaleY: WISP_PULSE_Y,
      yoyo: true,
      repeat: -1,
      duration: WISP_PULSE_DURATION,
    });
  }
}
