import type { GameObject } from "../common/types";
import { BaseGameObjectComponent } from "./base-game-object";

export class HPComponent extends BaseGameObjectComponent {
  #maxHP: number;
  #currentHP: number;

  constructor(gameObject: GameObject, maxHP: number, currentHP: number) {
    super(gameObject);
    this.#maxHP = maxHP;
    this.#currentHP = currentHP;
  }

  get HP(): number {
    return this.#currentHP;
  }

  get maxHP(): number {
    return this.#maxHP;
  }

  public takeDamage(damage: number): void {
    if (this.#currentHP === 0) {
      return; // No HP left, cannot take damage
    }
    this.#currentHP -= damage;
    if (this.#currentHP < 0) {
      this.#currentHP = 0; // Ensure HP does not go below zero
    }
  }

  public resetHP(): void {
    this.#currentHP = this.#maxHP;
  }
}
