import { INTERACTIVE_OBJECT_TYPE } from "../common/constants";
import type { GameObject, InteractiveObjectType } from "../common/types";
import { BaseGameObjectComponent } from "./base-game-object";
import { HeldObjectComponent } from "./held-object-component";

export class InteractiveObjectComponent extends BaseGameObjectComponent {
  #objectType: InteractiveObjectType;
  #callback: (heldObject?: GameObject) => boolean;
  #canInteractCheck: () => boolean;

  constructor(
    gameObject: GameObject,
    objectType: InteractiveObjectType,
    callback: (heldObject?: GameObject) => boolean = () => true,
    canInteractCheck: () => boolean = () => true,
  ) {
    super(gameObject);
    this.#objectType = objectType;
    this.#callback = callback;
    this.#canInteractCheck = canInteractCheck;
  }

  get objectType(): InteractiveObjectType {
    return this.#objectType;
  }

  /**
   * Interacts with the object by invoking the callback.
   * heldObject is the object currently held by the player, if any.
   */
  public interact(): boolean {
    const heldObject = this.getPlayerHeldObject();
    return this.#callback(heldObject);
  }

  public canInteractWith(): boolean {
    const heldObject = this.getPlayerHeldObject();
    if (this.#requiresHeldObject() && heldObject === undefined) {
      return false;
    } else if (this.#requiresNoHeldObject() && heldObject !== undefined) {
      return false;
    }
    return this.#canInteractCheck();
  }

  public blocksMovement(): boolean {
    return this.#objectType !== INTERACTIVE_OBJECT_TYPE.AUTO;
  }

  /**
   * Returns the object currently held by the player, if any.
   */
  private getPlayerHeldObject(): GameObject | undefined {
    // Search for Player instance in scene's children
    const player = this.scene.children.list.find(
      (obj): obj is GameObject => obj.constructor.name === "Player",
    );
    if (!player) return undefined;
    const heldComponent = HeldObjectComponent.getComponent(
      player,
    ) as HeldObjectComponent;
    return heldComponent?.object;
  }

  #requiresHeldObject(): boolean {
    return this.#objectType === INTERACTIVE_OBJECT_TYPE.DELIVER;
  }

  #requiresNoHeldObject(): boolean {
    return (
      this.#objectType === INTERACTIVE_OBJECT_TYPE.LIFTUP ||
      this.#objectType === INTERACTIVE_OBJECT_TYPE.OPEN
    );
  }
}
