import * as Phaser from "phaser";
import type { Direction } from "../../common/types";
import type { InputComponent } from "../../components/input-component";
import type { ToolComponent } from "../../components/tool-component";

export type Tool = {
  inUse: boolean;
  isToggleable: boolean;
  toolType: string;
  use(direction: Direction): void;
  update(): void;
  onCollisionCallback(): void;
  reset(): void;
  handleInput?(controls: InputComponent): void; // Optional method for toggleable tools
};

export type UseToolAnimationConfig = Record<Direction, string>;

export abstract class BaseTool implements Tool {
  protected _toolComponent: ToolComponent;
  protected _inUse: boolean;
  protected _sprite: Phaser.GameObjects.Sprite;
  protected _useToolAnimationConfig: UseToolAnimationConfig;
  protected _isToggleable = false; // Default to false, override in subclasses
  public abstract readonly toolType: string; // Must be implemented by subclasses

  constructor(
    sprite: Phaser.GameObjects.Sprite,
    toolComponent: ToolComponent,
    animationConfig: UseToolAnimationConfig,
  ) {
    this._sprite = sprite;
    this._toolComponent = toolComponent;
    this._useToolAnimationConfig = animationConfig;
    this._inUse = false;
  }

  get inUse(): boolean {
    return this._inUse;
  }

  get isToggleable(): boolean {
    return this._isToggleable;
  }

  protected useTool(direction: Direction): void {
    const animationKey = this._useToolAnimationConfig[direction];
    this._inUse = true;
    this._sprite.play({ key: animationKey, repeat: 0 }, true);
    this._toolComponent.body.enable = true;
    this._sprite.once(
      Phaser.Animations.Events.ANIMATION_COMPLETE_KEY + animationKey,
      () => {
        this.toolAnimCompleteHandler();
      },
    );
  }

  protected toolAnimCompleteHandler(): void {
    this._inUse = false;
    this._toolComponent.body.enable = false;
  }

  public abstract use(direction: Direction): void;

  public update(): void {
    // Not implemented
  }

  public onCollisionCallback(): void {
    // Not implemented
  }

  public reset(): void {
    this._inUse = false;
    this._toolComponent.body.enable = false;
  }
}
