import * as Phaser from "phaser";
import type { CharacterAnimation, GameObject } from "../common/types";
import { BaseGameObjectComponent } from "./base-game-object";

export type AnimationConfig = Partial<
  Record<
    CharacterAnimation,
    { key: string; repeat: number; ignoreIfPlaying: boolean }
  >
>;

export class AnimationComponent extends BaseGameObjectComponent {
  declare protected gameObject: Phaser.GameObjects.Sprite;

  #config: AnimationConfig;

  constructor(gameObject: GameObject, config: AnimationConfig) {
    super(gameObject);
    this.#config = config;
  }

  public getAnimationKey(animationKey: CharacterAnimation): string | undefined {
    if (this.#config[animationKey] === undefined) {
      return undefined;
    }
    return this.#config[animationKey].key;
  }

  public playAnimation(
    animationKey: CharacterAnimation,
    callback?: () => void,
  ): void {
    if (this.#config[animationKey] === undefined) {
      if (callback) {
        callback();
      }
      return;
    }
    const animationConfig: Phaser.Types.Animations.PlayAnimationConfig = {
      key: this.#config[animationKey].key,
      repeat: this.#config[animationKey].repeat,
      timeScale: 1,
    };
    if (callback) {
      const aniCompleteKey =
        Phaser.Animations.Events.ANIMATION_COMPLETE_KEY +
        this.#config[animationKey].key;
      this.gameObject.once(aniCompleteKey, () => {
        callback();
      });
    }

    this.gameObject.play(
      animationConfig,
      this.#config[animationKey].ignoreIfPlaying,
    );
  }

  public playReverseAnimation(
    animationKey: CharacterAnimation,
    callback?: () => void,
  ): void {
    if (this.#config[animationKey] === undefined) {
      if (callback) {
        callback();
      }
      return;
    }
    const animationConfig: Phaser.Types.Animations.PlayAnimationConfig = {
      key: this.#config[animationKey].key,
      repeat: this.#config[animationKey].repeat,
      timeScale: 1.75,
    };
    if (callback) {
      const aniCompleteKey =
        Phaser.Animations.Events.ANIMATION_COMPLETE_KEY +
        this.#config[animationKey].key;
      this.gameObject.once(aniCompleteKey, () => {
        callback();
      });
    }

    this.gameObject.playReverse(
      animationConfig,
      this.#config[animationKey].ignoreIfPlaying,
    );
  }

  public isAnimationPlaying(): boolean {
    return this.gameObject.anims.isPlaying;
  }
}
