import * as Phaser from "phaser";
import {
  LIFT_ITEM_DELAY,
  LIFT_ITEM_DURATION,
  LIFT_ITEM_ENABLE_DEBUGGING,
} from "../../../common/config";
import { type GameObject, isVisualGameObject } from "../../../common/types";
import { isArcadePhysicsBody } from "../../../common/utils";
import { type CharacterObject } from "../../../entities/common/character-object";
import { HeldObjectComponent } from "../../held-object-component";
import { BaseCharacterState } from "./base-character-state";
import { CHARACTER_STATES } from "./character-states";

export class LiftState extends BaseCharacterState {
  constructor(gameObject: CharacterObject) {
    super(CHARACTER_STATES.LIFT_STATE, gameObject);
  }

  public onEnter(args: unknown[]): void {
    const object = args[0] as GameObject;

    this._resetVelocity();

    const heldComponent = HeldObjectComponent.getComponent<HeldObjectComponent>(
      this._gameObject,
    );
    if (heldComponent === undefined) {
      this._stateMachine.setState(CHARACTER_STATES.IDLE_STATE);
      return;
    }
    heldComponent.object = object;
    if (isArcadePhysicsBody(object.body)) {
      object.body.enable = false;
    }
    object.setDepth(2).setOrigin(0.5, 0.5);

    const startPoint = new Phaser.Math.Vector2(object.x + 8, object.y - 8);
    const controlPoint1 = new Phaser.Math.Vector2(object.x + 8, object.y - 24);
    const controlPoint2 = new Phaser.Math.Vector2(object.x + 8, object.y - 24);
    const endPoint = new Phaser.Math.Vector2(
      this._gameObject.x,
      this._gameObject.y - 8,
    );
    const curve = new Phaser.Curves.CubicBezier(
      startPoint,
      controlPoint1,
      controlPoint2,
      endPoint,
    );
    const curvePath = new Phaser.Curves.Path(startPoint.x, startPoint.y).add(
      curve,
    );

    let g: Phaser.GameObjects.Graphics | undefined;

    if (LIFT_ITEM_ENABLE_DEBUGGING) {
      g = this._gameObject.scene.add.graphics();
      g.clear();
      g.lineStyle(4, 0x00ff00, 1);
      curvePath.draw(g);
    }

    // Only lift visual objects (Sprites/Images), not Zones
    if (!isVisualGameObject(object)) {
      return;
    }

    object.setAlpha(0);

    const follower = this._gameObject.scene.add
      .follower(
        curvePath,
        startPoint.x,
        startPoint.y,
        object.texture.key,
        object.frame.name,
      )
      .setAlpha(1);
    follower.startFollow({
      delay: LIFT_ITEM_DELAY,
      duration: LIFT_ITEM_DURATION,
      onComplete: () => {
        follower.destroy();

        if (g !== undefined) {
          g.destroy();
        }

        object.setPosition(follower.x, follower.y).setAlpha(1);
      },
    });

    // TODO: Occasionlly there are jitters which causes the item to be dropped.
    // Likely due to transitioning to IDLE_STATE for some reason?
    this._gameObject.animationComponent.playAnimation(
      `LIFT_${this._gameObject.direction}`,
      () => {
        this._stateMachine.setState(CHARACTER_STATES.IDLE_HOLDING_STATE);
      },
    );
  }
}
