import { type CharacterObject } from "../../../entities/common/character-object";
import { HeldObjectComponent } from "../../held-object-component";
import { ThrowableObjectComponent } from "../../throwable-object-component";
import { BaseCharacterState } from "./base-character-state";
import { CHARACTER_STATES } from "./character-states";
import { handleInteraction } from "./interaction-utils";

export class IdleDivingState extends BaseCharacterState {
  constructor(gameObject: CharacterObject) {
    super(CHARACTER_STATES.IDLE_DIVING_STATE, gameObject);
  }

  public onEnter(): void {
    this._gameObject.animationComponent.playAnimation(
      `IDLE_DIVING_${this._gameObject.direction}`,
    );

    this._resetVelocity();

    const heldComponent = HeldObjectComponent.getComponent<HeldObjectComponent>(
      this._gameObject,
    );
    if (heldComponent?.object !== undefined) {
      const throwComponent =
        ThrowableObjectComponent.getComponent<ThrowableObjectComponent>(
          heldComponent.object,
        );
      if (throwComponent !== undefined) {
        throwComponent.drop();
      }
      heldComponent.drop(this._gameObject.direction);
    }
  }

  public onUpdate(): void {
    const controls = this._gameObject.controls;

    // Can't use item while diving.
    if (controls.isUseJustDown) {
      return;
    }

    // Handle interactions while idle diving
    if (
      handleInteraction(this._gameObject, this._stateMachine, controls, {
        isDiving: true,
      })
    ) {
      return;
    }

    if (
      !controls.isDownDown &&
      !controls.isUpDown &&
      !controls.isLeftDown &&
      !controls.isRightDown
    ) {
      return;
    }
    this._stateMachine.setState(CHARACTER_STATES.MOVE_DIVING_STATE);
  }
}
