import { INTERACTIVE_OBJECT_TYPE, LEVEL_NAME } from "../../../common/constants";
import { getSceneDataManager } from "../../../common/data-manager";
import { CUSTOM_EVENTS, EVENT_BUS } from "../../../common/event-bus";
import { type CharacterObject } from "../../../entities/common/character-object";
import { Deliverable } from "../../../entities/objects/deliverable";
import { type HeldObjectComponent } from "../../held-object-component";
import { type InputComponent } from "../../input-component";
import { InteractiveObjectComponent } from "../../interactive-object-component";
import { ProximityDetectionComponent } from "../../proximity-detection-component";
import { CHARACTER_STATES } from "./character-states";

/**
 * Handles action key presses for all interaction states (idle, move, diving, holding).
 * Returns true if onUpdate should return immediately.
 */
export function handleInteraction(
  gameObject: CharacterObject,
  stateMachine: { setState: (state: string, ...args: unknown[]) => void },
  controls: InputComponent,
  options: {
    isDiving?: boolean;
    isHolding?: boolean;
    heldComponent?: HeldObjectComponent;
  } = {},
): boolean {
  if (!controls.isActionKeyJustDown) {
    return false;
  }

  // Don't allow interactions when movement is locked
  if (controls.isMovementLocked || controls.movementControlsLocked) {
    return false;
  }

  const { isDiving = false, isHolding = false, heldComponent } = options;

  // Handle holding states first (deliverables vs other objects)
  if (isHolding) {
    return handleHoldingInteraction(
      gameObject,
      stateMachine,
      controls,
      heldComponent,
    );
  }

  // Use direction-based proximity detection if available
  const proximityComponent =
    ProximityDetectionComponent.getComponent<ProximityDetectionComponent>(
      gameObject,
    );
  if (!proximityComponent) {
    // If no proximity detection component, skip interaction
    return false;
  }

  const frontObject = proximityComponent.getNearestInteractiveObjectInFront();
  if (!frontObject) {
    return false;
  }

  const interactiveObj =
    InteractiveObjectComponent.getComponent<InteractiveObjectComponent>(
      frontObject,
    );
  if (!interactiveObj?.canInteractWith()) {
    return false;
  }

  // Handle diving-specific logic
  if (isDiving) {
    return handleDivingInteraction(
      interactiveObj,
      stateMachine,
      gameObject.scene,
    );
  }

  // Handle normal mode logic
  return handleNormalInteraction(interactiveObj, stateMachine, frontObject);
}

/**
 * Handles interaction logic for diving states.
 * Returns true if interaction occurred.
 */
function handleDivingInteraction(
  interactiveObj: InteractiveObjectComponent,
  stateMachine: { setState: (state: string, ...args: unknown[]) => void },
  scene: Phaser.Scene,
): boolean {
  // Handle pickup attempts while diving
  if (interactiveObj.objectType === INTERACTIVE_OBJECT_TYPE.LIFTUP) {
    stateMachine.setState(CHARACTER_STATES.DIALOG_STATE);
    // Hardcoding room 1 as not under water.
    const currentArea = getSceneDataManager(scene).data.currentArea;
    if (currentArea.level === LEVEL_NAME.SHORE) {
      if (currentArea.roomId === 1) {
        EVENT_BUS.emit(CUSTOM_EVENTS.DIALOG_START, {
          messages: [
            "You can't pick up anything while wearing diving gear...",
            "Talk to the professor to switch back to normal gear.",
          ],
          choices: [],
        });
        return true;
      }
    }
    EVENT_BUS.emit(CUSTOM_EVENTS.DIALOG_START, {
      messages: [
        "You can't pick up anything while wearing diving gear, try pushing instead...",
      ],
      choices: [],
    });
    return true;
  }

  // Ignore all other non-NPC interactions while diving
  if (interactiveObj.objectType !== INTERACTIVE_OBJECT_TYPE.NPC) {
    return false;
  }

  interactiveObj.interact();
  return true;
}

/**
 * Handles interaction logic for normal (non-diving) states.
 * Returns true if interaction occurred.
 */
function handleNormalInteraction(
  interactiveObj: InteractiveObjectComponent,
  stateMachine: { setState: (state: string, ...args: unknown[]) => void },
  frontObject: unknown,
): boolean {
  interactiveObj.interact();

  if (interactiveObj.objectType === INTERACTIVE_OBJECT_TYPE.LIFTUP) {
    stateMachine.setState(CHARACTER_STATES.LIFT_STATE, frontObject);
    return true;
  } else if (interactiveObj.objectType === INTERACTIVE_OBJECT_TYPE.OPEN) {
    stateMachine.setState(CHARACTER_STATES.OPEN_CHEST_STATE, frontObject);
    return true;
  }

  return interactiveObj.blocksMovement();
}

/**
 * Handles action key presses for holding states.
 * Returns true if onUpdate should return immediately.
 */
function handleHoldingInteraction(
  gameObject: CharacterObject,
  stateMachine: { setState: (state: string, ...args: unknown[]) => void },
  controls: InputComponent,
  heldComponent: HeldObjectComponent | undefined,
): boolean {
  // Don't allow interactions when movement is locked
  if (controls.isMovementLocked || controls.movementControlsLocked) {
    return false;
  }

  if (!(heldComponent?.object instanceof Deliverable)) {
    stateMachine.setState(CHARACTER_STATES.THROW_STATE);
    return true;
  }

  // Use direction-based proximity detection if available
  const proximityComponent =
    ProximityDetectionComponent.getComponent<ProximityDetectionComponent>(
      gameObject,
    );
  if (!proximityComponent) {
    // If no proximity detection component, skip interaction
    return false;
  }

  const frontObject = proximityComponent.getNearestInteractiveObjectInFront();
  if (!frontObject) {
    return false;
  }

  const interactiveObj =
    InteractiveObjectComponent.getComponent<InteractiveObjectComponent>(
      frontObject,
    );
  if (!interactiveObj?.canInteractWith()) {
    return false;
  }

  // Handle state transitions for specific object types
  if (interactiveObj.objectType === INTERACTIVE_OBJECT_TYPE.DELIVER) {
    stateMachine.setState(CHARACTER_STATES.DELIVER_ITEM_STATE, frontObject);
    return true;
  }

  interactiveObj.interact();
  return interactiveObj.blocksMovement();
}
