import { DIRECTION } from "../../../common/constants";
import type { Direction } from "../../../common/types";
import { isArcadePhysicsBody } from "../../../common/utils";
import { type CharacterObject } from "../../../entities/common/character-object";
import { type InputComponent } from "../../input-component";
import { BaseCharacterState } from "./base-character-state";

export abstract class BaseMoveState extends BaseCharacterState {
  protected _moveAnimationPrefix: "WALK" | "WALK_HOLD" | "WALK_DIVING";

  constructor(
    stateName: string,
    gameObject: CharacterObject,
    moveAnimationPrefix: "WALK" | "WALK_HOLD" | "WALK_DIVING",
  ) {
    super(stateName, gameObject);
    this._moveAnimationPrefix = moveAnimationPrefix;
  }

  protected handleCharacterMovement(): void {
    const controls = this._gameObject.controls;

    // Handle vertical movement
    if (controls.isUpDown) {
      this.updateVelocity(false, -1);
    } else if (controls.isDownDown) {
      this.updateVelocity(false, 1);
    } else {
      this.updateVelocity(false, 0);
    }

    // Handle horizontal movement
    if (controls.isLeftDown) {
      this.updateVelocity(true, -1);
    } else if (controls.isRightDown) {
      this.updateVelocity(true, 1);
    } else {
      this.updateVelocity(true, 0);
    }

    // Update direction based on primary movement (prioritize horizontal for diagonal)
    if (controls.isLeftDown) {
      this.updateDirection(DIRECTION.LEFT);
    } else if (controls.isRightDown) {
      this.updateDirection(DIRECTION.RIGHT);
    } else if (controls.isUpDown) {
      this.updateDirection(DIRECTION.UP);
    } else if (controls.isDownDown) {
      this.updateDirection(DIRECTION.DOWN);
    }

    this.normalizeVelocity();
  }

  protected isNoMoveInput(controls: InputComponent): boolean {
    return (
      (!controls.isDownDown &&
        !controls.isUpDown &&
        !controls.isLeftDown &&
        !controls.isRightDown) ||
      controls.isMovementLocked
    );
  }

  protected updateVelocity(isX: boolean, value: number): void {
    if (!isArcadePhysicsBody(this._gameObject.body)) {
      return;
    }
    if (isX) {
      this._gameObject.body.velocity.x = value;
      return;
    }
    this._gameObject.body.velocity.y = value;
  }

  protected normalizeVelocity(): void {
    if (!isArcadePhysicsBody(this._gameObject.body)) {
      return;
    }
    this._gameObject.body.velocity.normalize().scale(this._gameObject.speed);
  }

  protected updateDirection(direction: Direction): void {
    this._gameObject.direction = direction;
    this._gameObject.animationComponent.playAnimation(
      `${this._moveAnimationPrefix}_${direction}`,
    );
  }
}
