import * as CONFIG from "../common/config";

export enum LogLevel {
  ERROR = 0,
  WARN = 1,
  INFO = 2,
}

export type LogContext = {
  scene?: string;
  entity?: string;
  method?: string;
  [key: string]: unknown;
};

class GameLogger {
  private static instance: GameLogger;
  private logLevel: LogLevel = LogLevel.INFO;

  private constructor() {
    // Set log level based on config
    if (CONFIG.ENABLE_DEBUG) {
      this.logLevel = LogLevel.INFO;
    } else {
      this.logLevel = LogLevel.WARN;
    }
  }

  public static getInstance(): GameLogger {
    if (!GameLogger.instance) {
      GameLogger.instance = new GameLogger();
    }
    return GameLogger.instance;
  }

  /**
   * Set the global log level
   */
  public setLogLevel(level: LogLevel): void {
    this.logLevel = level;
  }

  /**
   * Get the current log level
   */
  public getLogLevel(): LogLevel {
    return this.logLevel;
  }

  /**
   * Format a log message with context
   */
  private formatMessage(
    level: string,
    message: string,
    context?: LogContext,
  ): string {
    const timestamp = new Date().toISOString();
    let formattedMessage = `[${timestamp}] [${level}] ${message}`;

    if (context) {
      const contextParts: string[] = [];
      if (context.scene) contextParts.push(`Scene: ${context.scene}`);
      if (context.entity) contextParts.push(`Entity: ${context.entity}`);
      if (context.method) contextParts.push(`Method: ${context.method}`);

      // Add any other custom context
      Object.entries(context).forEach(([key, value]) => {
        if (!["scene", "entity", "method"].includes(key)) {
          contextParts.push(`${key}: ${value}`);
        }
      });

      if (contextParts.length > 0) {
        formattedMessage += ` | ${contextParts.join(" | ")}`;
      }
    }

    return formattedMessage;
  }

  /**
   * Log an error message (always visible)
   */
  public error(message: string, context?: LogContext, error?: Error): void {
    if (this.logLevel >= LogLevel.ERROR) {
      const formattedMessage = this.formatMessage("ERROR", message, context);
      console.error(formattedMessage);
      if (error) {
        console.error(error);
      }
    }
  }

  /**
   * Log a warning message (always visible)
   */
  public warn(message: string, context?: LogContext): void {
    if (this.logLevel >= LogLevel.WARN) {
      const formattedMessage = this.formatMessage("WARN", message, context);
      console.warn(formattedMessage);
    }
  }

  /**
   * Log an info message (visible when log level >= INFO)
   */
  public info(message: string, context?: LogContext): void {
    if (this.logLevel >= LogLevel.INFO) {
      const formattedMessage = this.formatMessage("INFO", message, context);
      console.log(formattedMessage);
    }
  }

  /**
   * Event-specific logging (controlled by DEBUG_EVENTS flag)
   */
  public event(message: string, data?: unknown, context?: LogContext): void {
    if (CONFIG.DEBUG_EVENTS) {
      const formattedMessage = this.formatMessage("EVENT", message, context);
      if (data !== undefined) {
        console.log(formattedMessage, data);
      } else {
        console.log(formattedMessage);
      }
    }
  }

  /**
   * Create a logger instance with predefined context
   */
  public withContext(context: LogContext): ContextualLogger {
    return new ContextualLogger(this, context);
  }
}

/**
 * Contextual logger that automatically includes context with all log calls
 */
export class ContextualLogger {
  constructor(
    private logger: GameLogger,
    private context: LogContext,
  ) {}

  public error(
    message: string,
    additionalContext?: LogContext,
    error?: Error,
  ): void {
    this.logger.error(
      message,
      { ...this.context, ...additionalContext },
      error,
    );
  }

  public warn(message: string, additionalContext?: LogContext): void {
    this.logger.warn(message, { ...this.context, ...additionalContext });
  }

  public info(message: string, additionalContext?: LogContext): void {
    this.logger.info(message, { ...this.context, ...additionalContext });
  }

  public event(
    message: string,
    data?: unknown,
    additionalContext?: LogContext,
  ): void {
    this.logger.event(message, data, { ...this.context, ...additionalContext });
  }
}

// Export the singleton instance
export const logger = GameLogger.getInstance();

// Export convenience functions for direct usage
export const logError = (
  message: string,
  context?: LogContext,
  error?: Error,
) => {
  logger.error(message, context, error);
};

export const logWarn = (message: string, context?: LogContext) => {
  logger.warn(message, context);
};

export const logInfo = (message: string, context?: LogContext) => {
  logger.info(message, context);
};

export const logEvent = (
  message: string,
  data?: unknown,
  context?: LogContext,
) => {
  logger.event(message, data, context);
};
