import { CHARACTER_ANIMATIONS } from "../../../common/assets";
import { PLAYER_HURT_PUSHBACK_DELAY } from "../../../common/config";
import { DIRECTION } from "../../../common/constants";
import type { Direction } from "../../../common/types";
import { assertNeverCalled, isArcadePhysicsBody } from "../../../common/utils";
import { ToolComponent } from "../../../components/tool-component";
import type { CharacterObject } from "../../../entities/common/character-object";
import { HeldObjectComponent } from "../../held-object-component";
import { ThrowableObjectComponent } from "../../throwable-object-component";
import { BaseCharacterState } from "./base-character-state";
import { CHARACTER_STATES } from "./character-states";

export class HurtState extends BaseCharacterState {
  #hurtPushBackSpeed: number;
  #onHurtCallback: () => void;
  #nextState: string;

  constructor(
    gameObject: CharacterObject,
    hurtPushBackSpeed: number,
    onHurtCallback: () => void = () => undefined,
    nextState: string = CHARACTER_STATES.IDLE_STATE,
  ) {
    super(CHARACTER_STATES.HURT_STATE, gameObject);
    this.#hurtPushBackSpeed = hurtPushBackSpeed;
    this.#onHurtCallback = onHurtCallback;
    this.#nextState = nextState;
  }

  public onEnter(args: unknown[]): void {
    const attackDirection = args[0] as Direction;

    this._resetVelocity();

    const heldComponent = HeldObjectComponent.getComponent<HeldObjectComponent>(
      this._gameObject,
    );
    if (heldComponent?.object) {
      const throwComponent =
        ThrowableObjectComponent.getComponent<ThrowableObjectComponent>(
          heldComponent.object,
        );
      if (throwComponent !== undefined) {
        throwComponent.drop();
      }
      heldComponent.drop(this._gameObject.direction);
    }

    const toolComponent = ToolComponent.getComponent<ToolComponent>(
      this._gameObject,
    );
    if (toolComponent?.tool) {
      toolComponent.tool.reset();
    }

    if (isArcadePhysicsBody(this._gameObject.body)) {
      const body = this._gameObject.body;

      switch (attackDirection) {
        case DIRECTION.DOWN:
          body.setVelocityY(this.#hurtPushBackSpeed);
          break;
        case DIRECTION.UP:
          body.setVelocityY(-this.#hurtPushBackSpeed);
          break;
        case DIRECTION.LEFT:
          body.setVelocityX(-this.#hurtPushBackSpeed);
          break;
        case DIRECTION.RIGHT:
          body.setVelocityX(this.#hurtPushBackSpeed);
          break;
        default:
          assertNeverCalled(attackDirection);
      }

      this._gameObject.scene.time.delayedCall(
        PLAYER_HURT_PUSHBACK_DELAY,
        () => {
          this._resetVelocity();
        },
      );
    }

    this._gameObject.invulnerableComponent.invulnerable = true;
    this.#onHurtCallback();

    this._gameObject.animationComponent.playAnimation(
      CHARACTER_ANIMATIONS.HURT_DOWN,
      () => {
        this.#transition();
      },
    );
  }

  #transition(): void {
    this._gameObject.scene.time.delayedCall(
      this._gameObject.invulnerableComponent.invulnerableDuration,
      () => {
        this._gameObject.invulnerableComponent.invulnerable = false;
      },
    );
    this._stateMachine.setState(this.#nextState);
  }
}
