import * as Phaser from "phaser";
import { INTERACTIVE_OBJECT_TYPE } from "../../../common/constants";
import { type TiledHidingPlaceObject } from "../../../common/tiled/types";
import type { CustomObject } from "../../../common/types";
import { InteractiveObjectComponent } from "../../../components/interactive-object-component";

/**
 * Type for entities that can hide in hiding places
 */
export type HidingEntity = {
  /**
   * Reveals the entity from its hiding place
   */
  revealFromHidingPlace(): void;

  /**
   * Gets the current hiding place the entity is in, or null if not hiding
   */
  currentHidingPlace: HidingPlace | null;
};

export class HidingPlace
  extends Phaser.GameObjects.Zone
  implements CustomObject
{
  #identifier: string;
  #hiddenEntities: HidingEntity[] = [];

  constructor(scene: Phaser.Scene, config: TiledHidingPlaceObject) {
    super(scene, config.x, config.y, config.width, config.height);

    this.#identifier = config.identifier;

    this.setOrigin(0, 0);
    scene.add.existing(this);
    scene.physics.world.enable(this);

    new InteractiveObjectComponent(
      this,
      INTERACTIVE_OBJECT_TYPE.GENERIC_INTERACT,
      () => {
        // Reveal all entities hiding in this place
        const hidingEntities = this.#hiddenEntities;

        if (hidingEntities.length > 0) {
          hidingEntities.forEach((entity) => {
            entity.revealFromHidingPlace();
          });
        }
        // If no entities hiding here, do nothing
        return true;
      },
    );

    this.disableObject();
  }

  /**
   * Registers an entity as hiding in this place
   * Called by the collision system when an entity reaches this hiding place
   */
  public registerHidingEntity(entity: HidingEntity): void {
    if (!this.#hiddenEntities.includes(entity)) {
      this.#hiddenEntities.push(entity);
    }
  }

  /**
   * Unregisters an entity from this hiding place
   * Called when an entity leaves or is revealed
   */
  public unregisterHidingEntity(entity: HidingEntity): void {
    const index = this.#hiddenEntities.indexOf(entity);
    if (index !== -1) {
      this.#hiddenEntities.splice(index, 1);
    }
  }

  public disableObject(): void {
    (this.body as Phaser.Physics.Arcade.Body).enable = false;
    this.active = false;
    this.visible = false;
  }

  public enableObject(): void {
    (this.body as Phaser.Physics.Arcade.Body).enable = true;
    this.active = true;
    this.visible = true; // Zones are invisible by default, but need visible=true for proximity detection
  }

  public get identifier(): string {
    return this.#identifier;
  }

  /**
   * Checks if there are any entities currently hiding in this place
   */
  public hasHiddenEntities(): boolean {
    return this.#hiddenEntities.length > 0;
  }
}
