import * as Phaser from "phaser";
import { ASSET_KEYS, EFFECTS_ANIMATION_KEYS } from "../../common/assets";
import type { TiledEffectObject } from "../../common/tiled/types";
import type { CustomObject } from "../../common/types";

/**
 * Maps effect names from Tiled to their corresponding asset and animation keys
 */
const EFFECT_MAP: Record<
  string,
  {
    assetKey: keyof typeof ASSET_KEYS;
    animationKey: keyof typeof EFFECTS_ANIMATION_KEYS;
  }
> = {
  sparkle: {
    assetKey: "SPARKLE",
    animationKey: "SPARKLE",
  },
  bubbles: {
    assetKey: "BUBBLES",
    animationKey: "BUBBLES",
  },
} as const;

export class Effect extends Phaser.GameObjects.Sprite implements CustomObject {
  #animationKey?: keyof typeof EFFECTS_ANIMATION_KEYS;

  constructor(scene: Phaser.Scene, config: TiledEffectObject) {
    // Look up the effect in the map
    const effectConfig = EFFECT_MAP[config.effect.toLowerCase()];

    // Center the sprite in the effect zone
    const centerX = config.x + config.width / 2;
    const centerY = config.y + config.height / 2;
    const assetKey = effectConfig?.assetKey ?? "SPARKLE";

    // Call super first with the asset
    super(scene, centerX, centerY, ASSET_KEYS[assetKey]);

    if (!effectConfig) {
      console.warn(
        `Unknown effect type: ${config.effect}. Available effects: ${Object.keys(EFFECT_MAP).join(", ")}`,
      );
    } else {
      this.#animationKey = effectConfig.animationKey;
    }

    this.setOrigin(0.5, 0.5);
    scene.add.existing(this);

    // Initially disabled
    this.disableObject();
  }

  public enableObject(): void {
    this.active = true;
    this.visible = true;

    // Show and play animation when enabled
    if (this.#animationKey) {
      if (!this.anims.isPlaying) {
        const animKey = EFFECTS_ANIMATION_KEYS[this.#animationKey];

        // Randomize start time (0 to 1000ms delay) for de-syncing
        const randomDelay = Math.random() * 1000;

        // Delay the animation start slightly to de-sync effects
        this.scene.time.delayedCall(randomDelay, () => {
          if (this.active && !this.anims.isPlaying) {
            this.play({
              key: animKey,
              repeat: -1,
            });
          }
        });
      }
    }
  }

  public disableObject(): void {
    this.active = false;
    this.visible = false;
    this.stop();
  }
}
