import * as Phaser from "phaser";
import {
  CHARACTER_ACTIVE_STATE,
  DEATH_REASON,
  DIRECTION,
} from "../../common/constants";
import { getSceneDataManager } from "../../common/data-manager";
import type {
  CustomObject,
  Position,
  CharacterColor,
  DeathReason,
  Direction,
  CharacterActiveState,
} from "../../common/types";
import { getRelativeDirection } from "../../common/utils";
import {
  type AnimationConfig,
  AnimationComponent,
} from "../../components/animation-component";
import { ControlsComponent } from "../../components/controls-component";
import { DirectionComponent } from "../../components/direction-component";
import { HPComponent } from "../../components/hp-component";
import { type InputComponent } from "../../components/input-component";
import { InvulnerableComponent } from "../../components/invulnerable-component";
import { SpeedComponent } from "../../components/speed-component";
import { StateMachine } from "../../components/state-machine/state-machine";
import { CHARACTER_STATES } from "../../components/state-machine/states/character-states";
import { VisibilityComponent } from "../../components/visibility-component";
import { type Rock } from "../objects/rock";

export type CharacterConfig = {
  id?: string;
  scene: Phaser.Scene;
  position: Position;
  assetKey: string;
  frame?: number;
  inputComponent: InputComponent;
  animationConfig: AnimationConfig;
  speed: number;
  isPlayer: boolean;
  isInvulnerable?: boolean;
  invulnerableDuration?: number;
  maxHP: number;
  currentHP?: number;
  visibleTo?: CharacterColor[];
  shouldFlipLeft?: boolean;
  activeState?: CharacterActiveState;
};

export abstract class CharacterObject
  extends Phaser.Physics.Arcade.Sprite
  implements CustomObject
{
  protected _controlsComponent: ControlsComponent;
  protected _speedComponent: SpeedComponent;
  protected _directionComponent: DirectionComponent;
  protected _animationComponent: AnimationComponent;
  protected _invulnerableComponent: InvulnerableComponent;
  protected _hpComponent: HPComponent;
  protected _visibilityComponent: VisibilityComponent;

  protected _stateMachine: StateMachine;
  protected _isPlayer: boolean;
  protected _isDefeated: boolean;
  protected _visibleTo: CharacterColor[];
  protected _activeState: CharacterActiveState;
  protected _shouldFlipLeft: boolean;
  protected _lastDeathReason: DeathReason;
  protected _exclamationSprite?: Phaser.GameObjects.Sprite;

  protected get dataManager() {
    return getSceneDataManager(this.scene);
  }

  constructor(config: CharacterConfig) {
    const {
      id,
      scene,
      position,
      assetKey,
      frame,
      inputComponent,
      animationConfig,
      speed,
      isPlayer,
      isInvulnerable,
      invulnerableDuration,
      maxHP,
      currentHP,
      visibleTo,
      shouldFlipLeft,
      activeState,
    } = config;
    const { x, y } = position;
    super(scene, x, y, assetKey, frame || 0);

    scene.add.existing(this);
    scene.physics.add.existing(this);

    this._isPlayer = isPlayer;
    this._isDefeated = false;
    this._visibleTo = visibleTo || ["GREEN", "BLUE", "RED", "YELLOW"];
    this._activeState = activeState || CHARACTER_ACTIVE_STATE.REVEALED;
    this._shouldFlipLeft = shouldFlipLeft || false;
    this._lastDeathReason = DEATH_REASON.UNKNOWN;

    // Initialize components
    this._controlsComponent = new ControlsComponent(this, inputComponent);
    this._speedComponent = new SpeedComponent(this, speed);
    this._directionComponent = new DirectionComponent(this);
    this._animationComponent = new AnimationComponent(this, animationConfig);
    this._invulnerableComponent = new InvulnerableComponent(
      this,
      isInvulnerable || false,
      invulnerableDuration,
    );
    this._hpComponent = new HPComponent(this, maxHP, currentHP || maxHP);
    this._visibilityComponent = new VisibilityComponent(this, this._visibleTo);

    this._stateMachine = new StateMachine(id);

    if (!this._isPlayer) {
      this.disableObject();
    }
  }

  get isDefeated(): boolean {
    return this._isDefeated;
  }

  get isPlayer(): boolean {
    return this._isPlayer;
  }

  get isEnemy(): boolean {
    return !this._isPlayer;
  }

  get controls(): InputComponent {
    return this._controlsComponent.controls;
  }

  get speed(): number {
    return this._speedComponent.speed;
  }

  public setSpeedModifier(modifier: number): void {
    this._speedComponent.setSpeedModifier(modifier);
  }

  public resetSpeedModifier(): void {
    this._speedComponent.resetSpeedModifier();
  }

  get direction(): Direction {
    return this._directionComponent.direction;
  }

  set direction(value: Direction) {
    this._directionComponent.direction = value;
    if (value === DIRECTION.LEFT && this._shouldFlipLeft) {
      this.setFlipX(true);
    } else {
      this.setFlipX(false);
    }
  }

  get shouldFlipLeft(): boolean {
    return this._shouldFlipLeft;
  }

  get activeState(): CharacterActiveState {
    return this._activeState;
  }

  set activeState(value: CharacterActiveState) {
    this._activeState = value;
    // Update visibility based on new state
    if (value === CHARACTER_ACTIVE_STATE.HIDDEN) {
      this.disableObject();
    } else {
      this.enableObject();
    }
  }

  get visibleTo(): CharacterColor[] {
    return this._visibleTo;
  }

  get animationComponent(): AnimationComponent {
    return this._animationComponent;
  }

  get invulnerableComponent(): InvulnerableComponent {
    return this._invulnerableComponent;
  }

  get stateMachine(): StateMachine {
    return this._stateMachine;
  }

  get physicsBody(): Phaser.Physics.Arcade.Body {
    return this.body as Phaser.Physics.Arcade.Body;
  }

  update(): void {
    this._stateMachine.update();
  }

  public setDeathReason(reason: DeathReason): void {
    this._lastDeathReason = reason;
  }

  public get lastDeathReason(): DeathReason {
    return this._lastDeathReason;
  }

  public hit(
    direction: Direction,
    damage: number,
    deathReason?: DeathReason,
  ): void {
    if (this._isDefeated) {
      return;
    }
    if (this._invulnerableComponent.invulnerable) {
      return;
    }

    if (deathReason) {
      this._lastDeathReason = deathReason;
    }

    this._hpComponent.takeDamage(damage);
    if (this._hpComponent.HP === 0) {
      this._isDefeated = true;
      this._stateMachine.setState(CHARACTER_STATES.DEATH_STATE, direction);
      return;
    }

    this._stateMachine.setState(CHARACTER_STATES.HURT_STATE, direction);
  }

  public disableObject(): void {
    (this.body as Phaser.Physics.Arcade.Body).enable = false;

    this.active = false;
    if (!this._isPlayer) {
      this.visible = false;
    }

    this.updateExclamationVisibility();
  }

  public enableObject(): void {
    if (this._isDefeated) {
      return;
    }
    // Only enable if the object is supposed to be revealed
    if (this._activeState === CHARACTER_ACTIVE_STATE.HIDDEN) {
      return;
    }
    (this.body as Phaser.Physics.Arcade.Body).enable = true;
    this.active = true;
    this.visible = true;

    this.updateExclamationVisibility();
  }

  public respawnObject(): void {
    this._isDefeated = false;
    this._hpComponent.resetHP();
    this._invulnerableComponent.resetInvulnerable();
    this.enableObject();
    this._stateMachine.setState(CHARACTER_STATES.IDLE_STATE);
  }

  /**
   * Get position next to the character based on a specified direction
   * @param offset - Distance to place the target position (default: 16px)
   * @param direction - Direction to place the target position (default: uses character's current facing direction)
   * @returns Position coordinates
   */
  public getPositionNextTo(
    offset = 8,
    direction?: Direction,
  ): { x: number; y: number } {
    let targetX = this.x;
    let targetY = this.y;

    // Use provided direction or fall back to character's current direction
    const targetDirection = direction || this.direction;

    // Adjust position based on the target direction to place target in front
    switch (targetDirection) {
      case "UP":
        targetY -= offset;
        break;
      case "DOWN":
        targetY += this.height + offset;
        break;
      case "LEFT":
        targetX -= offset;
        break;
      case "RIGHT":
        targetX += this.width + offset;
        break;
      default:
        // Default to slightly below the character
        targetY -= offset;
    }
    return { x: targetX, y: targetY };
  }

  /**
   * Automated movement to a target position
   * @param targetPos - The target position to move to
   * @param checkInterval - How often to check position (default: 50ms)
   * @param arrivalDistance - Distance at which to consider arrival (default: 16px)
   * @returns Promise that resolves when movement is complete
   */
  public startAutomatedMovement(
    targetPos: { x: number; y: number },
    checkInterval = 50,
    arrivalDistance = 6,
  ): Promise<void> {
    const dataManager = this.dataManager;
    return new Promise((resolve) => {
      // Store initial room/level to detect transitions
      const initialArea = {
        level: dataManager.data.currentArea.level,
        roomId: dataManager.data.currentArea.roomId,
        doorId: dataManager.data.currentArea.doorId,
      };

      // Check if we've reached the target
      const interval = setInterval(() => {
        // If character is disabled, stop movement
        if (!this.active) {
          clearInterval(interval);
          this.controls.reset();
          resolve();
          return;
        }

        // Check if we've changed rooms/levels during movement
        const currentArea = dataManager.data.currentArea;
        if (
          currentArea.level !== initialArea.level ||
          currentArea.roomId !== initialArea.roomId ||
          currentArea.doorId !== initialArea.doorId
        ) {
          clearInterval(interval);

          // Stop moving
          this.controls.reset();

          // Resolve immediately - we've transitioned to a different room/level
          resolve();
          return;
        }

        const dx = targetPos.x - this.x;
        const dy = targetPos.y - this.y;
        const distance = Phaser.Math.Distance.Between(
          this.x,
          this.y,
          targetPos.x,
          targetPos.y,
        );

        if (distance < arrivalDistance) {
          clearInterval(interval);

          // Stop moving
          this.controls.reset();

          // Resolve the promise instead of emitting an event
          resolve();
          return;
        }

        // Clear previous movement inputs
        this.controls.reset();

        // Determine which direction to press - allow both horizontal and vertical movement
        let horizontalInput = 0;
        let verticalInput = 0;

        // Add braking when close to target to prevent overshooting
        const brakingDistance = 3; // Start braking when within this distance
        const isBraking = distance < brakingDistance;

        // Set horizontal input if there's significant horizontal distance
        if (Math.abs(dx) > 4) {
          horizontalInput = dx > 0 ? 1 : -1; // Right or Left
        }

        // Set vertical input if there's significant vertical distance
        if (Math.abs(dy) > 4) {
          verticalInput = dy > 0 ? 1 : -1; // Down or Up
        }

        // If we're very close to target on one axis, stop moving in that direction
        if (Math.abs(dx) < 4) {
          horizontalInput = 0;
        }
        if (Math.abs(dy) < 4) {
          verticalInput = 0;
        }

        // Apply braking by intermittently disabling movement when close to target
        if (isBraking) {
          // Use a simple time-based braking pattern to slow down movement
          const brakePattern = Math.floor(Date.now() / 100) % 2; // Alternates between 0 and 1 every 100ms

          // Only brake the axis that's close to the target
          if (brakePattern === 0) {
            if (Math.abs(dx) < brakingDistance) {
              horizontalInput = 0;
            }
            if (Math.abs(dy) < brakingDistance) {
              verticalInput = 0;
            }
          }
        }

        // Extra precise movement when very close to target
        if (distance < 8) {
          // Use slower, more precise movement pattern
          const precisePattern = Math.floor(Date.now() / 150) % 3; // 3-state pattern every 150ms
          if (precisePattern === 0) {
            horizontalInput = 0;
            verticalInput = 0;
          }
        }

        // Simulate input - allow both directions simultaneously for diagonal movement
        if (horizontalInput > 0) {
          this.controls.isRightDown = true;
        } else if (horizontalInput < 0) {
          this.controls.isLeftDown = true;
        }

        if (verticalInput > 0) {
          this.controls.isDownDown = true;
        } else if (verticalInput < 0) {
          this.controls.isUpDown = true;
        }
      }, checkInterval);
    });
  }

  /**
   * Stop any ongoing automated movement
   */
  public stopAutomatedMovement(): void {
    // Clear all movement inputs
    this.controls.reset();
  }

  /**
   * Make this character face another character
   * Uses the center of both objects for accurate facing direction
   */
  public faceCharacter(targetCharacter: CharacterObject): void {
    // Calculate centers of both characters
    const thisCenter = {
      x: this.physicsBody.x + (this.physicsBody.width ?? 0) / 2,
      y: this.physicsBody.y + (this.physicsBody.height ?? 0) / 2,
    };
    const targetCenter = {
      x:
        targetCharacter.physicsBody.x +
        (targetCharacter.physicsBody.width ?? 0) / 2,
      y:
        targetCharacter.physicsBody.y +
        (targetCharacter.physicsBody.height ?? 0) / 2,
    };

    const relativeDirection = getRelativeDirection(thisCenter, targetCenter);

    this.direction = relativeDirection;
    // Play the appropriate idle animation for the new direction
    this.animationComponent.playAnimation(`IDLE_${relativeDirection}` as const);
  }

  /**
   * Start a spinning animation by cycling through directions
   * @param spinCount Number of complete rotations (4 directions = 1 rotation)
   * @param delayBetweenDirections Delay in milliseconds between direction changes
   * @returns Promise that resolves when spin animation is complete
   */
  public startSpin(
    spinCount: number,
    delayBetweenDirections = 200,
  ): Promise<void> {
    return new Promise((resolve) => {
      // Define a clockwise spin sequence from character's perspective: UP -> LEFT -> DOWN -> RIGHT
      const directions = [
        DIRECTION.UP,
        DIRECTION.LEFT,
        DIRECTION.DOWN,
        DIRECTION.RIGHT,
      ];
      const totalDirectionChanges = spinCount * directions.length;
      let currentDirectionIndex = 0;

      // Find the starting direction index
      let startDirectionIndex = directions.indexOf(this.direction);
      if (startDirectionIndex === -1) {
        // Fallback to UP if current direction is not found
        startDirectionIndex = 0;
      }

      // Lock controls during spin
      const wasMovementControlsLocked = this.controls.movementControlsLocked;
      this.controls.movementControlsLocked = true;

      const spinInterval = setInterval(() => {
        if (currentDirectionIndex >= totalDirectionChanges) {
          // Spin complete
          clearInterval(spinInterval);
          this.controls.movementControlsLocked = wasMovementControlsLocked;
          resolve();
          return;
        }

        // Calculate the direction index starting from the current facing direction
        const directionIndex =
          (startDirectionIndex + currentDirectionIndex) % directions.length;
        const newDirection = directions[directionIndex];

        // Update the direction using the setter
        this.direction = newDirection;

        // Play the idle animation for the new direction directly
        this.animationComponent.playAnimation(`IDLE_${newDirection}`);

        currentDirectionIndex++;
      }, delayBetweenDirections);
    });
  }

  /**
   * Check if the character is currently standing on an ice tile.
   * Default implementation returns false - should be overridden by Player class.
   */
  public isOnIce(): boolean {
    return false;
  }

  /**
   * Check if the character is currently standing on an ice stairs tile.
   * Default implementation returns false - should be overridden by Player class.
   */
  public isOnIceStairs(): boolean {
    return false;
  }

  /**
   * Check if the character is currently standing on a rock object.
   * Default implementation returns false - should be overridden by Player class.
   */
  public touchingRock(): Rock | undefined {
    return undefined;
  }

  /**
   * Updates the exclamation sprite visibility based on character visibility
   * Called automatically by enableObject/disableObject
   */
  protected updateExclamationVisibility(): void {
    if (this._exclamationSprite) {
      this._exclamationSprite.setVisible(this.visible);
    }
  }

  /**
   * Destroys the exclamation sprite
   * Can be overridden by subclasses that use exclamation sprites
   */
  protected destroyExclamationSprite(): void {
    if (this._exclamationSprite) {
      this._exclamationSprite.destroy();
      this._exclamationSprite = undefined;
    }
  }

  /**
   * Destroy this character object and clean up resources
   */
  public destroy(): void {
    this.destroyExclamationSprite();
    super.destroy();
  }
}
