import * as Phaser from "phaser";
import type { GameObjects } from "phaser";
import { ASSET_KEYS } from "../../common/assets";
import { LEVEL_NAME, type INSTRUMENT_TOOL_TYPE } from "../../common/constants";
import { getSceneDataManager } from "../../common/data-manager";
import { CUSTOM_EVENTS, EVENT_BUS } from "../../common/event-bus";
import type { Direction } from "../../common/types";
import type { InputComponent } from "../../components/input-component";
import type { ToolComponent } from "../../components/tool-component";
import { BaseTool, type UseToolAnimationConfig } from "./base-tool";

export type InstrumentType =
  (typeof INSTRUMENT_TOOL_TYPE)[keyof typeof INSTRUMENT_TOOL_TYPE];
const SCENE_SHUTDOWN_EVENT = "shutdown";

type MusicNote = {
  sprite: Phaser.GameObjects.Image;
  initialX: number;
  time: number;
  speed: number;
  offset: number;
  linearVelocity: [number, number];
  lifetime: number;
};

// Maps number row keys to chromatic notes (C, C#, D, D#, E, F, F#, G, G#, A, A#, B)
const KEY_TO_NOTE: Record<string, string> = {
  "1": "C",
  "2": "Cs",
  "3": "D",
  "4": "Ds",
  "5": "E",
  "6": "F",
  "7": "Fs",
  "8": "G",
  "9": "Gs",
  "0": "A",
  "-": "As",
  "=": "B",
};

export class InstrumentTool extends BaseTool {
  #instrumentType: InstrumentType;

  // Toggle mode state
  #isInToggleMode = false;

  // Song detection constants
  #noteHistory: string[] = [];
  static readonly #MAX_NOTE_HISTORY_LENGTH = 32;
  static readonly #DETECTION_RADIUS = 48;

  // Music bird position tracking
  #songPositionStack: { x: number; y: number }[] = [];
  #pendingSongPosition: { x: number; y: number } | undefined;
  #isAwaitingMusicBird = false; // Lock input while the music bird is en route

  // Keyboard keys for note input
  #noteKeys: Phaser.Input.Keyboard.Key[] = [];
  #shiftKey: Phaser.Input.Keyboard.Key | undefined;
  #zKey: Phaser.Input.Keyboard.Key | undefined;

  // Visual effects
  #notes: MusicNote[] = [];
  #noteDepth = 100;

  // Music bird song constants
  static readonly #UP_BIRD_SEQUENCE = ["D4", "D4", "D4"] as const; // up-up-up
  static readonly #UNDO_SEQUENCE = ["F3", "D3", "F3"] as const; // down-space-down
  static readonly #DOWN_RIGHT_SEQUENCE = ["F3", "A3", "F3", "A3"] as const; // down-right-down-right
  static readonly #HOME_SEQUENCE = [
    "A3",
    "A3",
    "B3",
    "B3",
    "F3",
    "F3",
    "D4",
    "D4",
  ] as const; // right-right-left-left-down-down-up-up
  static readonly #DEEP_DOWN_LEFT_SEQUENCE = ["F3", "F3", "F3", "B3"] as const; // down-down-down-left
  static readonly #SPEED_BOOST_SEQUENCE = [
    "G3",
    "E3",
    "D3",
    "C3",
    "G3",
    "E3",
    "D3",
    "C3",
    "G3",
    "E3",
    "D3",
    "C3",
    "G3",
    "E3",
    "D3",
    "C3",
    "A3",
    "E3",
    "D3",
    "C3",
    "A3",
    "E3",
    "D3",
    "C3",
    "A3",
    "E3",
    "D3",
    "C3",
    "A3",
    "E3",
    "D3",
    "C3",
  ] as const;
  static readonly #MUSIC_BIRD_ROOM_ID = 1;
  static readonly #MUSIC_BAT_ROOM_ID = 15;
  static readonly #TILE_LENGTH_PX = 16;
  static readonly #HOT_COLD_SEQUENCE = ["D3", "F3", "A3"] as const; // up-up-down-down

  public get toolType(): string {
    return this.#instrumentType;
  }

  constructor(
    sprite: GameObjects.Sprite,
    toolComponent: ToolComponent,
    animationConfig: UseToolAnimationConfig,
    instrumentType: InstrumentType,
  ) {
    super(sprite, toolComponent, animationConfig);
    this._isToggleable = true;
    this.#instrumentType = instrumentType;
    this.#setupNoteKeys();

    this._sprite.scene.events.on(
      Phaser.Scenes.Events.UPDATE,
      this.iUpdate.bind(this),
      this,
    );

    EVENT_BUS.on(
      CUSTOM_EVENTS.MUSIC_BIRD_DROPPED,
      this.#handleMusicBirdDropped,
      this,
    );
    EVENT_BUS.on(
      CUSTOM_EVENTS.MUSIC_BIRD_SUMMON_FAILED,
      this.#handleMusicBirdSummonFailed,
      this,
    );
    this._sprite.scene.events.once(SCENE_SHUTDOWN_EVENT, () => {
      EVENT_BUS.off(
        CUSTOM_EVENTS.MUSIC_BIRD_DROPPED,
        this.#handleMusicBirdDropped,
        this,
      );
      EVENT_BUS.off(
        CUSTOM_EVENTS.MUSIC_BIRD_SUMMON_FAILED,
        this.#handleMusicBirdSummonFailed,
        this,
      );
    });
  }

  #setupNoteKeys(): void {
    const keyboard = this._sprite.scene.input.keyboard;
    if (!keyboard) return;

    // Add number row keys for notes
    const keyCodes = [
      Phaser.Input.Keyboard.KeyCodes.ONE,
      Phaser.Input.Keyboard.KeyCodes.TWO,
      Phaser.Input.Keyboard.KeyCodes.THREE,
      Phaser.Input.Keyboard.KeyCodes.FOUR,
      Phaser.Input.Keyboard.KeyCodes.FIVE,
      Phaser.Input.Keyboard.KeyCodes.SIX,
      Phaser.Input.Keyboard.KeyCodes.SEVEN,
      Phaser.Input.Keyboard.KeyCodes.EIGHT,
      Phaser.Input.Keyboard.KeyCodes.NINE,
      Phaser.Input.Keyboard.KeyCodes.ZERO,
      Phaser.Input.Keyboard.KeyCodes.MINUS,
      Phaser.Input.Keyboard.KeyCodes.PLUS, // = key
    ];

    this.#noteKeys = keyCodes.map((code) => keyboard.addKey(code));
    this.#shiftKey = keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.SHIFT);
    this.#zKey = keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.Z);
  }

  public use(_direction: Direction): void {
    this.enterToggleMode();
  }

  public handleInput(controls: InputComponent): void {
    if (!this.#isInToggleMode) return;
    if (this.#isAwaitingMusicBird) return;

    // Check for E key to exit toggle mode
    if (controls.isUseJustDown) {
      this.exitToggleMode();
      return;
    }

    // Map keybinds to notes and play if triggered
    const note = this.#getNoteFromControls(controls);
    if (note) {
      const soundKey = this.#getSoundAssetKey(note);
      this._sprite.scene.sound.play(soundKey);
      this.addNote(note);
    }
  }

  #getNoteFromControls(controls: InputComponent): string | undefined {
    // Check number row keys for chromatic notes
    const noteFromKeyboard = this.#getNoteFromKeyboard();
    if (noteFromKeyboard) {
      return noteFromKeyboard;
    }

    if (controls.isUpJustDown) {
      return "D4";
    }
    if (controls.isDownJustDown) {
      return "F3";
    }
    if (controls.isLeftJustDown) {
      return "B3";
    }
    if (controls.isRightJustDown) {
      return "A3";
    }
    if (controls.isActionKeyJustDown) {
      return "D3";
    }
    return undefined;
  }

  #getNoteFromKeyboard(): string | undefined {
    // Must match order of keyCodes in #setupNoteKeys
    const keyChars = [
      "1",
      "2",
      "3",
      "4",
      "5",
      "6",
      "7",
      "8",
      "9",
      "0",
      "-",
      "=",
    ];

    for (let i = 0; i < this.#noteKeys.length; i++) {
      const key = this.#noteKeys[i];
      if (Phaser.Input.Keyboard.JustDown(key)) {
        const noteName = KEY_TO_NOTE[keyChars[i]];
        if (!noteName) continue;
        return `${noteName}${this.#getOctave()}`;
      }
    }
    return undefined;
  }

  #getOctave(): number {
    if (this.#shiftKey?.isDown) return 4;
    if (this.#zKey?.isDown) return 2;
    return 3;
  }

  #getSoundAssetKey(note: string): string {
    return `NOTE_${note}_SFX`;
  }

  #getAnimationKey(): string {
    return `player_${this.#instrumentType}_down`;
  }

  private enterToggleMode(): void {
    this.#isInToggleMode = true;
    this._inUse = true;
    this._toolComponent.body.enable = true;
    this._sprite.play({ key: this.#getAnimationKey(), repeat: -1 }, true);

    // Set up tool body for song detection
    this._toolComponent.body.setCircle(InstrumentTool.#DETECTION_RADIUS);
    // Center the circle on the player (body position is top-left of bounding box, so offset by radius)
    this._toolComponent.body.position.set(
      this._sprite.x - InstrumentTool.#DETECTION_RADIUS,
      this._sprite.y - InstrumentTool.#DETECTION_RADIUS,
    );
    this._toolComponent.body.setImmovable(true);
  }

  private exitToggleMode(): void {
    this.#isAwaitingMusicBird = false;
    this.#isInToggleMode = false;
    this.#noteHistory = [];
    this._inUse = false;
    this._toolComponent.body.enable = false;
    this._sprite.stop();
  }

  public override reset(): void {
    this.#isAwaitingMusicBird = false;
    this.exitToggleMode();
    this.#clearVisualNotes();
  }

  private iUpdate(_: number, delta: number): void {
    const dt = delta / 1000.0;
    for (let i = this.#notes.length - 1; i >= 0; i--) {
      const note = this.#notes[i];
      note.time += dt;
      note.sprite.x += note.linearVelocity[0] * dt;
      note.sprite.x +=
        25 * dt * Math.sin(((note.time + note.offset) * note.speed) / 20);
      note.sprite.y += dt * note.linearVelocity[1];
      note.sprite.alpha = Phaser.Math.Clamp(
        note.sprite.alpha - dt / note.lifetime,
        0,
        1,
      );

      if (note.time >= note.lifetime) {
        note.sprite.destroy();
        this.#notes.splice(i, 1);
      }
    }
  }

  public get isInToggleMode(): boolean {
    return this.#isInToggleMode;
  }

  public get instrumentType(): InstrumentType {
    return this.#instrumentType;
  }

  // Song detection methods
  public addNote(note: string): void {
    this.#noteHistory.push(note);
    if (this.#noteHistory.length > InstrumentTool.#MAX_NOTE_HISTORY_LENGTH) {
      this.#noteHistory.shift(); // Remove oldest note
    }
    this.#checkForSongs();
    this.#spawnNoteVisual();
  }

  #spawnNoteVisual(): void {
    const x = this._sprite.x - 6 + Math.random() * 6;
    const y = this._sprite.y - 3 + Math.random() * 6;
    const noteSprite = this._sprite.scene.add.image(
      x,
      y,
      ASSET_KEYS.MUSIC_NOTE,
    );
    noteSprite.setDepth(this._sprite.depth + this.#noteDepth);
    this.#noteDepth += 1;
    if (this.#noteDepth > 200) {
      this.#noteDepth = 100;
    }

    noteSprite.setScale(Phaser.Math.RND.realInRange(0.45, 0.75));
    noteSprite.setTint(
      Phaser.Math.RND.pick([
        0xfff4e6, 0xffe4b3, 0xffd480, 0xffc966, 0xffb84d, 0xffa733,
      ]),
    );

    this.#notes.push({
      sprite: noteSprite,
      initialX: x,
      time: 0,
      speed: 20 + Math.random() * 16,
      offset: Math.random() * Math.PI * 2,
      linearVelocity: [
        Phaser.Math.RND.realInRange(-20, 20),
        Phaser.Math.RND.realInRange(-20, -50),
      ],
      lifetime: Math.random() * 1.2 + 1,
    });
  }

  #clearVisualNotes(): void {
    this.#notes.forEach((note) => {
      note.sprite.destroy();
    });
    this.#notes = [];
  }

  public getNoteHistory(): string[] {
    return [...this.#noteHistory]; // Return a copy
  }

  public clearNoteHistory(): void {
    this.#noteHistory = [];
  }

  #checkForSongs(): void {
    if (!this.#isInToggleMode) {
      return;
    }

    const dataManager = getSceneDataManager(this._sprite.scene);
    const area = dataManager.data.currentArea;

    this.#maybeHandleSong(
      InstrumentTool.#SPEED_BOOST_SEQUENCE,
      this.#handleSpeedBoostSong.bind(this),
    );

    const isMountainBirdRoom =
      area.level === LEVEL_NAME.MOUNTAIN &&
      area.roomId === InstrumentTool.#MUSIC_BIRD_ROOM_ID;
    const isCemeteryBirdRoom =
      area.level === LEVEL_NAME.CEMETERY &&
      area.roomId === InstrumentTool.#MUSIC_BAT_ROOM_ID;
    const isCemeteryRoom1 =
      area.level === LEVEL_NAME.CEMETERY && area.roomId === 1;

    if (isCemeteryRoom1) {
      this.#maybeHandleSong(
        InstrumentTool.#HOT_COLD_SEQUENCE,
        this.#handleHotColdSong.bind(this),
      );
    }

    const isBirdSongRoom = isMountainBirdRoom || isCemeteryBirdRoom;
    if (!isBirdSongRoom) {
      return;
    }

    this.#maybeHandleSong(InstrumentTool.#UP_BIRD_SEQUENCE, () => {
      this.#handleLiftSong();
    });
    this.#maybeHandleSong(InstrumentTool.#DOWN_RIGHT_SEQUENCE, () => {
      this.#handleDownRightSong();
    });
    this.#maybeHandleSong(InstrumentTool.#DEEP_DOWN_LEFT_SEQUENCE, () => {
      this.#handleDeepDownLeftSong();
    });

    this.#maybeHandleSong(
      InstrumentTool.#UNDO_SEQUENCE,
      this.#handleUndoSong.bind(this),
    );

    if (isMountainBirdRoom) {
      this.#maybeHandleSong(
        InstrumentTool.#HOME_SEQUENCE,
        this.#handleHomeSong.bind(this),
      );
    }
  }

  #maybeHandleSong(sequence: readonly string[], handler: () => void): boolean {
    const requiredLength = sequence.length;
    if (this.#noteHistory.length < requiredLength) {
      return false;
    }

    const lastNotes = this.#noteHistory.slice(-requiredLength);
    const matchesSequence = sequence.every(
      (note, index) => lastNotes[index] === note,
    );

    if (!matchesSequence) {
      return false;
    }

    handler();
    this.clearNoteHistory();
    return true;
  }

  #handleLiftSong(): void {
    this.#handleMoveSong({
      x: 0,
      y: -InstrumentTool.#TILE_LENGTH_PX * 2,
    });
  }

  #handleDownRightSong(): void {
    this.#handleMoveSong({
      x: InstrumentTool.#TILE_LENGTH_PX * 2,
      y: InstrumentTool.#TILE_LENGTH_PX * 2,
    });
  }

  #handleDeepDownLeftSong(): void {
    this.#handleMoveSong({
      x: -InstrumentTool.#TILE_LENGTH_PX,
      y: InstrumentTool.#TILE_LENGTH_PX * 3,
    });
  }

  #handleUndoSong(): void {
    const lastPosition = this.#songPositionStack.pop();
    if (!lastPosition) {
      EVENT_BUS.emit(CUSTOM_EVENTS.DIALOG_START, {
        messages: ["There's nothing left to undo."],
      });
      return;
    }

    this.#isAwaitingMusicBird = true;
    EVENT_BUS.emit(CUSTOM_EVENTS.MUSIC_BIRD_SUMMON, {
      from: { x: this._sprite.x, y: this._sprite.y },
      to: lastPosition,
    });
  }

  #handleHotColdSong(): void {
    const dataManager = getSceneDataManager(this._sprite.scene);
    const { level, roomId } = dataManager.data.currentArea;

    EVENT_BUS.emit(CUSTOM_EVENTS.HOT_COLD_SONG, {
      x: this._sprite.x,
      y: this._sprite.y,
      level,
      roomId,
    });
  }

  #handleHomeSong(): void {
    // Below room 1 door 1: (1320, 1504)
    const homePosition = { x: 1320, y: 1504 };
    this.#isAwaitingMusicBird = true;
    this.#pendingSongPosition = { x: this._sprite.x, y: this._sprite.y };
    EVENT_BUS.emit(CUSTOM_EVENTS.MUSIC_BIRD_SUMMON, {
      from: { x: this._sprite.x, y: this._sprite.y },
      to: homePosition,
    });
  }

  #handleSpeedBoostSong(): void {
    EVENT_BUS.emit(CUSTOM_EVENTS.PLAYER_SPEED_BOOST, { modifier: 1.3 });
    EVENT_BUS.emit(CUSTOM_EVENTS.DIALOG_START, {
      messages: ["You feel a sudden burst of energy!"],
    });
  }

  #handleMoveSong(offset: { x: number; y: number }): void {
    this.#isAwaitingMusicBird = true;
    this.#pendingSongPosition = { x: this._sprite.x, y: this._sprite.y };
    const destination = {
      x: this._sprite.x + offset.x,
      y: this._sprite.y + offset.y,
    };
    EVENT_BUS.emit(CUSTOM_EVENTS.MUSIC_BIRD_SUMMON, {
      from: { x: this._sprite.x, y: this._sprite.y },
      to: destination,
    });
  }

  #handleMusicBirdDropped = (): void => {
    if (this.#pendingSongPosition) {
      this.#songPositionStack.push(this.#pendingSongPosition);
      this.#pendingSongPosition = undefined;
    }
    this.#isAwaitingMusicBird = false;
  };

  #handleMusicBirdSummonFailed = (): void => {
    this.#pendingSongPosition = undefined;
    this.#isAwaitingMusicBird = false;
  };
}
