import * as Phaser from "phaser";
import {
  ASSET_KEYS,
  TREASURE_FRAME_KEYS,
  type TreasureFrameKey,
  EFFECTS_ANIMATION_KEYS,
} from "../../common/assets";
import { FLAG_TO_INTERACTION_MAP } from "../../common/constants";
import { getSceneDataManager } from "../../common/data-manager";
import { CUSTOM_EVENTS, EVENT_BUS } from "../../common/event-bus";
import type { TiledBuriedTreasureObject } from "../../common/tiled/types";
import type { CustomObject } from "../../common/types";
import { DiggableComponent } from "../../components/diggable-component";

export class BuriedTreasure
  extends Phaser.GameObjects.Zone
  implements CustomObject
{
  #treasureTexture: TreasureFrameKey;
  #isDiscoveredInSession = false;
  #isDiscoveredInHunt = false;
  #treasureSprite?: Phaser.GameObjects.Sprite;
  #diggableComponent?: DiggableComponent;
  #sparkle?: Phaser.GameObjects.Sprite;
  #hasSparkle = false;
  #storyFlag?: string;
  #discoverableByProximity = false;

  constructor(scene: Phaser.Scene, config: TiledBuriedTreasureObject) {
    super(scene, config.x, config.y, config.width, config.height);

    this.#treasureTexture = config.texture;
    this.#storyFlag = config.storyFlag;
    this.#discoverableByProximity = config.discoverableByProximity;
    this.#hasSparkle = config.sparkle ?? false;

    this.setOrigin(0, 0);
    scene.add.existing(this);
    scene.physics.world.enable(this);
    (this.body as Phaser.Physics.Arcade.Body).setImmovable(true);

    // Add diggable component to mark as buried
    this.#diggableComponent = new DiggableComponent(this);

    // Initially disabled and invisible
    this.disableObject();
    this.visible = false;

    if (this.#hasSparkle) {
      this.#createSparkle();
    }
  }

  get treasureTexture(): TreasureFrameKey {
    return this.#treasureTexture;
  }

  get storyFlag(): string | undefined {
    return this.#storyFlag;
  }

  get isDiscoveredInHunt(): boolean {
    return this.#isDiscoveredInHunt;
  }

  set isDiscoveredInHunt(value: boolean) {
    this.#isDiscoveredInHunt = value;
  }

  get discoverableByProximity(): boolean {
    return this.#discoverableByProximity;
  }

  public resetTreasure(): void {
    this.#isDiscoveredInSession = false;
    this.#diggableComponent?.reset();
    if (this.#treasureSprite) {
      this.#treasureSprite.destroy();
      this.#treasureSprite = undefined;
    }
    if (!this.#sparkle && this.#hasSparkle) {
      this.#createSparkle();
    }
  }

  /**
   * Called when treasure is discovered (e.g., by digging or proximity)
   */
  public discover(player: Phaser.GameObjects.Sprite): void {
    if (this.#isDiscoveredInSession) {
      return;
    }

    this.#isDiscoveredInSession = true;
    this.#diggableComponent?.unbury();
    if (this.#sparkle) {
      this.#sparkle.destroy();
      this.#sparkle = undefined;
    }

    // Show treasure sprite at burial site (treasure and events are handled in the tween onComplete)
    this.#createTreasureSprite(player);
  }

  /**
   * Hide treasure sprite when dialog closes
   */
  #handleDialogClosed(): void {
    if (this.#treasureSprite) {
      this.#treasureSprite.setVisible(false);
    }
  }

  /**
   * Gets the default message based on texture type
   */
  #treasureMessage(): string {
    const objectTypes: Partial<Record<TreasureFrameKey, string>> = {
      PINK_PEARL: "marble",
    };

    if (this.#isDiscoveredInHunt) {
      return `You found this ${objectTypes[this.#treasureTexture] ?? "treasure"} already!`;
    }

    // Map texture names directly to messages
    const messageMap: Record<TreasureFrameKey, string> = {
      /* Aviaria */
      PAPERS:
        "A portfolio of papers, it seems to be a diary detailing the every day life of an egg.",
      /* Western */
      BELT: "A belt! Perfect for… chewing. Why was this even buried?",
      BOOK: "Buried literature! A real dog-eared edition—just how we like it.",
      CREDIT_CARD: "You dug up a credit card! If only it wasn't expired...",
      KEY: "A key! What the heck is it doing out here?",
      SHOE: "A buried shoe—finally, justice for all the chewed-up soles!",
      TENNIS_BALL:
        "A tennis ball! The ultimate treasure. Return to sender immediately for fetch duties.",
      /* Campground */
      APPLE: "An apple, red and delicious! Too bad it isn't golden.",
      CHOCOLATE:
        "A wrapped chocolate bar... was someone just hiding this or were they hoping for something more?",
      DONUT:
        "A box of donuts! You extract one as your prize and rebury the box.",
      SHOVEL:
        "A buried shovel, if you dig deep you can find something poetic about this.",
      TENT_STAKES:
        "A bundle of tent stakes! Wait, if these are here then how are the tents holding up!?",
      PINK_PEARL: "A marble! I'll keep this and give it to Burnham.",
      ONION:
        "You unearth an onion. It's got layers. So do your feelings about this forest.",
      CARROT:
        "A carrot, still crunchy despite being buried. The bunnies will be jealous.",
      POTATO: "A potato, lightly seasoned with dirt. Mash later; treasure now.",
      PUMPKIN: "A tiny pumpkin! You could carve a jack-o-lantern for an ant.",
      TURNIP: "A turnip turns up. It insists it's the root of all good stew.",
      /* Bone Treasures (cross-zone) */
      GOLD_BONE: "A golden bone! It shimmers with an otherworldly glow.",
      SHELL_FOSSIL: "A fossilized shell, preserved perfectly through the ages.",
      DRAGON_HORN:
        "A dragon's horn! This must have belonged to a legendary creature.",
    };

    return messageMap[this.#treasureTexture] ?? "You found treasure!";
  }

  /**
   * Creates a treasure sprite at the burial site
   */
  #createTreasureSprite(player: Phaser.GameObjects.Sprite): void {
    if (!this.#isDiscoveredInHunt) {
      if (this.#treasureSprite) {
        this.#treasureSprite.destroy();
      }

      // Show the treasure at the burial location
      // Account for the -4 offset we added in constructor
      this.#treasureSprite = this.scene.add.sprite(
        this.x + 4 + (this.width - 8) / 2,
        this.y + 4,
        ASSET_KEYS.TREASURES,
        TREASURE_FRAME_KEYS[this.#treasureTexture],
      );

      this.#treasureSprite.setOrigin(0.5, 1); // Center horizontally, align bottom
      this.#treasureSprite.setDepth(player.depth + 100); // Render well above player

      // Hide treasure sprite when dialog closes
      EVENT_BUS.once(CUSTOM_EVENTS.DIALOG_COMPLETE, () => {
        this.#handleDialogClosed();
      });

      // Animate the treasure sprite upward
      this.scene.tweens.add({
        targets: this.#treasureSprite,
        y: this.#treasureSprite.y - 16,
        duration: 500,
        onComplete: (): void => {
          this.#completeAssociatedInteraction();
        },
      });
    }
    // After animation, show the dialog with default message
    EVENT_BUS.emit(CUSTOM_EVENTS.DIALOG_START, {
      messages: [this.#treasureMessage()],
      choices: [],
    });
  }

  public disableObject(): void {
    (this.body as Phaser.Physics.Arcade.Body).enable = false;
    this.active = false;
    this.visible = false;
    if (this.#sparkle) {
      this.#sparkle.setVisible(false);
    }
  }

  public enableObject(): void {
    (this.body as Phaser.Physics.Arcade.Body).enable = true;
    this.active = true;
    this.visible = true; // Zones are invisible by default, but need visible=true for collision detection
    // Show sparkle while buried
    if (
      this.#diggableComponent?.isBuried() &&
      this.#sparkle &&
      !this.#isDiscoveredInHunt
    ) {
      this.#sparkle.setVisible(true);
      if (!this.#sparkle.anims.isPlaying) {
        this.#sparkle.play({
          key: EFFECTS_ANIMATION_KEYS.SPARKLE,
          repeat: -1,
        });
      }
    } else if (this.#sparkle) {
      this.#sparkle.setVisible(false);
      this.#sparkle.stop();
    }
  }

  #completeAssociatedInteraction(): void {
    // Skip if already discovered in hunt (prevents duplicate API calls)
    if (this.#isDiscoveredInHunt || !this.#storyFlag) {
      return;
    }

    const dataManager = getSceneDataManager(this.scene);
    const interactionId =
      FLAG_TO_INTERACTION_MAP[
        this.#storyFlag as keyof typeof FLAG_TO_INTERACTION_MAP
      ];

    // Only proceed if there's an interaction to complete
    if (interactionId) {
      // Mark as discovered before making the call to prevent duplicates
      this.#isDiscoveredInHunt = true;
    }

    // Set flag to completed and complete the associated interaction
    dataManager.setFlagToCompleted(this.#storyFlag);
    dataManager.completeInteraction(this.#storyFlag);
  }

  #createSparkle(): void {
    if (this.#sparkle) {
      return;
    }
    // Account for the -4 offset we added in constructor
    this.#sparkle = this.scene.add.sprite(
      this.x + 4,
      this.y + 4,
      ASSET_KEYS.SPARKLE,
    );
    this.#sparkle.setOrigin(0, 0);
    this.#sparkle.setDepth(this.depth + 1);
    this.#sparkle.setVisible(false);
  }
}
