import { DIRECTION } from "../common/constants";
import { getSceneDataManager } from "../common/data-manager";
import { TILED_LAYER_NAMES } from "../common/tiled/constants";
import type * as TILED_TYPES from "../common/tiled/types";
import type { GameObject } from "../common/types";
import { getPositionInDirection } from "../common/utils";
import type { Player } from "../entities/player/player";
import type { BaseGameScene } from "../scenes/base-game-scene";
import { BaseGameObjectComponent } from "./base-game-object";

export class PushableComponent extends BaseGameObjectComponent {
  #pushConfig: TILED_TYPES.TiledPushConfig;
  #isBeingPushed = false;
  #pushDistance = 16; // 16px push distance
  #pushFailCounter = 0;
  #pushTween?: Phaser.Tweens.Tween;
  #pushIntentStartTime: number | null = null;
  #pushIntentDuration = 200; // ms - how long player must press into object before pushing
  #lastPlayerDirection: string | null = null;

  constructor(gameObject: GameObject, pushConfig: TILED_TYPES.TiledPushConfig) {
    super(gameObject);
    this.#pushConfig = pushConfig;
  }

  get isBeingPushed(): boolean {
    return this.#isBeingPushed;
  }

  get pushFailCounter(): number {
    return this.#pushFailCounter;
  }

  set pushFailCounter(value: number) {
    this.#pushFailCounter = value;
  }

  public cancelPush(player?: Player): void {
    if (this.#pushTween) {
      this.#pushTween.stop();
      this.#pushTween = undefined;
    }
    this.#isBeingPushed = false;
    this.#resetPushIntent();
    if (player) {
      player.controls.isMovementLocked = false;
    }
  }

  public tryPush(player: Player): boolean {
    if (this.#isBeingPushed) {
      return false; // Already being pushed
    }

    const currentArea = getSceneDataManager(this.scene).data.currentArea;

    // Check all requirements are satisfied.
    if (this.#pushConfig.requiredLevel !== undefined) {
      if (currentArea.level !== this.#pushConfig.requiredLevel) {
        this.#resetPushIntent();
        return false; // Can't push outside of required level
      }
      if (this.#pushConfig.requiredRoom !== undefined) {
        if (currentArea.roomId !== this.#pushConfig.requiredRoom) {
          this.#pushFailCounter++;
          this.#resetPushIntent();
          return false; // Can't push outside of required room
        }
      }
    }

    // Check if player is moving towards the pushable
    if (!this.#isPlayerMovingTowardsPushable(player)) {
      this.#resetPushIntent();
      return false; // Player not moving towards pushable
    }

    // Start or continue push intent timer
    const now = this.scene.time.now;
    if (this.#pushIntentStartTime === null) {
      this.#pushIntentStartTime = now;
      this.#lastPlayerDirection = player.direction;
      return false; // Not ready to push yet, but intent started
    }

    // Check if player changed direction (reset intent)
    if (this.#lastPlayerDirection !== player.direction) {
      this.#pushIntentStartTime = now;
      this.#lastPlayerDirection = player.direction;
      return false; // Direction changed, reset timer
    }

    // Check if enough time has passed
    const elapsed = now - this.#pushIntentStartTime;
    if (elapsed < this.#pushIntentDuration) {
      return false; // Not enough time yet
    }

    // Calculate new position (16px in push direction)
    const newPosition = getPositionInDirection(
      { x: this.gameObject.x, y: this.gameObject.y },
      player.direction,
      this.#pushDistance,
    );

    // Check if the new position would collide with collision tiles
    if (!this.#isValidPushPosition(newPosition)) {
      this.#resetPushIntent();
      return false; // Can't push into collision
    }

    // Push successful - reset intent and push
    this.#resetPushIntent();
    this.#push(player, newPosition);
    this.#pushFailCounter = 0;
    return true; // Push successful
  }

  #isPlayerMovingTowardsPushable(player: Player): boolean {
    // Check if player has movement input in their current direction
    // Since we're already colliding, we just need to verify they're pressing
    // in a direction that would push the object away
    const controls = player.controls;
    const objectBody = (this.gameObject as Phaser.Physics.Arcade.Image).body as
      | Phaser.Physics.Arcade.Body
      | undefined;
    const playerBody = player.physicsBody;

    if (!objectBody || !playerBody) {
      return false;
    }

    // Check both input direction and that player is on the correct side of the object
    if (player.direction === DIRECTION.UP && controls.isUpDown) {
      // To push UP, player must be below the object
      return playerBody.y >= objectBody.y + objectBody.height;
    }
    if (player.direction === DIRECTION.DOWN && controls.isDownDown) {
      // To push DOWN, player must be above the object
      return playerBody.y + playerBody.height <= objectBody.y;
    }
    if (player.direction === DIRECTION.LEFT && controls.isLeftDown) {
      // To push LEFT, player must be to the right of the object
      return playerBody.x >= objectBody.x + objectBody.width;
    }
    if (player.direction === DIRECTION.RIGHT && controls.isRightDown) {
      return playerBody.x + playerBody.width <= objectBody.x;
    }
    return false;
  }

  #resetPushIntent(): void {
    this.#pushIntentStartTime = null;
    this.#lastPlayerDirection = null;
  }

  #isValidPushPosition(position: { x: number; y: number }): boolean {
    const baseGameScene = this.scene as unknown as BaseGameScene;
    const map = baseGameScene.tilemap;
    if (!map) {
      return true; // No map, allow push
    }

    const collisionLayer = map.getLayer(
      TILED_LAYER_NAMES.COLLISION,
    )?.tilemapLayer;
    if (!collisionLayer) {
      return true; // No collision layer, allow push
    }

    // Get collision body bounds (more accurate than sprite dimensions)
    // The pushable has a 12x12 body with offset (2, 2)
    const body = (this.gameObject as Phaser.Physics.Arcade.Image).body as
      | Phaser.Physics.Arcade.Body
      | undefined;

    let bodyX: number;
    let bodyY: number;
    let bodyWidth: number;
    let bodyHeight: number;

    if (body) {
      // Body position accounts for offset: sprite position + body offset
      bodyX = position.x + body.offset.x;
      bodyY = position.y + body.offset.y;
      bodyWidth = body.width;
      bodyHeight = body.height;
    } else {
      // Fallback to sprite dimensions if no body
      bodyX = position.x;
      bodyY = position.y;
      bodyWidth = this.gameObject.width ?? 12;
      bodyHeight = this.gameObject.height ?? 12;
    }

    // Check bounds using body dimensions
    const withinBounds =
      bodyX >= 0 &&
      bodyY >= 0 &&
      bodyX + bodyWidth <= map.widthInPixels &&
      bodyY + bodyHeight <= map.heightInPixels;
    if (!withinBounds) {
      return false;
    }

    // Check for colliding tiles using body bounds
    const tiles =
      collisionLayer.getTilesWithinWorldXY(
        bodyX,
        bodyY,
        bodyWidth,
        bodyHeight,
        { isColliding: true, isNotEmpty: true },
      ) ?? [];

    const collidingTile = tiles.find((tile) => tile?.collides);
    if (collidingTile) {
      return false;
    }

    // Also check partial collision rectangles using body bounds
    const hasPartial = baseGameScene.hasPartialCollision({
      x: bodyX,
      y: bodyY,
      width: bodyWidth,
      height: bodyHeight,
    });
    if (hasPartial) {
      return false;
    }

    // Check if this position would overlap with any other pushable
    // Create a temporary zone at the target position using body bounds
    const testZone = this.scene.add.zone(
      bodyX + bodyWidth / 2,
      bodyY + bodyHeight / 2,
      bodyWidth,
      bodyHeight,
    );
    this.scene.physics.add.existing(testZone);

    // Get pushable group through type assertion (we know it's BaseGameScene)
    const pushableGroup = (
      baseGameScene as unknown as {
        pushableGroup: Phaser.GameObjects.Group;
      }
    ).pushableGroup;

    // Check for overlaps with other pushables (excluding self)
    const otherPushables = pushableGroup.children.entries.filter(
      (obj) => obj !== this.gameObject,
    ) as Phaser.GameObjects.GameObject[];

    let wouldOverlap = false;
    for (const otherPushable of otherPushables) {
      if (
        this.scene.physics.overlap(
          testZone as Phaser.Types.Physics.Arcade.GameObjectWithBody,
          otherPushable as Phaser.Types.Physics.Arcade.GameObjectWithBody,
        )
      ) {
        wouldOverlap = true;
        break;
      }
    }

    // Clean up test zone
    testZone.destroy();

    if (wouldOverlap) {
      return false;
    }

    return true;
  }

  #push(player: Player, newPosition: { x: number; y: number }): void {
    if (this.#isBeingPushed) {
      return;
    }

    this.#isBeingPushed = true;
    player.controls.isMovementLocked = true;

    // Tween the object to new position
    this.#pushTween = this.gameObject.scene.tweens.add({
      targets: this.gameObject,
      x: newPosition.x,
      y: newPosition.y,
      duration: 200, // 200ms for smooth movement
      ease: "Power2",
      onComplete: () => {
        this.#isBeingPushed = false;
        this.#pushTween = undefined;
        this.#resetPushIntent();
        player.controls.isMovementLocked = false;
      },
    });
  }
}
