import { DEBUG_CHARACTER_STATE } from "../../common/config";

export type State = {
  stateMachine: StateMachine;
  name: string;
  onEnter?: (args: unknown[]) => void;
  onUpdate?: () => void;
  onExit?: () => void;
};

export class StateMachine {
  #id: string;
  #states: Map<string, State>;
  #currentState: State | undefined;
  #nextStateQueue: { state: string; args: unknown[] }[];
  #isChangingState: boolean;
  #enabled: boolean;

  constructor(id?: string) {
    if (id === undefined) {
      this.#id = Phaser.Math.RND.uuid();
    } else {
      this.#id = id;
    }
    this.#states = new Map<string, State>();

    this.#currentState = undefined;
    this.#nextStateQueue = [];
    this.#isChangingState = false;
    this.#enabled = true;
  }

  public update(): void {
    if (!this.#enabled) {
      return;
    }

    const queuedState = this.#nextStateQueue.shift();
    if (queuedState !== undefined) {
      this.setState(queuedState.state, queuedState.args);
    }
    if (this.#currentState && this.#currentState.onUpdate) {
      this.#currentState.onUpdate();
    }
  }

  public setState(name: string, ...args: unknown[]): void {
    if (!this.#states.has(name)) {
      console.warn(
        `State "${name}" not found in state machine "${StateMachine.name}-${this.#id}"`,
      );
      return;
    }
    if (this.#isCurrentState(name)) {
      return;
    }
    if (this.#isChangingState) {
      this.#nextStateQueue.push({ state: name, args });
      return;
    }

    this.#isChangingState = true;

    // Call onExit on the current state before changing
    if (this.#currentState?.onExit) {
      this.#currentState.onExit();
    }

    this.#debugLog(
      `Changing state from ${this.#currentState?.name ?? "none"} to "${name}"`,
    );
    this.#currentState = this.#states.get(name);

    if (this.#currentState?.onEnter) {
      this.#currentState.onEnter(args);
    }

    this.#isChangingState = false;
  }

  public get currentState(): State | undefined {
    return this.#currentState;
  }

  public addState(state: State): void {
    state.stateMachine = this;
    this.#states.set(state.name, state);
  }

  public get enabled(): boolean {
    return this.#enabled;
  }

  public set enabled(value: boolean) {
    this.#enabled = value;
  }

  #isCurrentState(name: string): boolean {
    if (!this.#currentState) {
      return false;
    }
    return this.#currentState.name === name;
  }

  #debugLog(message: string): void {
    if (!DEBUG_CHARACTER_STATE) {
      return;
    }
    console.log(`[${StateMachine.name}-${this.#id}] ${message}`);
  }
}
