  protected enableRoomObjects(roomId: number): void {
    this.updateForegroundOverride(roomId);
    this.#objectsByRoomId[roomId].animatedObjects.forEach((animatedObject) => {
      animatedObject.enableObject();
    });
    this.#objectsByRoomId[roomId].doors.forEach((door) => {
      door.enableObject();
    });
    this.#objectsByRoomId[roomId].chests.forEach((chest) => {
      chest.enableObject();
    });
    this.#objectsByRoomId[roomId].switches.forEach((switchObj) => {
      switchObj.enableObject();
    });
    this.#objectsByRoomId[roomId].floorToggles.forEach((floorToggle) => {
      floorToggle.enableObject();
    });
    this.#objectsByRoomId[roomId].colorClues.forEach((colorClue) => {
      colorClue.enableObject();
    });
    this.#objectsByRoomId[roomId].events.forEach((eventZone) => {
      eventZone.enableObject();
    });
    this.#objectsByRoomId[roomId].readables.forEach((readable) => {
      readable.enableObject();
    });
    this.#objectsByRoomId[roomId].buriedTreasures.forEach((treasure) => {
      treasure.enableObject();
    });
    this.#objectsByRoomId[roomId].effects.forEach((effect) => {
      effect.enableObject();
    });
    this.#objectsByRoomId[roomId].fishingSpots.forEach((fishingSpot) => {
      fishingSpot.enableObject();
    });
    const monGroup = this.#objectsByRoomId[roomId].monGroup;
    if (monGroup !== undefined) {
      for (const mon of monGroup.getChildren()) {
        (mon as CharacterObject).enableObject();
      }
    }
    const npcGroup = this.#objectsByRoomId[roomId].npcGroup;
    if (npcGroup !== undefined) {
      for (const npc of npcGroup.getChildren()) {
        const npcObject = npc as NPC;
        npcObject.enableObject();
      }
    }
  }

